#!/bin/bash

# Movie Hardlink/Rename Simulator
# Mimics movie management's exact hardlinking and renaming process with directory batch support
# Naming formats based on TRaSH-Guides: https://trash-guides.info/Movies/Movie-recommended-naming-scheme/

set -e

# Global interrupt flag for immediate Ctrl+C response
INTERRUPTED=false

# Trap Ctrl+C and cleanup - more aggressive handling
cleanup_on_exit() {
    local exit_code=$?
    INTERRUPTED=true
    
    # Restore cursor visibility and terminal state
    tput cnorm 2>/dev/null
    stty echo 2>/dev/null
    
    # Kill any child processes immediately
    pkill -P $$ 2>/dev/null || true
    
    # Clean up temp files
    rm -f /tmp/movie_*.$$* 2>/dev/null
    rm -rf /tmp/tv_lookup_locks/* 2>/dev/null
    
    # Clean up this instance's file locks (only ones we own)
    if [[ -d "$PROCESSING_LOCKS_DIR" ]]; then
        find "$PROCESSING_LOCKS_DIR" -name "*.lock" -type d 2>/dev/null | while read -r lockdir; do
            if [[ -f "${lockdir}/pid" ]]; then
                local lock_pid=$(cat "${lockdir}/pid" 2>/dev/null)
                if [[ "$lock_pid" == "$$" ]]; then
                    rm -rf "$lockdir" 2>/dev/null
                fi
            fi
        done
    fi
    
    if [[ $exit_code -ne 0 ]] || [[ "$INTERRUPTED" == "true" ]]; then
        echo "" >&2
        echo -e "\n${YELLOW:-}Script interrupted or exited.${NC:-}" >&2
    fi
    
    # Restart any media server containers we stopped
    if [[ -n "${STOPPED_MEDIA_CONTAINERS:-}" ]] && command -v docker &> /dev/null; then
        echo -e "${GREEN:-}Restarting media server containers...${NC:-}" >&2
        for cid in $STOPPED_MEDIA_CONTAINERS; do
            docker start "$cid" &>/dev/null || true
        done
        STOPPED_MEDIA_CONTAINERS=""
    fi
    
    # Restart any native media services we stopped
    if [[ -n "${STOPPED_NATIVE_SERVICES:-}" ]]; then
        echo -e "${GREEN:-}Restarting native media services...${NC:-}" >&2
        for entry in $STOPPED_NATIVE_SERVICES; do
            local kind="${entry%%:*}"
            local target="${entry#*:}"
            case "$kind" in
                systemctl) sudo systemctl start "$target" 2>/dev/null || true ;;
                launchctl) launchctl load "$target" 2>/dev/null || true ;;
                brew)      brew services start "$target" &>/dev/null || true ;;
            esac
        done
        STOPPED_NATIVE_SERVICES=""
    fi
    
    # Force exit
    exit ${exit_code:-130}
}

# More aggressive interrupt handler
interrupt_handler() {
    INTERRUPTED=true
    # Restore cursor visibility and terminal state immediately
    tput cnorm 2>/dev/null
    stty echo 2>/dev/null
    echo "" >&2
    echo -e "\n${YELLOW:-}Ctrl+C detected - stopping...${NC:-}" >&2
    exit 130
}

# Check for interrupt signal during processing
check_interrupt() {
    if [[ "$INTERRUPTED" == "true" ]]; then
        echo "\n[INFO] Processing interrupted by user" >&2
        exit 130
    fi
}

# Acquire lock for processing a specific file (returns 0 if acquired, 1 if already locked)
acquire_file_lock() {
    local file_path="$1"
    local file_inode=$(_stat_inode "$file_path")
    [[ -z "$file_inode" ]] && return 1
    
    local lockdir="${PROCESSING_LOCKS_DIR}/file_${file_inode}.lock"
    
    # Try to acquire lock (mkdir is atomic across processes)
    # Add small random delay (0-200ms) to reduce race condition likelihood
    local random_delay="0.$(printf "%03d" $((RANDOM % 200)))" 2>/dev/null || random_delay="0.001"
    sleep "$random_delay" 2>/dev/null || true
    
    local attempts=0
    while ! mkdir "$lockdir" 2>/dev/null; do
        attempts=$((attempts + 1))
        if [[ $attempts -gt 3 ]]; then
            # Timeout after 3 seconds - check if lock is stale
            if [[ -f "${lockdir}/timestamp" ]]; then
                local lock_time=$(cat "${lockdir}/timestamp" 2>/dev/null)
                local now=$(date +%s)
                local age=$((now - lock_time))
                # If lock is older than 30 seconds, assume it's stale
                if [[ $age -gt 30 ]]; then
                    local lock_pid=$(cat "${lockdir}/pid" 2>/dev/null)
                    # Check if the process is still running
                    if ! kill -0 "$lock_pid" 2>/dev/null; then
                        # Process is dead, remove stale lock
                        rm -rf "$lockdir" 2>/dev/null
                        mkdir "$lockdir" 2>/dev/null || return 1
                        break
                    fi
                fi
            fi
            # Lock is not stale or process still alive, file is being processed
            return 1
        fi
        sleep 1
    done
    
    # Store lock info immediately after acquiring
    echo "$$" > "${lockdir}/pid" 2>/dev/null
    echo "$(date +%s)" > "${lockdir}/timestamp" 2>/dev/null
    echo "$file_path" > "${lockdir}/file" 2>/dev/null
    return 0
}

# Release lock for a specific file
release_file_lock() {
    local file_path="$1"
    local file_inode=$(_stat_inode "$file_path")
    [[ -z "$file_inode" ]] && return 0
    
    local lockdir="${PROCESSING_LOCKS_DIR}/file_${file_inode}.lock"
    
    # Only remove if we own it
    if [[ -f "${lockdir}/pid" ]]; then
        local lock_pid=$(cat "${lockdir}/pid" 2>/dev/null)
        if [[ "$lock_pid" == "$$" ]]; then
            rm -rf "$lockdir" 2>/dev/null
        fi
    fi
}

# Set up traps - use interrupt_handler for INT for faster response
trap cleanup_on_exit EXIT TERM
trap interrupt_handler INT

# Colors for output
RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
BLUE='\033[1;36m'
CYAN='\033[0;36m'
PINK='\033[1;35m'
NEON_GREEN='\033[1;92m'
BRIGHT_RED='\033[1;91m'
APRICOT='\033[38;2;255;176;60m'
SKY='\033[38;2;100;200;235m'
DIM='\033[2m'
NC='\033[0m' # No Color

# Flash text helper - prints text with blink for 3 seconds then reprints without blink
flash_instruction() {
    local text="$1"
    local color="${2:-$YELLOW}"
    
    # Print with blink
    echo -e "${color}\033[5m${text}\033[25m${NC}"
    
    # Schedule to reprint without blink after 3 seconds in background
    (
        sleep 3
        # Move cursor up one line and clear it
        tput cuu1 2>/dev/null
        tput el 2>/dev/null
        # Reprint without blink
        echo -e "${color}${text}${NC}"
    ) &
}

# ═══════════════════════════════════════════════════════════════════════════════
# DEPENDENCY CHECK AND INSTALLATION
# ═══════════════════════════════════════════════════════════════════════════════

# Cross-platform package manager helpers
# Returns install/uninstall command + package name for the selected OS
# Usage:  _pkg_install <tool>   → outputs the full install command
#         _pkg_uninstall <tool> → outputs the full uninstall command
#         _pkg_label <tool>     → outputs human-readable label e.g. "apt package: mediainfo"
_pkg_install() {
    local tool="$1"
    local os="${SELECTED_OS:-macOS}"
    # Map tool → package name per OS
    local pkg="$tool"
    case "${os}::${tool}" in
        "Ubuntu/Debian::ffprobe")      pkg="ffmpeg" ;;
        "Fedora/RHEL/CentOS::ffprobe") pkg="ffmpeg" ;;
        "Arch Linux::ffprobe")         pkg="ffmpeg" ;;
        "macOS::ffprobe")              pkg="ffmpeg" ;;
        "Ubuntu/Debian::vips")         pkg="libvips-tools" ;;
        "Arch Linux::vips")            pkg="libvips" ;;
        *"::ffprobe")                  pkg="ffmpeg" ;;
    esac
    case "$os" in
        "macOS")            echo "brew install $pkg" ;;
        "Ubuntu/Debian")    echo "sudo apt-get install -y $pkg" ;;
        "Fedora/RHEL/CentOS") echo "sudo dnf install -y $pkg" ;;
        "Arch Linux")       echo "sudo pacman -S --noconfirm $pkg" ;;
        *)                  echo "sudo apt-get install -y $pkg" ;;
    esac
}

_pkg_uninstall() {
    local tool="$1"
    local os="${SELECTED_OS:-macOS}"
    local pkg="$tool"
    case "${os}::${tool}" in
        "Ubuntu/Debian::ffprobe")      pkg="ffmpeg" ;;
        "Fedora/RHEL/CentOS::ffprobe") pkg="ffmpeg" ;;
        "Arch Linux::ffprobe")         pkg="ffmpeg" ;;
        "macOS::ffprobe")              pkg="ffmpeg" ;;
        "Ubuntu/Debian::vips")         pkg="libvips-tools" ;;
        "Arch Linux::vips")            pkg="libvips" ;;
        *"::ffprobe")                  pkg="ffmpeg" ;;
    esac
    case "$os" in
        "macOS")            echo "brew uninstall $pkg" ;;
        "Ubuntu/Debian")    echo "sudo apt-get remove -y $pkg" ;;
        "Fedora/RHEL/CentOS") echo "sudo dnf remove -y $pkg" ;;
        "Arch Linux")       echo "sudo pacman -R --noconfirm $pkg" ;;
        *)                  echo "sudo apt-get remove -y $pkg" ;;
    esac
}

_pkg_label() {
    local tool="$1" action="${2:-install}"
    local os="${SELECTED_OS:-macOS}"
    local mgr="package manager"
    case "$os" in
        "macOS")              mgr="homebrew" ;;
        "Ubuntu/Debian")      mgr="apt" ;;
        "Fedora/RHEL/CentOS") mgr="dnf" ;;
        "Arch Linux")         mgr="pacman" ;;
    esac
    local pkg="$tool"
    case "${os}::${tool}" in
        *"::ffprobe") pkg="ffmpeg (includes ffprobe)" ;;
        "Ubuntu/Debian::vips") pkg="libvips-tools" ;;
        "Arch Linux::vips")    pkg="libvips" ;;
    esac
    if [[ "$action" == "install" ]]; then
        echo "Will install ${mgr} package: ${pkg}"
    else
        echo "Will uninstall ${mgr} package: ${pkg}"
    fi
}

# Selective install menu
select_install_dependencies() {
    # Timer for flashing instruction
    local flash_start=$SECONDS
    
    # Build list of installable dependencies
    # Format: name|||desc|||pkg_info|||cmd|||checked (using ||| as delimiter to avoid conflicts)
    local -a install_items=()
    
    # On macOS, offer Homebrew install if missing
    if [[ "${SELECTED_OS:-macOS}" == "macOS" ]] && ! command -v brew &>/dev/null; then
        install_items+=("brew|||Package manager for macOS|||Will install: Homebrew|||brewinstall|||1")
    fi
    
    if ! command -v mediainfo &>/dev/null; then
        install_items+=("mediainfo|||Extract accurate video/audio metadata|||$(_pkg_label mediainfo)|||$(_pkg_install mediainfo)|||0")
    fi
    
    if ! command -v ffprobe &>/dev/null; then
        install_items+=("ffprobe|||Alternative metadata extraction tool|||$(_pkg_label ffprobe)|||$(_pkg_install ffprobe)|||0")
    fi
    
    if ! command -v imgcat &>/dev/null && ! command -v chafa &>/dev/null; then
        install_items+=("chafa|||Display poster images in terminal|||$(_pkg_label chafa)|||$(_pkg_install chafa)|||0")
    fi
    
    if ! command -v vipsthumbnail &>/dev/null; then
        install_items+=("vips|||Fast image resizer (vipsthumbnail)|||$(_pkg_label vips)|||$(_pkg_install vips)|||0")
    fi
    
    if ! command -v gawk &>/dev/null; then
        install_items+=("gawk|||GNU AWK - Enhanced text processing|||$(_pkg_label gawk)|||$(_pkg_install gawk)|||0")
    fi
    
    if ! command -v mawk &>/dev/null; then
        install_items+=("mawk|||Mike's AWK - Fastest AWK implementation|||$(_pkg_label mawk)|||$(_pkg_install mawk)|||0")
    fi
    
    if [[ ${#install_items[@]} -eq 0 ]]; then
        clear
        echo ""
        echo -e "${GREEN}All optional dependencies are already installed!${NC}"
        echo ""
        sleep 2
        return 0
    fi
    
    local selected_idx=0
    tput civis 2>/dev/null
    
    while true; do
        # Redraw full screen
        clear
        
        echo ""
        echo -e "${BLUE}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
        echo -e "${CYAN}INSTALL DEPENDENCIES${NC}"
        echo -e "${BLUE}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
        echo ""
        # Flash instruction for 5 seconds
        if [[ $((SECONDS - flash_start)) -lt 5 ]]; then
            echo -e "${YELLOW}\033[5mSelect dependencies to install (use 'x' or Space to toggle, Enter to confirm, 'b' to go back)\033[25m${NC}"
        else
            echo -e "${YELLOW}Select dependencies to install (use 'x' or Space to toggle, Enter to confirm, 'b' to go back)${NC}"
        fi
        echo -e "${DIM}Note: Packages will be installed using Homebrew${NC}"
        echo ""
        
        # Display items
        for i in "${!install_items[@]}"; do
            local item="${install_items[$i]}"
            local name="${item%%|||*}"
            local rest="${item#*|||}"
            local desc="${rest%%|||*}"
            rest="${rest#*|||}"
            local pkg_info="${rest%%|||*}"
            rest="${rest#*|||}"
            local cmd="${rest%%|||*}"
            local checked="${rest##*|||}"
            
            local checkbox="[ ]"
            [[ "$checked" == "1" ]] && checkbox="[✓]"
            
            if [[ $i -eq $selected_idx ]]; then
                echo -e "  ${GREEN}► $checkbox $name${NC}"
                echo -e "        ${DIM}$desc${NC}"
                echo -e "        ${CYAN}$pkg_info${NC}"
            else
                echo -e "  ${DIM}  $checkbox $name${NC}"
                echo -e "        ${DIM}$desc${NC}"
            fi
            echo ""
        done
        
        echo ""
        # Flash instruction for 5 seconds
        if [[ $((SECONDS - flash_start)) -lt 5 ]]; then
            echo -e "${DIM}\033[5mPress 'x' or Space to toggle, Enter to install selected, 'b' to cancel\033[25m${NC}"
        else
            echo -e "${DIM}Press 'x' or Space to toggle, Enter to install selected, 'b' to cancel${NC}"
        fi
        
        # Read input
        read -rsn1 key 2>/dev/null
        
        if [[ "$key" == $'\x1b' ]]; then
            read -rsn2 -t 1 key 2>/dev/null
            case "$key" in
                '[A'|'OA') # Up
                    ((selected_idx--)) || true
                    [[ $selected_idx -lt 0 ]] && selected_idx=$((${#install_items[@]} - 1))
                    ;;
                '[B'|'OB') # Down
                    ((selected_idx++)) || true
                    [[ $selected_idx -ge ${#install_items[@]} ]] && selected_idx=0
                    ;;
            esac
        elif [[ "$key" == " " ]] || [[ "$key" == "x" ]] || [[ "$key" == "X" ]]; then
            # Toggle selection with space bar or 'x' key
            local item="${install_items[$selected_idx]}"
            local name="${item%%|||*}"
            local rest="${item#*|||}"
            local desc="${rest%%|||*}"
            rest="${rest#*|||}"
            local pkg_info="${rest%%|||*}"
            rest="${rest#*|||}"
            local cmd="${rest%%|||*}"
            local checked="${rest##*|||}"
            
            if [[ "$checked" == "1" ]]; then
                install_items[$selected_idx]="$name|||$desc|||$pkg_info|||$cmd|||0"
            else
                install_items[$selected_idx]="$name|||$desc|||$pkg_info|||$cmd|||1"
            fi
        elif [[ "$key" == "b" ]] || [[ "$key" == "B" ]]; then
            tput cnorm 2>/dev/null
            clear
            return 0
        elif [[ "$key" == "" ]]; then
            # Enter - install selected
            tput cnorm 2>/dev/null
            clear
            echo ""
            
            local -a to_install=()
            for item in "${install_items[@]}"; do
                local name="${item%%|||*}"
                local rest="${item#*|||}"
                local desc="${rest%%|||*}"
                rest="${rest#*|||}"
                local pkg_info="${rest%%|||*}"
                rest="${rest#*|||}"
                local cmd="${rest%%|||*}"
                local checked="${rest##*|||}"
                
                [[ "$checked" == "1" ]] && to_install+=("$name|||$pkg_info|||$cmd")
            done
            
            if [[ ${#to_install[@]} -eq 0 ]]; then
                echo -e "${YELLOW}No dependencies selected for install${NC}"
                echo ""
                sleep 2
                return 0
            fi
            
            echo -e "${CYAN}Installing selected dependencies...${NC}"
            echo ""
            
            for item in "${to_install[@]}"; do
                local name="${item%%|||*}"
                local rest="${item#*|||}"
                rest="${rest#*|||}"
                local cmd="${rest##*|||}"
                echo -e "${YELLOW}Installing $name...${NC}"
                
                # Special handling for brew install
                if [[ "$cmd" == "brewinstall" ]]; then
                    /bin/bash -c "$(curl -fsSL https://raw.githubusercontent.com/Homebrew/install/HEAD/install.sh)"
                    
                    # Add brew to PATH for this session
                    if [[ -f "/opt/homebrew/bin/brew" ]]; then
                        eval "$(/opt/homebrew/bin/brew shellenv)"
                    elif [[ -f "/usr/local/bin/brew" ]]; then
                        eval "$(/usr/local/bin/brew shellenv)"
                    fi
                else
                    eval "$cmd"
                fi
                echo ""
            done
            
            echo -e "${GREEN}✓ Installation complete!${NC}"
            echo ""
            sleep 2
            return 0
        fi
    done
}

# Selective uninstall menu
select_uninstall_dependencies() {
    # Timer for flashing instruction
    local flash_start=$SECONDS
    
    # Build list of uninstallable dependencies
    # Format: name|||desc|||pkg_info|||cmd|||checked (using ||| as delimiter to avoid conflicts)
    local -a uninstall_items=()
    
    if command -v mediainfo &>/dev/null; then
        uninstall_items+=("mediainfo|||Extract accurate video/audio metadata|||$(_pkg_label mediainfo uninstall)|||$(_pkg_uninstall mediainfo)|||0")
    fi
    
    if command -v ffprobe &>/dev/null; then
        uninstall_items+=("ffprobe|||Alternative metadata extraction tool|||$(_pkg_label ffprobe uninstall)|||$(_pkg_uninstall ffprobe)|||0")
    fi
    
    if command -v chafa &>/dev/null; then
        uninstall_items+=("chafa|||Display poster images in terminal|||$(_pkg_label chafa uninstall)|||$(_pkg_uninstall chafa)|||0")
    fi
    
    if command -v vipsthumbnail &>/dev/null; then
        uninstall_items+=("vips|||Fast image resizer (vipsthumbnail)|||$(_pkg_label vips uninstall)|||$(_pkg_uninstall vips)|||0")
    fi
    
    if command -v gawk &>/dev/null; then
        uninstall_items+=("gawk|||GNU AWK - Enhanced text processing|||$(_pkg_label gawk uninstall)|||$(_pkg_uninstall gawk)|||0")
    fi
    
    if command -v mawk &>/dev/null; then
        uninstall_items+=("mawk|||Mike's AWK - Fastest AWK|||$(_pkg_label mawk uninstall)|||$(_pkg_uninstall mawk)|||0")
    fi
    
    # Only offer brew uninstall on macOS
    if [[ "${SELECTED_OS:-macOS}" == "macOS" ]] && command -v brew &>/dev/null; then
        uninstall_items+=("brew|||Package manager (REMOVES ALL BREW PACKAGES! including BREW itself)|||Will uninstall: Homebrew + all installed packages|||brewuninstall|||0")
    fi
    
    if [[ ${#uninstall_items[@]} -eq 0 ]]; then
        echo -e "${YELLOW}No optional dependencies to uninstall${NC}"
        echo ""
        sleep 2
        return 0
    fi
    
    local selected_idx=0
    tput civis 2>/dev/null
    
    while true; do
        # Redraw full screen
        clear
        
        echo ""
        echo -e "${BLUE}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
        echo -e "${CYAN}UNINSTALL DEPENDENCIES${NC}"
        echo -e "${BLUE}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
        echo ""
        # Flash instruction for 5 seconds
        if [[ $((SECONDS - flash_start)) -lt 5 ]]; then
            echo -e "${YELLOW}\033[5m↑/↓: Navigate  x/Space: Toggle  ENTER: Confirm  ←/b: Back\033[25m${NC}"
        else
            echo -e "${YELLOW}↑/↓: Navigate  x/Space: Toggle  ENTER: Confirm  ←/b: Back${NC}"
        fi
        echo -e "${DIM}Note: Only checked items will be uninstalled. System tools (curl, sips, imgcat) cannot be uninstalled.${NC}"
        echo ""
        
        # Display items
        for i in "${!uninstall_items[@]}"; do
            local item="${uninstall_items[$i]}"
            local name="${item%%|||*}"
            local rest="${item#*|||}"
            local desc="${rest%%|||*}"
            rest="${rest#*|||}"
            local pkg_info="${rest%%|||*}"
            rest="${rest#*|||}"
            local cmd="${rest%%|||*}"
            local checked="${rest##*|||}"
            
            local checkbox="[ ]"
            [[ "$checked" == "1" ]] && checkbox="[✓]"
            
            if [[ $i -eq $selected_idx ]]; then
                echo -e "  ${GREEN}► $checkbox $name${NC}"
                echo -e "        ${DIM}$desc${NC}"
                echo -e "        ${YELLOW}$pkg_info${NC}"
            else
                echo -e "  ${DIM}  $checkbox $name${NC}"
                echo -e "        ${DIM}$desc${NC}"
            fi
            echo ""
        done
        
        echo ""
        # Flash instruction for 5 seconds
        if [[ $((SECONDS - flash_start)) -lt 5 ]]; then
