                elif [[ "$sub_basename_lower" =~ (nynorsk) ]]; then
                    regional_desc="nynorsk"
                    has_regional=true
                elif [[ "$sub_basename_lower" =~ (cyrillic) ]]; then
                    regional_desc="cyrillic"
                    has_regional=true
                elif [[ "$sub_basename_lower" =~ ^(latin)[^a-z] ]]; then
                    regional_desc="latin"
                    has_regional=true
                fi
                
                # Add regional descriptor first if found
                if [[ "$has_regional" == true ]]; then
                    ordered_parts+=("$regional_desc")
                fi
                
                # Now parse filename parts in order, preserving original positions
                # For "sdh.eng.hi.srt" we want output "sdh.eng.hi.srt" (exact order preserved)
                if [[ -n "$name_without_ext" ]]; then
                    IFS='.' read -ra parts <<< "$name_without_ext"
                    for part in "${parts[@]}"; do
                        local normalized_part=""
                        
                        # Check if this is the language code - add it in original position (only if not empty)
                        if [[ -n "$lang_code" ]] && [[ "$part" == "$lang_code" ]]; then
                            ordered_parts+=("$lang_code")
                            continue
                        fi
                        
                        # Check if this part is a known descriptor
                        local is_descriptor=false
                        
                        # Quality/format descriptors with boundaries
                        if [[ "$part" =~ ^(forced)$ ]]; then
                            normalized_part="forced"
                            is_descriptor=true
                        elif [[ "$part" =~ ^(sdh)$ ]]; then
                            normalized_part="sdh"
                            is_descriptor=true
                        elif [[ "$part" =~ ^(hi)$ ]]; then
                            normalized_part="hi"
                            is_descriptor=true
                        elif [[ "$part" =~ ^(cc)$ ]]; then
                            normalized_part="cc"
                            is_descriptor=true
                        elif [[ "$part" =~ ^(commentary)$ ]]; then
                            normalized_part="commentary"
                            is_descriptor=true
                        # Language variant descriptors with boundaries
                        elif [[ "$part" =~ ^(simplified|simp)$ ]]; then
                            normalized_part="simplified"
                            is_descriptor=true
                        elif [[ "$part" =~ ^(traditional|trad)$ ]]; then
                            normalized_part="traditional"
                            is_descriptor=true
                        elif [[ "$part" =~ ^(cantonese)$ ]]; then
                            normalized_part="cantonese"
                            is_descriptor=true
                        fi
                        
                        # Add descriptor in its original position (after regional)
                        if [[ "$is_descriptor" == true ]]; then
                            ordered_parts+=("$normalized_part")
                        fi
                    done
                fi
                
                # Add parenthetical descriptors that weren't detected via dot-parsing
                # Only add if not already present in ordered_parts
                local has_forced=false has_sdh=false has_hi=false has_cc=false
                for part in "${ordered_parts[@]}"; do
                    [[ "$part" == "forced" ]] && has_forced=true
                    [[ "$part" == "sdh" ]] && has_sdh=true
                    [[ "$part" == "hi" ]] && has_hi=true
                    [[ "$part" == "cc" ]] && has_cc=true
                done
                if [[ "$paren_forced" == true && "$has_forced" == false ]]; then
                    ordered_parts+=("forced")
                fi
                if [[ "$paren_sdh" == true && "$has_sdh" == false ]]; then
                    ordered_parts+=("sdh")
                fi
                if [[ "$paren_hi" == true && "$has_hi" == false ]]; then
                    ordered_parts+=("hi")
                fi
                if [[ "$paren_cc" == true && "$has_cc" == false ]]; then
                    ordered_parts+=("cc")
                fi
                
                # Convert 3-letter language codes to 2-letter ISO 639-1 codes for output
                # Matches all 85+ languages from the audio language normalizer
                local lang_code_output="$lang_code"
                case "$lang_code" in
                    # Major world languages
                    eng) lang_code_output="en" ;;
                    spa) lang_code_output="es" ;;
                    chi|zho|cmn|yue) lang_code_output="zh" ;;
                    hin) lang_code_output="hi" ;;
                    ara) lang_code_output="ar" ;;
                    por) lang_code_output="pt" ;;
                    ben) lang_code_output="bn" ;;
                    rus) lang_code_output="ru" ;;
                    jpn) lang_code_output="ja" ;;
                    ger|deu) lang_code_output="de" ;;
                    fre|fra) lang_code_output="fr" ;;
                    # European languages
                    alb|sqi) lang_code_output="sq" ;;
                    arm|hye) lang_code_output="hy" ;;
                    baq|eus) lang_code_output="eu" ;;
                    bel) lang_code_output="be" ;;
                    bos) lang_code_output="bs" ;;
                    bul) lang_code_output="bg" ;;
                    cat) lang_code_output="ca" ;;
                    hrv) lang_code_output="hr" ;;
                    cze|ces) lang_code_output="cs" ;;
                    dan) lang_code_output="da" ;;
                    dut|nld) lang_code_output="nl" ;;
                    est) lang_code_output="et" ;;
                    fin) lang_code_output="fi" ;;
                    glg) lang_code_output="gl" ;;
                    geo|kat) lang_code_output="ka" ;;
                    gre|ell) lang_code_output="el" ;;
                    hun) lang_code_output="hu" ;;
                    ice|isl) lang_code_output="is" ;;
                    gle) lang_code_output="ga" ;;
                    ita) lang_code_output="it" ;;
                    lav) lang_code_output="lv" ;;
                    lit) lang_code_output="lt" ;;
                    ltz) lang_code_output="lb" ;;
                    mac|mkd) lang_code_output="mk" ;;
                    mlt) lang_code_output="mt" ;;
                    nor|nob|nno) lang_code_output="no" ;;
                    pol) lang_code_output="pl" ;;
                    rum|ron) lang_code_output="ro" ;;
                    srp) lang_code_output="sr" ;;
                    slo|slk) lang_code_output="sk" ;;
                    slv) lang_code_output="sl" ;;
                    swe) lang_code_output="sv" ;;
                    ukr) lang_code_output="uk" ;;
                    wel|cym) lang_code_output="cy" ;;
                    # Asian languages
                    bur|mya) lang_code_output="my" ;;
                    khm) lang_code_output="km" ;;
                    ind) lang_code_output="id" ;;
                    kor) lang_code_output="ko" ;;
                    lao) lang_code_output="lo" ;;
                    may|msa) lang_code_output="ms" ;;
                    nep) lang_code_output="ne" ;;
                    tgl|fil) lang_code_output="tl" ;;
                    tha) lang_code_output="th" ;;
                    vie) lang_code_output="vi" ;;
                    # Indian languages
                    asm) lang_code_output="as" ;;
                    guj) lang_code_output="gu" ;;
                    kan) lang_code_output="kn" ;;
                    mal) lang_code_output="ml" ;;
                    mar) lang_code_output="mr" ;;
                    ori) lang_code_output="or" ;;
                    pan) lang_code_output="pa" ;;
                    san) lang_code_output="sa" ;;
                    snd) lang_code_output="sd" ;;
                    sin) lang_code_output="si" ;;
                    tam) lang_code_output="ta" ;;
                    tel) lang_code_output="te" ;;
                    urd) lang_code_output="ur" ;;
                    # Middle Eastern languages
                    aze) lang_code_output="az" ;;
                    fas|per) lang_code_output="fa" ;;
                    heb) lang_code_output="he" ;;
                    kur) lang_code_output="ku" ;;
                    pus) lang_code_output="ps" ;;
                    tur) lang_code_output="tr" ;;
                    # African languages
                    afr) lang_code_output="af" ;;
                    amh) lang_code_output="am" ;;
                    hau) lang_code_output="ha" ;;
                    ibo) lang_code_output="ig" ;;
                    kin) lang_code_output="rw" ;;
                    mlg) lang_code_output="mg" ;;
                    som) lang_code_output="so" ;;
                    swa) lang_code_output="sw" ;;
                    xho) lang_code_output="xh" ;;
                    yor) lang_code_output="yo" ;;
                    zul) lang_code_output="zu" ;;
                    # Central Asian & Other
                    kaz) lang_code_output="kk" ;;
                    kir) lang_code_output="ky" ;;
                    mon) lang_code_output="mn" ;;
                    tgk) lang_code_output="tg" ;;
                    tuk) lang_code_output="tk" ;;
                    uig) lang_code_output="ug" ;;
                    uzb) lang_code_output="uz" ;;
                    # Latin American & Caribbean
                    que) lang_code_output="qu" ;;
                    grn) lang_code_output="gn" ;;
                    aym) lang_code_output="ay" ;;
                    hat) lang_code_output="ht" ;;
                    # Pacific languages
                    mao|mri) lang_code_output="mi" ;;
                    smo) lang_code_output="sm" ;;
                    ton) lang_code_output="to" ;;
                    fij) lang_code_output="fj" ;;
                    # Constructed/Special
                    epo) lang_code_output="eo" ;;
                    lat) lang_code_output="la" ;;
                esac
                
                # Build filename: moviename.lang[.descriptor1][.descriptor2].ext
                local new_sub_name="${video_base}"
                
                # Build subtitle signature for duplicate tracking (lang + all descriptors)
                local sub_signature=""
                if [[ -n "$lang_code_output" ]]; then
                    sub_signature="${lang_code_output}"
                fi
                
                # Add language code first (2-letter format)
                if [[ -n "$lang_code_output" ]]; then
                    new_sub_name="${new_sub_name}.${lang_code_output}"
                fi
                
                # Add all descriptor parts after language
                for desc in "${ordered_parts[@]}"; do
                    # Skip the language code since we already added it
                    if [[ "$desc" != "$lang_code" && "$desc" != "$lang_code_output" ]]; then
                        new_sub_name="${new_sub_name}.${desc}"
                        sub_signature="${sub_signature}.${desc}"
                    fi
                done
                
                # Check if this exact subtitle signature has been used before (handle true duplicates)
                # Use full signature (lang + descriptors) so en.forced and en.sdh are different
                if [[ -n "$sub_signature" ]]; then
                    local lang_count=1
                    
                    while [[ "$used_languages" == *"|${sub_signature}:${lang_count}|"* ]]; do
                        ((lang_count++)) || true
                    done
                    
                    # Append counter if duplicate
                    if [[ $lang_count -gt 1 ]]; then
                        new_sub_name="${new_sub_name}.${lang_count}"
                    fi
                    
                    # Mark this signature as used
                    used_languages="${used_languages}|${sub_signature}:${lang_count}|"
                fi
                
                # Add extension
                new_sub_name="${new_sub_name}.${sub_ext}"
                
                local dest_subtitle="${movie_folder}/${new_sub_name}"
                
                # Check if subtitle already exists and is hardlinked
                if [[ -f "$dest_subtitle" ]]; then
                    local source_inode=$(_stat_inode "$sub_file")
                    local dest_inode=$(_stat_inode "$dest_subtitle")
                    
                    if [[ "$source_inode" != "$dest_inode" ]]; then
                        rm "$dest_subtitle"
                        if $USE_COPY; then
                            cp "$sub_file" "$dest_subtitle"
                        elif $USE_SYMLINK; then
                            ln -s "$sub_file" "$dest_subtitle"
                        else
                            ln "$sub_file" "$dest_subtitle" 2>/dev/null || cp "$sub_file" "$dest_subtitle"
                        fi
                        ((subtitle_count++)) || true
                    fi
                else
                    if $USE_COPY; then
                        cp "$sub_file" "$dest_subtitle"
                    elif $USE_SYMLINK; then
                        ln -s "$sub_file" "$dest_subtitle"
                    else
                        ln "$sub_file" "$dest_subtitle" 2>/dev/null || cp "$sub_file" "$dest_subtitle"
                    fi
                    ((subtitle_count++)) || true
                fi
            done < <(find "$subs_dir" -type f \( -iname "*.srt" -o -iname "*.sub" -o -iname "*.idx" -o -iname "*.ass" -o -iname "*.ssa" -o -iname "*.vtt" \) -print0)
        done < <(find "$source_dir" -maxdepth 1 -type d \( -iname "subs" -o -iname "subtitles" -o -iname "subtitle" -o -iname "lang" -o -iname "language" -o -iname "languages" \) -print0)
        
        # Process language-specific subtitle folders (e.g., Subs-English, Subs-Arabic, etc.)
        while IFS= read -r -d '' lang_subs_dir; do
            local folder_name=$(basename "$lang_subs_dir")
            
            # Extract language from folder name (e.g., "Subs-English" -> "english")
            if [[ "$folder_name" =~ ^Subs-(.+)$ ]]; then
                local lang_identifier="${BASH_REMATCH[1]}"
                local lang_identifier_lower=$(echo "$lang_identifier" | tr '[:upper:]' '[:lower:]' | tr -d ' ')
                
                # Skip "Subs-Multi Languages" as it's handled separately
                if [[ "$lang_identifier_lower" == "multilanguages" ]]; then
                    continue
                fi
                
                should_debug low && echo "[DEBUG] Processing language-specific folder: $folder_name (identifier: $lang_identifier_lower)" >&2
                
                # Process subtitle files in this language folder
                while IFS= read -r -d '' sub_file; do
                    local sub_basename=$(basename "$sub_file")
                    local sub_ext="${sub_file##*.}"
                    
                    # Check if this language has been used before (handle duplicates)
                    local lang_count=1
                    while [[ "$used_languages" == *"|${lang_identifier_lower}:${lang_count}|"* ]]; do
                        ((lang_count++)) || true
                    done
                    
                    # Build new subtitle name with language identifier
                    local new_sub_name="${new_video_basename%.*}.${lang_identifier_lower}"
                    
                    # Append counter if duplicate
                    if [[ $lang_count -gt 1 ]]; then
                        new_sub_name="${new_sub_name}.${lang_count}"
                    fi
                    
                    new_sub_name="${new_sub_name}.${sub_ext}"
                    
                    # Mark this language instance as used
                    used_languages="${used_languages}|${lang_identifier_lower}:${lang_count}|"
                    
                    local dest_subtitle="${movie_folder}/${new_sub_name}"
                    
                    if [[ -f "$dest_subtitle" ]]; then
                        local source_inode=$(_stat_inode "$sub_file")
                        local dest_inode=$(_stat_inode "$dest_subtitle")
                        
                        if [[ "$source_inode" != "$dest_inode" ]]; then
                            rm "$dest_subtitle"
                            if $USE_COPY; then
                                cp "$sub_file" "$dest_subtitle"
                            elif $USE_SYMLINK; then
                                ln -s "$sub_file" "$dest_subtitle"
                            else
                                ln "$sub_file" "$dest_subtitle" 2>/dev/null || cp "$sub_file" "$dest_subtitle"
                            fi
                            ((subtitle_count++)) || true
                        fi
                    else
                        if $USE_COPY; then
                            cp "$sub_file" "$dest_subtitle"
                        elif $USE_SYMLINK; then
                            ln -s "$sub_file" "$dest_subtitle"
                        else
                            ln "$sub_file" "$dest_subtitle" 2>/dev/null || cp "$sub_file" "$dest_subtitle"
                        fi
                        ((subtitle_count++)) || true
                    fi
                done < <(find "$lang_subs_dir" -type f \( -iname "*.srt" -o -iname "*.sub" -o -iname "*.idx" -o -iname "*.ass" -o -iname "*.ssa" \) -print0)
            fi
        done < <(find "$source_dir" -mindepth 1 -maxdepth 1 -type d -iname "Subs-*" -print0 2>/dev/null)
    fi
    
    [[ $subtitle_count -gt 0 ]] && print_success "Hardlinked $subtitle_count subtitle file(s)"
    should_debug low && echo "[DEBUG] Subtitle processing complete for movie: $subtitle_count subtitles processed" >&2
    
    # Hardlink extras/bonus content if enabled (Plex/Emby/Jellyfin format)
    if [[ "$HARDLINK_EXTRAS" == "true" ]] || [[ "$HARDLINK_EXTRAS" == "no-rename" ]]; then
        local extras_count=0
        
        # Check if this is a loose file (shares directory with other movie files)
        # Count non-extras video files directly in source_dir (not in subfolders)
        # Exclude extras-type filenames (samples, trailers, etc.) so they don't trigger the loose-file guard
        local video_count_extras=$(find "$source_dir" -maxdepth 1 -type f \( -iname "*.mkv" -o -iname "*.mp4" -o -iname "*.avi" -o -iname "*.m4v" -o -iname "*.mov" -o -iname "*.vob" -o -iname "*.wmv" -o -iname "*.flv" -o -iname "*.webm" -o -iname "*.ts" -o -iname "*.m2ts" -o -iname "*.mpg" -o -iname "*.mpeg" \) 2>/dev/null | awk -F'/' '{
            n = tolower($NF)
            if (n ~ /sample/) next
            if (n ~ /^trailer/ || n ~ /[-.]trailer[-.]/) next
            if (n ~ /(behind.the.scene|bts|deleted.scene|featurette|interview|bonus|extra|short|clip|outtake|gag.reel|theme.music|backdrop)/) next
            if (n ~ /making.of/ && n !~ /the.making.of/) next
            if (n ~ /\[(trailer|behind.the.scene|deleted.scene|interview|scene|sample|short|featurette|clip|other|extra|bonus|theme.music|backdrop|making.of|outtake|gag.reel)/) next
            count++
        } END { print count+0 }')
        
        if [[ $video_count_extras -gt 1 ]]; then
            # Multiple video files in same directory = loose files, skip extras processing
            should_debug low && echo "[DEBUG] Found $video_count_extras video files in source directory - skipping extras processing for loose file" >&2
        else
        
        # Official Plex/Emby/Jellyfin extras folder names
        local -a extras_folders=("behind the scenes" "deleted scenes" "interviews" "scenes" "samples" "shorts" "featurettes" "clips" "other" "extras" "trailers" "dvd extras" "dvd-extras" "blu-ray extras" "blu-ray-extras" "bluray extras" "bluray-extras")
        
        # Process existing extras folders (exact match)
        local -a _processed_extras_dirs=()
        for folder_name in "${extras_folders[@]}"; do
            while IFS= read -r -d '' extras_dir; do
                # Use the normalized folder name for destination (not the original casing)
                _processed_extras_dirs+=("$extras_dir")
                
                # Hardlink video files and subtitles from extras directory
                # Sort each file into folder by filename (source folder is fallback)
                while IFS= read -r -d '' extra_file; do
                    local extra_basename=$(basename "$extra_file")
                    local _fname_lower=$(echo "$extra_basename" | tr '[:upper:]' '[:lower:]')
                    local _file_target=""
                    if [[ "$_fname_lower" =~ (behind.?the.?scene|bts|making.?of) ]]; then
                        _file_target="behind the scenes"
                    elif [[ "$_fname_lower" =~ deleted.?scene ]]; then
                        _file_target="deleted scenes"
                    elif [[ "$_fname_lower" =~ interview ]]; then
                        _file_target="interviews"
                    elif [[ "$_fname_lower" =~ sample ]]; then
                        _file_target="samples"
                    elif [[ "$_fname_lower" =~ short ]]; then
                        _file_target="shorts"
                    elif [[ "$_fname_lower" =~ featurette ]]; then
                        _file_target="featurettes"
                    elif [[ "$_fname_lower" =~ clip ]]; then
                        _file_target="clips"
                    elif [[ "$_fname_lower" =~ scene ]]; then
                        _file_target="scenes"
                    elif [[ "$_fname_lower" =~ trailer ]]; then
                        _file_target="trailers"
                    elif [[ "$_fname_lower" =~ (extra|bonus) ]]; then
                        _file_target="extras"
                    else
                        _file_target="$folder_name"
                    fi
                    local dest_extras_dir="${movie_folder}/${_file_target}"
                    mkdir -p "$dest_extras_dir"
                    local dest_extra="${dest_extras_dir}/${extra_basename}"
                    
                    # Check if extra file already exists and is hardlinked
                    if [[ -f "$dest_extra" ]]; then
                        local source_inode=$(_stat_inode "$extra_file")
                        local dest_inode=$(_stat_inode "$dest_extra")
                        
                        if [[ "$source_inode" != "$dest_inode" ]]; then
                            rm "$dest_extra"
                            if $USE_COPY; then
                                cp "$extra_file" "$dest_extra"
                            elif $USE_SYMLINK; then
                                ln -s "$extra_file" "$dest_extra"
                            else
                                ln "$extra_file" "$dest_extra" 2>/dev/null || cp "$extra_file" "$dest_extra"
                            fi
                            ((extras_count++)) || true
                        fi
                    else
                        if $USE_COPY; then
                            cp "$extra_file" "$dest_extra"
                        elif $USE_SYMLINK; then
                            ln -s "$extra_file" "$dest_extra"
                        else
                            ln "$extra_file" "$dest_extra" 2>/dev/null || cp "$extra_file" "$dest_extra"
                        fi
                        ((extras_count++)) || true
                    fi
                done < <(find "$extras_dir" -type f \( -iname "*.mkv" -o -iname "*.mp4" -o -iname "*.avi" -o -iname "*.m4v" -o -iname "*.mov" -o -iname "*.vob" -o -iname "*.wmv" -o -iname "*.flv" -o -iname "*.webm" -o -iname "*.ts" -o -iname "*.m2ts" -o -iname "*.mpg" -o -iname "*.mpeg" -o -iname "*.srt" -o -iname "*.sub" -o -iname "*.idx" -o -iname "*.ass" -o -iname "*.ssa" \) -print0)
            done < <(find "$source_dir" -maxdepth 1 -type d -iname "$folder_name" -print0)
        done
        
        # Process folders with extras-related keywords (like "Movie.Extras-Grym", "Other", etc.)
        while IFS= read -r -d '' extras_dir; do
            local extras_dirname=$(basename "$extras_dir")
            local extras_lower=$(echo "$extras_dirname" | tr '[:upper:]' '[:lower:]')
            
            # Skip if already processed (exact match above) or is the main movie folder
            [[ "$extras_dir" == "$source_dir" ]] && continue
            local _already_done=false
            for _pd in "${_processed_extras_dirs[@]}"; do
                if [[ "$_pd" == "$extras_dir" ]]; then _already_done=true; break; fi
            done
            [[ "$_already_done" == "true" ]] && continue
            
            # Determine which standard extras folder this should map to
            local target_folder=""
            if [[ "$extras_lower" =~ (behind.?the.?scene|bts|making.?of) ]]; then
                target_folder="behind the scenes"
            elif [[ "$extras_lower" =~ deleted.?scene ]]; then
                target_folder="deleted scenes"
            elif [[ "$extras_lower" =~ interview ]]; then
                target_folder="interviews"
            elif [[ "$extras_lower" =~ sample ]]; then
                target_folder="samples"
            elif [[ "$extras_lower" =~ short ]]; then
                target_folder="shorts"
            elif [[ "$extras_lower" =~ featurette ]]; then
                target_folder="featurettes"
            elif [[ "$extras_lower" =~ clip ]]; then
                target_folder="clips"
            elif [[ "$extras_lower" =~ trailer ]]; then
                target_folder="trailers"
            elif [[ "$extras_lower" =~ extra ]]; then
                target_folder="extras"
            elif [[ "$extras_lower" =~ bonus ]]; then
                target_folder="extras"
            elif [[ "$extras_lower" =~ other ]]; then
                target_folder="other"
            else
                # Skip folders that don't match extras patterns
                continue
            fi
            
            # Hardlink all video files from this extras folder
            # Sort each file into folder by filename (source folder category is fallback)
            while IFS= read -r -d '' extra_file; do
                local extra_basename=$(basename "$extra_file")
                local _fname_lower=$(echo "$extra_basename" | tr '[:upper:]' '[:lower:]')
                local _file_target=""
                if [[ "$_fname_lower" =~ (behind.?the.?scene|bts|making.?of) ]]; then
                    _file_target="behind the scenes"
                elif [[ "$_fname_lower" =~ deleted.?scene ]]; then
                    _file_target="deleted scenes"
                elif [[ "$_fname_lower" =~ interview ]]; then
                    _file_target="interviews"
                elif [[ "$_fname_lower" =~ sample ]]; then
                    _file_target="samples"
                elif [[ "$_fname_lower" =~ short ]]; then
                    _file_target="shorts"
                elif [[ "$_fname_lower" =~ featurette ]]; then
                    _file_target="featurettes"
                elif [[ "$_fname_lower" =~ clip ]]; then
                    _file_target="clips"
                elif [[ "$_fname_lower" =~ scene ]]; then
                    _file_target="scenes"
                elif [[ "$_fname_lower" =~ trailer ]]; then
                    _file_target="trailers"
                elif [[ "$_fname_lower" =~ (extra|bonus) ]]; then
                    _file_target="extras"
                else
                    _file_target="$target_folder"
                fi
                local dest_extras_dir="${movie_folder}/${_file_target}"
                mkdir -p "$dest_extras_dir"
                local dest_extra="${dest_extras_dir}/${extra_basename}"
                
                # Check if extra file already exists and is hardlinked
                if [[ -f "$dest_extra" ]]; then
                    local source_inode=$(_stat_inode "$extra_file")
                    local dest_inode=$(_stat_inode "$dest_extra")
                    
                    if [[ "$source_inode" != "$dest_inode" ]]; then
                        rm "$dest_extra"
                        if $USE_COPY; then
                            cp "$extra_file" "$dest_extra"
                        elif $USE_SYMLINK; then
                            ln -s "$extra_file" "$dest_extra"
                        else
                            ln "$extra_file" "$dest_extra" 2>/dev/null || cp "$extra_file" "$dest_extra"
                        fi
                        ((extras_count++)) || true
                    fi
                else
                    if $USE_COPY; then
                        cp "$extra_file" "$dest_extra"
                    elif $USE_SYMLINK; then
                        ln -s "$extra_file" "$dest_extra"
                    else
                        ln "$extra_file" "$dest_extra" 2>/dev/null || cp "$extra_file" "$dest_extra"
                    fi
                    ((extras_count++)) || true
                fi
            done < <(find "$extras_dir" -type f \( -iname "*.mkv" -o -iname "*.mp4" -o -iname "*.avi" -o -iname "*.m4v" -o -iname "*.mov" -o -iname "*.vob" -o -iname "*.wmv" -o -iname "*.flv" -o -iname "*.webm" -o -iname "*.ts" -o -iname "*.m2ts" -o -iname "*.mpg" -o -iname "*.mpeg" -o -iname "*.srt" -o -iname "*.sub" -o -iname "*.idx" -o -iname "*.ass" -o -iname "*.ssa" \) -print0)
        done < <(find "$source_dir" -maxdepth 1 -type d ! -path "$source_dir" -print0)
        
        # Process loose extras files (not in folders) - categorize by filename
        while IFS= read -r -d '' extra_file; do
            # Skip if this is the main movie file (prevents double-linking movies titled "Making Of..." etc.)
            [[ "$extra_file" == "$source_file" ]] && continue
            local extra_basename=$(basename "$extra_file")
            local extra_lower=$(echo "$extra_basename" | tr '[:upper:]' '[:lower:]')
            
            # Determine which extras folder this file belongs to based on filename
            local target_folder=""
            if [[ "$extra_lower" =~ (behind.?the.?scene|bts|making.?of) ]]; then
                target_folder="behind the scenes"
            elif [[ "$extra_lower" =~ deleted.?scene ]]; then
                target_folder="deleted scenes"
            elif [[ "$extra_lower" =~ interview ]]; then
                target_folder="interviews"
            elif [[ "$extra_lower" =~ sample ]]; then
                target_folder="samples"
            elif [[ "$extra_lower" =~ short ]]; then
                target_folder="shorts"
            elif [[ "$extra_lower" =~ featurette ]]; then
                target_folder="featurettes"
            elif [[ "$extra_lower" =~ clip ]]; then
                target_folder="clips"
            elif [[ "$extra_lower" =~ scene ]]; then
                target_folder="scenes"
            elif [[ "$extra_lower" =~ trailer ]]; then
                target_folder="trailers"
            elif [[ "$extra_lower" =~ (extra|bonus) ]]; then
                target_folder="extras"
            else
                # Default catch-all
                target_folder="other"
            fi
            
            # Create destination extras folder and hardlink file
            local dest_extras_dir="${movie_folder}/${target_folder}"
            mkdir -p "$dest_extras_dir"
            local dest_extra="${dest_extras_dir}/${extra_basename}"
            
            # Check if extra file already exists and is hardlinked
            if [[ -f "$dest_extra" ]]; then
                local source_inode=$(_stat_inode "$extra_file")
                local dest_inode=$(_stat_inode "$dest_extra")
                
                if [[ "$source_inode" != "$dest_inode" ]]; then
                    rm "$dest_extra"
                    if $USE_COPY; then
                        cp "$extra_file" "$dest_extra"
                    elif $USE_SYMLINK; then
                        ln -s "$extra_file" "$dest_extra"
                    else
                        ln "$extra_file" "$dest_extra" 2>/dev/null || cp "$extra_file" "$dest_extra"
                    fi
                    ((extras_count++)) || true
                fi
            else
                if $USE_COPY; then
                    cp "$extra_file" "$dest_extra"
                elif $USE_SYMLINK; then
                    ln -s "$extra_file" "$dest_extra"
                else
                    ln "$extra_file" "$dest_extra" 2>/dev/null || cp "$extra_file" "$dest_extra"
                fi
                ((extras_count++)) || true
            fi
        done < <(find "$source_dir" -maxdepth 1 -type f \( -iname "*behind*the*scene*" -o -iname "*bts*" -o -iname "*making*of*" -o -iname "*deleted*scene*" -o -iname "*interview*" -o -iname "*featurette*" -o -iname "*trailer*" -o -iname "*bonus*" -o -iname "*extra*" -o -iname "*short*" -o -iname "*sample*" -o -iname "*clip*" \) \( -iname "*.mkv" -o -iname "*.mp4" -o -iname "*.avi" -o -iname "*.m4v" -o -iname "*.mov" -o -iname "*.vob" -o -iname "*.wmv" -o -iname "*.flv" -o -iname "*.webm" -o -iname "*.ts" -o -iname "*.m2ts" -o -iname "*.mpg" -o -iname "*.mpeg" \) -print0)
        
        [[ $extras_count -gt 0 ]] && print_success "Hardlinked $extras_count file(s) from extras folders and loose extras files"
        
        fi  # End of loose file check for true/no-rename mode
        
    elif [[ "$HARDLINK_EXTRAS" == "preserve" ]]; then
        # Preserve folder structure mode - only hardlink video files and subtitle files
        local extras_count=0
        
        # Check if this is a loose file (shares directory with other movie files)
        # Count non-extras video files directly in source_dir (not in subfolders)
        # Exclude extras-type filenames (samples, trailers, etc.) so they don't trigger the loose-file guard
        local video_count=$(find "$source_dir" -maxdepth 1 -type f \( -iname "*.mkv" -o -iname "*.mp4" -o -iname "*.avi" -o -iname "*.m4v" -o -iname "*.mov" -o -iname "*.vob" -o -iname "*.wmv" -o -iname "*.flv" -o -iname "*.webm" -o -iname "*.ts" -o -iname "*.m2ts" -o -iname "*.mpg" -o -iname "*.mpeg" \) | awk -F'/' '{
            n = tolower($NF)
            if (n ~ /sample/) next
            if (n ~ /^trailer/ || n ~ /[-.]trailer[-.]/) next
            if (n ~ /(behind.the.scene|bts|deleted.scene|featurette|interview|bonus|extra|short|clip|outtake|gag.reel|theme.music|backdrop)/) next
            if (n ~ /making.of/ && n !~ /the.making.of/) next
            if (n ~ /\[(trailer|behind.the.scene|deleted.scene|interview|scene|sample|short|featurette|clip|other|extra|bonus|theme.music|backdrop|making.of|outtake|gag.reel)/) next
            count++
        } END { print count+0 }')
        
        local is_loose_file=false
        if [[ $video_count -gt 1 ]]; then
            # Multiple video files in same directory = loose files, not a dedicated movie folder
            is_loose_file=true
            should_debug low && echo "[DEBUG] Found $video_count video files in source directory - this is a loose file, skipping preserve mode" >&2
        fi
        
        # If it's a loose file, skip preserve mode entirely (other files are separate movies, not extras)
        if $is_loose_file; then
            should_debug low && echo "[DEBUG] Skipping preserve mode for loose file to prevent treating other movies as extras" >&2
        else
            # Mirror the entire directory structure, but only hardlink video and subtitle files
            while IFS= read -r -d '' source_file_extra; do
                # Get the relative path from source_dir
                local rel_path="${source_file_extra#$source_dir/}"
                
                # Skip if this is the main movie file or its associated files
                [[ "$source_file_extra" == "$source_file" ]] && continue
            
            # Check if this file is actually a different movie (not an extra)
            # Parse the filename to see if it has a different title/year
            local extra_basename=$(basename "$source_file_extra")
            if [[ "$extra_basename" =~ ([0-9]{4}) ]]; then
                local extra_year="${BASH_REMATCH[1]}"
                # If the year is different from the current movie, skip it (it's a different movie)
                if [[ -n "$YEAR" && "$extra_year" != "$YEAR" ]]; then
                    should_debug low && echo "[DEBUG] Skipping $extra_basename as separate movie (year $extra_year != $YEAR)" >&2
                    continue
                fi
            fi
            
            # Create the destination path preserving folder structure
            local dest_file="${movie_folder}/${rel_path}"
            local dest_dir=$(dirname "$dest_file")
            
            # Create the directory structure if it doesn't exist
            mkdir -p "$dest_dir"
            
            # Check if file already exists and is hardlinked
            if [[ -f "$dest_file" ]]; then
                local source_inode=$(_stat_inode "$source_file_extra")
                local dest_inode=$(_stat_inode "$dest_file")
                
                if [[ "$source_inode" != "$dest_inode" ]]; then
                    rm "$dest_file"
                    if $USE_COPY; then
                        cp "$source_file_extra" "$dest_file"
                    elif $USE_SYMLINK; then
                        ln -s "$source_file_extra" "$dest_file"
                    else
                        ln "$source_file_extra" "$dest_file" 2>/dev/null || cp "$source_file_extra" "$dest_file"
                    fi
                    ((extras_count++)) || true
                fi
            else
                if $USE_COPY; then
                    cp "$source_file_extra" "$dest_file"
                elif $USE_SYMLINK; then
                    ln -s "$source_file_extra" "$dest_file"
                else
                    ln "$source_file_extra" "$dest_file" 2>/dev/null || cp "$source_file_extra" "$dest_file"
                fi
                ((extras_count++)) || true
            fi
        done < <(find "$source_dir" -type f \( -iname "*.mkv" -o -iname "*.mp4" -o -iname "*.avi" -o -iname "*.m4v" -o -iname "*.mov" -o -iname "*.vob" -o -iname "*.wmv" -o -iname "*.flv" -o -iname "*.webm" -o -iname "*.ts" -o -iname "*.m2ts" -o -iname "*.mpg" -o -iname "*.mpeg" -o -iname "*.srt" -o -iname "*.sub" -o -iname "*.idx" -o -iname "*.ass" -o -iname "*.ssa" -o -iname "*.vtt" \) -print0)
        
            [[ $extras_count -gt 0 ]] && print_success "Hardlinked $extras_count file(s) preserving original folder structure"
        fi
    fi
    
    # Release lock before returning
    release_file_lock "$source_file"
    echo "⚠️  DIAGNOSTIC Z: process_file reaching normal end, returning 0" >&2
    return 0
}

# Function to edit custom format
edit_custom_format() {
    local format_type="$1"  # "folder" or "file"
    local format_file
    local default_format
    
    if [[ "$format_type" == "folder" ]]; then
        format_file="$CUSTOM_FOLDER_FORMAT"
        default_format="{Movie CleanTitle} ({Release Year})"
    else
        format_file="$CUSTOM_FILE_FORMAT"
        default_format="{Movie CleanTitle} ({Release Year})"
    fi
    
    # Load existing custom format or use default
    local current_format
    if [[ -f "$format_file" ]]; then
        current_format=$(<"$format_file")
    else
        current_format="$default_format"
    fi
    
    echo
    echo -e "${BLUE}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
    echo -e "${CYAN}Custom ${format_type^} Format Editor${NC}"
    echo -e "${BLUE}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
    echo
    echo -e "${YELLOW}Available Variables:${NC}"
    echo "  {Movie CleanTitle}    - Movie title without special characters"
    echo "  {Release Year}        - Year of release"
    echo "  {ImdbId}              - IMDb ID (e.g., tt1234567)"
    echo "  {TmdbId}              - TMDb ID (e.g., 12345)"
    
    if [[ "$format_type" == "file" ]]; then
        echo
        echo -e "${YELLOW}Additional File Variables:${NC}"
        echo "  {Edition Tags}        - Edition info (e.g., Extended, Director's Cut)"
        echo "  {Quality Full}        - Quality (e.g., Bluray-1080p, WEBDL-2160p)"
        echo "  {Custom Formats}      - Custom format tags"
        echo "  {MediaInfo 3D}        - 3D indicator"
        echo "  {AudioCodec}          - Audio codec (e.g., DTS, TrueHD)"
        echo "  {AudioChannels}       - Audio channels (e.g., 5.1, 7.1)"
        echo "  {AudioLanguages}      - Audio languages (e.g., EN, DE)"
        echo "  {VideoDynamicRange}   - HDR type (e.g., DV, HDR10)"
        echo "  {VideoCodec}          - Video codec (e.g., x264, HEVC)"
        echo "  {VideoBitDepth}       - Bit depth (e.g., 10bit)"
        echo "  {Release Group}       - Release group name"
    fi
    
    echo
    echo -e "${YELLOW}Format Styles:${NC}"
    echo "  Curly braces:   {imdb-{ImdbId}}    → {imdb-tt1234567}"
    echo "  Square brackets: [imdb-{ImdbId}]   → [imdb-tt1234567]"
    echo "  Dots:           {Movie.CleanTitle} → Movie.Title"
    echo "  Spaces:         {Movie CleanTitle} → Movie Title"
    echo
    echo -e "${GREEN}Current format:${NC}"
    echo "  $current_format"
    echo
    echo -e "${YELLOW}Options:${NC}"
    echo "  ${GREEN}e${NC}) Edit format"
    echo "  ${GREEN}t${NC}) Test format with example"
    echo "  ${GREEN}r${NC}) Reset to default"
    echo "  ${GREEN}s${NC}) Save and return"
    echo "  ${GREEN}q${NC}) Cancel without saving"
    echo
    
    while true; do
        read -p "$(echo -e ${CYAN}Choose option:${NC} )" choice
        
        case "$choice" in
            e|E)
                echo
                echo -e "${CYAN}Enter new format (or press Enter to keep current):${NC}"
                read -e -i "$current_format" new_format
                if [[ -n "$new_format" ]]; then
                    current_format="$new_format"
                    echo -e "${GREEN}✓${NC} Format updated"
                fi
                echo
                echo -e "${GREEN}Current format:${NC} $current_format"
                echo
                ;;
            t|T)
                echo
                echo -e "${CYAN}Testing format with example data...${NC}"
                local test_output="$current_format"
                test_output="${test_output//\{Movie CleanTitle\}/The Movie Title}"
                test_output="${test_output//\{Movie.CleanTitle\}/The.Movie.Title}"
                test_output="${test_output//\{Release Year\}/2010}"
                test_output="${test_output//\{ImdbId\}/tt1234567}"
                test_output="${test_output//\{TmdbId\}/345691}"
                test_output="${test_output//\{Edition Tags\}/Ultimate Extended Edition}"
                test_output="${test_output//\{Quality Full\}/Bluray-1080p Proper}"
                test_output="${test_output//\{Custom Formats\}/IMAX HYBRID}"
                test_output="${test_output//\{MediaInfo 3D\}/3D}"
                test_output="${test_output//\{AudioCodec\}/DTS}"
                test_output="${test_output//\{AudioChannels\}/5.1}"
                test_output="${test_output//\{AudioLanguages\}/EN}"
                test_output="${test_output//\{VideoDynamicRange\}/DV HDR10}"
                test_output="${test_output//\{VideoCodec\}/x264}"
                test_output="${test_output//\{VideoBitDepth\}/10bit}"
                test_output="${test_output//\{Release Group\}/RlsGrp}"
                echo -e "${GREEN}Example output:${NC}"
                echo "  $test_output"
                echo
                ;;
            r|R)
                current_format="$default_format"
                echo
                echo -e "${GREEN}✓${NC} Reset to default format"
                echo -e "${GREEN}Current format:${NC} $current_format"
                echo
                ;;
            s|S)
                echo "$current_format" > "$format_file"
                echo
                echo -e "${GREEN}✓${NC} Custom format saved"
                return 0
                ;;
            q|Q)
                echo
                echo -e "${YELLOW}Cancelled - no changes saved${NC}"
                return 1
                ;;
            *)
                echo -e "${RED}Invalid option${NC}"
                ;;
        esac
    done
}

# Arrow key selection menu
arrow_select_menu() {
    local title="$1"
    local saved_value="$2"
    local return_var="$3"
    shift 3
    local options=("$@")
    local selected_idx=0
    
    # Find currently selected index based on saved value
    for i in "${!options[@]}"; do
        local num="${options[$i]%%|*}"
        if [[ "$num" == "$saved_value" ]]; then
            selected_idx=$i
            break
        fi
    done
    
    # Timer for flashing instruction
    local flash_start=$SECONDS
    
    # Hide cursor
    tput civis 2>/dev/null
    
    while true; do
        # Clear screen and move to top
        clear
        
        echo ""
        echo -e "${BLUE}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
        echo -e "${CYAN}$title${NC}"
        echo -e "${BLUE}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
        echo ""
        # Flash instruction for 5 seconds
        if [[ $((SECONDS - flash_start)) -lt 5 ]]; then
            echo -e "${YELLOW}\033[5mUse ↑/↓ to navigate, →/Enter to select, ←/b to go back\033[25m${NC}"
        else
            echo -e "${YELLOW}Use ↑/↓ to navigate, →/Enter to select, ←/b to go back${NC}"
        fi
        echo ""
        
        # Display options
        for i in "${!options[@]}"; do
            local num="${options[$i]%%|*}"
            local desc="${options[$i]#*|}"
            
            if [[ $i -eq $selected_idx ]]; then
                echo -e "  ${GREEN}► [✓] ${CYAN}$num) $desc${NC}"
            else
                echo -e "  ${DIM}  [ ] ${CYAN}$num) $desc${NC}"
            fi
        done
        
        echo ""
        echo -e "${DIM}Press →/Enter to confirm, ←/b to go back${NC}"
        
        # Read key input
        read -rsn1 key 2>/dev/null
        
        # Check if it's an escape sequence (arrow keys)
        if [[ "$key" == $'\x1b' ]]; then
            # Read next two characters for arrow keys
            read -rsn2 -t 1 key 2>/dev/null
            case "$key" in
                '[A'|'OA') # Up arrow
                    ((selected_idx--)) || true
                    if [[ $selected_idx -lt 0 ]]; then
                        selected_idx=$((${#options[@]} - 1))
                    fi
                    ;;
                '[B'|'OB') # Down arrow
                    ((selected_idx++)) || true
                    if [[ $selected_idx -ge ${#options[@]} ]]; then
                        selected_idx=0
                    fi
                    ;;
                '[C'|'OC') # Right arrow - act like Enter (select)
                    tput cnorm 2>/dev/null  # Show cursor
                    clear
                    local selected_num="${options[$selected_idx]%%|*}"
                    eval "$return_var='$selected_num'"
                    return 0
                    ;;
                '[D'|'OD') # Left arrow - act like back
                    tput cnorm 2>/dev/null  # Show cursor
                    clear
                    return 1
                    ;;
            esac
            # Flush any remaining buffered input to prevent key display leak
            read -rsn 999 -t 0.01 2>/dev/null || true
        elif [[ "$key" == "b" ]] || [[ "$key" == "B" ]]; then
            # Back key pressed
            tput cnorm 2>/dev/null  # Show cursor
            clear
            return 1
        elif [[ "$key" == "" ]]; then
            # Enter key pressed
            tput cnorm 2>/dev/null  # Show cursor
            clear
            local selected_num="${options[$selected_idx]%%|*}"
            # Use eval to set the variable in the calling scope
            eval "$return_var='$selected_num'"
            return 0
        fi
    done
}

# Link type selection with arrow key interface
select_link_type() {
    local -a link_opts=(
        "1|Hardlink (recommended for seeding)|Must be on same drive/volume/filesystem|Keeps original filename intact for seeding|Both files point to same data on disk|Deleting one file doesn't affect the other"
        "2|Symbolic link (for cross-volume)|Can link across different drives/volumes|Creates a pointer to original file|Original file must remain in place|Deleting original breaks the link"
        "3|Copy files|Creates full duplicate (uses more space)|Works across any filesystem||"
    )
    local selected_idx=0
    
    # Load saved preference
    if [[ -f "$LINK_TYPE_PREFS" ]]; then
        local saved_type=$(cat "$LINK_TYPE_PREFS")
        case "$saved_type" in
            "hardlink")
                selected_idx=0
                USE_SYMLINK=false
                USE_COPY=false
                ;;
            "symlink")
                selected_idx=1
                USE_SYMLINK=true
                USE_COPY=false
                ;;
            "copy")
                selected_idx=2
                USE_SYMLINK=false
                USE_COPY=true
                ;;
        esac
    fi
    
    # Hide cursor
    tput civis 2>/dev/null
    
    while true; do
        # Clear screen and move to top
        clear
        
        echo ""
        echo -e "${BLUE}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
        echo -e "${CYAN}LINK TYPE SELECTION${NC}"
        echo -e "${BLUE}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
        echo ""
        echo -e "${YELLOW}↑/↓: Navigate  →/ENTER: Select  ←/b: Go Back${NC}"
        echo ""
        
        # Display options
        for i in "${!link_opts[@]}"; do
            IFS='|' read -r num title desc1 desc2 desc3 desc4 <<< "${link_opts[$i]}"
            
            if [[ $i -eq $selected_idx ]]; then
                echo -e "  ${GREEN}► [✓] $num) $title${NC}"
            else
                echo -e "  ${DIM}  [ ] $num) $title${NC}"
            fi
            echo -e "     ${DIM}• $desc1${NC}"
            [[ -n "$desc2" ]] && echo -e "     ${DIM}• $desc2${NC}"
            [[ -n "$desc3" ]] && echo -e "     ${DIM}• $desc3${NC}"
            [[ -n "$desc4" ]] && echo -e "     ${DIM}• $desc4${NC}"
            echo ""
        done
        
        echo -e "${DIM}→/ENTER to confirm selection, ←/b to go back${NC}"
        
        # Read key input
        read -rsn1 key 2>/dev/null
        local select_link=false
        
        # Check if it's an escape sequence (arrow keys)
        if [[ "$key" == $'\x1b' ]]; then
            # Read next two characters for arrow keys
            read -rsn2 -t 1 key 2>/dev/null
            case "$key" in
                '[A'|'OA') # Up arrow
                    ((selected_idx--)) || true
                    if [[ $selected_idx -lt 0 ]]; then
                        selected_idx=$((${#link_opts[@]} - 1))
                    fi
                    ;;
                '[B'|'OB') # Down arrow
                    ((selected_idx++)) || true
                    if [[ $selected_idx -ge ${#link_opts[@]} ]]; then
                        selected_idx=0
                    fi
                    ;;
                '[C'|'OC') # Right arrow - select
                    select_link=true
                    ;;
                '[D'|'OD') # Left arrow - go back
                    tput cnorm 2>/dev/null
                    clear
                    return 1
                    ;;
            esac
            # Flush any remaining buffered input to prevent key display leak
            read -rsn 999 -t 0.01 2>/dev/null || true
        elif [[ "$key" == "b" ]] || [[ "$key" == "B" ]]; then
            # Back key pressed
            tput cnorm 2>/dev/null  # Show cursor
            clear
            return 1
        elif [[ "$key" == "" ]]; then
            # Enter key pressed
            select_link=true
        fi
        
        if [[ "$select_link" == "true" ]]; then
            tput cnorm 2>/dev/null  # Show cursor
            clear
            local selected_num="${link_opts[$selected_idx]%%|*}"
            
            case "$selected_num" in
                1)
                    USE_SYMLINK=false
                    USE_COPY=false
                    echo "hardlink" > "$LINK_TYPE_PREFS"
                    ;;
                2)
                    USE_SYMLINK=true
                    USE_COPY=false
                    echo "symlink" > "$LINK_TYPE_PREFS"
                    ;;
                3)
                    USE_SYMLINK=false
                    USE_COPY=true
                    echo "copy" > "$LINK_TYPE_PREFS"
                    ;;
            esac
            return 0
        fi
    done
}

# Select extras/bonus content options
select_extras_options() {
    # Determine the action verb based on link type
    local action_verb="process"
    local action_verb_past="processed"
    local action_title="Process"
    if [[ "$USE_COPY" == "true" ]]; then
        action_verb="copy"
        action_verb_past="copied"
        action_title="Copy"
    elif [[ "$USE_SYMLINK" == "true" ]]; then
        action_verb="symlink"
        action_verb_past="symlinked"
        action_title="Symlink"
    else
        action_verb="hardlink"
        action_verb_past="hardlinked"
        action_title="Hardlink"
    fi
    
    local -a extras_opts=(
        "1|Don't ${action_verb} extras/bonus content|Only main video and subtitles are ${action_verb_past}|Skips featurettes, behind-the-scenes, bonus content|Sample files are automatically skipped"
        "2|${action_title} extras into subfolders|Extras are ${action_verb_past} with original filenames|Organized into proper subfolders (behind the scenes, samples, etc.)|Processes featurettes, behind-the-scenes, deleted scenes, trailers|Extracts and renames subtitles from Subs/Subtitles folders (MovieName.en.srt)"
        "3|${action_title} with preserved folder structure|Preserves original folder hierarchy|Only ${action_verb}s video and subtitle files|Includes: .mkv .mp4 .avi .mov .vob .srt .sub .idx .ass .ssa .vtt|All other files (nfo, jpg, txt, etc.) are skipped"
    )
    local selected_idx=0
    
    # Load saved preference
    if [[ -f "$EXTRAS_MODE_PREFS" ]]; then
        local saved_mode=$(cat "$EXTRAS_MODE_PREFS")
        if [[ "$saved_mode" == "true" ]]; then
            selected_idx=1
            HARDLINK_EXTRAS="true"
        elif [[ "$saved_mode" == "false" ]]; then
            selected_idx=0
            HARDLINK_EXTRAS="false"
        elif [[ "$saved_mode" == "preserve" ]]; then
            selected_idx=2
            HARDLINK_EXTRAS="preserve"
        fi
    elif [[ "$HARDLINK_EXTRAS" == "true" ]]; then
        selected_idx=1
    elif [[ "$HARDLINK_EXTRAS" == "preserve" ]]; then
        selected_idx=2
    fi
    
    # Hide cursor
    tput civis 2>/dev/null
    
    while true; do
        # Clear screen and move to top
        clear
        
        echo ""
        echo -e "${BLUE}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
        echo -e "${CYAN}EXTRAS/BONUS CONTENT OPTIONS${NC}"
        echo -e "${BLUE}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
        echo ""
        echo -e "${YELLOW}Use ↑/↓ arrow keys to navigate, Enter to select, 'b' to go back${NC}"
        echo ""
        
        # Display options
        for i in "${!extras_opts[@]}"; do
            IFS='|' read -r num title desc1 desc2 desc3 desc4 <<< "${extras_opts[$i]}"
            
            if [[ $i -eq $selected_idx ]]; then
                echo -e "  ${GREEN}► [✓] $num) $title${NC}"
            else
                echo -e "  ${DIM}  [ ] $num) $title${NC}"
            fi
            echo -e "     ${DIM}• $desc1${NC}"
            [[ -n "$desc2" ]] && echo -e "     ${DIM}• $desc2${NC}"
            [[ -n "$desc3" ]] && echo -e "     ${DIM}• $desc3${NC}"
            [[ -n "$desc4" ]] && echo -e "     ${DIM}• $desc4${NC}"
            echo ""
        done
        
        echo -e "${DIM}Press Enter to confirm selection, 'b' to go back${NC}"
        
        # Read key input
        read -rsn1 key 2>/dev/null
        
        # Check if it's an escape sequence (arrow keys)
        if [[ "$key" == $'\x1b' ]]; then
            # Read next two characters for arrow keys
            read -rsn2 -t 1 key 2>/dev/null
            case "$key" in
                '[A'|'OA') # Up arrow
                    ((selected_idx--)) || true
                    if [[ $selected_idx -lt 0 ]]; then
                        selected_idx=$((${#extras_opts[@]} - 1))
                    fi
                    ;;
                '[B'|'OB') # Down arrow
                    ((selected_idx++)) || true
                    if [[ $selected_idx -ge ${#extras_opts[@]} ]]; then
                        selected_idx=0
                    fi
                    ;;
            esac
        elif [[ "$key" == "b" ]] || [[ "$key" == "B" ]]; then
            # Back key pressed
            tput cnorm 2>/dev/null  # Show cursor
            clear
            return 1
        elif [[ "$key" == "" ]]; then
            # Enter key pressed
            tput cnorm 2>/dev/null  # Show cursor
            clear
            local selected_num="${extras_opts[$selected_idx]%%|*}"
            
            case "$selected_num" in
                1)
                    HARDLINK_EXTRAS=false
                    echo "false" > "$EXTRAS_MODE_PREFS"
                    ;;
                2)
                    HARDLINK_EXTRAS=true
                    echo "true" > "$EXTRAS_MODE_PREFS"
                    ;;
                3)
                    HARDLINK_EXTRAS=preserve
                    echo "preserve" > "$EXTRAS_MODE_PREFS"
                    ;;
            esac
            return 0
        fi
    done
}

# Select parsing mode (Fast vs Thorough)
select_parsing_mode() {
    local -a parse_opts=(
        "fast|Fast Mode (Recommended)|Parses each file once and caches results in temp file|Reuses cached title/year during duplicate detection, cache sorting, and processing|Faster processing, especially for large batches|Suitable for most use cases"
        "fast-nocache|Fast No-Cache Mode|Parses each file once but doesn't use temp cache file|Still does duplicate detection and cache sorting by re-parsing|Slightly slower than fast mode|Good if temp file issues occur"
        "thorough|Thorough Mode|Re-parses files at each stage and caches results in temp file|Reuses cached results during each stage for consistency|More thorough than fast mode|Use if you suspect parsing inconsistencies"
        "thorough-nocache|Thorough No-Cache Mode|Re-parses files at each stage without using temp cache file|Skips cache-based file sorting but still does duplicate detection|Processes files in alphabetical order|Useful for debugging parsing issues"
    )
    local selected_idx=0
    
    # Load saved preference
    local parse_mode_file="$CACHE_DIR/parsing_mode.txt"
    if [[ -f "$parse_mode_file" ]]; then
        local saved_mode=$(cat "$parse_mode_file")
        if [[ "$saved_mode" == "fast-nocache" ]]; then
            selected_idx=1
        elif [[ "$saved_mode" == "thorough" ]]; then
            selected_idx=2
        elif [[ "$saved_mode" == "thorough-nocache" ]]; then
            selected_idx=3
        fi
    fi
    
    # Hide cursor
    tput civis 2>/dev/null
    
    while true; do
        # Clear screen and move to top
        clear
        
        echo ""
        echo -e "${BLUE}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
        echo -e "${CYAN}PARSING MODE SELECTION${NC}"
        echo -e "${BLUE}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
        echo ""
        echo -e "${YELLOW}↑/↓: Navigate  →/ENTER: Select  ←/b: Go Back${NC}"
        echo ""
        
        # Display options
        for i in "${!parse_opts[@]}"; do
            IFS='|' read -r mode title desc1 desc2 desc3 desc4 <<< "${parse_opts[$i]}"
            
            if [[ $i -eq $selected_idx ]]; then
                echo -e "  ${GREEN}► [✓] $(echo "$title" | tr '[:lower:]' '[:upper:]')${NC}"
            else
                echo -e "  ${DIM}  [ ] $title${NC}"
            fi
            echo -e "     ${DIM}• $desc1${NC}"
            [[ -n "$desc2" ]] && echo -e "     ${DIM}• $desc2${NC}"
            [[ -n "$desc3" ]] && echo -e "     ${DIM}• $desc3${NC}"
            [[ -n "$desc4" ]] && echo -e "     ${DIM}• $desc4${NC}"
            echo ""
        done
        
        echo -e "${DIM}→/ENTER to confirm selection, ←/b to go back${NC}"
        
        # Read key input
        read -rsn1 key 2>/dev/null
        local select_parse=false
        
        if [[ "$key" == $'\x1b' ]]; then
            read -rsn2 -t 1 key 2>/dev/null
            case "$key" in
                '[A'|'OA') # Up arrow - with wrap around
                    ((selected_idx--)) || true
                    [[ $selected_idx -lt 0 ]] && selected_idx=$((${#parse_opts[@]} - 1))
                    ;;
                '[B'|'OB') # Down arrow - with wrap around
                    ((selected_idx++)) || true
                    [[ $selected_idx -ge ${#parse_opts[@]} ]] && selected_idx=0
                    ;;
                '[C'|'OC') # Right arrow - select
                    select_parse=true
                    ;;
                '[D'|'OD') # Left arrow - go back
                    tput cnorm 2>/dev/null
                    return 1
                    ;;
            esac
        elif [[ "$key" == "b" || "$key" == "B" ]]; then
            # Back pressed
            tput cnorm 2>/dev/null
            return 1
        elif [[ "$key" == "" ]]; then
            # Enter - confirm selection
            select_parse=true
        fi
        
        if [[ "$select_parse" == "true" ]]; then
            IFS='|' read -r mode title _ <<< "${parse_opts[$selected_idx]}"
            
            # Save preference
            echo "$mode" > "$parse_mode_file"
            
            tput cnorm 2>/dev/null
            return 0
        fi
    done
}

