                    else
                        lang_code=""
                    fi
                fi
                
                # Parse filename sequentially to preserve original order of descriptors
                # This ensures "SDH.eng.HI.srt" becomes "episodename.sdh.eng.hi.srt" (correct order)
                # instead of "episodename.sdh.hi.eng.srt" (wrong: IF statement order)
                local -a ordered_parts=()
                local has_regional=false
                local regional_desc=""
                
                # First check for multi-word regional descriptors that span multiple parts
                # These must be detected before splitting by dots
                if [[ "$sub_basename_lower" =~ (latin[[:space:]._-]+american|latinoamericano|latam) ]]; then
                    regional_desc="latinamerican"
                    has_regional=true
                elif [[ "$sub_basename_lower" =~ (castilian|spain) ]]; then
                    regional_desc="spain"
                    has_regional=true
                elif [[ "$sub_basename_lower" =~ (mexican|mexico) ]]; then
                    regional_desc="mexican"
                    has_regional=true
                elif [[ "$sub_basename_lower" =~ (argentine|argentina) ]]; then
                    regional_desc="argentine"
                    has_regional=true
                elif [[ "$sub_basename_lower" =~ (brazilian|brazil) ]]; then
                    regional_desc="brazilian"
                    has_regional=true
                elif [[ "$sub_basename_lower" =~ (european.portuguese|portugal) ]]; then
                    regional_desc="european"
                    has_regional=true
                elif [[ "$sub_basename_lower" =~ (british|uk) ]]; then
                    regional_desc="british"
                    has_regional=true
                elif [[ "$sub_basename_lower" =~ ^(american|us)[^a-z] ]]; then
                    regional_desc="american"
                    has_regional=true
                elif [[ "$sub_basename_lower" =~ (australian|australia) ]]; then
                    regional_desc="australian"
                    has_regional=true
                elif [[ "$sub_basename_lower" =~ (canadian.english) ]]; then
                    regional_desc="canadian"
                    has_regional=true
                elif [[ "$sub_basename_lower" =~ (new.zealand) ]]; then
                    regional_desc="newzealand"
                    has_regional=true
                elif [[ "$sub_basename_lower" =~ (south.african) ]]; then
                    regional_desc="southafrican"
                    has_regional=true
                elif [[ "$sub_basename_lower" =~ (irish|ireland) ]]; then
                    regional_desc="irish"
                    has_regional=true
                elif [[ "$sub_basename_lower" =~ (canadian.french|quebec) ]]; then
                    regional_desc="canadian"
                    has_regional=true
                elif [[ "$sub_basename_lower" =~ (belgian.french) ]]; then
                    regional_desc="belgian"
                    has_regional=true
                elif [[ "$sub_basename_lower" =~ (swiss.french) ]]; then
                    regional_desc="swiss"
                    has_regional=true
                elif [[ "$sub_basename_lower" =~ (african.french) ]]; then
                    regional_desc="african"
