                fi
                
                # Add regional descriptor first if found
                if [[ "$has_regional" == true ]]; then
                    ordered_parts+=("$regional_desc")
                fi
                
                # Now parse filename parts in order, preserving original positions
                # For "sdh.eng.hi.srt" we want output "sdh.eng.hi.srt" (exact order preserved)
                if [[ -n "$name_without_ext" ]]; then
                    IFS='.' read -ra parts <<< "$name_without_ext"
                    for part in "${parts[@]}"; do
