                        elif [[ "$part" =~ ^(sdh)$ ]]; then
                            normalized_part="sdh"
                            is_descriptor=true
                        elif [[ "$part" =~ ^(hi)$ ]]; then
                            normalized_part="hi"
                            is_descriptor=true
                        elif [[ "$part" =~ ^(cc)$ ]]; then
                            normalized_part="cc"
                            is_descriptor=true
                        elif [[ "$part" =~ ^(commentary)$ ]]; then
                            normalized_part="commentary"
                            is_descriptor=true
