                        elif [[ "$part" =~ ^(simplified|simp)$ ]]; then
                            normalized_part="simplified"
                            is_descriptor=true
                        elif [[ "$part" =~ ^(traditional|trad)$ ]]; then
                            normalized_part="traditional"
                            is_descriptor=true
                        elif [[ "$part" =~ ^(cantonese)$ ]]; then
                            normalized_part="cantonese"
                            is_descriptor=true
                        fi
                        
                        # Add descriptor in its original position (after regional)
                        if [[ "$is_descriptor" == true ]]; then
                            ordered_parts+=("$normalized_part")
                        fi
