                # Add parenthetical descriptors that weren't detected via dot-parsing
                # Only add if not already present in ordered_parts
                local has_forced=false has_sdh=false has_hi=false has_cc=false
                for part in "${ordered_parts[@]}"; do
                    [[ "$part" == "forced" ]] && has_forced=true
                    [[ "$part" == "sdh" ]] && has_sdh=true
                    [[ "$part" == "hi" ]] && has_hi=true
                    [[ "$part" == "cc" ]] && has_cc=true
                done
                if [[ "$paren_forced" == true && "$has_forced" == false ]]; then
                    ordered_parts+=("forced")
                fi
                if [[ "$paren_sdh" == true && "$has_sdh" == false ]]; then
                    ordered_parts+=("sdh")
                fi
                if [[ "$paren_hi" == true && "$has_hi" == false ]]; then
