                    swa) lang_code_output="sw" ;;
                    xho) lang_code_output="xh" ;;
                    yor) lang_code_output="yo" ;;
                    zul) lang_code_output="zu" ;;
                    # Central Asian & Other
                    kaz) lang_code_output="kk" ;;
                    kir) lang_code_output="ky" ;;
                    mon) lang_code_output="mn" ;;
                    tgk) lang_code_output="tg" ;;
                    tuk) lang_code_output="tk" ;;
                    uig) lang_code_output="ug" ;;
                    uzb) lang_code_output="uz" ;;
                    # Latin American & Caribbean
                    que) lang_code_output="qu" ;;
                    grn) lang_code_output="gn" ;;
                    aym) lang_code_output="ay" ;;
                    hat) lang_code_output="ht" ;;
                    # Pacific languages
                    mao|mri) lang_code_output="mi" ;;
                    smo) lang_code_output="sm" ;;
                    ton) lang_code_output="to" ;;
                    fij) lang_code_output="fj" ;;
                    # Constructed/Special
                    epo) lang_code_output="eo" ;;
                    lat) lang_code_output="la" ;;
                esac
                
                # Build destination subtitle name: episodename.lang[.descriptor1][.descriptor2].ext
                local dest_subtitle_sub="${dest_file%.*}"
                
                # Build subtitle signature for duplicate tracking (lang + all descriptors)
                local sub_signature=""
                if [[ -n "$lang_code_output" ]]; then
                    sub_signature="${lang_code_output}"
                fi
                
                # Add language code first (2-letter format)
                if [[ -n "$lang_code_output" ]]; then
                    dest_subtitle_sub="${dest_subtitle_sub}.${lang_code_output}"
                fi
                
                # Add all descriptor parts after language
                for desc in "${ordered_parts[@]}"; do
                    # Skip the language code since we already added it
                    if [[ "$desc" != "$lang_code" && "$desc" != "$lang_code_output" ]]; then
                        dest_subtitle_sub="${dest_subtitle_sub}.${desc}"
                        sub_signature="${sub_signature}.${desc}"
                    fi
                done
                
                # Check if this exact subtitle signature has been used before (handle true duplicates)
                # Use full signature (lang + descriptors) so en.forced and en.sdh are different
                if [[ -n "$sub_signature" ]]; then
                    local lang_count=1
                    
                    while [[ "$used_subtitles" == *"|${sub_signature}:${lang_count}|"* ]]; do
                        ((lang_count++)) || true
                    done
                    
                    # Append counter if duplicate
                    if [[ $lang_count -gt 1 ]]; then
                        dest_subtitle_sub="${dest_subtitle_sub}.${lang_count}"
                    fi
                    
                    # Mark this signature as used
                    used_subtitles="${used_subtitles}|${sub_signature}:${lang_count}|"
                fi
                
                # Add extension
                dest_subtitle_sub="${dest_subtitle_sub}.${sub_ext}"
                
                if [[ -f "$dest_subtitle_sub" ]]; then
                    local source_inode=$(_stat_inode "$subtitle_subfile")
                    local dest_inode=$(_stat_inode "$dest_subtitle_sub")
                    
                    if [[ "$source_inode" != "$dest_inode" ]]; then
                        rm "$dest_subtitle_sub"
                        if $USE_COPY; then
                            cp "$subtitle_subfile" "$dest_subtitle_sub"
                        elif $USE_SYMLINK; then
                            ln -s "$subtitle_subfile" "$dest_subtitle_sub"
                        else
                            ln "$subtitle_subfile" "$dest_subtitle_sub" 2>/dev/null || cp "$subtitle_subfile" "$dest_subtitle_sub"
                        fi
                        ((subtitle_count++)) || true
                    fi
                else
                    if $USE_COPY; then
                        cp "$subtitle_subfile" "$dest_subtitle_sub"
                    elif $USE_SYMLINK; then
                        ln -s "$subtitle_subfile" "$dest_subtitle_sub"
                    else
                        ln "$subtitle_subfile" "$dest_subtitle_sub" 2>/dev/null || cp "$subtitle_subfile" "$dest_subtitle_sub"
                    fi
                    ((subtitle_count++)) || true
                fi
            done < <(find "$season_subs_dir" -type f \( -iname "*.srt" -o -iname "*.sub" -o -iname "*.idx" -o -iname "*.ass" -o -iname "*.ssa" \) -print0)
            else
                should_debug low && echo "[DEBUG] Skipping direct subtitle processing - episode subfolders found, will use episode-specific processing instead" >&2
            fi
        fi
        
        # Also check for episode-specific subtitle folders within the same-directory Subs folder
        # Handle structures like: same_dir/Subs/The.Show.S02E01.../2_English.srt  
        if [[ -n "$season_subs_dir" && -d "$season_subs_dir" ]]; then
            if [[ -n "$TV_SEASON" ]] && [[ -n "$TV_EPISODE" ]]; then
                # Track used language codes to handle duplicates (Bash 3.2 compatible)
                local used_languages=""
                local season_padded=$(printf "%02d" "$TV_SEASON")
                local episode_padded=$(printf "%02d" "$TV_EPISODE")
                
                should_debug low && echo "[DEBUG] Same-dir: Looking for episode folders matching S${season_padded}E${episode_padded} in: $season_subs_dir" >&2
                
                # Find folders containing this episode pattern within the Subs directory
                while IFS= read -r -d '' episode_subs_folder; do
                    # Extract season and episode from folder name for proper matching
                    local folder_basename=$(basename "$episode_subs_folder")
                    local folder_season="" folder_episode=""
                    if [[ "$folder_basename" =~ [Ss]([0-9]{1,2})[Ee]([0-9]{1,3}) ]]; then
                        # Remove leading zeros to avoid octal interpretation
                        folder_season=$((10#${BASH_REMATCH[1]}))
                        folder_episode=$((10#${BASH_REMATCH[2]}))
                        should_debug low && echo "[DEBUG] Same-dir: Regex match found - Raw: S${BASH_REMATCH[1]}E${BASH_REMATCH[2]}, Parsed: S${folder_season}E${folder_episode}" >&2
                    else
                        should_debug low && echo "[DEBUG] Same-dir: No S##E## pattern found in folder: '$folder_basename'" >&2
                    fi
                    
                    should_debug low && echo "[DEBUG] Same-dir: Subtitle folder check: '$folder_basename' -> S${folder_season}E${folder_episode}, Current: S${TV_SEASON}E${TV_EPISODE}" >&2
                    
                    # Only process if folder matches current episode being processed
                    if [[ "$folder_season" == "$TV_SEASON" && "$folder_episode" == "$TV_EPISODE" ]]; then
                        should_debug low && echo "[DEBUG] Same-dir: *** MATCH FOUND *** Processing subtitles from folder: $folder_basename" >&2
                        local folder_subtitle_count=0
                        while IFS= read -r -d '' sub_file; do
                            # Skip if already processed (Bash 3.2 compatible)
                            if [[ "$processed_subtitles" == *"|$sub_file|"* ]]; then
                                continue
                            fi
                            processed_subtitles="$processed_subtitles|$sub_file|"
                            
                            local sub_basename=$(basename "$sub_file")
                            local sub_ext="${sub_file##*.}"
                            
                            # Comprehensive subtitle parsing (same as movies)
                            local sub_basename_lower=$(echo "$sub_basename" | tr '[:upper:]' '[:lower:]')
                            local lang_code=""
                            
                            # Extract filename without extension for parsing
                            local name_without_ext=""
                            if [[ "$sub_basename_lower" =~ ^(.+)\.(srt|sub|idx|ass|ssa|vtt)$ ]]; then
                                name_without_ext="${BASH_REMATCH[1]}"
                            fi
                            
                            # Detect parenthetical descriptors like (Forced), (SDH), (HI), (CC)
                            local paren_forced=false paren_sdh=false paren_hi=false paren_cc=false
                            [[ "$sub_basename_lower" =~ \(forced\) ]] && paren_forced=true
                            [[ "$sub_basename_lower" =~ \(sdh\) ]] && paren_sdh=true
                            [[ "$sub_basename_lower" =~ \(hi\)|\(hearing[[:space:]]*impaired\) ]] && paren_hi=true
                            [[ "$sub_basename_lower" =~ \(cc\)|\(closed[[:space:]]*caption(s|ed)?\) ]] && paren_cc=true
                            
                            # Known descriptors
                            local known_descriptors="sdh|hi|cc|forced|commentary|full|non|foreign|parts|only|hearing|impaired|simplified|simp|traditional|trad|cantonese"
                            
                            # Split by dots and find language code
                            if [[ -n "$name_without_ext" ]]; then
                                IFS='.' read -ra parts <<< "$name_without_ext"
                                for part in "${parts[@]}"; do
                                    if [[ "$part" =~ ^[a-z]{2,4}(-[a-z]{2})?$ ]] && [[ ! "$part" =~ ^($known_descriptors)$ ]]; then
                                        lang_code="$part"
                                        break
                                    fi
                                done
                            fi
                            
                            # Fallback: try underscore pattern for short codes (2-4 letters)
                            if [[ -z "$lang_code" ]]; then
                                if [[ "$sub_basename_lower" =~ _([a-z]{2,4}(-[a-z]{2})?)\.(srt|sub|idx|ass|ssa|vtt)$ ]]; then
                                    local candidate="${BASH_REMATCH[1]}"
                                    [[ ! "$candidate" =~ ^($known_descriptors)$ ]] && lang_code="$candidate"
                                fi
                            fi
                            
                            # Fallback: try underscore pattern for full language names (e.g., 4_Chinese.srt, 5_Danish.srt)
                            # Comprehensive 85+ language mapping matching movie subtitle processing
                            if [[ -z "$lang_code" ]]; then
                                if [[ "$sub_basename_lower" =~ _([a-z]+)\.(srt|sub|idx|ass|ssa|vtt)$ ]]; then
                                    local lang_name="${BASH_REMATCH[1]}"
                                    # Map full language names to ISO 639-2 codes (will be converted to 2-letter later)
                                    case "$lang_name" in
