                                        tagalog|filipino) lang_code="tgl" ;;
                                        thai) lang_code="tha" ;;
                                        vietnamese) lang_code="vie" ;;
                                        # Indian languages
                                        assamese) lang_code="asm" ;;
                                        gujarati) lang_code="guj" ;;
                                        kannada) lang_code="kan" ;;
                                        malayalam) lang_code="mal" ;;
                                        marathi) lang_code="mar" ;;
                                        oriya) lang_code="ori" ;;
