                            local dest_subtitle_ep="${dest_file%.*}"
                            [[ -n "$lang_code_output" ]] && dest_subtitle_ep="${dest_subtitle_ep}.${lang_code_output}"
                            
                            # Add descriptors
                            for desc in "${ordered_parts[@]}"; do
