                            if [[ -n "$sub_signature" ]]; then
                                local lang_count=1
                                while [[ "$used_languages" == *"|${sub_signature}:${lang_count}|"* ]]; do
                                    ((lang_count++)) || true
                                done
                                [[ $lang_count -gt 1 ]] && dest_subtitle_ep="${dest_subtitle_ep}.${lang_count}"
                                used_languages="${used_languages}|${sub_signature}:${lang_count}|"
                            fi
                            
                            dest_subtitle_ep="${dest_subtitle_ep}.${sub_ext}"
                        
                        if [[ -f "$dest_subtitle_ep" ]]; then
                            local source_inode=$(_stat_inode "$sub_file")
                            local dest_inode=$(_stat_inode "$dest_subtitle_ep")
                            
                            if [[ "$source_inode" != "$dest_inode" ]]; then
                                rm "$dest_subtitle_ep"
                                if $USE_COPY; then
                                    cp "$sub_file" "$dest_subtitle_ep"
                                elif $USE_SYMLINK; then
