                                        slovenian) lang_code="slv" ;;
                                        swedish) lang_code="swe" ;;
                                        ukrainian) lang_code="ukr" ;;
                                        welsh) lang_code="wel" ;;
                                        # Asian languages
                                        burmese) lang_code="bur" ;;
                                        khmer|cambodian) lang_code="khm" ;;
                                        indonesian) lang_code="ind" ;;
                                        korean) lang_code="kor" ;;
                                        lao) lang_code="lao" ;;
                                        malay) lang_code="may" ;;
                                        nepali) lang_code="nep" ;;
                                        tagalog|filipino) lang_code="tgl" ;;
                                        thai) lang_code="tha" ;;
                                        vietnamese) lang_code="vie" ;;
                                        # Indian languages
                                        assamese) lang_code="asm" ;;
                                        gujarati) lang_code="guj" ;;
                                        kannada) lang_code="kan" ;;
                                        malayalam) lang_code="mal" ;;
                                        marathi) lang_code="mar" ;;
                                        oriya) lang_code="ori" ;;
                                        punjabi) lang_code="pan" ;;
                                        sanskrit) lang_code="san" ;;
