                                        hebrew) lang_code="heb" ;;
                                        kurdish) lang_code="kur" ;;
                                        pashto) lang_code="pus" ;;
                                        turkish) lang_code="tur" ;;
                                        # African languages
                                        afrikaans) lang_code="afr" ;;
                                        amharic) lang_code="amh" ;;
                                        hausa) lang_code="hau" ;;
                                        igbo) lang_code="ibo" ;;
                                        kinyarwanda) lang_code="kin" ;;
                                        malagasy) lang_code="mlg" ;;
                                        somali) lang_code="som" ;;
                                        swahili) lang_code="swa" ;;
                                        xhosa) lang_code="xho" ;;
                                        yoruba) lang_code="yor" ;;
                                        zulu) lang_code="zul" ;;
                                        # Central Asian & Other
                                        kazakh) lang_code="kaz" ;;
                                        kyrgyz) lang_code="kir" ;;
                                        mongolian) lang_code="mon" ;;
                                        tajik) lang_code="tgk" ;;
                                        turkmen) lang_code="tuk" ;;
                                        uyghur) lang_code="uig" ;;
                                        uzbek) lang_code="uzb" ;;
                                        # Latin American & Caribbean
                                        quechua) lang_code="que" ;;
                                        guarani) lang_code="grn" ;;
                                        aymara) lang_code="aym" ;;
                                        haitian) lang_code="hat" ;;
                                        # Pacific languages
                                        maori) lang_code="mao" ;;
                                        samoan) lang_code="smo" ;;
                                        tongan) lang_code="ton" ;;
                                        fijian) lang_code="fij" ;;
                                        # Constructed/Special
                                        esperanto) lang_code="epo" ;;
                                        latin) lang_code="lat" ;;
                                    esac
                                fi
                            fi
                            
                            # Fallback: check full language names at start of filename
                            if [[ -z "$lang_code" ]]; then
                                if [[ "$sub_basename_lower" =~ ^(english|eng)[._-] ]]; then lang_code="eng"
                                elif [[ "$sub_basename_lower" =~ ^(spanish|spa|esp)[._-] ]]; then lang_code="spa"
                                elif [[ "$sub_basename_lower" =~ ^(french|fre|fra)[._-] ]]; then lang_code="fre"
                                elif [[ "$sub_basename_lower" =~ ^(german|ger|deu)[._-] ]]; then lang_code="ger"
                                elif [[ "$sub_basename_lower" =~ ^(italian|ita)[._-] ]]; then lang_code="ita"
                                elif [[ "$sub_basename_lower" =~ ^(portuguese|por)[._-] ]]; then lang_code="por"
                                elif [[ "$sub_basename_lower" =~ ^(dutch|dut|nld)[._-] ]]; then lang_code="dut"
                                elif [[ "$sub_basename_lower" =~ ^(russian|rus)[._-] ]]; then lang_code="rus"
                                elif [[ "$sub_basename_lower" =~ ^(chinese|chi|zho)[._-] ]]; then lang_code="chi"
                                elif [[ "$sub_basename_lower" =~ ^(japanese|jpn)[._-] ]]; then lang_code="jpn"
                                elif [[ "$sub_basename_lower" =~ ^(korean|kor)[._-] ]]; then lang_code="kor"
                                elif [[ "$sub_basename_lower" =~ ^(arabic|ara)[._-] ]]; then lang_code="ara"
                                fi
                            fi
                            
                            # Parse descriptor parts in order
                            local -a ordered_parts=()
                            if [[ -n "$name_without_ext" ]]; then
                                IFS='.' read -ra parts <<< "$name_without_ext"
                                for part in "${parts[@]}"; do
                                    case "$part" in
                                        forced) ordered_parts+=("forced") ;;
                                        sdh) ordered_parts+=("sdh") ;;
                                        hi) ordered_parts+=("hi") ;;
                                        cc) ordered_parts+=("cc") ;;
                                        commentary) ordered_parts+=("commentary") ;;
                                    esac
                                done
                            fi
                            
                            # Add parenthetical descriptors if not already present
                            local has_forced=false has_sdh=false has_hi=false has_cc=false
                            for part in "${ordered_parts[@]}"; do
                                [[ "$part" == "forced" ]] && has_forced=true
                                [[ "$part" == "sdh" ]] && has_sdh=true
                                [[ "$part" == "hi" ]] && has_hi=true
                                [[ "$part" == "cc" ]] && has_cc=true
                            done
                            [[ "$paren_forced" == true && "$has_forced" == false ]] && ordered_parts+=("forced")
                            [[ "$paren_sdh" == true && "$has_sdh" == false ]] && ordered_parts+=("sdh")
                            [[ "$paren_hi" == true && "$has_hi" == false ]] && ordered_parts+=("hi")
                            [[ "$paren_cc" == true && "$has_cc" == false ]] && ordered_parts+=("cc")
                            
                            # Convert 3-letter language codes to 2-letter ISO 639-1 codes for output
                            # Matches all 85+ languages from the audio language normalizer
                            local lang_code_output="$lang_code"
                            case "$lang_code" in
                                # Major world languages
