                                # Asian languages
                                bur|mya) lang_code_output="my" ;;
                                khm) lang_code_output="km" ;;
                                ind) lang_code_output="id" ;;
                                kor) lang_code_output="ko" ;;
                                lao) lang_code_output="lo" ;;
                                may|msa) lang_code_output="ms" ;;
                                nep) lang_code_output="ne" ;;
                                tgl|fil) lang_code_output="tl" ;;
                                tha) lang_code_output="th" ;;
                                vie) lang_code_output="vi" ;;
                                # Indian languages
                                asm) lang_code_output="as" ;;
                                guj) lang_code_output="gu" ;;
                                kan) lang_code_output="kn" ;;
                                mal) lang_code_output="ml" ;;
                                mar) lang_code_output="mr" ;;
