                                sin) lang_code_output="si" ;;
                                tam) lang_code_output="ta" ;;
                                tel) lang_code_output="te" ;;
                                urd) lang_code_output="ur" ;;
                                # Middle Eastern languages
                                aze) lang_code_output="az" ;;
                                fas|per) lang_code_output="fa" ;;
                                heb) lang_code_output="he" ;;
                                kur) lang_code_output="ku" ;;
                                pus) lang_code_output="ps" ;;
                                tur) lang_code_output="tr" ;;
                                # African languages
                                afr) lang_code_output="af" ;;
                                amh) lang_code_output="am" ;;
                                hau) lang_code_output="ha" ;;
                                ibo) lang_code_output="ig" ;;
                                kin) lang_code_output="rw" ;;
                                mlg) lang_code_output="mg" ;;
                                som) lang_code_output="so" ;;
                                swa) lang_code_output="sw" ;;
