                            esac
                            
                            # Build subtitle signature for duplicate tracking
                            local sub_signature=""
                            [[ -n "$lang_code_output" ]] && sub_signature="${lang_code_output}"
                            
                            # Build destination filename
                            local dest_subtitle_ep="${dest_file%.*}"
                            [[ -n "$lang_code_output" ]] && dest_subtitle_ep="${dest_subtitle_ep}.${lang_code_output}"
                            
                            # Add descriptors
                            for desc in "${ordered_parts[@]}"; do
                                if [[ "$desc" != "$lang_code" && "$desc" != "$lang_code_output" ]]; then
                                    dest_subtitle_ep="${dest_subtitle_ep}.${desc}"
                                    sub_signature="${sub_signature}.${desc}"
                                fi
                            done
                            
                            # Check for duplicates using full signature
                            if [[ -n "$sub_signature" ]]; then
                                local lang_count=1
                                while [[ "$used_languages_parent" == *"|${sub_signature}:${lang_count}|"* ]]; do
                                    ((lang_count++)) || true
                                done
                                [[ $lang_count -gt 1 ]] && dest_subtitle_ep="${dest_subtitle_ep}.${lang_count}"
                                used_languages_parent="${used_languages_parent}|${sub_signature}:${lang_count}|"
                            fi
                            
                            dest_subtitle_ep="${dest_subtitle_ep}.${sub_ext}"
                        
                        if [[ -f "$dest_subtitle_ep" ]]; then
                            local source_inode=$(_stat_inode "$sub_file")
                            local dest_inode=$(_stat_inode "$dest_subtitle_ep")
                            
                            if [[ "$source_inode" != "$dest_inode" ]]; then
                                rm "$dest_subtitle_ep"
                                if $USE_COPY; then
                                    cp "$sub_file" "$dest_subtitle_ep"
                                elif $USE_SYMLINK; then
                                    ln -s "$sub_file" "$dest_subtitle_ep"
                                else
                                    ln "$sub_file" "$dest_subtitle_ep" 2>/dev/null || cp "$sub_file" "$dest_subtitle_ep"
                                fi
                                ((subtitle_count++)) || true
                            fi
                        else
                            if $USE_COPY; then
                                cp "$sub_file" "$dest_subtitle_ep"
                            elif $USE_SYMLINK; then
                                ln -s "$sub_file" "$dest_subtitle_ep"
                            else
                                ln "$sub_file" "$dest_subtitle_ep" 2>/dev/null || cp "$sub_file" "$dest_subtitle_ep"
                            fi
                            ((subtitle_count++)) || true
                            ((folder_subtitle_count++)) || true
                        fi
                    done < <(find "$episode_subs_folder" -type f \( -iname "*.srt" -o -iname "*.sub" -o -iname "*.idx" -o -iname "*.ass" -o -iname "*.ssa" \) -print0)
                    should_debug low && echo "[DEBUG] Parent-dir: Processed $folder_subtitle_count subtitles from folder: $folder_basename" >&2
                    else
