                        # Process subtitle files in this language folder
                        # For Subs-{Language} folders, subtitles are often just numbered (1.srt, 2.srt, etc.)
                        # Match by episode number in filename if present, otherwise match by file order
                        while IFS= read -r -d '' sub_file; do
                            # Skip if already processed
                            if [[ "$processed_subtitles" == *"|$sub_file|"* ]]; then
                                continue
                            fi
                            processed_subtitles="$processed_subtitles|$sub_file|"
                            
                            local sub_basename=$(basename "$sub_file")
                            local matches_episode=0
                            
