                            if [[ "$sub_basename" =~ [Ss]0*([0-9]+)[Ee]0*([0-9]+) ]]; then
                                # Has S##E## pattern - compare episode numbers
                                local sub_season_int=$((10#${BASH_REMATCH[1]}))
                                local sub_episode_int=$((10#${BASH_REMATCH[2]}))
                                local tv_season_int=$((10#$TV_SEASON))
                                local tv_episode_int=$((10#$TV_EPISODE))
                                
                                if [[ "$sub_season_int" == "$tv_season_int" ]] && [[ "$sub_episode_int" == "$tv_episode_int" ]]; then
                                    matches_episode=1
                                    should_debug low && echo "[DEBUG] Subs-Lang: Pattern match S${sub_season_int}E${sub_episode_int} == S${tv_season_int}E${tv_episode_int}: $sub_basename" >&2
                                else
                                    should_debug low && echo "[DEBUG] Subs-Lang: Pattern mismatch S${sub_season_int}E${sub_episode_int} != S${tv_season_int}E${tv_episode_int}: $sub_basename" >&2
                                    continue
                                fi
