                                local sub_number=$((10#${BASH_REMATCH[1]}))
                                if [[ "$sub_number" == "$((10#$TV_EPISODE))" ]]; then
                                    matches_episode=1
                                    should_debug low && echo "[DEBUG] Subs-Lang: Number match $sub_number == $TV_EPISODE: $sub_basename" >&2
                                else
