                            if (( $(echo "$API_DELAY < 0.10" | bc -l) )); then
                                new_delay=$(echo "$API_DELAY + 0.01" | bc)
                            elif (( $(echo "$API_DELAY < 2.0" | bc -l) )); then
                                new_delay=$(echo "$API_DELAY + 0.1" | bc)
                            else
                                new_delay=$(echo "$API_DELAY + 0.5" | bc)
                            fi
                            # Cap at 5.0
                            if (( $(echo "$new_delay > 5.0" | bc -l) )); then
                                new_delay="5.0"
                            fi
                        else
                            # Determine increment based on current value
                            if (( $(awk "BEGIN {print ($API_DELAY < 0.10)}") )); then
                                new_delay=$(awk "BEGIN {print $API_DELAY + 0.01}")
                            elif (( $(awk "BEGIN {print ($API_DELAY < 2.0)}") )); then
                                new_delay=$(awk "BEGIN {print $API_DELAY + 0.1}")
                            else
