                    # If on API Delay (index 17), decrease by 0.01 (at/below 0.10), 0.1 (below/at 2.0), or 0.5 (above 2.0)
                    elif [[ $selected_idx -eq 17 ]]; then
                        [[ -f "${CACHE_DIR}/api_delay.txt" ]] && API_DELAY=$(cat "${CACHE_DIR}/api_delay.txt")
                        local new_delay
                        if command -v bc &> /dev/null; then
                            # Determine decrement based on current value
                            if (( $(echo "$API_DELAY <= 0.10" | bc -l) )); then
                                new_delay=$(echo "$API_DELAY - 0.01" | bc)
