                        echo "$AWK_PARSER" > "${CACHE_DIR}/awk_parser.txt"
                    # If on Extension Duplicate Mode (index 19), cycle backward
                    elif [[ $selected_idx -eq 19 ]]; then
                        [[ -f "${CACHE_DIR}/extension_dup_mode.txt" ]] && EXTENSION_DUP_MODE=$(cat "${CACHE_DIR}/extension_dup_mode.txt") || EXTENSION_DUP_MODE="off"
                        case "$EXTENSION_DUP_MODE" in
                            off) EXTENSION_DUP_MODE="bitrate" ;;
                            bitrate) EXTENSION_DUP_MODE="resolution" ;;
                            resolution) EXTENSION_DUP_MODE="off" ;;
                            *) EXTENSION_DUP_MODE="off" ;;
                        esac
                        echo "$EXTENSION_DUP_MODE" > "${CACHE_DIR}/extension_dup_mode.txt"
                    # If on TV Extension Duplicate Mode (index 20), cycle backward
                    elif [[ $selected_idx -eq 20 ]]; then
                        [[ -f "${CACHE_DIR}/tv_extension_dup_mode.txt" ]] && TV_EXTENSION_DUP_MODE=$(cat "${CACHE_DIR}/tv_extension_dup_mode.txt") || TV_EXTENSION_DUP_MODE="off"
                        case "$TV_EXTENSION_DUP_MODE" in
                            off) TV_EXTENSION_DUP_MODE="bitrate" ;;
                            bitrate) TV_EXTENSION_DUP_MODE="resolution" ;;
                            resolution) TV_EXTENSION_DUP_MODE="off" ;;
                            *) TV_EXTENSION_DUP_MODE="off" ;;
                        esac
                        echo "$TV_EXTENSION_DUP_MODE" > "${CACHE_DIR}/tv_extension_dup_mode.txt"
                    # If on Image Resizer (index 21), cycle backward
                    elif [[ $selected_idx -eq 21 ]]; then
                        [[ -f "${CACHE_DIR}/image_resizer.txt" ]] && IMAGE_RESIZER=$(cat "${CACHE_DIR}/image_resizer.txt") || IMAGE_RESIZER="auto"
                        # Backward: auto → vips → sips → auto
                        case "$IMAGE_RESIZER" in
                            auto) IMAGE_RESIZER="vips" ;;
                            vips) IMAGE_RESIZER="sips" ;;
                            sips) IMAGE_RESIZER="auto" ;;
                            *) IMAGE_RESIZER="auto" ;;
                        esac
                        echo "$IMAGE_RESIZER" > "${CACHE_DIR}/image_resizer.txt"
                    # If on Round Resolution (index 25), toggle
                    elif [[ $selected_idx -eq 25 ]]; then
                        if [[ "$ROUND_RESOLUTION" == "yes" ]]; then
                            ROUND_RESOLUTION="no"
                        else
                            ROUND_RESOLUTION="yes"
                        fi
                        echo "$ROUND_RESOLUTION" > "${CACHE_DIR}/round_resolution.txt"
                    fi
                    ;;
                *) # ESC pressed (no arrow key) - treat as back/exit
                    tput cnorm 2>/dev/null
                    stty echo 2>/dev/null
                    clear
                    echo ""
                    echo -e "${YELLOW}Are you sure you want to exit? (y/n)${NC}"
                    read -r confirm_exit
                    if [[ "$confirm_exit" =~ ^[Yy]$ ]]; then
                        print_warning "Cancelled"
                        exit 0
                    fi
                    stty -echo 2>/dev/null
                    tput civis 2>/dev/null
                    ;;
            esac
        elif [[ "$key" == "b" ]] || [[ "$key" == "B" ]]; then
            # Go back to dependency check
            tput cnorm 2>/dev/null
            clear
            check_and_install_dependencies
            # After returning from dependency check, continue with menu
            continue
        elif [[ "$key" == "d" ]] || [[ "$key" == "D" ]]; then
            # Alternative dependency key (same as 'b')
            tput cnorm 2>/dev/null
            clear
            check_and_install_dependencies
            # After returning from dependency check, continue with menu
            continue
        fi
        
        # Handle Enter key or right arrow selection (for indices 0-3)
        if [[ "$key" == "" ]] || [[ "$select_mode" == "true" ]]; then
            # Enter or right arrow - confirm selection
            tput cnorm 2>/dev/null
            clear
            
            if [[ $selected_idx -eq 0 ]]; then
                # Quick Movies - use saved settings, skip to cache selection
                tput civis 2>/dev/null
                
                # Check if required saved settings exist
                if [[ ! -f "${CACHE_DIR}/naming_scheme.txt" ]] || [[ ! -f "${CACHE_DIR}/link_type.txt" ]]; then
                    tput cnorm 2>/dev/null
                    echo ""
                    print_warning "No saved settings found!"
                    echo -e "${YELLOW}Quick Movies requires previously saved settings.${NC}"
                    echo -e "${CYAN}Please use 'Movies (Movie)' option first to configure your preferences.${NC}"
                    echo ""
                    echo -e "${DIM}Press any key to return to main menu...${NC}"
                    read -n 1 -s
                    continue
                fi
                
                # Load all saved settings from cache
                [[ -f "${CACHE_DIR}/naming_scheme.txt" ]] && NAMING_SCHEME=$(cat "${CACHE_DIR}/naming_scheme.txt")
                [[ -f "${CACHE_DIR}/link_type.txt" ]] && LINK_TYPE=$(cat "${CACHE_DIR}/link_type.txt")
                [[ -f "${CACHE_DIR}/extras_option.txt" ]] && EXTRAS_OPTION=$(cat "${CACHE_DIR}/extras_option.txt")
                [[ -f "${CACHE_DIR}/parallel_parsing.txt" ]] && PARALLEL_PARSING=$(cat "${CACHE_DIR}/parallel_parsing.txt")
                [[ -f "${CACHE_DIR}/parallel_processing.txt" ]] && PARALLEL_PROCESSING=$(cat "${CACHE_DIR}/parallel_processing.txt")
                [[ -f "${CACHE_DIR}/use_mediainfo.txt" ]] && USE_MEDIAINFO=$(cat "${CACHE_DIR}/use_mediainfo.txt")
                
                # Parse naming scheme to extract folder and file format choices
                if [[ -f "${CACHE_DIR}/naming_scheme.txt" ]]; then
                    NAMING_FOLDER=$(sed -n '1p' "${CACHE_DIR}/naming_scheme.txt")
                    NAMING_FILE=$(sed -n '2p' "${CACHE_DIR}/naming_scheme.txt")
                fi
                
                # Load poster preference
                [[ -f "${CACHE_DIR}/poster_preference.txt" ]] && SHOW_MOVIE_POSTERS=$(cat "${CACHE_DIR}/poster_preference.txt")
                
                # Load link mode settings (copy/hardlink/symlink modes)
                if [[ -f "${CACHE_DIR}/copy_mode.txt" ]]; then
                    local copy_mode=$(cat "${CACHE_DIR}/copy_mode.txt")
                    [[ "$copy_mode" == "true" ]] && COPY_ENTIRE_FOLDER="true" || COPY_ENTIRE_FOLDER="false"
                fi
                if [[ -f "${CACHE_DIR}/extras_mode.txt" ]]; then
                    HARDLINK_EXTRAS=$(cat "${CACHE_DIR}/extras_mode.txt")
                fi
                
                # Load parsing method (AWK parser preference)
                [[ -f "${CACHE_DIR}/awk_parser.txt" ]] && AWK_PARSER=$(cat "${CACHE_DIR}/awk_parser.txt")
                
                # Set link type flags based on saved preference
                case "$LINK_TYPE" in
                    hardlink)
                        USE_HARDLINK="true"
                        USE_SYMLINK="false"
                        USE_COPY="false"
                        ;;
                    symlink)
                        USE_HARDLINK="false"
                        USE_SYMLINK="true"
                        USE_COPY="false"
                        ;;
                    copy)
                        USE_HARDLINK="false"
                        USE_SYMLINK="false"
                        USE_COPY="true"
                        ;;
                esac
                
                # Show movie cache selection (includes folder/file naming, mediainfo, profile)
                if select_movie_cache_interactive; then
                    # All selections done, proceed to source input
                    break
                else
                    # User backed out, return to main menu
                    continue
                fi
            elif [[ $selected_idx -eq 1 ]]; then
                # Quick TV Shows - use saved settings, skip to cache selection  
                tput civis 2>/dev/null
                
                # Check if required saved TV settings exist
                if [[ ! -f "${CACHE_DIR}/tv_naming_scheme.txt" ]]; then
                    tput cnorm 2>/dev/null
                    stty echo 2>/dev/null
                    echo ""
                    print_warning "No saved TV settings found!"
                    echo -e "${YELLOW}Quick TV Shows requires previously saved settings.${NC}"
                    echo -e "${CYAN}Please use 'TV Shows (Series)' option first to configure your preferences.${NC}"
                    echo ""
                    echo -e "${DIM}Press any key to return to main menu...${NC}"
                    read -n 1 -s
                    stty -echo 2>/dev/null
                    continue
                fi
                
                # Set TV mode flag
                IS_TV_MODE=true
                
                # Load all saved TV settings from cache
                [[ -f "${CACHE_DIR}/tv_naming_scheme.txt" ]] && TV_NAMING_SCHEME=$(cat "${CACHE_DIR}/tv_naming_scheme.txt")
                [[ -f "${CACHE_DIR}/tv_link_type.txt" ]] && TV_LINK_TYPE=$(cat "${CACHE_DIR}/tv_link_type.txt")
                [[ -f "${CACHE_DIR}/tv_extras_option.txt" ]] && TV_EXTRAS_OPTION=$(cat "${CACHE_DIR}/tv_extras_option.txt")
                [[ -f "${CACHE_DIR}/parallel_parsing.txt" ]] && PARALLEL_PARSING=$(cat "${CACHE_DIR}/parallel_parsing.txt")
                [[ -f "${CACHE_DIR}/parallel_processing.txt" ]] && PARALLEL_PROCESSING=$(cat "${CACHE_DIR}/parallel_processing.txt")
                [[ -f "${CACHE_DIR}/use_mediainfo.txt" ]] && USE_MEDIAINFO=$(cat "${CACHE_DIR}/use_mediainfo.txt")
                
                # Source TV naming scheme to load TV_NAMING_FOLDER and TV_NAMING_EPISODE variables
                if [[ -f "${CACHE_DIR}/tv_naming_scheme.txt" ]]; then
                    source "${CACHE_DIR}/tv_naming_scheme.txt"
                fi
                
                # Load poster preference
                [[ -f "${CACHE_DIR}/tv_poster_preference.txt" ]] && SHOW_TV_POSTERS=$(cat "${CACHE_DIR}/tv_poster_preference.txt")
                
                # Load TV episode renaming preference
                [[ -f "${CACHE_DIR}/tv_rename_episodes.txt" ]] && TV_RENAME_EPISODES=$(cat "${CACHE_DIR}/tv_rename_episodes.txt")
                
                # Load TV link mode settings
                if [[ -f "${CACHE_DIR}/tv_extras_mode.txt" ]]; then
                    TV_EXTRAS_HANDLING=$(cat "${CACHE_DIR}/tv_extras_mode.txt")
                fi
                
                # Load parsing method (AWK parser preference)
                [[ -f "${CACHE_DIR}/awk_parser.txt" ]] && AWK_PARSER=$(cat "${CACHE_DIR}/awk_parser.txt")
                
                # Set link type flags based on saved TV preference
                case "$TV_LINK_TYPE" in
                    hardlink)
                        USE_HARDLINK="true"
                        USE_SYMLINK="false"
                        USE_COPY="false"
                        ;;
                    symlink)
                        USE_HARDLINK="false"
                        USE_SYMLINK="true"
                        USE_COPY="false"
                        ;;
                    copy)
                        USE_HARDLINK="false"
                        USE_SYMLINK="false"
                        USE_COPY="true"
                        ;;
                esac
                
                # Show TV cache selection (includes folder/episode naming, mediainfo, profile)
                if select_tv_cache_interactive; then
                    # All selections done, run TV mode
                    tput civis 2>/dev/null
                    if interactive_tv_mode "true"; then
                        exit 0
                    fi
                    # TV mode was cancelled, return to main menu
                fi
                continue
            elif [[ $selected_idx -eq 2 ]]; then
                # Movie mode - continue with movie flow
                tput civis 2>/dev/null
                # Menu navigation loop for movies
                local movie_setup_done=false
                local current_menu="naming"
                local naming_start_step=1  # Track which step to start naming scheme at
                
                while true; do
                    case "$current_menu" in
                        naming)
                            # Select naming scheme (start at specified step)
                            if ! select_naming_scheme "$naming_start_step"; then
                                # User backed out from naming scheme, return to main menu
                                movie_setup_done=false
                                break
                            fi
                            naming_start_step=1  # Reset for next iteration
                            current_menu="link_type"
                            ;;
                        
                        link_type)
                            # Select link type
                            if ! select_link_type; then
                                # User backed out, go back to naming scheme at step 4 (cache - last step)
                                naming_start_step=4
                                current_menu="naming"
                            else
                                current_menu="mode"
                            fi
                            ;;
                        
                        mode)
                            # Show mode-specific menus based on link type
                            local mode_result=true
                            if [[ "$USE_COPY" == "true" ]]; then
                                # Copy mode menu
                                if ! select_copy_mode; then
                                    mode_result=false
                                fi
                            elif [[ "$USE_SYMLINK" == "true" ]]; then
                                # Symlink mode menu
                                if ! select_symlink_mode; then
                                    mode_result=false
                                fi
                            else
                                # Hardlink mode menu (default)
                                if ! select_hardlink_mode; then
                                    mode_result=false
                                fi
                            fi
                            
                            if [[ "$mode_result" == "false" ]]; then
                                # User backed out, go back to link type
                                current_menu="link_type"
                            else
                                # Hardlink/Symlink modes already set extras preferences, skip extras menu
                                # Copy mode with entire folder also skips extras menu
                                if [[ "$USE_COPY" == "true" ]] && [[ "$COPY_ENTIRE_FOLDER" != "true" ]]; then
                                    # Copy mode with individual files - show extras menu
                                    current_menu="extras"
                                else
                                    # Hardlink/Symlink modes or Copy entire folder - skip extras menu
                                    current_menu="parsing"
                                fi
                            fi
                            ;;
                        
                        extras)
                            # Select extras/bonus options (only for copy mode with individual files)
                            if ! select_extras_options; then
                                # User backed out, go back to the mode menu
                                current_menu="mode"
                            else
                                current_menu="parsing"
                            fi
                            ;;
                        
                        parsing)
                            # Select parsing mode
                            if ! select_parsing_mode; then
                                # User backed out, check if extras menu was shown
                                if [[ "$USE_COPY" == "true" ]] && [[ "$COPY_ENTIRE_FOLDER" != "true" ]]; then
                                    # Copy mode showed extras menu, go back to it
                                    current_menu="extras"
                                else
                                    # Extras was skipped, go back to mode menu
                                    current_menu="mode"
                                fi
                            else
                                current_menu="mediainfo"
                            fi
                            ;;
                        
                        mediainfo)
                            # Select MediaInfo tool
                            if select_mediainfo_tool; then
                                current_menu="profile"
                            else
                                # User backed out, go back to parsing mode
                                current_menu="parsing"
                            fi
                            ;;
                        
                        profile)
                            # Select source/dest profile
                            stty echo 2>/dev/null
                            PROFILE_MODE=""
                            if select_source_dest_profile "movie"; then
                                movie_setup_done=true
                                break
                            else
                                stty -echo 2>/dev/null
                                tput civis 2>/dev/null
                                current_menu="mediainfo"
                            fi
                            ;;
                    esac
                done
                
                # Check if movie setup was completed or user backed out
                if [[ "$movie_setup_done" != "true" ]]; then
                    # User backed out to main menu, continue mode selection loop
                    continue
                fi
                
                # Movie setup completed, proceed to file processing
                break
            elif [[ $selected_idx -eq 3 ]]; then
                # TV Show mode - run TV interactive mode
                tput civis 2>/dev/null
                if interactive_tv_mode; then
                    # TV mode completed successfully, exit
                    exit 0
                fi
                # TV mode was cancelled (user pressed back), return to mode selection
                # Loop will restart and show mode selection again
            elif [[ $selected_idx -eq 4 ]]; then
                # Stop Media Servers - instant toggle without screen change
                [[ -f "${CACHE_DIR}/stop_media_servers.txt" ]] && STOP_MEDIA_SERVERS=$(cat "${CACHE_DIR}/stop_media_servers.txt")
                if [[ "$STOP_MEDIA_SERVERS" == "true" ]]; then
                    STOP_MEDIA_SERVERS="false"
                    echo "false" > "${CACHE_DIR}/stop_media_servers.txt"
                else
                    STOP_MEDIA_SERVERS="true"
                    echo "true" > "${CACHE_DIR}/stop_media_servers.txt"
                fi
                # Menu will refresh automatically on next loop iteration
            elif [[ $selected_idx -eq 5 ]]; then
                # Parallel Processing - instant toggle without screen change
                # Load current setting
                [[ -f "${CACHE_DIR}/parallel_processing.txt" ]] && PARALLEL_PROCESSING=$(cat "${CACHE_DIR}/parallel_processing.txt")
                # Toggle
                if [[ "$PARALLEL_PROCESSING" == "true" ]]; then
                    PARALLEL_PROCESSING="false"
                    echo "false" > "${CACHE_DIR}/parallel_processing.txt"
                else
                    PARALLEL_PROCESSING="true"
                    echo "true" > "${CACHE_DIR}/parallel_processing.txt"
                fi
                # Menu will refresh automatically on next loop iteration
            elif [[ $selected_idx -eq 6 ]]; then
                # Parallel Jobs Count
                tput cnorm 2>/dev/null
                clear
                echo ""
                echo -e "${CYAN}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
                echo -e "${CYAN}Set Parallel Jobs Count${NC}"
                echo -e "${CYAN}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
                echo ""
                [[ -f "${CACHE_DIR}/parallel_jobs.txt" ]] && PARALLEL_JOBS=$(cat "${CACHE_DIR}/parallel_jobs.txt")
                echo -e "${DIM}Current: ${PARALLEL_JOBS} jobs${NC}"
                echo ""
                echo -e "${YELLOW}Enter number of parallel jobs (minimum: 2, recommended: 4-16):${NC}"
                stty echo
                read -r input_jobs
                stty -echo
                
                if [[ "$input_jobs" =~ ^[0-9]+$ ]] && [[ $input_jobs -ge 2 ]]; then
                    PARALLEL_JOBS=$input_jobs
                    echo "$PARALLEL_JOBS" > "${CACHE_DIR}/parallel_jobs.txt"
                    echo ""
                    if [[ $input_jobs -gt 64 ]]; then
                        echo -e "${YELLOW}⚠ Warning: ${input_jobs} jobs may consume significant system resources${NC}"
                    fi
                    echo -e "${GREEN}✓ Parallel jobs set to: ${PARALLEL_JOBS}${NC}"
                else
                    echo ""
                    echo -e "${RED}✗ Invalid input. Must be 2 or greater.${NC}"
                fi
                echo ""
                echo -e "${DIM}Press any key to continue...${NC}"
                read -rsn1
                tput civis 2>/dev/null
            elif [[ $selected_idx -eq 7 ]]; then
                # Rolling Queue Mode - instant toggle
                [[ -f "${CACHE_DIR}/rolling_queue_mode.txt" ]] && ROLLING_QUEUE_MODE=$(cat "${CACHE_DIR}/rolling_queue_mode.txt")
                if [[ "$ROLLING_QUEUE_MODE" == "true" ]]; then
                    ROLLING_QUEUE_MODE="false"
                    echo "false" > "${CACHE_DIR}/rolling_queue_mode.txt"
                else
                    ROLLING_QUEUE_MODE="true"
                    echo "true" > "${CACHE_DIR}/rolling_queue_mode.txt"
                fi
                # Menu will refresh automatically
            elif [[ $selected_idx -eq 8 ]]; then
                # Parallel Parsing - instant toggle
                [[ -f "${CACHE_DIR}/parallel_parsing.txt" ]] && PARALLEL_PARSING=$(cat "${CACHE_DIR}/parallel_parsing.txt")
                if [[ "$PARALLEL_PARSING" == "true" ]]; then
                    PARALLEL_PARSING="false"
                    echo "false" > "${CACHE_DIR}/parallel_parsing.txt"
                else
                    PARALLEL_PARSING="true"
                    echo "true" > "${CACHE_DIR}/parallel_parsing.txt"
                fi
                # Menu will refresh automatically
            elif [[ $selected_idx -eq 9 ]]; then
                # Parallel Parse Jobs Count
                tput cnorm 2>/dev/null
                clear
                echo ""
                echo -e "${CYAN}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
                echo -e "${CYAN}Set Parallel Parse Jobs Count${NC}"
                echo -e "${CYAN}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
                echo ""
                [[ -f "${CACHE_DIR}/parallel_parse_jobs.txt" ]] && PARALLEL_PARSE_JOBS=$(cat "${CACHE_DIR}/parallel_parse_jobs.txt")
                echo -e "${DIM}Current: ${PARALLEL_PARSE_JOBS} parse jobs${NC}"
                echo ""
                echo -e "${YELLOW}Enter number of parallel parse jobs (minimum: 2, recommended: 4-16):${NC}"
                stty echo
                read -r input_parse_jobs
                stty -echo
                
                if [[ "$input_parse_jobs" =~ ^[0-9]+$ ]] && [[ $input_parse_jobs -ge 2 ]]; then
                    PARALLEL_PARSE_JOBS=$input_parse_jobs
                    echo "$PARALLEL_PARSE_JOBS" > "${CACHE_DIR}/parallel_parse_jobs.txt"
                    echo ""
                    if [[ $input_parse_jobs -gt 64 ]]; then
                        echo -e "${YELLOW}⚠ Warning: ${input_parse_jobs} jobs may consume significant system resources${NC}"
                    fi
                    echo -e "${GREEN}✓ Parallel parse jobs set to: ${PARALLEL_PARSE_JOBS}${NC}"
                else
                    echo ""
                    echo -e "${RED}✗ Invalid input. Must be 2 or greater.${NC}"
                fi
                echo ""
                echo -e "${DIM}Press any key to continue...${NC}"
                read -rsn1
                tput civis 2>/dev/null
            elif [[ $selected_idx -eq 10 ]]; then
                # Parsing Rolling Queue - toggle (instant)
                [[ -f "${CACHE_DIR}/parsing_rolling_queue_mode.txt" ]] && PARSING_ROLLING_QUEUE_MODE=$(cat "${CACHE_DIR}/parsing_rolling_queue_mode.txt")
                if [[ "$PARSING_ROLLING_QUEUE_MODE" == "true" ]]; then
                    PARSING_ROLLING_QUEUE_MODE="false"
                else
                    PARSING_ROLLING_QUEUE_MODE="true"
                fi
                echo "$PARSING_ROLLING_QUEUE_MODE" > "${CACHE_DIR}/parsing_rolling_queue_mode.txt"
                # Menu will refresh automatically
            elif [[ $selected_idx -eq 11 ]]; then
                # JSON Database Mode - cycle through modes (instant)
                [[ -f "${CACHE_DIR}/json_db_mode.txt" ]] && JSON_DB_MODE=$(cat "${CACHE_DIR}/json_db_mode.txt")
                
                case "$JSON_DB_MODE" in
                    hybrid)
                        JSON_DB_MODE="json_only"
                        ;;
                    json_only)
                        JSON_DB_MODE="api_only"
                        ;;
                    api_only)
                        JSON_DB_MODE="hybrid"
                        ;;
                    *)
                        JSON_DB_MODE="hybrid"
                        ;;
                esac
                echo "$JSON_DB_MODE" > "${CACHE_DIR}/json_db_mode.txt"
                # Menu will refresh automatically
            elif [[ $selected_idx -eq 12 ]]; then
                # Cache Management
                tput civis 2>/dev/null
                show_cache_management_menu
                # Return to main menu after cache management
            elif [[ $selected_idx -eq 13 ]]; then
                # Parsing Database
                tput civis 2>/dev/null
                show_parsing_db_menu
                # Return to main menu after parsing db management
            elif [[ $selected_idx -eq 14 ]]; then
                # Debug Mode: Movies - cycle through off/low/medium/high (instant)
                # Load current setting
                local current_level="off"
                if [[ -f "${CACHE_DIR}/debug_mode_movies.txt" ]]; then
                    local value=$(cat "${CACHE_DIR}/debug_mode_movies.txt")
                    case "$value" in
                        true) current_level="high" ;;
                        false) current_level="off" ;;
                        off|low|medium|high) current_level="$value" ;;
                    esac
                fi
                # Cycle to next level: off → low → medium → high → off
                case "$current_level" in
                    off) DEBUG_LEVEL_MOVIES="low" ;;
                    low) DEBUG_LEVEL_MOVIES="medium" ;;
                    medium) DEBUG_LEVEL_MOVIES="high" ;;
                    high) DEBUG_LEVEL_MOVIES="off" ;;
                esac
                echo "$DEBUG_LEVEL_MOVIES" > "${CACHE_DIR}/debug_mode_movies.txt"
                # Update backward compat variable
                [[ "$DEBUG_LEVEL_MOVIES" != "off" ]] && DEBUG_MODE_MOVIES="true" || DEBUG_MODE_MOVIES="false"
                # Menu will refresh automatically
            elif [[ $selected_idx -eq 15 ]]; then
                # Debug Mode: TV Shows - cycle through off/low/medium/high (instant)
                # Load current setting
                local current_level="off"
                if [[ -f "${CACHE_DIR}/debug_mode_tv.txt" ]]; then
                    local value=$(cat "${CACHE_DIR}/debug_mode_tv.txt")
                    case "$value" in
                        true) current_level="high" ;;
                        false) current_level="off" ;;
                        off|low|medium|high) current_level="$value" ;;
                    esac
                fi
                # Cycle to next level: off → low → medium → high → off
                case "$current_level" in
                    off) DEBUG_LEVEL_TV="low" ;;
                    low) DEBUG_LEVEL_TV="medium" ;;
                    medium) DEBUG_LEVEL_TV="high" ;;
                    high) DEBUG_LEVEL_TV="off" ;;
                esac
                echo "$DEBUG_LEVEL_TV" > "${CACHE_DIR}/debug_mode_tv.txt"
                # Update backward compat variable
                [[ "$DEBUG_LEVEL_TV" != "off" ]] && DEBUG_MODE_TV="true" || DEBUG_MODE_TV="false"
                # Menu will refresh automatically
            elif [[ $selected_idx -eq 16 ]]; then
                # Diagnostics Mode - instant toggle
                # Load current setting
                [[ -f "${CACHE_DIR}/diagnostics_mode.txt" ]] && DIAGNOSTICS_MODE=$(cat "${CACHE_DIR}/diagnostics_mode.txt")
                # Toggle
                if [[ "$DIAGNOSTICS_MODE" == "true" ]]; then
                    DIAGNOSTICS_MODE="false"
                    echo "false" > "${CACHE_DIR}/diagnostics_mode.txt"
                else
                    DIAGNOSTICS_MODE="true"
                    echo "true" > "${CACHE_DIR}/diagnostics_mode.txt"
                fi
                # Menu will refresh automatically
            elif [[ $selected_idx -eq 17 ]]; then
                # API Delay - same as in settings menu
                tput cnorm 2>/dev/null
                clear
                echo ""
                echo -e "${BLUE}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
                echo -e "${CYAN}API DELAY CONFIGURATION${NC}"
                echo -e "${BLUE}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
                echo ""
                echo -e "${DIM}Current delay: ${API_DELAY}s${NC}"
                echo ""
                echo -e "${YELLOW}Delay between API calls (in seconds):${NC}"
                echo -e "${DIM}  • 0.01 = Very fast (minimum)${NC}"
                echo -e "${DIM}  • 0.25 = Fast (recommended for personal use)${NC}"
                echo -e "${DIM}  • 0.5  = Moderate${NC}"
                echo -e "${DIM}  • 1.0  = Safe (conservative)${NC}"
                echo ""
                echo -e "${YELLOW}Enter delay (0.01-5.0 seconds):${NC}"
                stty echo
                read -r input_delay
                stty -echo
                
                if [[ "$input_delay" =~ ^[0-9]+\.?[0-9]*$ ]]; then
                    if command -v bc &> /dev/null; then
                        if (( $(echo "$input_delay >= 0.01" | bc -l) )) && (( $(echo "$input_delay <= 5.0" | bc -l) )); then
                            API_DELAY=$input_delay
                            echo "$API_DELAY" > "${CACHE_DIR}/api_delay.txt"
                            echo ""
                            echo -e "${GREEN}✓ API delay set to: ${API_DELAY}s${NC}"
                        else
                            echo ""
                            echo -e "${RED}✗ Invalid input. Must be between 0.01 and 5.0 seconds.${NC}"
                        fi
                    else
                        API_DELAY=$input_delay
                        echo "$API_DELAY" > "${CACHE_DIR}/api_delay.txt"
                        echo ""
                        echo -e "${GREEN}✓ API delay set to: ${API_DELAY}s${NC}"
                    fi
                else
                    echo ""
                    echo -e "${RED}✗ Invalid input. Please enter a number.${NC}"
                fi
                echo ""
                echo -e "${DIM}Press any key to continue...${NC}"
                read -rsn1
                tput civis 2>/dev/null
            elif [[ $selected_idx -eq 18 ]]; then
                # AWK Parser - toggle cycle through installed parsers (instant)
                [[ -f "${CACHE_DIR}/awk_parser.txt" ]] && AWK_PARSER=$(cat "${CACHE_DIR}/awk_parser.txt") || AWK_PARSER="awk"
                
                # Cycle forward through available parsers
                case "$AWK_PARSER" in
                    awk)
                        if command -v gawk &> /dev/null; then
                            AWK_PARSER="gawk"
                        elif command -v mawk &> /dev/null; then
                            AWK_PARSER="mawk"
                        fi
                        ;;
                    gawk)
                        if command -v mawk &> /dev/null; then
                            AWK_PARSER="mawk"
                        else
                            AWK_PARSER="awk"
                        fi
                        ;;
                    mawk) AWK_PARSER="awk" ;;
                esac
                echo "$AWK_PARSER" > "${CACHE_DIR}/awk_parser.txt"
                # Menu will refresh automatically
            elif [[ $selected_idx -eq 19 ]]; then
                # Extension Duplicate Mode - cycle through off/resolution/bitrate
                [[ -f "${CACHE_DIR}/extension_dup_mode.txt" ]] && EXTENSION_DUP_MODE=$(cat "${CACHE_DIR}/extension_dup_mode.txt") || EXTENSION_DUP_MODE="off"
                
                # Cycle forward through modes
                case "$EXTENSION_DUP_MODE" in
                    off) EXTENSION_DUP_MODE="resolution" ;;
                    resolution) EXTENSION_DUP_MODE="bitrate" ;;
                    bitrate) EXTENSION_DUP_MODE="off" ;;
                    *) EXTENSION_DUP_MODE="off" ;;
                esac
                echo "$EXTENSION_DUP_MODE" > "${CACHE_DIR}/extension_dup_mode.txt"
                # Menu will refresh automatically
            elif [[ $selected_idx -eq 20 ]]; then
                # TV Extension Duplicate Mode - cycle through off/resolution/bitrate
                [[ -f "${CACHE_DIR}/tv_extension_dup_mode.txt" ]] && TV_EXTENSION_DUP_MODE=$(cat "${CACHE_DIR}/tv_extension_dup_mode.txt") || TV_EXTENSION_DUP_MODE="off"
                
                # Cycle forward through modes
                case "$TV_EXTENSION_DUP_MODE" in
                    off) TV_EXTENSION_DUP_MODE="resolution" ;;
                    resolution) TV_EXTENSION_DUP_MODE="bitrate" ;;
                    bitrate) TV_EXTENSION_DUP_MODE="off" ;;
                    *) TV_EXTENSION_DUP_MODE="off" ;;
                esac
                echo "$TV_EXTENSION_DUP_MODE" > "${CACHE_DIR}/tv_extension_dup_mode.txt"
                # Menu will refresh automatically
            elif [[ $selected_idx -eq 21 ]]; then
                # Image Resizer - toggle cycle through available tools (instant)
                [[ -f "${CACHE_DIR}/image_resizer.txt" ]] && IMAGE_RESIZER=$(cat "${CACHE_DIR}/image_resizer.txt") || IMAGE_RESIZER="auto"
                
                # Cycle forward through tools: auto → sips → vips
                case "$IMAGE_RESIZER" in
                    auto) IMAGE_RESIZER="sips" ;;
                    sips) IMAGE_RESIZER="vips" ;;
                    vips) IMAGE_RESIZER="auto" ;;
                    *) IMAGE_RESIZER="auto" ;;
                esac
                echo "$IMAGE_RESIZER" > "${CACHE_DIR}/image_resizer.txt"
                # Menu will refresh automatically
            elif [[ $selected_idx -eq 22 ]]; then
                # Test API Connection
                tput cnorm 2>/dev/null
                clear
                echo ""
                echo -e "${BLUE}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
                echo -e "${CYAN}TEST API CONNECTION${NC}"
                echo -e "${BLUE}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
                echo ""
                echo -e "${YELLOW}Testing TMDb API connection...${NC}"
                echo ""
                
                # Array of popular movies for random testing
                local -a test_movies=(
                    "Avatar|2009"
                    "The Shawshank Redemption|1994"
                    "The Godfather|1972"
                    "The Dark Knight|2008"
                    "Inception|2010"
                    "Fight Club|1999"
                    "Forrest Gump|1994"
                    "The Matrix|1999"
                    "Interstellar|2014"
                    "Pulp Fiction|1994"
                    "The Lord of the Rings|2001"
                    "Titanic|1997"
                    "Jurassic Park|1993"
                    "Star Wars|1977"
                    "Back to the Future|1985"
                )
                
                # Select random movie
                local random_idx=$((RANDOM % ${#test_movies[@]}))
                local test_movie="${test_movies[$random_idx]}"
                local test_query=$(echo "$test_movie" | cut -d'|' -f1)
                local test_year=$(echo "$test_movie" | cut -d'|' -f2)
                
                echo -e "${DIM}Testing with: ${test_query} (${test_year})${NC}"
                echo ""
                
                local test_start=$SECONDS
                local test_result=$(curl -s --connect-timeout 10 --max-time 30 "${TMDB_API_BASE}/search/movie?api_key=${TMDB_API_KEY}&query=$(echo "$test_query" | sed 's/ /%20/g')&year=${test_year}" 2>/dev/null)
                local test_time=$((SECONDS - test_start))
                
                if [[ -n "$test_result" ]] && echo "$test_result" | grep -q '"id"'; then
                    echo -e "${GREEN}✓ API connection successful!${NC}"
                    echo ""
                    echo -e "${DIM}Response time: ${test_time}s${NC}"
                    
                    local movie_id=$(echo "$test_result" | grep -oE '"id":[0-9]+' | head -1 | grep -oE '[0-9]+')
                    local movie_title=$(echo "$test_result" | grep -oE '"title":"[^"]+' | head -1 | cut -d'"' -f4)
                    
                    if [[ -n "$movie_id" && -n "$movie_title" ]]; then
                        echo -e "${DIM}Test search found: ${movie_title} (TMDb ID: ${movie_id})${NC}"
                    fi
                elif echo "$test_result" | grep -q "Invalid API key"; then
                    echo -e "${RED}✗ API key invalid!${NC}"
                    echo ""
                    echo -e "${YELLOW}Please update your TMDb API key.${NC}"
                else
                    echo -e "${RED}✗ API connection failed!${NC}"
                    echo ""
                    echo -e "${YELLOW}Please check:${NC}"
                    echo -e "${DIM}  • Your internet connection${NC}"
                    echo -e "${DIM}  • Your API key is valid${NC}"
                    echo -e "${DIM}  • TMDb service is online${NC}"
                fi
                
                echo ""
                echo -e "${DIM}Press any key to continue...${NC}"
                read -rsn1
                tput civis 2>/dev/null
            elif [[ $selected_idx -eq 23 ]]; then
                # API Settings
                tput civis 2>/dev/null
                show_settings_menu
                # Return to main menu after settings
            elif [[ $selected_idx -eq 24 ]]; then
                # OS Settings - go directly to OS selection
                tput civis 2>/dev/null
                # Save current OS before clearing
                local previous_os=""
                [[ -f "${CACHE_DIR}/selected_os.txt" ]] && previous_os=$(cat "${CACHE_DIR}/selected_os.txt")
                # Remove saved OS to force selection menu to appear
                rm -f "${CACHE_DIR}/selected_os.txt" 2>/dev/null
                # Call OS selection menu
                if ! select_operating_system; then
                    # User backed out - restore previous OS
                    [[ -n "$previous_os" ]] && echo "$previous_os" > "${CACHE_DIR}/selected_os.txt"
                fi
                # Restore terminal state after OS selection
                stty -echo 2>/dev/null
                tput civis 2>/dev/null
            elif [[ $selected_idx -eq 25 ]]; then
                # Round Resolution - toggle setting
                if [[ "$ROUND_RESOLUTION" == "yes" ]]; then
                    ROUND_RESOLUTION="no"
                else
                    ROUND_RESOLUTION="yes"
                fi
                echo "$ROUND_RESOLUTION" > "${CACHE_DIR}/round_resolution.txt"
            fi
        fi
    done
    
    # Cache selection is now handled within the menu loop for Quick options
    # Regular Movies/TV Shows options handle cache selection within their own flows
    
    stty echo 2>/dev/null
    
    if [[ "$PROFILE_MODE" != "profile" ]]; then
        # Custom mode — show manual drag-and-drop prompts
        # Prompt for sources - silently wait for non-empty input
        while :; do
            echo -e "${CYAN}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
            echo -e "${GREEN}📂 SOURCE INPUT${NC}"
            echo -e "${CYAN}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
            echo -e "${YELLOW}Drag and drop source(s) - multiple files/folders (press ENTER when done):${NC}"
            read -r SOURCE_INPUT
            [[ -n "$SOURCE_INPUT" ]] && break
        done
        
        # Prompt for destination - silently wait for non-empty input
        while :; do
            echo ""
            echo -e "${MAGENTA}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
            echo -e "${GREEN}📁 DESTINATION${NC}"
            echo -e "${MAGENTA}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
            echo -e "${YELLOW}Drag and drop ONE destination folder (press ENTER when done):${NC}"
            read -r DESTINATION
            [[ -n "$DESTINATION" ]] && break
        done
        
        DESTINATION=$(echo "$DESTINATION" | sed "s/^['\"]//;s/['\"]$//;s/\\\\ / /g;s/\\\\$//;s/[[:space:]]*$//")
    fi
    
    if [[ ! -d "$DESTINATION" ]]; then
        print_error "Destination must be a directory"
        exit 1
    fi
    
    # Parse multiple sources from input
    local -a SOURCES=()
    
    # Remove leading/trailing whitespace
    SOURCE_INPUT="${SOURCE_INPUT#"${SOURCE_INPUT%%[![:space:]]*}"}"
    SOURCE_INPUT="${SOURCE_INPUT%"${SOURCE_INPUT##*[![:space:]]}"}"
    
    # Remove quotes if present
    SOURCE_INPUT="${SOURCE_INPUT#\"}"
    SOURCE_INPUT="${SOURCE_INPUT%\"}"
    SOURCE_INPUT="${SOURCE_INPUT#\'}"
    SOURCE_INPUT="${SOURCE_INPUT%\'}"
    
    # Check if input contains backslash-escaped spaces (drag-and-drop)
    if [[ "$SOURCE_INPUT" =~ \\\  ]]; then
        should_debug high && echo "[DEBUG] SOURCE_INPUT with escaped spaces: '$SOURCE_INPUT'" >&2
        
        # Split on unescaped spaces (spaces not preceded by backslash)
        # This separates multiple files while preserving spaces within filenames
        local temp_input="$SOURCE_INPUT"
        local current_part=""
        local i=0
        
        while [[ $i -lt ${#temp_input} ]]; do
            local char="${temp_input:$i:1}"
            local next_char="${temp_input:$((i+1)):1}"
            
            if [[ "$char" == "\\" && -n "$next_char" ]]; then
                # Escaped character - check what it is
                if [[ "$next_char" == " " ]]; then
                    # Escaped space - separates multiple paths, so add space to current part
                    current_part+=" "
                    ((i+=2))
                else
                    # Other escaped character (like \( or \)) - just add the character without backslash
                    current_part+="$next_char"
                    ((i+=2))
                fi
            elif [[ "$char" == " " ]]; then
                # Unescaped space - end of current path
                if [[ -n "$current_part" ]]; then
                    # Remove quotes if present
                    current_part="${current_part#\"}"
                    current_part="${current_part%\"}"
                    current_part="${current_part#\'}"
                    current_part="${current_part%\'}"
                    # Remove trailing backslash (common with drag-and-drop on macOS)
                    current_part="${current_part%\\}"
                    should_debug high && echo "[DEBUG] Found source: '$current_part'" >&2
                    SOURCES+=("$current_part")
                    current_part=""
                fi
                ((i++)) || true
            else
                # Regular character
                current_part+="$char"
                ((i++)) || true
            fi
        done
        
        # Add the last part
        if [[ -n "$current_part" ]]; then
            current_part="${current_part#\"}"
            current_part="${current_part%\"}"
            current_part="${current_part#\'}"
            current_part="${current_part%\'}"
            # Remove trailing backslash (common with drag-and-drop on macOS)
            current_part="${current_part%\\}"
            should_debug high && echo "[DEBUG] Found source: '$current_part'" >&2
            SOURCES+=("$current_part")
        fi
    else
        # Pasted path: treat as single path (may contain spaces)
        if [[ -e "$SOURCE_INPUT" ]]; then
            # Single path exists
            SOURCES+=("$SOURCE_INPUT")
        else
            # Might be multiple space-separated paths, try splitting
            IFS=' ' read -ra temp_sources <<< "$SOURCE_INPUT"
            for source in "${temp_sources[@]}"; do
                [[ -z "$source" ]] && continue
                source="${source#\"}"
                source="${source%\"}"
                source="${source#\'}"
                source="${source%\'}"
                [[ -n "$source" ]] && SOURCES+=("$source")
            done
        fi
    fi
    
    if [[ ${#SOURCES[@]} -eq 0 ]]; then
        print_error "No sources provided"
        exit 1
    fi
    
    print_success "Found ${#SOURCES[@]} source(s) to process"
    echo ""
    
    # Ask once for auto-processing mode
    stty echo 2>/dev/null
    print_info "Process all files automatically? (ENTER = yes, n = no):"
    read -r AUTO_MODE
    [[ -z "$AUTO_MODE" ]] && AUTO_MODE="y"
    echo ""
    
    # Array to track failed ID lookups
    local -a FAILED_LOOKUPS=()
    
    # Array to track failed hardlinks
    local -a FAILED_HARDLINKS=()
    
    # Array to track files that couldn't be parsed (no title/year detected)
    local -a FAILED_PARSE=()
    
    # Array to track rejected files with reasons (format: "file_path|||reason")
    # Note: NOT using 'local' so it's accessible across function calls and in statistics
    REJECTED_FILES=()
    
    # Array to track all duplicate files across all sources
    local -a ALL_DUPLICATE_FILES=()
    
    # Array to collect all video files from all sources
    local -a ALL_VIDEO_FILES=()
    
    # First pass: collect all video files from all sources
    print_info "Collecting video files from all sources..."
    echo ""
    
    # ═══════════════════════════════════════════════════════════════════════════════
    # PRE-BUILD: Build destination inode map BEFORE file collection
    # ═══════════════════════════════════════════════════════════════════════════════
    # This allows us to skip extras checks for files already hardlinked
    # Building the map first saves significant time during collection
    
    # Clean up stale temp files from previous crashed runs (prevents hangs)
    rm -rf /tmp/movie_dest_lock_* /tmp/movie_filter_lock_* 2>/dev/null
    rm -f /tmp/movie_dest_map_*.txt /tmp/movie_linked_*.txt /tmp/movie_notlinked_*.txt /tmp/movie_linked_folders_*.txt 2>/dev/null
    
    print_info "Building destination inode map first (to skip already-linked files during collection)..."
    
    # Build a map of inodes to destination file paths
    local temp_dest_map="/tmp/movie_dest_map_$$.txt"
    > "$temp_dest_map"
    local pre_linked_count=0
    
    if [[ -d "$DESTINATION" ]]; then
        # Fast inode scan: single find | xargs stat pipeline (no per-file forks)
        print_info "Scanning destination inodes..."
        # Background progress monitor (updates every 0.5s)
        (
            while [[ -f "$temp_dest_map" ]]; do
                local _c=$(wc -l < "$temp_dest_map" 2>/dev/null | tr -d ' ')
                printf "\r${CYAN}[%s files scanned]${NC}" "$_c" >&2
                sleep 0.5
            done
        ) &
        local _dest_progress_pid=$!
        find "$DESTINATION" -type f -print0 2>/dev/null \
            | xargs -0 stat "$_STAT_FMT_FLAG" "$_STAT_INODE_NAME_FMT" 2>/dev/null \
            | awk -F'|' '{ n=tolower($2); sub(/.*\//, "", n); if (n ~ /\.(mkv|mp4|avi|m4v|mov|vob|wmv|flv|webm|ts|m2ts|mpg|mpeg|divx|xvid|iso)$/) print }' > "$temp_dest_map" || true
        kill "$_dest_progress_pid" 2>/dev/null; wait "$_dest_progress_pid" 2>/dev/null || true
        local dest_total=$(wc -l < "$temp_dest_map" 2>/dev/null | tr -d ' ')
        printf "\r${CYAN}[%s files scanned]${NC}\n" "$dest_total" >&2
    fi
    
    local dest_inode_count=$(wc -l < "$temp_dest_map" 2>/dev/null | tr -d ' ')
    # Break down destination files by category (single awk pass - no bash loop)
    local dest_main=0 dest_extras=0
    if [[ -s "$temp_dest_map" ]]; then
        local _dest_counts
        _dest_counts=$(awk -F'|' '{
            p = tolower($2)
            n = p; sub(/.*\//, "", n)
            if (n ~ /sample/) { e++ }
            else if (n ~ /^trailer/ || n ~ /[-.]trailer[-.]/ ||
                     n ~ /(behind.the.scene|deleted.scene|featurette)/) { e++ }
            else if (p ~ /\/extras[-_.]?[^\/]*\// || p ~ /\/extras$/ ||
                     p ~ /[^a-z]extras[-_.]?[^\/]*\// ||
                     p ~ /\/featurettes?[-_.]?[^\/]*\// || p ~ /\/featurettes?$/ ||
                     p ~ /\/bonus(es)?[-_.]?[^\/]*\// || p ~ /\/bonus(es)?$/ ||
                     p ~ /\/deleted.scenes?\// || p ~ /\/behind.the.scenes?\// ||
                     p ~ /\/interviews[-_.]?[^\/]*\// || p ~ /\/interviews$/ ||
                     p ~ /\/trailers?[-_.]?[^\/]*\// || p ~ /\/trailers?$/ ||
                     p ~ /\/clips?[-_.]?[^\/]*\// || p ~ /\/clips?$/ ||
                     p ~ /\/shorts?[-_.]?[^\/]*\// || p ~ /\/shorts?$/ ||
                     p ~ /\/making.of\// || p ~ /\/making.of$/ ||
                     p ~ /\/samples\//) { e++ }
            else { m++ }
        } END { print m+0, e+0 }' "$temp_dest_map")
        dest_main=${_dest_counts%% *}
        dest_extras=${_dest_counts#* }
    fi
    print_success "Built destination inode map: $dest_inode_count files indexed"
    print_info "  └─ Destination: $dest_main main movies | $dest_extras extras"
    echo ""
    
    # Set cache file BEFORE capturing the before count
    set_cache_by_resolution ""
    
    # Track cache entries before processing
    local cache_entries_before=0
    [[ -f "$CACHE_FILE" ]] && cache_entries_before=$(awk 'NF' "$CACHE_FILE" 2>/dev/null | wc -l | tr -d ' ' || echo 0)
    echo "$cache_entries_before" > "${CACHE_DIR}/movie_cache_before.txt"
    
    # Track overall statistics across all sources
    local overall_start_time=$SECONDS
    local overall_size=0
    local overall_success=0
    local overall_already_existed=0
    local overall_skipped=0
    local overall_failed=0
    
    # Track failed files for statistics (aggregate from temp files in all modes)
    local -a FAILED_FILES=()
    local FAILED_FILES_TMP=( )
    
    # Clean up any stale temp files from previous runs
    rm -f "${CACHE_DIR}/.failed_files_$$.tmp" 2>/dev/null
    rm -f "${CACHE_DIR}/.failed_files_${BASHPID}.tmp" 2>/dev/null
    rm -f "${CACHE_DIR}/.rejected_files_$$.tmp" 2>/dev/null
    rm -f "${CACHE_DIR}/.processed_folders_$$.tmp" 2>/dev/null
    rm -f "${CACHE_DIR}/.folders_with_files_$$.tmp" 2>/dev/null
    rm -f "${CACHE_DIR}/.successfully_hardlinked_$$.tmp" 2>/dev/null

    for SOURCE in "${SOURCES[@]}"; do
        # Sources are already properly parsed above, no need for additional sed
        
        if [[ ! -e "$SOURCE" ]]; then
            print_error "Source not found: $SOURCE"
            ((total_failed++)) || true
            # Write to temp file for aggregation in all modes (with reason)
            echo "$SOURCE|||Source path not found or inaccessible" >> "${CACHE_DIR}/.failed_files_$$.tmp"
            continue
        fi
        
        print_info "========================================="
        print_info "Processing source: $SOURCE"
        print_info "========================================="
        echo ""
        
        # Skip if SOURCE itself is an extras/bonus/featurettes folder
        if [[ "$SOURCE" =~ (extras|extra|bonus|bonuses|featurette|featurettes|behind.?the.?scenes|bts|interviews?|deleted.?scenes|sample|samples|proof) ]]; then
            print_warning "Skipping extras/bonus folder: $(basename "$SOURCE")"
            ((total_skipped++)) || true
            continue
        fi
        
        # Handle copy entire folder mode
        if [[ "$COPY_ENTIRE_FOLDER" == "true" ]] && [[ -d "$SOURCE" ]]; then
            local source_basename=$(basename "$SOURCE")
            local dest_folder="$DESTINATION/$source_basename"
            
            print_info "Copying entire folder: $source_basename"
            print_info "Destination: $dest_folder"
            
            # Create destination if it doesn't exist
            if [[ ! -d "$dest_folder" ]]; then
                mkdir -p "$dest_folder"
            fi
            
            # Copy entire folder recursively with verbose output
            if cp -Rv "$SOURCE/" "$dest_folder/"; then
                print_success "Successfully copied folder and all contents"
                ((total_success++)) || true
            else
                print_error "Failed to copy folder"
                ((total_failed++)) || true
            fi
            
            echo ""
            continue
        fi
        
        # Handle hardlink entire folder mode
        if [[ "$HARDLINK_ENTIRE_FOLDER" == "true" ]] && [[ -d "$SOURCE" ]]; then
            local source_basename=$(basename "$SOURCE")
            local dest_folder="$DESTINATION/$source_basename"
            
            print_info "Hardlinking entire folder structure: $source_basename"
            print_info "Destination: $dest_folder"
            
            # Create destination if it doesn't exist
            if [[ ! -d "$dest_folder" ]]; then
                mkdir -p "$dest_folder"
            fi
            
            # Recursively hardlink all files, preserving directory structure (skip sample files)
            local hardlink_count=0
            local hardlink_failed=0
            local hardlink_skipped=0
            while IFS= read -r -d '' source_file; do
                # Skip sample files
                local lowercase_basename=$(basename "$source_file" | tr '[:upper:]' '[:lower:]')
                if [[ "$lowercase_basename" =~ sample ]]; then
                    ((hardlink_skipped++)) || true
                    continue
                fi
                
                # Get relative path from source root
                local rel_path="${source_file#$SOURCE/}"
                local dest_file="$dest_folder/$rel_path"
                local dest_dir=$(dirname "$dest_file")
                
                # Create destination directory if needed
                if [[ ! -d "$dest_dir" ]]; then
                    mkdir -p "$dest_dir"
                fi
                
                # Create symlink
                if ln -s "$source_file" "$dest_file" 2>/dev/null; then
                    ((symlink_count++)) || true
                else
                    print_warning "Failed to symlink: $rel_path"
                    ((symlink_failed++)) || true
                fi
            done < <(find "$SOURCE" -type f -print0)
            
            if [[ $symlink_count -gt 0 ]]; then
                print_success "Successfully symlinked $symlink_count files"
                if [[ $symlink_skipped -gt 0 ]]; then
                    print_info "Skipped $symlink_skipped sample files"
                fi
                if [[ $symlink_failed -gt 0 ]]; then
                    print_warning "$symlink_failed files failed to symlink"
                fi
                ((total_success++)) || true
            else
                print_error "Failed to symlink folder"
                ((total_failed++)) || true
            fi
            
            echo ""
            continue
        fi
        
        # Check if source is directory or file
        if [[ -f "$SOURCE" ]]; then
            # Single file provided
            print_info "Processing single file: $SOURCE"
            VIDEO_FILES=("$SOURCE")
            print_success "Found 1 video file"
            
            # Add to global array
            ALL_VIDEO_FILES+=("${VIDEO_FILES[@]}")
        elif [[ -d "$SOURCE" ]]; then
            print_info "Processing directory: $SOURCE"
            
            # Build find command with optional extras folder exclusions
            local find_cmd="find \"$SOURCE\""
            
            # If extras linking is disabled, exclude extras folders from scan entirely (case-insensitive)
            if [[ "$HARDLINK_EXTRAS" == "false" ]]; then
                print_info "Searching for video files (excluding Extras/Bonus/Featurettes subfolders)..."
                find_cmd+=" \\( -ipath \"*/behind the scenes\" -o"
                find_cmd+=" -ipath \"*/behind the scenes/*\" -o"
                find_cmd+=" -ipath \"*/behind the scene\" -o"
                find_cmd+=" -ipath \"*/behind the scene/*\" -o"
                find_cmd+=" -ipath \"*/deleted scenes\" -o"
                find_cmd+=" -ipath \"*/deleted scenes/*\" -o"
                find_cmd+=" -ipath \"*/deleted scene\" -o"
                find_cmd+=" -ipath \"*/deleted scene/*\" -o"
                find_cmd+=" -ipath \"*/interviews\" -o"
                find_cmd+=" -ipath \"*/interviews/*\" -o"
                find_cmd+=" -ipath \"*/interview\" -o"
                find_cmd+=" -ipath \"*/interview/*\" -o"
                find_cmd+=" -ipath \"*/scenes\" -o"
                find_cmd+=" -ipath \"*/scenes/*\" -o"
                find_cmd+=" -ipath \"*/samples\" -o"
                find_cmd+=" -ipath \"*/samples/*\" -o"
                find_cmd+=" -ipath \"*/sample\" -o"
                find_cmd+=" -ipath \"*/sample/*\" -o"
                find_cmd+=" -ipath \"*/shorts\" -o"
                find_cmd+=" -ipath \"*/shorts/*\" -o"
                find_cmd+=" -ipath \"*/short\" -o"
                find_cmd+=" -ipath \"*/short/*\" -o"
                find_cmd+=" -ipath \"*/featurettes\" -o"
                find_cmd+=" -ipath \"*/featurettes/*\" -o"
                find_cmd+=" -ipath \"*/featurette\" -o"
                find_cmd+=" -ipath \"*/featurette/*\" -o"
                find_cmd+=" -ipath \"*/clips\" -o"
                find_cmd+=" -ipath \"*/clips/*\" -o"
                find_cmd+=" -ipath \"*/clip\" -o"
                find_cmd+=" -ipath \"*/clip/*\" -o"
                find_cmd+=" -ipath \"*/other\" -o"
                find_cmd+=" -ipath \"*/other/*\" -o"
                find_cmd+=" -ipath \"*/extras\" -o"
                find_cmd+=" -ipath \"*/extras/*\" -o"
                find_cmd+=" -ipath \"*/extra\" -o"
                find_cmd+=" -ipath \"*/extra/*\" -o"
                find_cmd+=" -ipath \"*/bonus\" -o"
                find_cmd+=" -ipath \"*/bonus/*\" -o"
                find_cmd+=" -ipath \"*/bonuses\" -o"
                find_cmd+=" -ipath \"*/bonuses/*\" -o"
                find_cmd+=" -ipath \"*/trailers\" -o"
                find_cmd+=" -ipath \"*/trailers/*\" -o"
                find_cmd+=" -ipath \"*/trailer\" -o"
                find_cmd+=" -ipath \"*/trailer/*\" \\) -prune -o"
            else
                print_info "Searching for video files..."
            fi
            
            find_cmd+=" -type f \\( -iname \"*.mkv\" -o -iname \"*.mp4\" -o -iname \"*.avi\" -o -iname \"*.m4v\" -o -iname \"*.mov\" -o -iname \"*.vob\" -o -iname \"*.wmv\" -o -iname \"*.flv\" -o -iname \"*.webm\" -o -iname \"*.ts\" -o -iname \"*.m2ts\" -o -iname \"*.mpg\" -o -iname \"*.mpeg\" -o -iname \"*.divx\" -o -iname \"*.xvid\" -o -iname \"*.iso\" \\) -print0"
            
            # Find video files - skip extras from main processing
            VIDEO_FILES=()
            local skipped_samples=0
            local skipped_extras=0
            local skipped_already_linked=0
            local skipped_ext_dups=0
            # Track source folders for already-linked files (for extras processing later)
            local already_linked_folders_tmp="/tmp/movie_linked_folders_$$.txt"
            # Collect non-linked extras files for direct linking later
            local nonlinked_extras_tmp="/tmp/movie_nonlinked_extras_$$.txt"
            > "$nonlinked_extras_tmp"
            
            # FAST INODE CHECK: Build source file -> inode mapping, then batch-check against dest map
            # This avoids O(n*m) grep calls by doing a single awk join operation
            local source_inodes_tmp="/tmp/movie_source_inodes_$$.txt"
            local linked_pairs_tmp="/tmp/movie_linked_pairs_$$.txt"
            local nonlinked_files_tmp="/tmp/movie_nonlinked_$$.txt"
            
            # Initialize temp files to ensure they exist
            > "$already_linked_folders_tmp"
            > "$source_inodes_tmp"
            > "$linked_pairs_tmp"
            > "$nonlinked_files_tmp"
            
            if [[ -s "$temp_dest_map" ]]; then
                # Fast inode scan: single find | xargs stat pipeline (no per-file forks)
                # Scan ALL video files in source (including extras) to match destination scan scope
                print_info "Scanning source inodes..."
                # Background progress monitor (updates every 0.5s)
                (
                    while [[ -f "$source_inodes_tmp" ]]; do
                        local _c=$(wc -l < "$source_inodes_tmp" 2>/dev/null | tr -d ' ')
                        printf "\r${CYAN}[%s files scanned]${NC}" "$_c" >&2
                        sleep 0.5
                    done
                ) &
                local _src_progress_pid=$!
                find "$SOURCE" -type f -print0 2>/dev/null \
                    | xargs -0 stat "$_STAT_FMT_FLAG" "$_STAT_INODE_NAME_FMT" 2>/dev/null \
                    | awk -F'|' '{ n=tolower($2); sub(/.*\//, "", n); if (n ~ /\.(mkv|mp4|avi|m4v|mov|vob|wmv|flv|webm|ts|m2ts|mpg|mpeg|divx|xvid|iso)$/) print }' > "$source_inodes_tmp" || true
                kill "$_src_progress_pid" 2>/dev/null; wait "$_src_progress_pid" 2>/dev/null || true
                local source_total=$(wc -l < "$source_inodes_tmp" 2>/dev/null | tr -d ' ')
                printf "\r${CYAN}[%s files scanned]${NC}\n" "$source_total" >&2
                
                # Break down source files by category (single awk pass - same logic as destination)
                local src_main=0 src_extras=0
                if [[ -s "$source_inodes_tmp" ]]; then
                    local _src_counts
                    _src_counts=$(awk -F'|' '{
                        p = tolower($2)
                        n = p; sub(/.*\//, "", n)
                        if (n ~ /sample/) { e++ }
                        else if (n ~ /^trailer/ || n ~ /[-.]trailer[-.]/ ||
                                 n ~ /(behind.the.scene|deleted.scene|featurette)/) { e++ }
                        else if (p ~ /\/extras[-_.]?[^\/]*\// || p ~ /\/extras$/ ||
                                 p ~ /[^a-z]extras[-_.]?[^\/]*\// ||
                                 p ~ /\/featurettes?[-_.]?[^\/]*\// || p ~ /\/featurettes?$/ ||
                                 p ~ /\/bonus(es)?[-_.]?[^\/]*\// || p ~ /\/bonus(es)?$/ ||
                                 p ~ /\/deleted.scenes?\// || p ~ /\/behind.the.scenes?\// ||
                                 p ~ /\/interviews[-_.]?[^\/]*\// || p ~ /\/interviews$/ ||
                                 p ~ /\/trailers?[-_.]?[^\/]*\// || p ~ /\/trailers?$/ ||
                                 p ~ /\/clips?[-_.]?[^\/]*\// || p ~ /\/clips?$/ ||
                                 p ~ /\/shorts?[-_.]?[^\/]*\// || p ~ /\/shorts?$/ ||
                                 p ~ /\/making.of\// || p ~ /\/making.of$/ ||
                                 p ~ /\/samples\//) { e++ }
                        else { m++ }
                    } END { print m+0, e+0 }' "$source_inodes_tmp")
                    src_main=${_src_counts%% *}
                    src_extras=${_src_counts#* }
                fi
                print_success "Built source inode map: $source_total files indexed"
                print_info "  └─ Source: $src_main main movies | $src_extras extras"
                
                # Show source vs destination comparison
                local linked_count=0 nonlinked_count=0 dest_only_count=0
                
                # Use awk to split files into linked vs non-linked (O(n+m) instead of O(n*m))
                # Initialize output files to ensure they exist
                > "$linked_pairs_tmp"
                > "$nonlinked_files_tmp"
                
                if [[ -s "$source_inodes_tmp" ]]; then
                    awk -F'|' -v linked="$linked_pairs_tmp" -v nonlinked="$nonlinked_files_tmp" '
                        NR==FNR {dest[$1]=$2; next}
                        $1 in dest {print $2"|"dest[$1] > linked}
                        !($1 in dest) {print $2 > nonlinked}
                    ' "$temp_dest_map" "$source_inodes_tmp"
                fi
                
                # Calculate and display inode comparison breakdown
                if [[ -s "$linked_pairs_tmp" ]]; then
                    linked_count=$(wc -l < "$linked_pairs_tmp" | tr -d ' ')
                fi
                if [[ -s "$nonlinked_files_tmp" ]]; then
                    nonlinked_count=$(wc -l < "$nonlinked_files_tmp" | tr -d ' ')
                fi
                # Count destination files with no matching source inode
                local dest_only_count=0
                local dest_dup_inode_count=0
                if [[ -s "$temp_dest_map" ]]; then
                    # Inodes in dest that are NOT in source
                    dest_only_count=$(awk -F'|' '
                        NR==FNR {src[$1]=1; next}
                        !($1 in src)
                    ' "$source_inodes_tmp" "$temp_dest_map" | wc -l | tr -d ' ')
                    # Count duplicate inode paths in dest (same source file linked to multiple dest locations)
                    local dest_unique_inodes=$(awk -F'|' '!seen[$1]++' "$temp_dest_map" | wc -l | tr -d ' ')
                    dest_dup_inode_count=$(( dest_inode_count - dest_unique_inodes ))
                fi
                
                echo ""
                print_info "Inode comparison: source (${source_total}) vs destination (${dest_inode_count})"
                print_info "  └─ Hardlinked (shared inodes): ${linked_count}"
                print_info "  └─ Source only (new/unlinked):  ${nonlinked_count}"
                if [[ $dest_only_count -gt 0 ]]; then
                    print_info "  └─ Destination only:            ${dest_only_count} (files not in source)"
                fi
                if [[ $dest_dup_inode_count -gt 0 ]]; then
                    print_warning "  └─ Dest duplicate links:        ${dest_dup_inode_count} (same source file → multiple dest paths)"
                    # Show which dest files are duplicates (appear from double-linking bug)
                    if [[ $dest_dup_inode_count -le 30 ]]; then
                        # Find duplicate inodes: inodes that appear more than once in dest map
                        awk -F'|' '
                            { count[$1]++; paths[$1] = paths[$1] "\n" $2 }
                            END {
                                for (inode in count) {
                                    if (count[inode] > 1) print paths[inode]
                                }
                            }
                        ' "$temp_dest_map" | while IFS= read -r _dup_path; do
                            [[ -z "$_dup_path" ]] && continue
                            print_warning "    dup: $(basename "$_dup_path") in $(dirname "$_dup_path" | sed "s|.*/||")/"
                        done
                    fi
                fi
                # Show source-only files for diagnostic (all paths with labels)
                if [[ $nonlinked_count -gt 0 && $nonlinked_count -le 50 ]]; then
                    print_info "  Source-only files (not hardlinked):"
                    while IFS= read -r _unlinked; do
                        [[ -z "$_unlinked" ]] && continue
                        local _bn=$(basename "$_unlinked")
                        local _bl=$(echo "$_bn" | tr '[:upper:]' '[:lower:]')
                        local _folder=$(dirname "$_unlinked" | sed "s|.*/||")
                        if [[ "$_bl" =~ sample ]] || echo "$_unlinked" | tr '[:upper:]' '[:lower:]' | grep -qE '/(extras|featurettes?|bonus|behind.the.scenes?|deleted.scenes?|making.of|interviews?|trailers?|samples?)/'; then
                            print_info "    • $_bn  [extras] in ${_folder}/"
                        else
                            print_info "    • $_bn  in ${_folder}/"
                        fi
                    done < "$nonlinked_files_tmp"
                fi
                echo ""
                
                # Build the already-linked folders map (movie root level only)
                # Only keep entries where src_folder is a direct child of SOURCE
                # This prevents subfolder entries (like Featurettes/) from creating nested duplicates
                if [[ "$HARDLINK_EXTRAS" == "true" ]] || [[ "$HARDLINK_EXTRAS" == "no-rename" ]] || [[ "$HARDLINK_EXTRAS" == "preserve" ]]; then
                    if [[ -s "$linked_pairs_tmp" ]]; then
                        # Count slash-separated components of SOURCE path for depth comparison
                        local _source_depth=$(echo "$SOURCE" | awk -F'/' '{print NF}')
                        awk -F'|' -v src_depth="$_source_depth" '{
                            # Get parent directory by stripping last /component
                            src_folder=$1; sub(/\/[^\/]*$/, "", src_folder)
                            dest_folder=$2; sub(/\/[^\/]*$/, "", dest_folder)
                            
                            # Only keep movie-root level: src_folder depth should be source_depth+1
                            src_f_depth = split(src_folder, d, "/")
                            if (src_f_depth == src_depth + 1) {
                                print src_folder"|"dest_folder
                            }
                        }' "$linked_pairs_tmp" | sort -u > "$already_linked_folders_tmp"
                    fi
                fi
                
                if [[ -s "$linked_pairs_tmp" ]]; then
                    skipped_already_linked=$(wc -l < "$linked_pairs_tmp" | tr -d ' ')
                else
                    skipped_already_linked=0
                fi
                ((pre_linked_count+=skipped_already_linked))
                
                # Build extension duplicate lookup using awk (fast, no per-file stat calls)
                # Format: group_key|source_path per line — group_key = path without extension
                local _ext_dup_lookup="/tmp/movie_ext_dup_lookup_$$.txt"
                if [[ -s "$linked_pairs_tmp" ]]; then
                    awk -F'|' '{
                        src=$1; gkey=src; sub(/\.[^.]*$/, "", gkey)
                        print gkey"|"src
                    }' "$linked_pairs_tmp" > "$_ext_dup_lookup"
                else
                    > "$_ext_dup_lookup"
                fi
                
                # Process only non-linked files for sample/extras filtering
                # Use single awk pass for bulk categorization (no per-file subprocesses)
                local _nonlinked_total=$(wc -l < "$nonlinked_files_tmp" 2>/dev/null | tr -d ' ')
                local _awk_main_tmp="/tmp/movie_awk_main_$$.txt"
                local _awk_extdup_tmp="/tmp/movie_awk_extdup_$$.txt"
                > "$_awk_extdup_tmp"
                
                printf "${CYAN}[Filtering %d non-linked files]${NC}" "$_nonlinked_total" >&2
                
                # Single awk pass: categorize + check extension duplicates
                # (replaces per-file tr/basename/regex/grep — ~100x faster)
                local _awk_counts
                _awk_counts=$(awk -v main_out="$_awk_main_tmp" -v extras_out="$nonlinked_extras_tmp" \
                    -v extdup_out="$_awk_extdup_tmp" '
                FILENAME == ARGV[1] {
                    split($0, a, "|")
                    if (!(a[1] in dk)) dk[a[1]] = a[2]
                    next
                }
                {
                    path = $0
                    if (path == "") next
                    lpath = tolower(path)
                    n = split(path, parts, "/")
                    lbname = tolower(parts[n])
                    if (lpath ~ /\/subs?\//) next
                    if (lpath ~ /\/subtitles\//) next
                    if (lbname ~ /sample/) { samples++; print path > extras_out; next }
                    if (lbname ~ /[Ss][0-9]+[Ee][0-9]+/) { tveps++; next }
                    if (lpath ~ /\/extras[-_.]?[^\/]*\// || lpath ~ /\/extras$/ ||
                        lpath ~ /[^a-z]extras[-_.]?[^\/]*\// ||
                        lpath ~ /\/featurettes?[-_.]?[^\/]*\// || lpath ~ /\/featurettes?$/ ||
                        lpath ~ /\/bonus(es)?[-_.]?[^\/]*\// || lpath ~ /\/bonus(es)?$/ ||
                        lpath ~ /\/deleted scenes?\// || lpath ~ /\/behind the scenes?\// ||
                        lpath ~ /\/interviews[-_.]?[^\/]*\// || lpath ~ /\/interviews$/ ||
                        lpath ~ /\/trailers?[-_.]?[^\/]*\// || lpath ~ /\/trailers?$/ ||
                        lpath ~ /\/clips?[-_.]?[^\/]*\// || lpath ~ /\/clips?$/ ||
                        lpath ~ /\/shorts?[-_.]?[^\/]*\// || lpath ~ /\/shorts?$/ ||
                        lbname ~ /^trailer/ || lbname ~ /[-.]trailer[-.]/ ||
                        lbname ~ /(behind.the.scene|deleted.scene|featurette|outtake|gag.reel|theme.music|backdrop)/ ||
                        lbname ~ /\[(trailer|behind.the.scene|deleted.scene|interview|scene|sample|short|featurette|clip|other|extra|bonus|theme.music|backdrop|making.of|outtake|gag.reel)/ ||
                        lpath ~ /\/making.of\// || lpath ~ /\/making.of$/) {
                        extras++; print path > extras_out; next
                    }
                    gkey = path; sub(/\.[^.]*$/, "", gkey)
                    if (gkey in dk && dk[gkey] != path) {
                        printf "%s\t%s\n", path, dk[gkey] > extdup_out; next
                    }
                    print path > main_out
                }
                END { printf "%d %d %d", samples+0, tveps+0, extras+0 }
                ' "$_ext_dup_lookup" "$nonlinked_files_tmp")
                
                # Parse awk counts: samples tveps extras
                skipped_samples=${_awk_counts%% *}
                local _rest=${_awk_counts#* }
                local _tv_skip=${_rest%% *}
                skipped_extras=$(( ${_rest#* } + _tv_skip ))
                
                # Load main files into VIDEO_FILES
                if [[ -s "$_awk_main_tmp" ]]; then
                    while IFS= read -r file; do
                        VIDEO_FILES+=("$file")
                    done < "$_awk_main_tmp"
                fi
                
                # Handle ext_dup candidates (stat for size comparison — few files)
                if [[ -s "$_awk_extdup_tmp" ]]; then
                    while IFS=$'\t' read -r file linked_src; do
                        local _file_size=$(_stat_size "$file" || echo 0)
                        local _linked_size=$(_stat_size "$linked_src" || echo 0)
                        if [[ $_linked_size -ge $_file_size ]]; then
                            ((skipped_ext_dups++)) || true
                        else
                            VIDEO_FILES+=("$file")
                        fi
                    done < "$_awk_extdup_tmp"
                fi
                
                rm -f "$_awk_main_tmp" "$_awk_extdup_tmp" 2>/dev/null
            printf "\r\033[K" >&2
            
            # Clean up temp files (keep linked_pairs_tmp for extension duplicate scan)
            rm -f "$source_inodes_tmp" "$nonlinked_files_tmp" "$_ext_dup_lookup" 2>/dev/null
            # NOTE: linked_pairs_tmp is cleaned up later after extension duplicate scan
            
            else
                # No destination map - process all files with find (original behavior)
                # Use single awk pass for bulk categorization (no per-file subprocesses)
                local _find_tmp="/tmp/movie_find_results_$$.txt"
                local _awk_main="/tmp/movie_awk_main_$$.txt"
                
                eval "$find_cmd" 2>/dev/null | tr '\0' '\n' > "$_find_tmp"
                local _find_total=$(wc -l < "$_find_tmp" | tr -d ' ')
                printf "${CYAN}[%d files found — filtering]${NC}" "$_find_total" >&2
                
                # Single awk pass categorizes all files
                # (replaces per-file tr/basename/regex — ~100x faster)
                local _awk_counts
                _awk_counts=$(awk -v main_out="$_awk_main" -v extras_out="$nonlinked_extras_tmp" '
                {
                    path = $0
                    if (path == "") next
                    lpath = tolower(path)
                    n = split(path, parts, "/")
                    lbname = tolower(parts[n])
                    if (lpath ~ /\/subs?\//) next
                    if (lpath ~ /\/subtitles\//) next
                    if (lbname ~ /sample/) { samples++; print path > extras_out; next }
                    if (lbname ~ /[Ss][0-9]+[Ee][0-9]+/) { tveps++; next }
                    if (lpath ~ /\/extras[-_.]?[^\/]*\// || lpath ~ /\/extras$/ ||
                        lpath ~ /[^a-z]extras[-_.]?[^\/]*\// ||
                        lpath ~ /\/featurettes?[-_.]?[^\/]*\// || lpath ~ /\/featurettes?$/ ||
                        lpath ~ /\/bonus(es)?[-_.]?[^\/]*\// || lpath ~ /\/bonus(es)?$/ ||
                        lpath ~ /\/deleted scenes?\// || lpath ~ /\/behind the scenes?\// ||
                        lpath ~ /\/interviews[-_.]?[^\/]*\// || lpath ~ /\/interviews$/ ||
                        lpath ~ /\/trailers?[-_.]?[^\/]*\// || lpath ~ /\/trailers?$/ ||
                        lpath ~ /\/clips?[-_.]?[^\/]*\// || lpath ~ /\/clips?$/ ||
                        lpath ~ /\/shorts?[-_.]?[^\/]*\// || lpath ~ /\/shorts?$/ ||
                        lbname ~ /^trailer/ || lbname ~ /[-.]trailer[-.]/ ||
                        lbname ~ /(behind.the.scene|deleted.scene|featurette|outtake|gag.reel|theme.music|backdrop)/ ||
                        lbname ~ /\[(trailer|behind.the.scene|deleted.scene|interview|scene|sample|short|featurette|clip|other|extra|bonus|theme.music|backdrop|making.of|outtake|gag.reel)/ ||
                        lpath ~ /\/making.of\// || lpath ~ /\/making.of$/) {
                        extras++; print path > extras_out; next
                    }
                    print path > main_out
                }
                END { printf "%d %d %d", samples+0, tveps+0, extras+0 }
                ' "$_find_tmp")
                
                # Parse awk counts: samples tveps extras
                skipped_samples=${_awk_counts%% *}
                local _rest=${_awk_counts#* }
                local _tv_skip=${_rest%% *}
                skipped_extras=$(( ${_rest#* } + _tv_skip ))
                
                # Load main files into VIDEO_FILES
                if [[ -s "$_awk_main" ]]; then
                    while IFS= read -r file; do
                        VIDEO_FILES+=("$file")
                    done < "$_awk_main"
                fi
                
                rm -f "$_find_tmp" "$_awk_main" 2>/dev/null
                printf "\r\033[K" >&2
            fi
            
            # Show skip statistics
            if [[ $skipped_already_linked -gt 0 || $skipped_samples -gt 0 || $skipped_extras -gt 0 || $skipped_ext_dups -gt 0 ]]; then
                echo "" >&2
                if [[ $skipped_already_linked -gt 0 ]]; then
                    # Show category breakdown of already-linked files (scan totals minus non-linked counts)
                    local _linked_extras=$((src_extras - skipped_extras - skipped_samples))
                    local _linked_main=$((skipped_already_linked - _linked_extras))
                    [[ $_linked_extras -lt 0 ]] && _linked_extras=0
                    [[ $_linked_main -lt 0 ]] && _linked_main=$skipped_already_linked
                    echo "[SKIP SUMMARY] Skipped $skipped_already_linked already-linked file(s): $_linked_main main, $_linked_extras extras" >&2
                fi
                local skipped_non_main=$((skipped_samples + skipped_extras))
                if [[ $skipped_non_main -gt 0 ]]; then
                    echo "[SKIP SUMMARY] Skipped $skipped_non_main non-linked extras file(s)" >&2
                fi
                if [[ $skipped_ext_dups -gt 0 ]]; then
                    echo "[SKIP SUMMARY] Skipped $skipped_ext_dups extension duplicate(s) (better quality already linked)" >&2
                fi
            fi
            
            # Track which subfolders have video files collected (for empty folder detection)
            # Create a temp file to track subfolders that have files
            local folders_with_files_tmp="${CACHE_DIR}/.folders_with_files_$$.tmp"
            for vf in "${VIDEO_FILES[@]}"; do
                # Get the relative path from SOURCE
                local rel="${vf#$SOURCE/}"
                # Get the first component (immediate subfolder)
                local subfolder="${rel%%/*}"
                if [[ -n "$subfolder" && "$subfolder" != "$rel" ]]; then
                    echo "$subfolder" >> "$folders_with_files_tmp"
                fi
            done
            
            # Check for empty subfolders (subfolders with no video files found)
            # Only show this warning if no files were skipped due to already being linked
            # (when files are already linked, it's expected that folders appear "empty")
            if [[ -d "$SOURCE" ]] && [[ $skipped_already_linked -eq 0 ]]; then
                local empty_folder_count=0
                local empty_folders_list=""
                while IFS= read -r subfolder; do
                    [[ -d "$SOURCE/$subfolder" ]] || continue
                    # Check if this subfolder has any video files collected
                    if [[ -f "$folders_with_files_tmp" ]]; then
                        if ! grep -qFx "$subfolder" "$folders_with_files_tmp" 2>/dev/null; then
                            ((empty_folder_count++)) || true
                            empty_folders_list+="  ⚠️  $subfolder"$'\n'
                        fi
                    else
                        # No files collected at all
                        ((empty_folder_count++)) || true
                        empty_folders_list+="  ⚠️  $subfolder"$'\n'
                    fi
                done < <(ls -1 "$SOURCE" 2>/dev/null)
                
                if [[ $empty_folder_count -gt 0 ]]; then
                    echo "" >&2
                    echo -e "${YELLOW}[WARNING] $empty_folder_count source folder(s) have NO video files collected:${NC}" >&2
                    echo "$empty_folders_list" >&2
                    echo -e "${DIM}(These folders may be empty, contain only extras, or have unsupported file types)${NC}" >&2
                fi
            fi
            rm -f "$folders_with_files_tmp" 2>/dev/null
            
            if [[ ${#VIDEO_FILES[@]} -eq 0 ]]; then
                if [[ $skipped_already_linked -gt 0 || $skipped_ext_dups -gt 0 ]]; then
                    local total_skipped=$((skipped_already_linked + skipped_ext_dups + skipped_extras + skipped_samples))
                    print_success "All ${total_skipped} file(s) in $(basename "$SOURCE") already linked/processed - nothing new to do"
                else
                    print_warning "No video files found in: $SOURCE"
                fi
                continue
            fi
            
            print_success "Found ${#VIDEO_FILES[@]} video file(s) in $(basename "$SOURCE")"
            should_debug high && echo "[DEBUG] Files found in source '$SOURCE':" >&2
            should_debug high && for vf in "${VIDEO_FILES[@]}"; do echo "[DEBUG]   - $vf" >&2; done
            
            # Add to global array
            ALL_VIDEO_FILES+=("${VIDEO_FILES[@]}")
        else
            print_error "Source is neither a file nor a directory: $SOURCE"
            continue
        fi
    done
    
    # Check if we collected any files at all
    local all_pre_linked=false
    if [[ ${#ALL_VIDEO_FILES[@]} -eq 0 ]]; then
        if [[ $pre_linked_count -gt 0 ]]; then
            echo ""
            print_success "All files across all sources are already linked - nothing new to process"
            echo ""
            all_pre_linked=true
            # Initialize variables needed by statistics section
            local ORIGINAL_FILE_COUNT=0
            local overall_success=0
            local overall_already_existed=$pre_linked_count
            local overall_skipped=0
            local overall_failed=0
            local overall_size=0
            
            # Process non-linked extras even when all main files are linked
            local linked_folders_file="/tmp/movie_linked_folders_$$.txt"
            local nonlinked_extras_file="/tmp/movie_nonlinked_extras_$$.txt"
            if [[ "$HARDLINK_EXTRAS" == "true" ]] || [[ "$HARDLINK_EXTRAS" == "no-rename" ]] || [[ "$HARDLINK_EXTRAS" == "preserve" ]]; then
                if [[ -s "$nonlinked_extras_file" ]] && [[ -s "$linked_folders_file" ]]; then
                    local extras_to_link=$(wc -l < "$nonlinked_extras_file" | tr -d ' ')
                    if [[ $extras_to_link -gt 0 ]]; then
                        echo ""
                        print_info "Linking $extras_to_link non-linked extras file(s)..."
                        
                        local _sorted_fmap="/tmp/movie_sorted_fmap_$$.txt"
                        sort -u "$linked_folders_file" > "$_sorted_fmap" 2>/dev/null
                        
                        local extras_processed=0
                        while IFS= read -r extra_file; do
                            [[ -z "$extra_file" ]] && continue
                            [[ ! -f "$extra_file" ]] && continue
                            
                            local _search_dir
                            _search_dir=$(dirname "$extra_file")
                            local _matched_src="" _matched_dest=""
                            while [[ -n "$_search_dir" ]] && [[ "$_search_dir" != "/" ]]; do
                                _matched_dest=$(grep -F "$_search_dir|" "$_sorted_fmap" 2>/dev/null | head -1 | cut -d'|' -f2)
                                if [[ -n "$_matched_dest" ]]; then
                                    _matched_src="$_search_dir"
                                    break
                                fi
                                _search_dir=$(dirname "$_search_dir")
                            done
                            
                            [[ -z "$_matched_dest" ]] && continue
                            
                            # Categorize extras into standard subfolder by filename (path is fallback)
                            local _ef_bn=$(basename "$extra_file")
                            local _ef_bl=$(echo "$_ef_bn" | tr '[:upper:]' '[:lower:]')
                            local _target_folder=""
                            
                            # Check filename for category
                            if [[ "$_ef_bl" =~ (behind.?the.?scene|bts|making.?of) ]]; then
                                _target_folder="behind the scenes"
                            elif [[ "$_ef_bl" =~ deleted.?scene ]]; then
                                _target_folder="deleted scenes"
                            elif [[ "$_ef_bl" =~ interview ]]; then
                                _target_folder="interviews"
                            elif [[ "$_ef_bl" =~ sample ]]; then
                                _target_folder="samples"
                            elif [[ "$_ef_bl" =~ short ]]; then
                                _target_folder="shorts"
                            elif [[ "$_ef_bl" =~ featurette ]]; then
                                _target_folder="featurettes"
                            elif [[ "$_ef_bl" =~ clip ]]; then
                                _target_folder="clips"
                            elif [[ "$_ef_bl" =~ scene ]]; then
                                _target_folder="scenes"
                            elif [[ "$_ef_bl" =~ trailer ]]; then
                                _target_folder="trailers"
                            elif [[ "$_ef_bl" =~ (extra|bonus) ]]; then
                                _target_folder="extras"
                            fi
                            
                            # Fall back to path-based categorization
                            if [[ -z "$_target_folder" ]]; then
                                local _ef_path_lower=$(echo "$extra_file" | tr '[:upper:]' '[:lower:]')
                                if [[ "$_ef_path_lower" =~ /(behind.?the.?scenes?|bts|making.?of)/ ]]; then
                                    _target_folder="behind the scenes"
                                elif [[ "$_ef_path_lower" =~ /deleted.?scenes?/ ]]; then
                                    _target_folder="deleted scenes"
                                elif [[ "$_ef_path_lower" =~ /interviews?/ ]]; then
                                    _target_folder="interviews"
                                elif [[ "$_ef_path_lower" =~ /samples?/ ]]; then
                                    _target_folder="samples"
                                elif [[ "$_ef_path_lower" =~ /shorts?/ ]]; then
                                    _target_folder="shorts"
                                elif [[ "$_ef_path_lower" =~ /featurettes?/ ]]; then
                                    _target_folder="featurettes"
                                elif [[ "$_ef_path_lower" =~ /clips?/ ]]; then
                                    _target_folder="clips"
                                elif [[ "$_ef_path_lower" =~ /trailers?/ ]]; then
                                    _target_folder="trailers"
                                elif [[ "$_ef_path_lower" =~ /extras?/ ]]; then
                                    _target_folder="extras"
                                elif [[ "$_ef_path_lower" =~ /bonus/ ]]; then
                                    _target_folder="extras"
                                elif [[ "$_ef_path_lower" =~ /scenes?/ ]]; then
                                    _target_folder="scenes"
                                elif [[ "$_ef_path_lower" =~ /other/ ]]; then
                                    _target_folder="other"
                                else
                                    _target_folder="extras"
                                fi
                            fi
                            
                            local _dest_file="${_matched_dest}/${_target_folder}/${_ef_bn}"
                            local _dest_dir="${_matched_dest}/${_target_folder}"
                            
                            if [[ ! -f "$_dest_file" ]]; then
                                mkdir -p "$_dest_dir" 2>/dev/null
                                ln "$extra_file" "$_dest_file" 2>/dev/null && ((extras_processed++)) || true
                            fi
                        done < "$nonlinked_extras_file"
                        
                        rm -f "$_sorted_fmap" 2>/dev/null
                        
                        if [[ $extras_processed -gt 0 ]]; then
                            print_success "Hardlinked $extras_processed extras file(s)"
                        else
                            print_info "All extras already linked"
                        fi
                    fi
                fi
            fi
            rm -f "$linked_folders_file" "$nonlinked_extras_file" 2>/dev/null
        else
            print_error "No video files found in any source"
            exit 1
        fi
    fi
    
    if [[ "$all_pre_linked" != "true" ]]; then
    
    # Sort files alphabetically by basename (filename only), case-insensitive
    local _allvf_sort_tmp="/tmp/movie_allvf_sort_$$.txt"
    printf '%s\n' "${ALL_VIDEO_FILES[@]}" | awk -F'/' '{print tolower($NF)"\t"$0}' | sort -k1,1 | cut -f2- > "$_allvf_sort_tmp"
    ALL_VIDEO_FILES=(); while IFS= read -r f; do ALL_VIDEO_FILES+=("$f"); done < "$_allvf_sort_tmp"
    rm -f "$_allvf_sort_tmp" 2>/dev/null
    
    echo ""
    print_success "Total video files collected from all sources: ${#ALL_VIDEO_FILES[@]}"
    
    # Deduplicate by inode (same file via different paths/symlinks)
    local duplicate_path_count=0
    if [[ $pre_linked_count -gt 0 ]]; then
        # Inode scan already ensured unique inodes — files came from nonlinked_files_tmp
        # which was built by awk split on unique inodes. No re-stat needed.
        :
    elif [[ ! -s "$temp_dest_map" ]]; then
        # No destination files — no hardlinks exist, so no inode duplicates possible. Skip stat.
        :
    else
    # Fallback: single xargs stat + awk — no per-file forks
    local temp_inode_dedup="/tmp/movie_inode_dedup_$$.txt"
    local temp_unique_files="/tmp/movie_unique_files_$$.txt"
    printf '%s\0' "${ALL_VIDEO_FILES[@]}" | xargs -0 stat "$_STAT_FMT_FLAG" "$_STAT_INODE_NAME_FMT" 2>/dev/null > "$temp_inode_dedup" || true
    
    # Single awk pass: keep first occurrence per inode
    awk -F'|' '!seen[$1]++ { print $2 }' "$temp_inode_dedup" > "$temp_unique_files"
    duplicate_path_count=$(( $(wc -l < "$temp_inode_dedup" | tr -d ' ') - $(wc -l < "$temp_unique_files" | tr -d ' ') ))
    
    if [[ $duplicate_path_count -gt 0 ]]; then
        print_info "Filtered out $duplicate_path_count duplicate path(s) (same file via multiple paths/symlinks)"
        ALL_VIDEO_FILES=()
        while IFS= read -r f; do ALL_VIDEO_FILES+=("$f"); done < "$temp_unique_files"
        print_success "Unique files after deduplication: ${#ALL_VIDEO_FILES[@]}"
    fi
    rm -f "$temp_inode_dedup" "$temp_unique_files" 2>/dev/null
    fi
    
    # Filter out .ia files if non-.ia version exists
    # Internet Archive often creates .ia.mp4 duplicates alongside .mp4 originals
    # Quick check: only scan if any .ia files exist in the list
    local skipped_ia_count=0
    local _has_ia=false
    for file in "${ALL_VIDEO_FILES[@]}"; do
        if [[ "$file" == *.ia.* ]]; then _has_ia=true; break; fi
    done
    if [[ "$_has_ia" == "true" ]]; then
        local -a FILTERED_FILES=()
        for file in "${ALL_VIDEO_FILES[@]}"; do
            if [[ "$file" =~ \.ia\.[^.]+$ ]]; then
                local non_ia_file="${file/.ia./.}"
                if [[ -f "$non_ia_file" ]]; then
                    should_debug low && echo "[DEBUG] Filtering out .ia duplicate: $file" >&2
                    ((skipped_ia_count++)) || true
                    continue
                fi
            fi
            FILTERED_FILES+=("$file")
        done
        ALL_VIDEO_FILES=("${FILTERED_FILES[@]}")
        if [[ $skipped_ia_count -gt 0 ]]; then
            print_info "Filtered out $skipped_ia_count Internet Archive duplicate(s) (.ia files)"
        fi
    fi
    
    echo ""
    
    # ═══════════════════════════════════════════════════════════════════════════════
    # SOURCE FILE CATEGORIZATION: Use pre-built destination inode map
    # ═══════════════════════════════════════════════════════════════════════════════
    # NOTE: Destination inode map was already built BEFORE file collection
    # Files already linked were skipped during collection (optimization)
    # This step categorizes remaining files for processing and cache sync
    
    local dest_file_count=$(wc -l < "$temp_dest_map" 2>/dev/null | tr -d ' ')
    should_debug low && echo "[DEBUG] Destination inode map has $dest_file_count entries" >&2
    
    # Check if cache needs syncing (empty or nearly empty compared to destination)
    local cache_entry_count=0
    if [[ -f "$CACHE_FILE" ]]; then
        cache_entry_count=$(wc -l < "$CACHE_FILE" 2>/dev/null | tr -d ' ')
    fi
    local need_cache_sync=false
    if [[ $cache_entry_count -lt $((dest_file_count / 2)) && $dest_file_count -gt 0 ]]; then
        need_cache_sync=true
        print_info "Cache has $cache_entry_count entries, destination has $dest_file_count files - will sync metadata"
    fi
    
    # Show count of already-linked files (skipped during collection)
    if [[ $pre_linked_count -gt 0 ]]; then
        print_success "Skipped $pre_linked_count already-linked file(s) during collection (inode match)"
        
        # Count linked sample/extras files for user info (from linked_pairs_file)
        local linked_pairs_file="/tmp/movie_linked_pairs_$$.txt"
        if [[ -s "$linked_pairs_file" ]]; then
            # Single awk pass to categorize linked pairs (no per-file tr/basename forks)
            local _linked_breakdown
            _linked_breakdown=$(awk -F'|' '{
                p = tolower($1)
                n = p; sub(/.*\//, "", n)
                if (n ~ /sample/) { e++ }
                else if (p ~ /\/extras\// || p ~ /\/featurettes?\// || p ~ /\/bonus\// ||
                         p ~ /\/behind.the.scenes\// || p ~ /\/deleted.scenes?\// || p ~ /\/trailers?\//) { e++ }
                else { m++ }
            } END { print m+0, e+0 }' "$linked_pairs_file")
            local linked_main=${_linked_breakdown%% *}
            local linked_extras=${_linked_breakdown#* }
            print_info "  └─ Already linked: $linked_main main movies | $linked_extras extras"
        fi
    fi
    
    # NOTE: Non-linked extras are handled by process_file() during main processing
    # (process_file scans source_dir for extras folders and loose extras files)
    # Clean up pre-processing temp files
    rm -f "$linked_folders_file" "$nonlinked_extras_file" 2>/dev/null
    
    # Categorize remaining source files (most already filtered during collection)
    local temp_linked="/tmp/movie_linked_$$.txt"
    local temp_notlinked="/tmp/movie_notlinked_$$.txt"
    > "$temp_linked"
    > "$temp_notlinked"
    
    local source_total=${#ALL_VIDEO_FILES[@]}
    local use_parallel_filter=false
    local filter_jobs=1
    
    # SKIP categorization entirely if inode scan already filtered linked files
    # (all remaining files are guaranteed non-linked — no stat/grep needed)
    if [[ $pre_linked_count -gt 0 ]] || [[ ! -s "$temp_dest_map" ]]; then
        # Files already filtered by inode scan, or dest is empty — all go to notlinked
        printf '%s\n' "${ALL_VIDEO_FILES[@]}" > "$temp_notlinked"
    else
    
    # Bulk categorization: single xargs stat + awk join (no per-file subshells)
    print_info "Categorizing ${#ALL_VIDEO_FILES[@]} remaining source files..."
    local _cat_src_inodes="/tmp/movie_cat_inodes_$$.txt"
    printf '%s\n' "${ALL_VIDEO_FILES[@]}" > "$_cat_src_inodes.list"
    xargs stat "$_STAT_FMT_FLAG" "$_STAT_INODE_NAME_FMT" < "$_cat_src_inodes.list" 2>/dev/null > "$_cat_src_inodes" || true
    rm -f "$_cat_src_inodes.list" 2>/dev/null
    
    # awk join: match source inodes against dest map in one pass
    awk -F'|' -v linked="$temp_linked" -v notlinked="$temp_notlinked" -v linked_hl="${CACHE_DIR}/.successfully_hardlinked_$$.tmp" '
        NR==FNR { dest[$1]=$0; next }
        {
            inode=$1; src=$2
            if (inode in dest) {
                print src"|"dest[inode] > linked
                n=split(src, parts, "/")
                if (n >= 2) print parts[n-1] > linked_hl
            } else {
                print src > notlinked
            }
        }
    ' "$temp_dest_map" "$_cat_src_inodes"
    rm -f "$_cat_src_inodes" 2>/dev/null
    
    fi  # end of pre_linked_count skip
    
    # Count results
    local already_linked_count=$(wc -l < "$temp_linked" 2>/dev/null | tr -d ' ')
    local cache_synced_count=0
    
    # Sync to cache if needed
    if [[ "$need_cache_sync" == "true" && $already_linked_count -gt 0 ]]; then
        print_info "Syncing metadata to cache..."
        
        # Debug: Show environment
        if [[ -n "$TMDB_API_KEY" ]]; then
            print_info "TMDb API Key: configured (${#TMDB_API_KEY} chars)"
        else
            print_warning "TMDb API Key: NOT SET - API lookups will fail!"
        fi
        
        # Use main menu settings but throttle to not exceed 45 API/sec
        # Calculate minimum delay needed: with N jobs, need delay >= N/45 to stay under 45/sec
        local DEST_SYNC_JOBS=${PARALLEL_JOBS:-8}
        local DEST_SYNC_API_DELAY=${API_DELAY:-0.01}
        
        # Throttle: ensure we don't exceed 45 API calls per second
        # min_delay = jobs / 45 (e.g., 14 jobs needs 0.31s delay minimum)
        local min_delay_for_rate=$(awk "BEGIN {printf \"%.2f\", $DEST_SYNC_JOBS / 45}")
        if (( $(awk "BEGIN {print ($DEST_SYNC_API_DELAY < $min_delay_for_rate) ? 1 : 0}") )); then
            DEST_SYNC_API_DELAY="$min_delay_for_rate"
            print_info "Throttled API delay to ${DEST_SYNC_API_DELAY}s (to stay under 45/sec with $DEST_SYNC_JOBS jobs)"
        fi
        
        export DEST_SYNC_API_DELAY TMDB_API_KEY TMDB_API_BASE CACHE_FILE
        print_info "Using API delay: ${DEST_SYNC_API_DELAY}s between calls"
        print_info "Parallel processing: $DEST_SYNC_JOBS jobs"
        
        # ====================================================================
        # SCAN DESTINATION FOLDERS DIRECTLY (top level only)
        # ====================================================================
        print_info "Scanning destination folders..."
        local temp_dest_folders=$(mktemp)
        
        # Find top-level movie folders only (maxdepth 1)
        find "$DESTINATION" -maxdepth 1 -type d 2>/dev/null | grep -E '\([0-9]{4}\)' | sort -u > "$temp_dest_folders"
        
        local total_dest_folders=$(wc -l < "$temp_dest_folders" | tr -d ' ')
        print_info "Found $total_dest_folders movie folders in destination"
        
        # This section intentionally empty - processing moved to batch loop below
        
        # Build list of folders not yet in cache
        local temp_folders_to_sync=$(mktemp)
        local temp_seen_ids=$(mktemp)
        local already_cached=0
        local no_id_folders=0
        local unique_to_sync=0
        
        while IFS= read -r folder_path; do
            [[ -z "$folder_path" ]] && continue
            
            local folder_name=$(basename "$folder_path")
            local f_imdb="" f_tmdb="" f_tvdb="" f_id=""
            
            # Extract IDs
            [[ "$folder_name" =~ \[imdbid-(tt[0-9]+)\] ]] && f_imdb="${BASH_REMATCH[1]}"
            [[ "$folder_name" =~ \[imdb-(tt[0-9]+)\] ]] && f_imdb="${BASH_REMATCH[1]}"
            [[ "$folder_name" =~ \{imdb-(tt[0-9]+)\} ]] && f_imdb="${BASH_REMATCH[1]}"
            [[ "$folder_name" =~ (tt[0-9]{7,}) ]] && f_imdb="${BASH_REMATCH[1]}"
            [[ "$folder_name" =~ \[tmdbid-([0-9]+)\] ]] && f_tmdb="${BASH_REMATCH[1]}"
            [[ "$folder_name" =~ \[tmdb-([0-9]+)\] ]] && f_tmdb="${BASH_REMATCH[1]}"
            [[ "$folder_name" =~ \{tmdb-([0-9]+)\} ]] && f_tmdb="${BASH_REMATCH[1]}"
            [[ "$folder_name" =~ \[tvdbid-([0-9]+)\] ]] && f_tvdb="${BASH_REMATCH[1]}"
            [[ "$folder_name" =~ \[tvdb-([0-9]+)\] ]] && f_tvdb="${BASH_REMATCH[1]}"
            [[ "$folder_name" =~ \{tvdb-([0-9]+)\} ]] && f_tvdb="${BASH_REMATCH[1]}"
            
            # Skip folders without any IDs
            if [[ -z "$f_imdb" && -z "$f_tmdb" && -z "$f_tvdb" ]]; then
                ((no_id_folders++)) || true
                continue
            fi
            
            f_id="${f_imdb:-${f_tmdb:+tmdb:$f_tmdb}}"
            [[ -z "$f_id" ]] && f_id="tvdb:$f_tvdb"
            
            # Check if already in cache
            local in_cache=0
            if [[ -n "$f_imdb" ]] && grep -qE "^[^|]*\|[^|]*\|${f_imdb}\|" "$CACHE_FILE" 2>/dev/null; then
                in_cache=1
            elif [[ -n "$f_tmdb" ]] && grep -qE "^[^|]*\|[^|]*\|[^|]*\|${f_tmdb}\|" "$CACHE_FILE" 2>/dev/null; then
                in_cache=1
            fi
            
            if [[ $in_cache -eq 1 ]]; then
                ((already_cached++)) || true
                continue
            fi
            
            # Skip duplicates
            if grep -Fxq "$f_id" "$temp_seen_ids" 2>/dev/null; then
                continue
            fi
            
            echo "$f_id" >> "$temp_seen_ids"
            echo "$folder_path" >> "$temp_folders_to_sync"
            ((unique_to_sync++)) || true
        done < "$temp_dest_folders"
        
        rm -f "$temp_seen_ids" "$temp_dest_folders" 2>/dev/null
        
        # Show statistics
        if [[ $no_id_folders -gt 0 ]]; then
            print_info "Skipped $no_id_folders folder(s) - no IMDb/TMDb ID found"
        fi
        if [[ $already_cached -gt 0 ]]; then
            print_info "Skipped $already_cached folder(s) - already in cache"
        fi
        
        local total_to_check=$unique_to_sync
        if [[ $total_to_check -gt 0 ]]; then
            # Build array of folder names for processing (same as cache management)
            local -a dest_missing_entries=()
            while IFS= read -r folder_path; do
                dest_missing_entries+=("$(basename "$folder_path")")
            done < "$temp_folders_to_sync"
            
            echo ""
            echo -e "${CYAN}Adding $total_to_check destination folders to cache...${NC}"
            echo -e "${DIM}Using API delay: ${DEST_SYNC_API_DELAY}s between calls${NC}"
            echo -e "${DIM}Parallel processing: ${DEST_SYNC_JOBS} jobs${NC}"
            
            local added=0
            local api_calls=0
            local sync_start_time=$SECONDS
            
            # ====================================================================
            # PARALLEL PROCESSING - SAME AS CACHE MANAGEMENT
            # ====================================================================
            local total_entries=${#dest_missing_entries[@]}
            local entry_index=0
            local batch_size=$DEST_SYNC_JOBS
            local temp_results="/tmp/cache_sync_results_$$.txt"
            local temp_progress="/tmp/cache_sync_progress_$$.txt"
            > "$temp_results"
            > "$temp_progress"
            
            while [[ $entry_index -lt $total_entries ]]; do
                local batch_pids=()
                local -a batch_folders=()
                
                for ((i=0; i<batch_size && entry_index<total_entries; i++)); do
                    local folder_name="${dest_missing_entries[$entry_index]}"
                    batch_folders+=("$folder_name")
                    ((entry_index++)) || true
                    
                    # Extract title and year for progress message
                    local display_title=$(echo "$folder_name" | sed -E 's/[[:space:]]*\([0-9]{4}\).*//' | sed -E 's/[[:space:]]*\[.*//')
                    local display_year=""
                    [[ "$folder_name" =~ \(([0-9]{4})\) ]] && display_year="${BASH_REMATCH[1]}"
                    
                    # Check if API call will be needed
                    local needs_api=false
                    local has_imdb=false has_tmdb=false
                    [[ "$folder_name" =~ \[(imdbid-|imdb-)(tt[0-9]+)\] ]] && has_imdb=true
                    [[ "$folder_name" =~ \[(tmdbid-|tmdb-)([0-9]+)\] ]] && has_tmdb=true
                    [[ "$has_imdb" == true && "$has_tmdb" == false ]] && needs_api=true
                    [[ "$has_imdb" == false && "$has_tmdb" == true ]] && needs_api=true
                    
                    if [[ "$needs_api" == true && -n "$TMDB_API_KEY" ]]; then
                        if [[ "$has_imdb" == true ]]; then
                            echo -e "${DIM}  Fetching TMDb ID for: $display_title ($display_year)...${NC}"
                        else
                            echo -e "${DIM}  Fetching IMDb ID for: $display_title ($display_year)...${NC}"
                        fi
                    fi
                    
                    # Process in background (same logic as cache management)
                    (
                        local folder_title="" folder_year="" folder_imdb="" folder_tmdb="" folder_tvdb=""
                        
                        [[ "$folder_name" =~ \(([0-9]{4})\) ]] && folder_year="${BASH_REMATCH[1]}"
                        
                        if [[ "$folder_name" =~ \[imdbid-(tt[0-9]+)\] ]]; then folder_imdb="${BASH_REMATCH[1]}"
                        elif [[ "$folder_name" =~ \[imdb-(tt[0-9]+)\] ]]; then folder_imdb="${BASH_REMATCH[1]}"
                        elif [[ "$folder_name" =~ \{imdb-(tt[0-9]+)\} ]]; then folder_imdb="${BASH_REMATCH[1]}"
                        fi
                        
                        if [[ "$folder_name" =~ \[tmdbid-([0-9]+)\] ]]; then folder_tmdb="${BASH_REMATCH[1]}"
                        elif [[ "$folder_name" =~ \[tmdb-([0-9]+)\] ]]; then folder_tmdb="${BASH_REMATCH[1]}"
                        elif [[ "$folder_name" =~ \{tmdb-([0-9]+)\} ]]; then folder_tmdb="${BASH_REMATCH[1]}"
                        fi
                        
                        if [[ "$folder_name" =~ \[tvdbid-([0-9]+)\] ]]; then folder_tvdb="${BASH_REMATCH[1]}"
                        elif [[ "$folder_name" =~ \[tvdb-([0-9]+)\] ]]; then folder_tvdb="${BASH_REMATCH[1]}"
                        elif [[ "$folder_name" =~ \{tvdb-([0-9]+)\} ]]; then folder_tvdb="${BASH_REMATCH[1]}"
                        fi
                        
                        folder_title=$(echo "$folder_name" | sed -E 's/[[:space:]]*\([0-9]{4}\).*//' | sed -E 's/[[:space:]]*\[.*//')
                        
                        local api_made=0
                        local canonical_title=""
                        if [[ -n "$folder_imdb" && -z "$folder_tmdb" && -n "$TMDB_API_KEY" ]]; then
                            sleep "$DEST_SYNC_API_DELAY"
                            local find_url="${TMDB_API_BASE}/find/${folder_imdb}?api_key=${TMDB_API_KEY}&external_source=imdb_id"
                            local find_result=$(curl -s "$find_url" 2>/dev/null)
                            folder_tmdb=$(echo "$find_result" | grep -oE '"id":[0-9]+' | head -1 | grep -oE '[0-9]+')
                            # Extract canonical title from find result (preserves colons and special chars)
                            canonical_title=$(echo "$find_result" | grep -oE '"title":"[^"]*"' | head -1 | sed 's/"title":"//;s/"//')
                            [[ -n "$canonical_title" ]] && folder_title="$canonical_title"
                            api_made=1
                            [[ -n "$folder_tmdb" ]] && echo "FOUND_TMDB|$folder_tmdb" >> "$temp_progress"
                        elif [[ -n "$folder_tmdb" && -z "$folder_imdb" && -n "$TMDB_API_KEY" ]]; then
                            sleep "$DEST_SYNC_API_DELAY"
                            local movie_url="${TMDB_API_BASE}/movie/${folder_tmdb}?api_key=${TMDB_API_KEY}&append_to_response=external_ids"
                            local movie_result=$(curl -s "$movie_url" 2>/dev/null)
                            folder_imdb=$(echo "$movie_result" | grep -oE '"imdb_id":"tt[0-9]+"' | grep -oE 'tt[0-9]+')
                            # Extract canonical title from movie details (preserves colons and special chars)
                            canonical_title=$(echo "$movie_result" | grep -oE '"title":"[^"]*"' | head -1 | sed 's/"title":"//;s/"//')
                            [[ -n "$canonical_title" ]] && folder_title="$canonical_title"
                            api_made=1
                            [[ -n "$folder_imdb" ]] && echo "FOUND_IMDB|$folder_imdb" >> "$temp_progress"
                        fi
                        
                        if [[ -n "$folder_title" && -n "$folder_year" && ( -n "$folder_imdb" || -n "$folder_tmdb" ) ]]; then
                            local timestamp=$(date +%s)
                            # Write to cache immediately (same as cache management)
                            # Ensure newline exists before appending to prevent cache corruption
                            [[ -f "$CACHE_FILE" ]] && [[ -n "$(tail -c 1 "$CACHE_FILE" 2>/dev/null)" ]] && echo "" >> "$CACHE_FILE"
                            echo "${folder_title}|${folder_year}|${folder_imdb}|${folder_tmdb}|${timestamp}" >> "$CACHE_FILE" 2>/dev/null || true
                            echo "ADDED|$api_made"
                        fi
                    ) >> "$temp_results" &
                    
                    batch_pids+=($!)
                done
                
                # Wait for batch to complete and show results
                for pid in "${batch_pids[@]}"; do
                    wait "$pid"
                done
                
                # Display completion messages for this batch (same as cache management)
                if [[ -f "$temp_progress" ]]; then
                    while IFS='|' read -r msg_type msg_value; do
                        if [[ "$msg_type" == "FOUND_TMDB" ]]; then
                            echo -e "${GREEN}  ✓ Found TMDb ID: $msg_value${NC}"
                        elif [[ "$msg_type" == "FOUND_IMDB" ]]; then
                            echo -e "${GREEN}  ✓ Found IMDb ID: $msg_value${NC}"
                        fi
                    done < "$temp_progress"
                    > "$temp_progress"
                fi
            done
            
            # Count results (cache already written immediately by each subshell)
            while IFS='|' read -r result_type api_made; do
                [[ "$result_type" == "ADDED" ]] && ((added++)) || true
                [[ "$api_made" == "1" ]] && ((api_calls++)) || true
            done < "$temp_results"
            
            rm -f "$temp_results" "$temp_progress"
            
            local sync_elapsed=$((SECONDS - sync_start_time))
            local api_rate=$(awk "BEGIN {printf \"%.2f\", $api_calls / ($sync_elapsed > 0 ? $sync_elapsed : 1)}")
            echo -e "${GREEN}✓ Added $added folders to cache${NC}"
            if [[ $api_calls -gt 0 ]]; then
                echo -e "${DIM}  API calls: $api_calls (${api_rate}/sec average, ${sync_elapsed}s total)${NC}"
            else
                echo -e "${DIM}  API calls: 0 (all IDs found in folder names)${NC}"
            fi
            
            cache_synced_count=$added
        fi
        
        # Cleanup
        rm -f "$temp_folders_to_sync" 2>/dev/null
    fi
    
    # Build array of files not yet linked
    local -a FILES_NOT_YET_LINKED=()
    while IFS= read -r file; do
        [[ -n "$file" ]] && FILES_NOT_YET_LINKED+=("$file")
    done < "$temp_notlinked"
    
    # Clean up temp files
    rm -f "$temp_dest_map" "$temp_linked" "$temp_notlinked" 2>/dev/null
    
    if [[ $already_linked_count -gt 0 ]]; then
        print_success "✓ Skipped $already_linked_count file(s) already hardlinked to destination"
        if [[ $cache_synced_count -gt 0 ]]; then
            print_success "✓ Synced $cache_synced_count entries to cache from destination"
        fi
        ALL_VIDEO_FILES=("${FILES_NOT_YET_LINKED[@]}")
        print_info "Files remaining to process: ${#ALL_VIDEO_FILES[@]}"
    elif [[ $pre_linked_count -gt 0 ]]; then
        # Inode scan already filtered linked files during collection — no 2nd pass needed
        print_info "All ${#ALL_VIDEO_FILES[@]} collected file(s) need processing (linked files already filtered by inode scan)"
    else
        print_info "No files already hardlinked - all ${#ALL_VIDEO_FILES[@]} need processing"
    fi
    
    # Check if there's anything left to process
    if [[ ${#ALL_VIDEO_FILES[@]} -eq 0 ]]; then
        echo ""
        print_success "All files already hardlinked to destination - nothing to do!"
        
        # NOTE: Extras processing already handled earlier (right after inode scan)
        
        exit 0
    fi
    
    echo ""
    
    # Clear temp tracking files from previous runs
    rm -f "${CACHE_DIR}/.missing_cache_ids.tmp"
    rm -f "${CACHE_DIR}/.cached_files.tmp"
    rm -f "${CACHE_DIR}/.duplicate_cache_entries.tmp"
    rm -f "${CACHE_DIR}/.current_run_processed.tmp"
    
    # Save original count before any filtering
    local ORIGINAL_FILE_COUNT=${#ALL_VIDEO_FILES[@]}
    
    # Determine cache mode for work file naming from the actual CACHE_FILE path
    # Extract the distinctive part between "MOVIE"/"SHOWS" and "CACHE.txt"
    # Examples: "MOVIE 4K CACHE.txt" -> "4k", "MOVIE 1080p X RATED CACHE.txt" -> "1080p_xrated"
    local cache_mode=""
    if [[ -n "$CACHE_FILE" ]]; then
        # Extract cache name from file path
        local cache_basename=$(basename "$CACHE_FILE" .txt)
        
        # Remove "MOVIE " or "SHOWS " prefix and " CACHE" suffix
        cache_mode=$(echo "$cache_basename" | sed -E 's/^(MOVIE|SHOWS) //;s/ CACHE$//')
        
        # Replace spaces with underscores for valid filename
        cache_mode=$(echo "$cache_mode" | tr ' ' '_')
        
        # Convert to lowercase for consistency
        cache_mode=$(echo "$cache_mode" | tr '[:upper:]' '[:lower:]')
        
        print_info "Detected cache mode: '$cache_mode' (from: $(basename "$CACHE_FILE"))"
    else
        print_error "CACHE_FILE is not set - cannot determine cache mode"
        exit 1
    fi
    
    # Create instance-specific work tracking
    local INSTANCE_WORK_DIR="/tmp/movie_instance_work"
    mkdir -p "$INSTANCE_WORK_DIR" 2>/dev/null
    local INSTANCE_WORK_FILE="${INSTANCE_WORK_DIR}/working_${cache_mode}_$$.txt"
    
    # Check for other instances working on the same cache
    echo ""
    print_info "Checking for other instances using '${cache_mode}' cache..."
    local -a OTHER_INSTANCE_FILES=()
    local other_count=0
    
    while IFS= read -r -d '' work_file; do
        [[ -z "$work_file" ]] && continue
        local other_pid=$(basename "$work_file" .txt | sed "s/working_${cache_mode}_//")
        
        # Skip our own PID
        [[ "$other_pid" == "$$" ]] && continue
        
        # Check if process is still alive
        if kill -0 "$other_pid" 2>/dev/null; then
            OTHER_INSTANCE_FILES+=("$work_file")
            ((other_count++)) || true
            echo "  Found active instance: PID $other_pid"
        else
            # Clean up stale work file from dead process
            echo "  Cleaning stale work file from dead PID $other_pid"
            rm -f "$work_file" 2>/dev/null
        fi
    done < <(find "$INSTANCE_WORK_DIR" -maxdepth 1 -name "working_${cache_mode}_*.txt" -print0 2>/dev/null)
    
    # Filter out files already claimed by other instances
    if [[ ${#OTHER_INSTANCE_FILES[@]} -gt 0 ]]; then
        print_info "Found ${#OTHER_INSTANCE_FILES[@]} other instance(s) - filtering claimed files..."
        local -a AVAILABLE_FILES=()
        local claimed_count=0
        
        for file in "${ALL_VIDEO_FILES[@]}"; do
            local is_claimed=false
            
            # Check if this file is claimed by any other instance
            for other_work_file in "${OTHER_INSTANCE_FILES[@]}"; do
                if grep -Fxq "$file" "$other_work_file" 2>/dev/null; then
                    is_claimed=true
                    ((claimed_count++)) || true
                    break
                fi
            done
            
            # Only add if not claimed
            if [[ "$is_claimed" == "false" ]]; then
                AVAILABLE_FILES+=("$file")
            fi
        done
        
        print_info "Files already claimed: $claimed_count"
        print_info "Files available for this instance: ${#AVAILABLE_FILES[@]}"
        
        # Sort available files alphabetically by basename before reassigning
        local _avail_sort_tmp="/tmp/movie_avail_sort_$$.txt"
        printf '%s\n' "${AVAILABLE_FILES[@]}" | awk -F'/' '{print tolower($NF)"\t"$0}' | sort -k1,1 | cut -f2- > "$_avail_sort_tmp"
        AVAILABLE_FILES=(); while IFS= read -r f; do AVAILABLE_FILES+=("$f"); done < "$_avail_sort_tmp"
        rm -f "$_avail_sort_tmp" 2>/dev/null
        
        # Update our file list
        ALL_VIDEO_FILES=("${AVAILABLE_FILES[@]}")
        
        if [[ ${#ALL_VIDEO_FILES[@]} -eq 0 ]]; then
            echo ""
            print_warning "No files available - all files already claimed by other instances"
            print_info "Other instances are handling all work for this cache"
            rm -f "$INSTANCE_WORK_FILE" 2>/dev/null
            exit 0
        fi
    else
        print_success "No other instances detected - claiming all ${#ALL_VIDEO_FILES[@]} files"
    fi
    
    # Save our claimed file list and track total for statistics
    printf '%s\n' "${ALL_VIDEO_FILES[@]}" > "$INSTANCE_WORK_FILE"
    local FILES_AFTER_CLAIMING=${#ALL_VIDEO_FILES[@]}
    local PROCESSING_START_TIME=$(date '+%Y-%m-%d %H:%M:%S')
    echo ""
    print_success "Instance PID $$ claimed ${#ALL_VIDEO_FILES[@]} files in: $(basename "$INSTANCE_WORK_FILE")"
    print_info "Start time: $PROCESSING_START_TIME"
    
    # Set up cleanup trap for work file
    trap "rm -f '$INSTANCE_WORK_FILE' 2>/dev/null; trap - EXIT INT TERM" EXIT INT TERM
    
    # Check parsing mode
    local parse_mode_file="$CACHE_DIR/parsing_mode.txt"
    local parsing_mode="fast"
    [[ -f "$parse_mode_file" ]] && parsing_mode=$(cat "$parse_mode_file")
    
    print_info "Parsing mode: $parsing_mode (using ${AWK_PARSER:-awk} parser)"
    
    # Show parallel parsing status
    if [[ "$PARALLEL_PARSING" == "true" ]]; then
        print_info "Parallel parsing: ${GREEN}ENABLED${NC} (${PARALLEL_PARSE_JOBS} concurrent jobs)"
    fi
    
    # All modes do duplicate detection (just implemented differently)
    # Fast or Thorough modes (with or without cache): Do duplicate detection
        
        # Now detect duplicates across ALL sources
        print_info "Scanning for duplicate movies across all sources..."
        should_debug high && echo "[DEBUG] HARDLINK_EXTRAS setting: '$HARDLINK_EXTRAS'" >&2
        print_info "Total video files to check: ${#ALL_VIDEO_FILES[@]}"
        local -a NON_DUPLICATE_FILES=()
        local -a DUPLICATE_FILES=()
        local temp_dup_detect="/tmp/movie_dup_detect_$$"
        local temp_parse_cache="/tmp/movie_parse_cache_$$"
        > "$temp_dup_detect"
        
        # Clean up only OUR temp files from previous runs (if this PID was reused)
        # DO NOT delete other running instances' temp files
        rm -f "/tmp/movie_dup_detect_$$" "/tmp/movie_parse_cache_$$" 2>/dev/null
        
        # Set up trap to clean up temp files on exit/cancel/error
        trap "rm -f '$temp_dup_detect' '$temp_parse_cache' 2>/dev/null" EXIT INT TERM
        
        # Create parse cache in fast and thorough modes (not no-cache modes)
        if [[ "$parsing_mode" == "fast" ]]; then
            > "$temp_parse_cache"
            should_debug high && echo "[DEBUG] Fast mode: Parse caching enabled" >&2
        elif [[ "$parsing_mode" == "thorough" ]]; then
            > "$temp_parse_cache"
            should_debug high && echo "[DEBUG] Thorough mode: Parse caching enabled, will re-parse at each stage" >&2
        elif [[ "$parsing_mode" == "fast-nocache" ]]; then
            should_debug high && echo "[DEBUG] Fast No-Cache mode: Duplicate detection enabled, temp cache disabled" >&2
        elif [[ "$parsing_mode" == "thorough-nocache" ]]; then
            should_debug high && echo "[DEBUG] Thorough No-Cache mode: Duplicate detection enabled, temp cache and cache sorting disabled" >&2
        fi
    
    # Parse all files ONCE and store results for reuse
    # Format: filepath<TAB>title<TAB>year<TAB>normalized_title
    
    # Check if parallel parsing is enabled
    if [[ "$PARALLEL_PARSING" == "true" && ${#ALL_VIDEO_FILES[@]} -ge 2 ]]; then
        # Adaptive: use minimum of total files and PARALLEL_PARSE_JOBS
        local actual_jobs=$PARALLEL_PARSE_JOBS
        [[ ${#ALL_VIDEO_FILES[@]} -lt $actual_jobs ]] && actual_jobs=${#ALL_VIDEO_FILES[@]}
        
        print_info "Parallel parsing enabled: ${actual_jobs} concurrent parse jobs"
        
        # IMPORTANT: Disable parsing database during parallel parsing to avoid lock contention
        # The DB will be populated during actual file processing instead
        local saved_parsing_db_enabled="$PARSING_DB_ENABLED"
        PARSING_DB_ENABLED="false"
        export PARSING_DB_ENABLED
        
        # Create temp files for parallel parsing with file locks
        local temp_parse_lock="/tmp/movie_parse_lock_$$"
        local temp_dup_lock="/tmp/movie_dup_lock_$$"
        
        # Parse files in batches
        local batch_size=$actual_jobs
        local total_files=${#ALL_VIDEO_FILES[@]}
        local parsed_count=0
        
        for ((batch_start=0; batch_start<total_files; batch_start+=batch_size)); do
            local batch_pids=()
            
            # Start batch of parallel parse jobs
            for ((i=0; i<batch_size && (batch_start+i)<total_files; i++)); do
                local file_index=$((batch_start + i))
                local file="${ALL_VIDEO_FILES[$file_index]}"
                
                # Run parsing in background subshell
                (
                    # Check for interrupt
                    check_interrupt
                    
                    # Flag to skip DB writes during parallel parsing (avoids lock contention)
                    IN_PARALLEL_PARSE="true"
                    
                    # Parse parent folder first (skip if parent IS the SOURCE directory)
                    local parent_folder=$(dirname "$file")
                    local folder_name=$(basename "$parent_folder")
                    local folder_title=""
                    local folder_year=""
                    
                    if [[ "$parent_folder" != "$SOURCE" ]]; then
                        parse_filename "$parent_folder" "folder"
                        folder_title="$PARSED_TITLE"
                        folder_year="$PARSED_YEAR"
                    fi
                    
                    # Parse the actual filename
                    parse_filename "$file"
                    
                    # Use folder info if filename parsing failed
                    if [[ -z "$PARSED_TITLE" && -n "$folder_title" ]]; then
                        PARSED_TITLE="$folder_title"
                    fi
                    if [[ -z "$PARSED_YEAR" && -n "$folder_year" ]]; then
                        PARSED_YEAR="$folder_year"
                    fi
                    
                    if [[ -n "$PARSED_TITLE" ]]; then
                        # Safety net: skip extras/trailers that slipped past awk filter
                        if is_trailer_or_extras_file "$file"; then
                            should_debug high && echo "[DEBUG] Skipping extras file from dup detection: '$(basename "$file")'" >&2
                        else
                        # Normalize title for comparison
                        local normalized_title=$(normalize_title_for_comparison "$PARSED_TITLE")
                        local key="${normalized_title}|${PARSED_YEAR:-unknown}"
                        
                        # Get file size
                        local size=0
                        if [[ -f "$file" ]]; then
                            size=$(_stat_size "$file" || echo "0")
                        fi
                        
                        should_debug high && echo "[DEBUG] Parsed: '$(basename "$file")' (folder: '$folder_name') -> key='$key' (normalized from '$PARSED_TITLE')" >&2
                        
                        # Use atomic mkdir for cross-platform file locking (macOS compatible)
                        while ! mkdir "$temp_dup_lock" 2>/dev/null; do
                            sleep 0.01
                        done
                        printf "%s\t%s\t%s\n" "$key" "$file" "$size" >> "$temp_dup_detect"
                        rmdir "$temp_dup_lock"
                        
                        while ! mkdir "$temp_parse_lock" 2>/dev/null; do
                            sleep 0.01
                        done
                        printf "%s\t%s\t%s\t%s\n" "$file" "$PARSED_TITLE" "${PARSED_YEAR:--}" "$normalized_title" >> "$temp_parse_cache"
                        rmdir "$temp_parse_lock"
                        fi  # end extras check
                    else
                        should_debug high && echo "[DEBUG] Cannot parse (no title/year): '$(basename "$file")' -> NON_DUPLICATE" >&2
                        # Use atomic mkdir for cross-platform file locking
                        while ! mkdir "$temp_parse_lock" 2>/dev/null; do
                            sleep 0.01
                        done
                        printf "%s\t-\t-\t-\n" "$file" >> "$temp_parse_cache"
                        rmdir "$temp_parse_lock"
                    fi
                ) &
                
                batch_pids+=($!)
            done
            
            # Wait for batch to complete
            for pid in "${batch_pids[@]}"; do
                wait "$pid" 2>/dev/null || true
            done
            
            # Update progress (use newline in debug mode to avoid mixing with debug output)
            parsed_count=$((parsed_count + batch_size))
            if [[ $parsed_count -gt $total_files ]]; then
                parsed_count=$total_files
            fi
            if should_debug high || should_debug medium; then
                # In debug mode, use newline so debug output doesn't overwrite progress
                echo -e "${CYAN}Parsed: ${parsed_count}/${total_files} files${NC}" >&2
            else
                # Normal mode, use carriage return for in-place update
                echo -ne "\r${CYAN}Parsed: ${parsed_count}/${total_files} files${NC}" >&2
            fi
        done
        
        echo "" >&2
        print_success "Parallel parsing complete: ${total_files} files parsed"
        
        # Clean up lock directories
        rmdir "$temp_parse_lock" "$temp_dup_lock" 2>/dev/null || true
        
        # Restore parsing database setting after parallel parsing completes
        PARSING_DB_ENABLED="$saved_parsing_db_enabled"
        export PARSING_DB_ENABLED
        
    else
        # Sequential parsing (original code)
        if [[ "$PARALLEL_PARSING" == "true" ]]; then
            print_info "Parallel parsing disabled: too few files (need > $((PARALLEL_PARSE_JOBS * 2)))"
        fi
        
#        # DEBUG: Show file order before processing
#        if should_debug high; then
#            echo "[DEBUG] Files in processing order:" >&2
#            local debug_idx=1
#            for debug_file in "${ALL_VIDEO_FILES[@]}"; do
#                echo "[DEBUG]   $debug_idx. $(basename "$debug_file")" >&2
#                ((debug_idx++)) || true
#            done
#        fi
        
        for file in "${ALL_VIDEO_FILES[@]}"; do
            # Check for interrupt at start of each file
            check_interrupt
            
            # Parse parent folder first (skip if parent IS the SOURCE directory)
            local parent_folder=$(dirname "$file")
            local folder_name=$(basename "$parent_folder")
            local folder_title=""
            local folder_year=""
            
            if [[ "$parent_folder" != "$SOURCE" ]]; then
                parse_filename "$parent_folder" "folder"
                folder_title="$PARSED_TITLE"
                folder_year="$PARSED_YEAR"
            fi
            
            # Now parse the actual filename
            parse_filename "$file"
            
            # Use folder info if filename parsing failed or is incomplete
            if [[ -z "$PARSED_TITLE" && -n "$folder_title" ]]; then
                PARSED_TITLE="$folder_title"
            fi
            if [[ -z "$PARSED_YEAR" && -n "$folder_year" ]]; then
                PARSED_YEAR="$folder_year"
            fi
            
            if [[ -n "$PARSED_TITLE" ]]; then
                # Safety net: skip extras/trailers that slipped past awk filter
                if is_trailer_or_extras_file "$file"; then
                    should_debug high && echo "[DEBUG] Skipping extras file from dup detection: '$(basename "$file")'" >&2
                    # Don't add to temp_dup_detect — treat as non-duplicate so it's not lost
                    NON_DUPLICATE_FILES+=("$file")
                    printf "%s\t%s\t%s\t%s\n" "$file" "$PARSED_TITLE" "${PARSED_YEAR:--}" "$(normalize_title_for_comparison "$PARSED_TITLE")" >> "$temp_parse_cache"
                else
                # Regular movie files - check for duplicates (year is optional)
                # Normalize title for comparison (remove apostrophes, punctuation, etc.)
                local normalized_title=$(normalize_title_for_comparison "$PARSED_TITLE")
                local key="${normalized_title}|${PARSED_YEAR:-unknown}"
                
                # Get file size (with additional safety check)
                local size=0
                if [[ -f "$file" ]]; then
                    size=$(_stat_size "$file" || echo "0")
                fi
                
                should_debug high && echo "[DEBUG] Parsed: '$(basename "$file")' (folder: '$folder_name') -> key='$key' (normalized from '$PARSED_TITLE')" >&2
                
                # Store in duplicate detection file
                printf "%s\t%s\t%s\n" "$key" "$file" "$size" >> "$temp_dup_detect"
                
                # Store parsed results for reuse in ALL modes (not just fast/thorough)
                # This eliminates redundant parsing during processing
                # Use "-" placeholder for empty year to preserve tab structure (bash IFS=$'\t' doesn't handle empty fields)
                printf "%s\t%s\t%s\t%s\n" "$file" "$PARSED_TITLE" "${PARSED_YEAR:--}" "$normalized_title" >> "$temp_parse_cache"
                fi  # end extras check
            else
                # Can't parse, treat as non-duplicate (likely not a movie file)
                should_debug high && echo "[DEBUG] Cannot parse (no title/year): '$(basename "$file")' -> NON_DUPLICATE" >&2
                NON_DUPLICATE_FILES+=("$file")
                # Store entry with "-" placeholders so we know it was checked (in ALL modes)
                printf "%s\t-\t-\t-\n" "$file" >> "$temp_parse_cache"
            fi
        done
    fi  # End parallel/sequential parsing
    
    # Load parse cache into memory arrays for instant lookups (bash 3.x compatible)
        if [[ "$parsing_mode" == "fast" ]] || [[ "$parsing_mode" == "thorough" ]]; then
            if [[ -f "$temp_parse_cache" ]]; then
                print_info "Loading parse cache into memory arrays..."
                PARSE_CACHE_COUNT=0
                while IFS=$'\t' read -r filepath title year normalized; do
                    # Convert "-" placeholder back to empty string for year
                    [[ "$year" == "-" ]] && year=""
                    PARSE_CACHE_PATHS[$PARSE_CACHE_COUNT]="$filepath"
                    PARSE_CACHE_TITLES[$PARSE_CACHE_COUNT]="$title"
                    PARSE_CACHE_YEARS[$PARSE_CACHE_COUNT]="$year"
                    PARSE_CACHE_NORMALIZED[$PARSE_CACHE_COUNT]="$normalized"
                    ((PARSE_CACHE_COUNT++)) || true
                done < "$temp_parse_cache"
                print_info "Loaded $PARSE_CACHE_COUNT entries into memory arrays"
            fi
        fi
        
        # Identify duplicates using sort/uniq (case-insensitive)
        if [[ -s "$temp_dup_detect" ]]; then
            # Debug: Check if temp_dup_detect has duplicate entries (same file listed multiple times)
            should_debug high && {
                local total_lines=$(wc -l < "$temp_dup_detect" | tr -d ' ')
                local unique_files=$(cut -f2 "$temp_dup_detect" | sort | uniq | wc -l | tr -d ' ')
                echo "[DEBUG] temp_dup_detect: $total_lines total lines, $unique_files unique files" >&2
                if [[ $total_lines -ne $unique_files ]]; then
                    echo "[DEBUG] WARNING: File(s) appear multiple times in temp_dup_detect!" >&2
                    # Show which files are duplicated
                    cut -f2 "$temp_dup_detect" | sort | uniq -d | while read -r dup_file; do
                        echo "[DEBUG]   Duplicated: $dup_file" >&2
                    done
                fi
            }
            
            # Find duplicate keys (appears more than once)
            local temp_keys="/tmp/movie_keys_$$.txt"
            cut -f1 "$temp_dup_detect" | sort -f | uniq -d -i > "$temp_keys"
            
            print_info "Scanning for duplicates (same title/year)..."
            
            # FIRST: Filter out lower resolution/bitrate duplicates (same basename, different extension)
            # This prevents marking both files as duplicates when we should just keep the best one
            local temp_filtered="/tmp/movie_filtered_$$.txt"
            local temp_groups="/tmp/movie_groups_$$.txt"
            > "$temp_filtered"
            > "$temp_groups"
            
            # Create group file: group_key TAB file TAB size TAB key TAB linked
            # Include both collected files AND already-linked files for complete duplicate detection
            # NOTE: Uses temp file instead of process substitution to avoid "Too many open files"
            local sibling_tmp="/tmp/movie_siblings_$$.txt"
            local linked_pairs_file="/tmp/movie_linked_pairs_$$.txt"
            
            # Build a set of group_keys from non-linked files so we only add relevant linked siblings
            # Single awk pass replaces bash while-read loop (no per-line dirname/basename forks)
            local nonlinked_group_keys="/tmp/movie_nonlinked_gkeys_$$.txt"
            awk -F'\t' '{
                file = $2
                # Split path into components
                n = split(file, parts, "/")
                # Rebuild parent dir
                dir = ""
                for (i = 1; i < n; i++) dir = dir (i > 1 ? "/" : "") parts[i]
                # Remove extension from filename
                fname = parts[n]
                sub(/\.[^.]*$/, "", fname)
                print dir "/" fname
            }' "$temp_dup_detect" > "$nonlinked_group_keys"
            
            # Build a set of parent dirs from non-linked files (for targeted linked_pairs lookup)
            local nonlinked_parent_dirs="/tmp/movie_nonlinked_pdirs_$$.txt"
            awk -F/ 'BEGIN{OFS="/"} {NF--; print}' "$nonlinked_group_keys" | sort -u > "$nonlinked_parent_dirs"
            
            # Single awk pass: build temp_groups base entries from temp_dup_detect
            # (replaces bash while-read loop with per-line dirname/basename/printf)
            awk -F'\t' '{
                file = $2; key = $1; size = $3
                n = split(file, parts, "/")
                dir = ""
                for (i = 1; i < n; i++) dir = dir (i > 1 ? "/" : "") parts[i]
                fname = parts[n]
                sub(/\.[^.]*$/, "", fname)
                gkey = dir "/" fname
                printf "%s\t%s\t%s\t%s\t%s\n", gkey, file, size, key, "no"
            }' "$temp_dup_detect" > "$temp_groups"
            
            # Find directories NOT covered by linked_pairs — only these need filesystem sibling checks
            local uncovered_dirs_tmp="/tmp/movie_uncovered_dirs_$$.txt"
            if [[ -s "$linked_pairs_file" ]]; then
                # Build set of linked dirs, then find parent dirs not in that set
                local linked_dirs_tmp="/tmp/movie_linked_dirs_$$.txt"
                awk -F'|' '{
                    src = $1
                    sub(/\/[^\/]*$/, "", src)
                    print src
                }' "$linked_pairs_file" | sort -u > "$linked_dirs_tmp"
                # Parent dirs from nonlinked files that are NOT in linked dirs
                comm -23 "$nonlinked_parent_dirs" "$linked_dirs_tmp" > "$uncovered_dirs_tmp"
                rm -f "$linked_dirs_tmp" 2>/dev/null
            else
                # No linked pairs at all — all dirs are uncovered
                cp "$nonlinked_parent_dirs" "$uncovered_dirs_tmp"
            fi
            
            # Only scan filesystem for sibling files in uncovered directories
            local uncovered_count=$(wc -l < "$uncovered_dirs_tmp" 2>/dev/null | tr -d ' ')
            if [[ $uncovered_count -gt 0 ]]; then
                # Build a lookup of uncovered group_keys with original filenames for exclusion
                local uncovered_gkeys_tmp="/tmp/movie_uncovered_gkeys_$$.txt"
                awk -F'\t' 'NR==FNR { dirs[$1]=1; next }
                {
                    file = $2
                    n = split(file, parts, "/")
                    dir = ""
                    for (i = 1; i < n; i++) dir = dir (i > 1 ? "/" : "") parts[i]
                    if (dir in dirs) {
                        fname = parts[n]
                        origname = fname
                        sub(/\.[^.]*$/, "", fname)
                        # gkey, parent_dir, base_name_no_ext, original_filename
                        print dir "/" fname "\t" dir "\t" fname "\t" origname
                    }
                }' "$uncovered_dirs_tmp" "$temp_dup_detect" | sort -u > "$uncovered_gkeys_tmp"
                
                # For each uncovered group_key, find sibling video files
                # Uses temp file instead of process substitution to avoid fd exhaustion
                local _sibling_find_tmp="/tmp/movie_sibling_find_$$.bin"
                while IFS=$'\t' read -r gkey parent_dir base_name orig_filename; do
                    [[ -z "$gkey" ]] && continue
                    # Find siblings with same basename but different extension (exclude original file)
                    find "$parent_dir" -maxdepth 1 -type f -name "${base_name}.*" -print0 2>/dev/null > "$_sibling_find_tmp"
                    while IFS= read -r -d '' sibling_file; do
                        # Skip the original file itself
                        [[ "$(basename "$sibling_file")" == "$orig_filename" ]] && continue
                        # Skip .ia files (Internet Archive duplicates - handled separately in process_file)
                        local sibling_basename="${sibling_file##*/}"
                        local sibling_noext="${sibling_basename%.*}"
                        [[ "$sibling_noext" == *".ia" ]] && continue
                        # Check if it's a video file (fast lowercase check)
                        local sibling_ext="${sibling_file##*.}"
                        sibling_ext=$(echo "$sibling_ext" | tr '[:upper:]' '[:lower:]')
                        if [[ "$sibling_ext" =~ ^(mkv|mp4|avi|m4v|mov|wmv|webm|ts|m2ts)$ ]]; then
                            local sibling_size=$(_stat_size "$sibling_file" || echo 0)
                            printf "%s\t%s\t%s\t%s\t%s\n" "$gkey" "$sibling_file" "$sibling_size" "found" "yes" >> "$temp_groups"
                        fi
                    done < "$_sibling_find_tmp"
                done < "$uncovered_gkeys_tmp"
                rm -f "$_sibling_find_tmp" 2>/dev/null
                rm -f "$uncovered_gkeys_tmp" 2>/dev/null
            fi
            rm -f "$uncovered_dirs_tmp" 2>/dev/null
            
            # Only add already-linked files that share a group_key with a non-linked file
            # (i.e., same folder + same basename = potential extension duplicates)
            if [[ -s "$linked_pairs_file" ]] && [[ -s "$nonlinked_group_keys" ]]; then
                # Single awk pass: compute group_key from linked_pairs source paths and
                # join against nonlinked_group_keys set — no bash loop at all
                local matched_linked="/tmp/movie_matched_linked_$$.txt"
                awk -F'|' '
                    NR==FNR { keys[$1]=1; next }
                    {
                        src=$1
                        # Extract parent_dir and basename-without-ext to form group_key
                        n=split(src, parts, "/")
                        dir=""
                        for(i=1; i<n; i++) dir = dir (i>1?"/":"") parts[i]
                        fname=parts[n]
                        # Remove last extension
                        sub(/\.[^.]*$/, "", fname)
                        gkey = dir "/" fname
                        if (gkey in keys) print gkey "\t" src
                    }
                ' "$nonlinked_group_keys" "$linked_pairs_file" > "$matched_linked"
                
                # Batch stat for matched linked files (single xargs pipeline instead of per-file stat)
                if [[ -s "$matched_linked" ]]; then
                    # Get file sizes in bulk: extract paths, stat them, then rejoin with group_keys
                    cut -f2 "$matched_linked" | tr '\n' '\0' | xargs -0 stat "$_STAT_FMT_FLAG" "$_STAT_SIZE_NAME_FMT" 2>/dev/null > "${matched_linked}.sizes"
                    # Join group_keys with sizes using awk
                    awk -F'\t' 'NR==FNR {
                        # Read sizes file: size|path
                        split($0, a, "|")
                        sizes[a[2]] = a[1]
                        next
                    }
                    {
                        gkey = $1; src = $2
                        sz = (src in sizes) ? sizes[src] : 0
                        printf "%s\t%s\t%s\t%s\t%s\n", gkey, src, sz, "linked", "yes"
                    }' "${matched_linked}.sizes" "$matched_linked" >> "$temp_groups"
                    rm -f "${matched_linked}.sizes" 2>/dev/null
                fi
                rm -f "$matched_linked" 2>/dev/null
            fi
            rm -f "$nonlinked_group_keys" "$nonlinked_parent_dirs" 2>/dev/null
            
            # Deduplicate temp_groups by file path (column 2) - same file may be added from
            # filesystem fallback ('found') AND linked_pairs ('linked') with different metadata
            sort -t$'\t' -k2,2 -u "$temp_groups" > "${temp_groups}.dedup"
            mv "${temp_groups}.dedup" "$temp_groups"
            
            local total_groups=$(wc -l < "$temp_groups" | tr -d ' ')
            should_debug low && echo "[DEBUG] Extension scan: $total_groups entries to check" >&2
            
            # Sort by group_key to group files together
            sort -t$'\t' -k1,1 "$temp_groups" > "${temp_groups}.sorted"
            mv "${temp_groups}.sorted" "$temp_groups"
            
            # Check if any group has multiple files (actual extension duplicates to resolve)
            local has_ext_dup_groups=$(cut -f1 "$temp_groups" | uniq -d | head -1)
            local skipped_extension_dups=0
            
            if [[ -z "$has_ext_dup_groups" ]]; then
                # No extension duplicate groups - copy all non-linked files directly
                awk -F'\t' '$5 == "no" { print $4 "\t" $2 "\t" $3 }' "$temp_groups" > "$temp_filtered"
            else
            # Multi-file groups found - process extension duplicates
            # Process each group
            local current_group=""
            local group_files_list="/tmp/movie_group_files_$$.txt"
            
            # Track which files were kept vs rejected
            local extension_dup_log="/tmp/movie_extension_dups_$$.txt"
            > "$extension_dup_log"
            
            while IFS=$'\t' read -r group_key file size key is_linked; do
                if [[ "$group_key" != "$current_group" ]]; then
                    # New group started - process previous group if it had files
                    if [[ -f "$group_files_list" && -s "$group_files_list" ]]; then
                        local file_count=$(wc -l < "$group_files_list" | tr -d ' ')
                        
                        if [[ $file_count -gt 1 ]]; then
                            # Multiple files with same basename - compare resolution first (fast)
                            local best_file=""
                            local best_resolution=0
                            local best_bitrate=0
                            local best_size=0
                            local best_key=""
                            
                            print_info "Checking resolution for files in group: $current_group"
                            
                            # FIRST PASS: Get resolution for all files (fast)
                            local -a group_resolutions=()
                            local -a group_files_array=()
                            local -a group_sizes_array=()
                            local -a group_keys_array=()
                            local -a group_linked_array=()
                            local index=0
                            local best_is_linked="no"
                            
                            while IFS=$'\t' read -r gfile gsize gkey glinked; do
                                local resolution=$(get_video_resolution_height "$gfile")
                                group_resolutions[$index]=$resolution
                                group_files_array[$index]="$gfile"
                                group_sizes_array[$index]=$gsize
                                group_keys_array[$index]="$gkey"
                                group_linked_array[$index]="$glinked"
                                local linked_tag=""
                                [[ "$glinked" == "yes" ]] && linked_tag=" [linked]"
                                echo -e "${CYAN}  File: $(basename "$gfile") - ${resolution}p (${gsize} bytes)${linked_tag}${NC}" >&2
                                
                                if [[ $resolution -gt $best_resolution ]] || 
                                   [[ $resolution -eq $best_resolution && $gsize -gt $best_size ]]; then
                                    best_resolution=$resolution
                                    best_size=$gsize
                                    best_file="$gfile"
                                    best_key="$gkey"
                                    best_is_linked="$glinked"
                                fi
                                ((index++)) || true
                            done < "$group_files_list"
                            
                            # SECOND PASS: Only check bitrate if multiple files have the same best resolution
                            local resolution_tie_count=0
                            for res in "${group_resolutions[@]}"; do
                                [[ $res -eq $best_resolution ]] && ((resolution_tie_count++)) || true
                            done
                            
                            if [[ $resolution_tie_count -gt 1 ]]; then
                                echo -e "${CYAN}  Resolution tie detected (${best_resolution}p) - checking bitrate...${NC}" >&2
                                best_bitrate=0
                                best_size=0
                                best_file=""
                                best_key=""
                                
                                for ((i=0; i<${#group_resolutions[@]}; i++)); do
                                    if [[ ${group_resolutions[$i]} -eq $best_resolution ]]; then
                                        local bitrate=$(get_video_bitrate "${group_files_array[$i]}")
                                        local bitrate_formatted=$(format_bitrate "$bitrate")
                                        echo -e "${CYAN}    Bitrate for $(basename "${group_files_array[$i]}"): ${bitrate_formatted}${NC}" >&2
                                        
                                        if [[ $bitrate -gt $best_bitrate ]] || 
                                           [[ $bitrate -eq $best_bitrate && ${group_sizes_array[$i]} -gt $best_size ]]; then
                                            best_bitrate=$bitrate
                                            best_size=${group_sizes_array[$i]}
                                            best_file="${group_files_array[$i]}"
                                            best_key="${group_keys_array[$i]}"
                                            best_is_linked="${group_linked_array[$i]}"
                                        fi
                                    fi
                                done
                            fi

                            
                            # Keep only the best file
                            if [[ -n "$best_file" ]]; then
                                local linked_indicator=""
                                [[ "$best_is_linked" == "yes" ]] && linked_indicator=" [already linked]"
                                if [[ $resolution_tie_count -gt 1 ]]; then
                                    local bitrate_formatted=$(format_bitrate "$best_bitrate")
                                    echo -e "${GREEN}  ✓ Best: $(basename "$best_file") (${best_resolution}p, ${bitrate_formatted})${linked_indicator}${NC}" >&2
                                else
                                    echo -e "${GREEN}  ✓ Best: $(basename "$best_file") (${best_resolution}p)${linked_indicator}${NC}" >&2
                                fi
                                
                                # Count non-linked files that will be skipped
                                local non_linked_skipped=0
                                
                                # Show rejected files
                                for ((i=0; i<${#group_files_array[@]}; i++)); do
                                    if [[ "${group_files_array[$i]}" != "$best_file" ]]; then
                                        local reject_linked_tag=""
                                        [[ "${group_linked_array[$i]}" == "yes" ]] && reject_linked_tag=" [linked]"
                                        echo -e "${RED}  ✗ Rejected: $(basename "${group_files_array[$i]}") (${group_resolutions[$i]}p)${reject_linked_tag}${NC}" >&2
                                        [[ "${group_linked_array[$i]}" == "no" ]] && ((non_linked_skipped++)) || true
                                    fi
                                done
                                
                                # Only add to filtered list if best file is NOT linked
                                if [[ "$best_is_linked" == "no" ]]; then
                                    printf "%s\t%s\t%s\n" "$best_key" "$best_file" "$best_size" >> "$temp_filtered"
                                else
                                    # Best file is linked, so non-linked files in this group should ALL be skipped
                                    non_linked_skipped=0
                                    for ((i=0; i<${#group_files_array[@]}; i++)); do
                                        [[ "${group_linked_array[$i]}" == "no" ]] && ((non_linked_skipped++)) || true
                                    done
                                    echo -e "${YELLOW}  → Skipping ${non_linked_skipped} file(s): better quality already linked${NC}" >&2
                                fi
                                
                                # Log kept vs rejected files with reason
                                local selection_reason="resolution"
                                if [[ $resolution_tie_count -gt 1 ]]; then
                                    selection_reason="bitrate"
                                fi
                                
                                for ((i=0; i<${#group_files_array[@]}; i++)); do
                                    if [[ "${group_files_array[$i]}" == "$best_file" ]]; then
                                        # Get bitrate for kept file if not already calculated
                                        if [[ $best_bitrate -eq 0 ]]; then
                                            best_bitrate=$(get_video_bitrate "$best_file")
                                        fi
                                        echo "KEPT|$best_file|${best_resolution}p|${best_bitrate}|$selection_reason" >> "$extension_dup_log"
                                    else
                                        # Always get bitrate for rejected files
                                        local rejected_bitrate=$(get_video_bitrate "${group_files_array[$i]}")
                                        echo "REJECTED|${group_files_array[$i]}|${group_resolutions[$i]}p|${rejected_bitrate}|$selection_reason" >> "$extension_dup_log"
                                    fi
                                done
                                
                                ((skipped_extension_dups += non_linked_skipped))
                            fi
                        else
                            # Only one file in group - keep it only if it's not linked
                            while IFS=$'\t' read -r gfile gsize gkey glinked; do
                                if [[ "$glinked" == "no" ]]; then
                                    printf "%s\t%s\t%s\n" "$gkey" "$gfile" "$gsize" >> "$temp_filtered"
                                fi
                            done < "$group_files_list"
                        fi
                    fi
                    
                    # Start new group
                    current_group="$group_key"
                    > "$group_files_list"
                fi
                
                # Add file to current group (include linked status)
                printf "%s\t%s\t%s\t%s\n" "$file" "$size" "$key" "$is_linked" >> "$group_files_list"
            done < "$temp_groups"
            
            # Process last group
            if [[ -f "$group_files_list" && -s "$group_files_list" ]]; then
                local file_count=$(wc -l < "$group_files_list" | tr -d ' ')
                
                if [[ $file_count -gt 1 ]]; then
                    local best_file=""
                    local best_resolution=0
                    local best_bitrate=0
                    local best_size=0
                    local best_key=""
                    local best_is_linked="no"
                    
                    print_info "Checking resolution for files in group: $current_group"
                    
                    # FIRST PASS: Get resolution for all files (fast)
                    local -a group_resolutions=()
                    local -a group_files_array=()
                    local -a group_sizes_array=()
                    local -a group_keys_array=()
                    local -a group_linked_array=()
                    local index=0
                    
                    while IFS=$'\t' read -r gfile gsize gkey glinked; do
                        local resolution=$(get_video_resolution_height "$gfile")
                        group_resolutions[$index]=$resolution
                        group_files_array[$index]="$gfile"
                        group_sizes_array[$index]=$gsize
                        group_keys_array[$index]="$gkey"
                        group_linked_array[$index]="$glinked"
                        local size_display=$(format_bytes "$gsize")
                        local linked_tag=""
                        [[ "$glinked" == "yes" ]] && linked_tag=" [linked]"
                        echo -e "${CYAN}  File: $(basename "$gfile") - ${resolution}p ($size_display)${linked_tag}${NC}" >&2
                        
                        if [[ $resolution -gt $best_resolution ]] || 
                           [[ $resolution -eq $best_resolution && $gsize -gt $best_size ]]; then
                            best_resolution=$resolution
                            best_size=$gsize
                            best_file="$gfile"
                            best_key="$gkey"
                            best_is_linked="$glinked"
                        fi
                        ((index++)) || true
                    done < "$group_files_list"
                    
                    # SECOND PASS: Only check bitrate if multiple files have the same best resolution
                    local resolution_tie_count=0
                    for res in "${group_resolutions[@]}"; do
                        [[ $res -eq $best_resolution ]] && ((resolution_tie_count++)) || true
                    done
                    
                    if [[ $resolution_tie_count -gt 1 ]]; then
                        echo -e "${CYAN}  Resolution tie detected (${best_resolution}p) - checking bitrate...${NC}" >&2
                        best_bitrate=0
                        best_size=0
                        best_file=""
                        best_key=""
                        
                        for ((i=0; i<${#group_resolutions[@]}; i++)); do
                            if [[ ${group_resolutions[$i]} -eq $best_resolution ]]; then
                                local bitrate=$(get_video_bitrate "${group_files_array[$i]}")
                                echo -e "${CYAN}    Bitrate for $(basename "${group_files_array[$i]}"): ${bitrate} kbps${NC}" >&2
                                
                                if [[ $bitrate -gt $best_bitrate ]] || 
                                   [[ $bitrate -eq $best_bitrate && ${group_sizes_array[$i]} -gt $best_size ]]; then
                                    best_bitrate=$bitrate
                                    best_size=${group_sizes_array[$i]}
                                    best_file="${group_files_array[$i]}"
                                    best_key="${group_keys_array[$i]}"
                                    best_is_linked="${group_linked_array[$i]}"
                                fi
                            fi
                        done
                    fi
                    
                    if [[ -n "$best_file" ]]; then
                        local linked_indicator=""
                        [[ "$best_is_linked" == "yes" ]] && linked_indicator=" [already linked]"
                        if [[ $resolution_tie_count -gt 1 ]]; then
                            local bitrate_formatted=$(format_bitrate "$best_bitrate")
                            echo -e "${GREEN}  ✓ Best: $(basename "$best_file") (${best_resolution}p, ${bitrate_formatted})${linked_indicator}${NC}" >&2
                        else
                            echo -e "${GREEN}  ✓ Best: $(basename "$best_file") (${best_resolution}p)${linked_indicator}${NC}" >&2
                        fi
                        
                        # Count non-linked files that will be skipped
                        local non_linked_skipped=0
                        
                        # Show rejected files
                        for ((i=0; i<${#group_files_array[@]}; i++)); do
                            if [[ "${group_files_array[$i]}" != "$best_file" ]]; then
                                local reject_linked_tag=""
                                [[ "${group_linked_array[$i]}" == "yes" ]] && reject_linked_tag=" [linked]"
                                echo -e "${RED}  ✗ Rejected: $(basename "${group_files_array[$i]}") (${group_resolutions[$i]}p)${reject_linked_tag}${NC}" >&2
                                [[ "${group_linked_array[$i]}" == "no" ]] && ((non_linked_skipped++)) || true
                            fi
                        done
                        
                        # Only add to filtered list if best file is NOT linked
                        if [[ "$best_is_linked" == "no" ]]; then
                            printf "%s\t%s\t%s\n" "$best_key" "$best_file" "$best_size" >> "$temp_filtered"
                        else
                            # Best file is linked, so non-linked files in this group should ALL be skipped
                            non_linked_skipped=0
                            for ((i=0; i<${#group_files_array[@]}; i++)); do
                                [[ "${group_linked_array[$i]}" == "no" ]] && ((non_linked_skipped++)) || true
                            done
                            echo -e "${YELLOW}  → Skipping ${non_linked_skipped} file(s): better quality already linked${NC}" >&2
                        fi
                        
                        # Log kept vs rejected files with reason
                        local selection_reason="resolution"
                        if [[ $resolution_tie_count -gt 1 ]]; then
                            selection_reason="bitrate"
                        fi
                        
                        for ((i=0; i<${#group_files_array[@]}; i++)); do
                            if [[ "${group_files_array[$i]}" == "$best_file" ]]; then
                                # Get bitrate for kept file if not already calculated
                                if [[ $best_bitrate -eq 0 ]]; then
                                    best_bitrate=$(get_video_bitrate "$best_file")
                                fi
                                echo "KEPT|$best_file|${best_resolution}p|${best_bitrate}|$selection_reason" >> "$extension_dup_log"
                            else
                                # Always get bitrate for rejected files
                                local rejected_bitrate=$(get_video_bitrate "${group_files_array[$i]}")
                                echo "REJECTED|${group_files_array[$i]}|${group_resolutions[$i]}p|${rejected_bitrate}|$selection_reason" >> "$extension_dup_log"
                            fi
                        done
                        
                        ((skipped_extension_dups += non_linked_skipped))
                    fi
                else
                    # Only one file in group - keep it only if it's not linked
                    while IFS=$'\t' read -r gfile gsize gkey glinked; do
                        if [[ "$glinked" == "no" ]]; then
                            printf "%s\t%s\t%s\n" "$gkey" "$gfile" "$gsize" >> "$temp_filtered"
                        fi
                    done < "$group_files_list"
                fi
            fi
            fi  # end has_ext_dup_groups
            
            # Clean up temp files
            rm -f "$temp_groups" "$group_files_list" "/tmp/movie_linked_pairs_$$.txt" 2>/dev/null
            
            # Show how many extension duplicates were filtered
            if [[ $skipped_extension_dups -gt 0 ]]; then
                echo ""
                print_info "Filtered out ${YELLOW}$skipped_extension_dups${NC} extension duplicate(s) - keeping only best quality from each group"
            fi
            
            # Use filtered list for duplicate detection
            mv "$temp_filtered" "$temp_dup_detect"
            
            # Regenerate duplicate keys from filtered list (not original list)
            rm -f "$temp_keys" 2>/dev/null
            cut -f1 "$temp_dup_detect" | sort -f | uniq -d -i > "$temp_keys"
            
            echo ""
            print_info "Title duplicates (same movie, different folders/files):"
            if [[ -s "$temp_keys" ]]; then
                # Sort keys alphabetically for display
                while IFS= read -r dup_key; do
                    local dup_title="${dup_key%%|*}"
                    local dup_year="${dup_key##*|}"
                    echo -e "${CYAN}  - Title: '$dup_title' Year: $dup_year${NC}" >&2
                done < <(sort -f < "$temp_keys")
            else
                echo -e "${CYAN}  (none)${NC}" >&2
            fi
            
            # Separate duplicates from non-duplicates (case-insensitive matching)
            if [[ ! -s "$temp_keys" ]]; then
                # No duplicate keys at all — every file is non-duplicate (fast path)
                while IFS=$'\t' read -r _k file _s; do
                    NON_DUPLICATE_FILES+=("$file")
                done < "$temp_dup_detect"
            else
                # Single awk pass replaces per-file grep (eliminates 1750+ subprocess forks)
                local _dup_split_dups="/tmp/movie_split_dups_$$.txt"
                local _dup_split_nondups="/tmp/movie_split_nondups_$$.txt"
                awk -F'\t' 'NR==FNR { keys[tolower($0)]=1; next }
                {
                    if (tolower($1) in keys) print $2 > "'"$_dup_split_dups"'"
                    else print $2 > "'"$_dup_split_nondups"'"
                }' "$temp_keys" "$temp_dup_detect"
                
                # Load results into arrays
                if [[ -s "$_dup_split_dups" ]]; then
                    while IFS= read -r file; do
                        DUPLICATE_FILES+=("$file")
                    done < "$_dup_split_dups"
                fi
                if [[ -s "$_dup_split_nondups" ]]; then
                    while IFS= read -r file; do
                        NON_DUPLICATE_FILES+=("$file")
                    done < "$_dup_split_nondups"
                fi
                rm -f "$_dup_split_dups" "$_dup_split_nondups" 2>/dev/null
            fi
            
            rm -f "$temp_keys" 2>/dev/null
        fi
        
    rm -f "$temp_dup_detect" 2>/dev/null
    # Keep temp_parse_cache for reuse in cache sorting and processing
    
    # Combine and sort arrays alphabetically by basename before reassigning
    local -a COMBINED_FILES=("${NON_DUPLICATE_FILES[@]}" "${DUPLICATE_FILES[@]}")
    local _combined_sort_tmp="/tmp/movie_combined_sort_$$.txt"
    printf '%s\n' "${COMBINED_FILES[@]}" | awk -F'/' '{print tolower($NF)"\t"$0}' | sort -k1,1 | cut -f2- > "$_combined_sort_tmp"
    COMBINED_FILES=(); while IFS= read -r f; do COMBINED_FILES+=("$f"); done < "$_combined_sort_tmp"
    rm -f "$_combined_sort_tmp" 2>/dev/null
    
    # Update ALL_VIDEO_FILES array to match filtered list
    ALL_VIDEO_FILES=("${COMBINED_FILES[@]}")
    
    # Show final count after filtering
    local final_file_count=${#ALL_VIDEO_FILES[@]}
    if [[ $skipped_extension_dups -gt 0 ]]; then
        echo ""
        print_success "Processing ${final_file_count} video file(s) (${#NON_DUPLICATE_FILES[@]} unique + ${#DUPLICATE_FILES[@]} title duplicates)"
    fi
    
    if [[ ${#DUPLICATE_FILES[@]} -gt 0 ]]; then
        print_warning "Found ${#DUPLICATE_FILES[@]} duplicate file(s) - will process ${#NON_DUPLICATE_FILES[@]} non-duplicates first"
        should_debug high && {
            echo "[DEBUG] Duplicate files detected:" >&2
            # Sort filenames alphabetically for display (with full paths to distinguish same names in different folders)
            for dup_file in "${DUPLICATE_FILES[@]}"; do
                # Show relative path from qtest folder to distinguish duplicates with same basename
                local relative_path="${dup_file#*/qtest/}"
                echo "$relative_path"
            done | sort -f | while read -r sorted_path; do
                echo "[DEBUG]   - $sorted_path" >&2
            done
        }
        # Add to global duplicate tracking array
        ALL_DUPLICATE_FILES=("${DUPLICATE_FILES[@]}")
    fi
    
    # Process non-duplicate files first (or all files in thorough-nocache mode)
    local total_success=0
    local total_failed=0
    
    # All modes: process non-duplicates first
    local all_filtered_by_extension=false
    if [[ ${#NON_DUPLICATE_FILES[@]} -eq 0 ]]; then
        if [[ ${#DUPLICATE_FILES[@]} -eq 0 ]]; then
            # All files were filtered (e.g., better quality already linked)
            # Continue to show stats and run post-processing scans
            print_success "All files filtered - better quality versions already linked"
            all_filtered_by_extension=true
        else
            print_warning "No non-duplicate files to process"
        fi
    fi
    
    # All modes use NON_DUPLICATE_FILES (unless all were filtered)
    if [[ "$all_filtered_by_extension" != "true" ]]; then
        VIDEO_FILES=("${NON_DUPLICATE_FILES[@]}")
    else
        VIDEO_FILES=()
    fi
    
    # Track duplicate count for statistics
    local DUPLICATES_DETECTED=$((FILES_AFTER_CLAIMING - ${#NON_DUPLICATE_FILES[@]}))
    local TOTAL_FILES_FOUND=${#NON_DUPLICATE_FILES[@]}
    export FILTERED_FILE_COUNT=${final_file_count:-$ORIGINAL_FILE_COUNT}
    export EXTENSION_DUPLICATES_FILTERED=${skipped_extension_dups:-0}
    export EXTENSION_DUP_LOG="${extension_dup_log:-}"
    
    if [[ ${#VIDEO_FILES[@]} -gt 0 ]]; then
            # Skip cache sorting in no-cache modes
            if [[ "$parsing_mode" == "fast-nocache" ]] || [[ "$parsing_mode" == "thorough-nocache" ]]; then
                echo ""
                print_success "Processing ${#VIDEO_FILES[@]} video file(s) in no-cache mode"
                echo ""
            else
                # Separate files into cached and non-cached for optimized processing
                echo ""
                print_info "Sorting files by cache status (cached files will be processed first)..."
            
            local -a CACHED_FILES=()
            local -a NON_CACHED_FILES=()
            
            # Use parallel cache lookups if enabled and enough files
            if [[ "$PARALLEL_PARSING" == "true" && ${#VIDEO_FILES[@]} -gt $((PARALLEL_PARSE_JOBS * 2)) ]]; then
                print_info "Parallel cache sorting enabled: ${PARALLEL_PARSE_JOBS} concurrent lookup jobs"
                
                # Create temp files for results
                local temp_cached_list="/tmp/movie_cached_$$"
                local temp_noncached_list="/tmp/movie_noncached_$$"
                local temp_cached_lock="/tmp/movie_cached_lock_$$"
                local temp_noncached_lock="/tmp/movie_noncached_lock_$$"
                > "$temp_cached_list"
                > "$temp_noncached_list"
                
                # Process in batches
                local batch_size=$PARALLEL_PARSE_JOBS
                local total_files=${#VIDEO_FILES[@]}
                local sorted_count=0
                
                for ((batch_start=0; batch_start<total_files; batch_start+=batch_size)); do
                    local batch_pids=()
                    
                    for ((i=0; i<batch_size && (batch_start+i)<total_files; i++)); do
                        local file_index=$((batch_start + i))
                        local file="${VIDEO_FILES[$file_index]}"
                        
                        # Run cache lookup in background
                        (
                            check_interrupt
                            
                            # Skip if file no longer exists
                            if [[ ! -f "$file" ]]; then
                                exit 0
                            fi
                            
                            local file_title=""
                            local file_year=""
                            
                            # Try in-memory cache first
                            local cached_data=$(lookup_parse_cache "$file")
                            if [[ -n "$cached_data" ]]; then
                                file_title="${cached_data%%|*}"
                                file_year="${cached_data#*|}"
                                should_debug high && echo "[DEBUG] Using cached parse results for: $(basename "$file") -> '$file_title' ($file_year)" >&2
                            else
                                # Cache miss: parse the file
                                should_debug high && echo "[DEBUG] Cache miss - parsing: $(basename "$file")" >&2
                                local parent_folder=$(dirname "$file")
                                local folder_title=""
                                local folder_year=""
                                if [[ "$parent_folder" != "$SOURCE" ]]; then
                                    parse_filename "$parent_folder" "folder"
                                    folder_title="$PARSED_TITLE"
                                    folder_year="$PARSED_YEAR"
                                fi
                                
                                parse_filename "$file"
                                
                                if [[ -z "$PARSED_TITLE" && -n "$folder_title" ]]; then
                                    PARSED_TITLE="$folder_title"
                                fi
                                if [[ -z "$PARSED_YEAR" && -n "$folder_year" ]]; then
                                    PARSED_YEAR="$folder_year"
                                fi
                                
                                file_title="$PARSED_TITLE"
                                file_year="$PARSED_YEAR"
                            fi
                            
                            # Check if in cache and write to appropriate list
                            if [[ -n "$file_title" && -n "$file_year" ]]; then
                                local cached_movie=$(get_cached_movie "$file_title" "$file_year")
                                if [[ -n "$cached_movie" ]]; then
                                    # Write to cached list with atomic lock
                                    while ! mkdir "$temp_cached_lock" 2>/dev/null; do
                                        sleep 0.01
                                    done
                                    echo "$file" >> "$temp_cached_list"
                                    rmdir "$temp_cached_lock"
                                else
                                    # Write to non-cached list with atomic lock
                                    while ! mkdir "$temp_noncached_lock" 2>/dev/null; do
                                        sleep 0.01
                                    done
                                    echo "$file" >> "$temp_noncached_list"
                                    rmdir "$temp_noncached_lock"
                                fi
                            else
                                # No title/year, treat as non-cached
                                while ! mkdir "$temp_noncached_lock" 2>/dev/null; do
                                    sleep 0.01
                                done
                                echo "$file" >> "$temp_noncached_list"
                                rmdir "$temp_noncached_lock"
                            fi
                        ) &
                        
                        batch_pids+=($!)
                    done
                    
                    # Wait for batch to complete
                    for pid in "${batch_pids[@]}"; do
                        wait "$pid" 2>/dev/null || true
                    done
                    
                    # Update progress
                    sorted_count=$((sorted_count + batch_size))
                    if [[ $sorted_count -gt $total_files ]]; then
                        sorted_count=$total_files
                    fi
                    
                    # Use newlines in debug mode to avoid overlapping with debug output
                    if should_debug high || should_debug medium; then
                        echo -e "${CYAN}Sorted: ${sorted_count}/${total_files} files${NC}" >&2
                    else
                        echo -ne "\r${CYAN}Sorted: ${sorted_count}/${total_files} files${NC}" >&2
                    fi
                done
                
                echo "" >&2
                
                # Load results into arrays
                if [[ -f "$temp_cached_list" ]]; then
                    while IFS= read -r file; do
                        CACHED_FILES+=("$file")
                    done < "$temp_cached_list"
                fi
                
                if [[ -f "$temp_noncached_list" ]]; then
                    while IFS= read -r file; do
                        NON_CACHED_FILES+=("$file")
                    done < "$temp_noncached_list"
                fi
                
                # Cleanup
                rm -f "$temp_cached_list" "$temp_noncached_list" 2>/dev/null
                rmdir "$temp_cached_lock" "$temp_noncached_lock" 2>/dev/null || true
                
                print_success "Parallel cache sorting complete: ${#CACHED_FILES[@]} cached, ${#NON_CACHED_FILES[@]} non-cached"
                
            else
                # Sequential cache sorting (original code)
                if [[ "$PARALLEL_PARSING" == "true" ]]; then
                    print_info "Parallel cache sorting disabled: too few files (need > $((PARALLEL_PARSE_JOBS * 2)))"
                fi
            
            for file in "${VIDEO_FILES[@]}"; do
                # Check for interrupt during file processing
                check_interrupt
                
                # Skip if file no longer exists (may have been moved by another instance)
                if [[ ! -f "$file" ]]; then
                    should_debug high && echo "[DEBUG] File disappeared during cache sorting, skipping: $(basename "$file")" >&2
                    continue
                fi
                
                local file_title=""
                local file_year=""
                
                # Always try in-memory cache first (eliminates redundant parsing)
                local cached_data=$(lookup_parse_cache "$file")
                if [[ -n "$cached_data" ]]; then
                    file_title="${cached_data%%|*}"
                    file_year="${cached_data#*|}"
                    should_debug high && echo "[DEBUG] Using cached parse results for: $(basename "$file") -> '$file_title' ($file_year)" >&2
                else
                    # Cache miss: parse the file (should be rare since duplicate scan caches everything)
                    should_debug high && echo "[DEBUG] Cache miss - parsing: $(basename "$file")" >&2
                    local parent_folder=$(dirname "$file")
                    local folder_title=""
                    local folder_year=""
                    if [[ "$parent_folder" != "$SOURCE" ]]; then
                        parse_filename "$parent_folder" "folder"
                        folder_title="$PARSED_TITLE"
                        folder_year="$PARSED_YEAR"
                    fi
                    
                    parse_filename "$file"
                    
                    # Use folder info if filename parsing failed
                    if [[ -z "$PARSED_TITLE" && -n "$folder_title" ]]; then
                        PARSED_TITLE="$folder_title"
                    fi
                    if [[ -z "$PARSED_YEAR" && -n "$folder_year" ]]; then
                        PARSED_YEAR="$folder_year"
                    fi
                    
                    file_title="$PARSED_TITLE"
                    file_year="$PARSED_YEAR"
                fi
                
                # Check if in cache
                if [[ -n "$file_title" && -n "$file_year" ]]; then
                    local cached_data=$(get_cached_movie "$file_title" "$file_year")
                    if [[ -n "$cached_data" ]]; then
                        CACHED_FILES+=("$file")
                    else
                        NON_CACHED_FILES+=("$file")
                    fi
                else
                    # No title/year, treat as non-cached
                    NON_CACHED_FILES+=("$file")
                fi
            done
            fi  # End parallel/sequential cache sorting
            
            # Sort each group alphabetically by basename and combine
            # Use temp files + awk pipeline instead of subshell for-loops (much faster for 1000+ files)
            local _sort_tmp="/tmp/movie_sort_$$.txt"
            if [[ ${#CACHED_FILES[@]} -gt 0 && ${#NON_CACHED_FILES[@]} -gt 0 ]]; then
                # Both groups: sort each, then concatenate (cached first)
                printf '%s\n' "${CACHED_FILES[@]}" | awk -F'/' '{print tolower($NF)"\t"$0}' | sort -k1,1 | cut -f2- > "$_sort_tmp"
                CACHED_FILES=(); while IFS= read -r f; do CACHED_FILES+=("$f"); done < "$_sort_tmp"
                printf '%s\n' "${NON_CACHED_FILES[@]}" | awk -F'/' '{print tolower($NF)"\t"$0}' | sort -k1,1 | cut -f2- > "$_sort_tmp"
                NON_CACHED_FILES=(); while IFS= read -r f; do NON_CACHED_FILES+=("$f"); done < "$_sort_tmp"
                VIDEO_FILES=("${CACHED_FILES[@]}" "${NON_CACHED_FILES[@]}")
            elif [[ ${#CACHED_FILES[@]} -gt 0 ]]; then
                # Only cached files
                printf '%s\n' "${CACHED_FILES[@]}" | awk -F'/' '{print tolower($NF)"\t"$0}' | sort -k1,1 | cut -f2- > "$_sort_tmp"
                VIDEO_FILES=(); while IFS= read -r f; do VIDEO_FILES+=("$f"); done < "$_sort_tmp"
            else
                # Only non-cached files (common case: empty cache/dest)
                # Single sort pass — no need to sort NON_CACHED_FILES separately then re-sort VIDEO_FILES
                printf '%s\n' "${NON_CACHED_FILES[@]}" | awk -F'/' '{print tolower($NF)"\t"$0}' | sort -k1,1 | cut -f2- > "$_sort_tmp"
                VIDEO_FILES=(); while IFS= read -r f; do VIDEO_FILES+=("$f"); done < "$_sort_tmp"
            fi
            rm -f "$_sort_tmp" 2>/dev/null
            
            echo ""
            if [[ ${#CACHED_FILES[@]} -gt 0 ]]; then
                print_success "Found ${#CACHED_FILES[@]} file(s) in cache (will process first)"
            fi
            if [[ ${#NON_CACHED_FILES[@]} -gt 0 ]]; then
                print_info "Found ${#NON_CACHED_FILES[@]} file(s) not in cache (will require API lookups)"
            fi
            echo ""
            
            # Show comprehensive processing info
            if [[ ${#DUPLICATE_FILES[@]} -gt 0 ]]; then
                local total_after_dups=$((${#VIDEO_FILES[@]} + ${#DUPLICATE_FILES[@]}))
                print_success "Processing ${#VIDEO_FILES[@]} non-duplicate file(s) | ${#DUPLICATE_FILES[@]} duplicate(s) queued for post-processing | ${#ALL_VIDEO_FILES[@]} total files | Expected ${total_after_dups} after duplicate processing"
            else
                print_success "Processing ${#VIDEO_FILES[@]} non-duplicate file(s) | ${#ALL_VIDEO_FILES[@]} total files"
            fi
            echo ""
            fi
            # End of cache sorting block (skipped in thorough-nocache mode)
            
            # Reset poster display flag for this batch
            unset POSTER_SHOWN
            
            # Track processing time
            local batch_start_time=$SECONDS
            
            # Set cache file based on cache mode before counting
            set_cache_by_resolution ""
            
            # Count cache entries before processing
            local cache_entries_before=0
            if [[ -f "$CACHE_FILE" ]]; then
                cache_entries_before=$(wc -l < "$CACHE_FILE" | tr -d ' ')
            fi
            
            # Initialize cache counter for this batch
            CACHE_COUNT=0
            
            # Set up Ctrl+C handler for immediate exit
            # Save current trap state to restore later
            local old_trap=$(trap -p INT)
            local old_exit_trap=$(trap -p EXIT)
            
            # More aggressive interrupt handler
            interrupt_handler() {
                INTERRUPTED=true
                echo "" >&2
                echo -e "\n${YELLOW:-}Ctrl+C detected - stopping...${NC:-}" >&2
                
                # Kill all child processes aggressively
                pkill -P $$ 2>/dev/null || true
                jobs -p | xargs kill -9 2>/dev/null || true
                
                trap - INT  # Restore default
                trap - EXIT
                exit 130  # Standard exit code for Ctrl+C
            }
            
            # Function to detect unexpected early exit
            exit_handler() {
                local exit_code=$?
                # Exit codes 0, 2, 3, 4, 130 are expected (success, already linked, locked, already processed, Ctrl+C)
                if [[ $exit_code -ne 0 && $exit_code -ne 2 && $exit_code -ne 3 && $exit_code -ne 4 && $exit_code -ne 130 ]]; then
                    echo ""
                    echo "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"
                    echo "⚠️  DEBUG: Instance PID $$ exiting unexpectedly with code $exit_code"
                    echo "   Current file index: ${current_index:-${file_index:-0}} / $total_files"
                    if [[ "$ROLLING_QUEUE_MODE" == "true" ]]; then
                        echo "   Processed so far: ${success_count:-0} successful, ${failed_count:-0} failed"
                        echo "   Already linked: $((${skipped_count:-0} + ${already_processed_count:-0})), Locked: ${locked_count:-0}"
                    else
                        echo "   Processed so far: $success successful, $failed failed"
                        echo "   Already linked: $already_linked_count, Locked: $locked_count"
                    fi
                    echo "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"
                    echo ""
                fi
            }
            
            trap interrupt_handler INT
            trap exit_handler EXIT
            
            # Process each file
            local success=0
            local failed=0
            local current_index=0
            local total_files=${#VIDEO_FILES[@]}
            local locked_count=0
            local already_linked_count=0
            local lower_bitrate_count=0
            local ia_duplicate_count=0
            
            # Stop media server containers once (only if there are files to process)
            if [[ "$STOP_MEDIA_SERVERS" == "true" && "${_DOCKER_STOPPED:-}" != "true" && $total_files -gt 0 ]]; then
                echo ""
                stop_media_server_containers
                _DOCKER_STOPPED=true
                echo ""
            fi

            # Debug: Show what we're about to process
            echo ""
            echo "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"
            echo "🔍 DEBUG: Instance PID $$ starting to process $total_files files"
            echo "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"
            echo ""
            
            # Initialize API counter file for parallel processing
            export API_COUNTER_FILE="${CACHE_DIR}/.api_counter_$$.tmp"
            > "$API_COUNTER_FILE"  # Create empty file
            
            # Check if parallel processing is enabled
            if [[ "$PARALLEL_PROCESSING" == "true" && "$AUTO_MODE" == "y" ]]; then
                # Load rolling queue mode setting
                [[ -f "${CACHE_DIR}/rolling_queue_mode.txt" ]] && ROLLING_QUEUE_MODE=$(cat "${CACHE_DIR}/rolling_queue_mode.txt")
                
                if [[ "$ROLLING_QUEUE_MODE" == "true" ]]; then
                    print_success "Parallel processing enabled: ${PARALLEL_JOBS} simultaneous jobs (rolling queue)"
                else
                    print_success "Parallel processing enabled: ${PARALLEL_JOBS} simultaneous jobs (batch mode)"
                fi
                echo ""
                
                if [[ "$ROLLING_QUEUE_MODE" == "true" ]]; then
                    # Use rolling queue approach - start new jobs as soon as slots open
                    local -a active_pids=()
                    local -a active_files=()
                    local -a active_indices=()
                    local file_index=0
                    local success_count=0
                    local failed_count=0
                    local already_linked_count_rq=0  # Exit 2: already hardlinked from previous run
                    local already_processed_count=0  # Exit 4: already processed after lock check
                    local locked_count_rq=0  # Exit 3: locked by another instance
                    local ia_duplicate_count_rq=0  # Exit 5: .ia duplicate
                    local lower_bitrate_count_rq=0  # Exit 6: lower quality duplicate
                    
                    # Disable posters during parallel processing to prevent terminal corruption
                    export DISABLE_IMAGES="true"
                    
                    # Main processing loop
                    while [[ $file_index -lt $total_files ]] || [[ ${#active_pids[@]} -gt 0 ]]; do
                        # Check for completed jobs (non-blocking) - collect completed indices first
                        local -a completed_indices=()
                        local jobs_completed=0
                        
                        for i in "${!active_pids[@]}"; do
                            local pid="${active_pids[$i]}"
                            if ! kill -0 "$pid" 2>/dev/null; then
                                local completed_idx="${active_indices[$i]}"
                                ((jobs_completed++)) || true
                                
                                # Capture exit code without triggering set -e
                                # IMPORTANT: Reset exit_code BEFORE wait to prevent previous iteration's value persisting
                                local exit_code=0
                                wait "$pid" 2>/dev/null || exit_code=$?
                                
                                echo "⚠️  PARENT DEBUG: PID=$pid waited, captured exit_code=$exit_code" >&2
                                
                                case $exit_code in
                                    0) ((success_count++)) || true ;; # Successfully processed
                                    1) ((failed_count++)) || true ;; # Failed to process
                                    2) ((already_linked_count_rq++)) || true ;; # Already linked before lock (from previous run)
                                    3) ((locked_count_rq++)) || true ;; # Locked by another instance
                                    4) ((already_processed_count++)) || true ;; # Already processed after lock
                                    5) ((ia_duplicate_count_rq++)) || true ;; # .ia duplicate
                                    6) ((lower_bitrate_count_rq++)) || true ;; # Lower quality duplicate
                                    7) ((already_linked_count_rq++)) || true ;; # Destination exists with different source (movie already processed)
                                    *) ((failed_count++)) || true ;; # Unknown error
                                esac
                                
                                if [[ "$DIAGNOSTICS_MODE" == "true" ]]; then
                                    echo "[DIAG] Parallel job END: PID=$pid Index=$completed_idx ExitCode=$exit_code Time=$(date '+%Y-%m-%d %H:%M:%S')" >&2
                                fi
                                
                                # Mark for removal
                                completed_indices+=("$i")
                            fi
                        done
                        
                        # Only compact arrays if jobs actually completed
                        if [[ $jobs_completed -gt 0 ]]; then
                            # Remove completed jobs from arrays (in reverse order to preserve indices)
                            for ((idx=${#completed_indices[@]}-1; idx>=0; idx--)); do
                                local i="${completed_indices[$idx]}"
                                unset 'active_pids[$i]'
                                unset 'active_files[$i]'
                                unset 'active_indices[$i]'
                            done
                            
                            # Compact arrays to remove gaps from unset elements
                            active_pids=("${active_pids[@]}")
                            active_files=("${active_files[@]}")
                            active_indices=("${active_indices[@]}")
                        fi
                        
                        # Start new jobs for available slots
                        while [[ ${#active_pids[@]} -lt $PARALLEL_JOBS ]] && [[ $file_index -lt $total_files ]]; do
                            local video_file="${VIDEO_FILES[$file_index]}"
                            local display_index=$((file_index + 1))
                            ((file_index++)) || true
                            
                            # Track which source folder is being processed
                            for src in "${SOURCES[@]}"; do
                                if [[ "$video_file" == "$src"/* ]]; then
                                    local rel_path="${video_file#$src/}"
                                    local source_subfolder="${rel_path%%/*}"
                                    if [[ -n "$source_subfolder" && "$source_subfolder" != "$rel_path" ]]; then
                                        echo "$source_subfolder" >> "${CACHE_DIR}/.processed_folders_$$.tmp"
                                    fi
                                    break
                                fi
                            done
                            
                            echo -e "${DIM}[QUEUE] Starting job ${display_index}/${total_files} (active: ${#active_pids[@]}/${PARALLEL_JOBS})${NC}" >&2
                            
                            if [[ "$DIAGNOSTICS_MODE" == "true" ]]; then
                                echo "[DIAG] Parallel job START: File='$(basename "$video_file")' Index=$display_index Time=$(date '+%Y-%m-%d %H:%M:%S')" >&2
                            fi
                            
                            (
                                local job_pid=$$
                                
                                if [[ ! -f "$video_file" ]]; then
                                    echo ""
                                    print_info "========================================="
                                    print_info "Movie ${display_index}/${total_files}: $(basename "$video_file")"
                                    print_info "========================================="
                                    echo "⚠️  DIAGNOSTIC C: File check before process_file failed"
                                    echo "   Path: $video_file"
                                    ls -la "$video_file" 2>&1 || true
                                    exit 4
                                fi
                                
                                echo ""
                                print_info "========================================="
                                print_info "Movie ${display_index}/${total_files}: $(basename "$video_file")"
                                print_info "========================================="
                                
                                set_cache_by_resolution "$video_file"
                                
                                process_file "$video_file" "$AUTO_MODE" || exit_code=$?
                                echo "⚠️  DEBUG: After process_file, exit_code=${exit_code:-UNSET} \$?=$?" >&2
                                if [[ ${exit_code:-0} -eq 4 ]]; then
                                    echo "⚠️  DIAGNOSTIC E: process_file returned exit code 4"
                                    echo "   File: $video_file"
                                fi
                                echo "⚠️  DEBUG: About to exit with: ${exit_code:-0}" >&2
                                exit ${exit_code:-0}
                            ) &
                            
                            local job_pid=$!
                            active_pids+=("$job_pid")
                            active_files+=("$video_file")
                            active_indices+=("$display_index")
                        done
                        
                        # Sleep only if we have active jobs but didn't complete any this iteration
                        if [[ ${#active_pids[@]} -gt 0 ]] && [[ $jobs_completed -eq 0 ]]; then
                            sleep 0.01
                        fi
                    done
                    
                    # Transfer rolling queue counters to main counters
                    success=$success_count
                    failed=$failed_count
                    already_linked_count=$already_linked_count_rq  # Files that were already hardlinked from previous run
                    locked_count=$locked_count_rq
                    lower_bitrate_count=$lower_bitrate_count_rq
                    ia_duplicate_count=$ia_duplicate_count_rq
                    # Note: already_processed_count (exit 4) is lumped with already_linked since both mean "already done"
                    already_linked_count=$((already_linked_count + already_processed_count))
                    
                else
                    # Batch mode - original behavior
                    # Process files in parallel batches
                    local batch_size=$PARALLEL_JOBS
                    local file_index=0
                    
                    # Disable posters during parallel processing to prevent terminal corruption
                    export DISABLE_IMAGES="true"
                
                while [[ $file_index -lt $total_files ]]; do
                    # Start batch of parallel jobs
                    local batch_pids=()
                    local batch_files=()
                    local batch_start=$file_index
                    
                    for ((i=0; i<batch_size && file_index<total_files; i++)); do
                        local video_file="${VIDEO_FILES[$file_index]}"
                        local display_index=$((file_index + 1))  # Calculate display index
                        ((file_index++)) || true
                        batch_files+=("$video_file")
                        
                        # Track which source folder is being processed
                        for src in "${SOURCES[@]}"; do
                            if [[ "$video_file" == "$src"/* ]]; then
                                local rel_path="${video_file#$src/}"
                                local source_subfolder="${rel_path%%/*}"
                                if [[ -n "$source_subfolder" && "$source_subfolder" != "$rel_path" ]]; then
                                    echo "$source_subfolder" >> "${CACHE_DIR}/.processed_folders_$$.tmp"
                                fi
                                break
                            fi
                        done

                        # Diagnostics: Log job start
                        if [[ "$DIAGNOSTICS_MODE" == "true" ]]; then
                            local job_start_time=$(date '+%Y-%m-%d %H:%M:%S')
                            echo "[DIAG] Parallel job START: PID=$$ File='$(basename "$video_file")' Index=$display_index Time=$job_start_time" >&2
                        fi

                        (
                            local job_pid=$$
                            
                            if [[ "$DIAGNOSTICS_MODE" == "true" ]]; then
                                local job_start_time=$(date '+%Y-%m-%d %H:%M:%S')
                                echo "[DIAG] [PID $job_pid] Job started: File='$(basename "$video_file")' Index=$display_index Time=$job_start_time" >&2

                                # Diagnostics: Log resource usage at job start
                                echo "[DIAG] [PID $job_pid] Resource usage at start:" >&2
                                top -l 1 | head -n 10 >&2
                            fi

                            # Check if file still exists (may have been moved/deleted by another instance)
                            if [[ ! -f "$video_file" ]]; then
                                echo ""
                                print_info "========================================="
                                print_info "Movie ${display_index}/${total_files}: $(basename "$video_file")"
                                print_info "========================================="
                                echo "⚠️  DIAGNOSTIC D: File check in batch mode failed"
                                echo "   Path: $video_file"
                                ls -la "$video_file" 2>&1 || true
                                exit 4  # Exit code 4: already processed
                            fi

                            echo ""
                            print_info "========================================="
                            print_info "Movie ${display_index}/${total_files}: $(basename "$video_file")"
                            print_info "========================================="

                            # Set appropriate cache file based on video resolution
                            set_cache_by_resolution "$video_file"

                            # Diagnostics: Log lock acquisition
                            if [[ "$DIAGNOSTICS_MODE" == "true" ]]; then
                                echo "[DIAG] [PID $job_pid] Attempting to acquire file lock for '$video_file' at $(date '+%Y-%m-%d %H:%M:%S')" >&2
                            fi

                            # Capture exit code without triggering set -e
                            process_file "$video_file" "$AUTO_MODE" || exit_code=$?
                            local exit_code=${exit_code:-0}

                            # Diagnostics: Log job finish
                            if [[ "$DIAGNOSTICS_MODE" == "true" ]]; then
                                local job_finish_time=$(date '+%Y-%m-%d %H:%M:%S')
                                echo "[DIAG] [PID $job_pid] Job finished: File='$(basename "$video_file")' Index=$display_index Time=$job_finish_time ExitCode=$exit_code" >&2

                                # Diagnostics: Log resource usage at job finish
                                echo "[DIAG] [PID $job_pid] Resource usage at finish:" >&2
                                top -l 1 | head -n 10 >&2
                            fi

                            # Exit with the same code so parent can track it
                            exit $exit_code
                        ) &
                        batch_pids+=($!)
                    done
                    
                    # Wait for all jobs in this batch to complete and track exit codes
                    for pid in "${batch_pids[@]}"; do
                        # Capture exit code without triggering set -e
                        # IMPORTANT: Reset exit_code BEFORE wait to prevent previous iteration's value persisting
                        local exit_code=0
                        wait "$pid" 2>/dev/null || exit_code=$?
                        
                        case $exit_code in
                            0)
                                # Successfully processed
                                ((success++)) || true
                                ;;
                            2)
                                # Already linked before lock
                                ((already_linked_count++)) || true
                                ;;
                            3)
                                # Locked by another instance
                                ((locked_count++)) || true
                                ;;
                            4)
                                # Already linked after lock
                                ((already_linked_count++)) || true
                                ;;
                            5)
                                # .ia duplicate skipped
                                ((already_linked_count++)) || true
                                ;;
                            6)
                                # Lower quality duplicate skipped (filtered during processing)
                                ((already_linked_count++)) || true
                                ;;
                            7)
                                # Destination exists with different source (movie already processed)
                                ((already_linked_count++)) || true
                                ;;
                            *)
                                # Failed to process
                                ((failed++)) || true
                                ;;
                        esac
                    done
                done
                
                    # Read failed files from temp file (populated by parallel jobs)
                    if [[ -f "${CACHE_DIR}/.failed_parse_$$.tmp" ]]; then
                        while IFS= read -r failed_file; do
                            FAILED_PARSE+=("$failed_file")
                        done < "${CACHE_DIR}/.failed_parse_$$.tmp"
                        rm -f "${CACHE_DIR}/.failed_parse_$$.tmp"
                    fi
                fi  # End of batch mode
                
                # Read failed files from temp file (populated by parallel jobs)
                if [[ -f "${CACHE_DIR}/.failed_parse_$$.tmp" ]]; then
                    while IFS= read -r failed_file; do
                        FAILED_PARSE+=("$failed_file")
                    done < "${CACHE_DIR}/.failed_parse_$$.tmp"
                    rm -f "${CACHE_DIR}/.failed_parse_$$.tmp"
                fi
            else
                # Sequential processing (original behavior)
                for video_file in "${VIDEO_FILES[@]}"; do
                    # Check for interrupt before processing each file
                    check_interrupt
                    
                    ((current_index++)) || true
                    echo ""
                    print_info "========================================="
                    print_info "Movie ${current_index}/${total_files}: $(basename "$video_file")"
                    print_info "========================================="
                    
                    # Check if file still exists (may have been moved/deleted by another instance)
                    if [[ ! -f "$video_file" ]]; then
                        echo "⏭️  File no longer exists (moved/processed by another instance)"
                        ((already_linked_count++)) || true
                        continue
                    fi
                    
                    # Set appropriate cache file based on video resolution
                    set_cache_by_resolution "$video_file"
                    
                    process_file "$video_file" "$AUTO_MODE"
                    local exit_code=$?
                    
                    case $exit_code in
                        0)
                            # Successfully processed
                            ((success++)) || true
                            
                            # Check if TMDb ID or IMDb ID is missing in the created folder
                            # Read folder name from process-specific temp file (PID is the subshell PID)
                            local folder_temp_file="${CACHE_DIR}/.folder_${pid}.tmp"
                            local created_folder=""
                            if [[ -f "$folder_temp_file" ]]; then
                                created_folder=$(cat "$folder_temp_file")
                                rm -f "$folder_temp_file"
                            fi
                            
                            if [[ -n "$created_folder" ]] && { [[ "$created_folder" =~ \[tmdbid-\] ]] || [[ "$created_folder" =~ \[imdbid-\] ]]; }; then
                                # Extract title and year for tracking (use in-memory cache)
                                local cached_data=$(lookup_parse_cache "$video_file")
                                if [[ -n "$cached_data" ]]; then
                                    PARSED_TITLE="${cached_data%%|*}"
                                    PARSED_YEAR="${cached_data#*|}"
                                else
                                    # Fallback: parse if not in cache
                                    parse_filename "$video_file"
                                fi
                                
                                # Check which IDs are missing
                                local missing_imdb=""
                                local missing_tmdb=""
                                [[ "$created_folder" =~ \[imdbid-\] ]] && missing_imdb="yes"
                                [[ "$created_folder" =~ \[tmdbid-\] ]] && missing_tmdb="yes"
                                
                                # Store the destination path for renaming later
                                local dest_path="${DESTINATION}/${created_folder}"
                                FAILED_LOOKUPS+=("$dest_path|||$PARSED_TITLE|||$PARSED_YEAR|||$missing_imdb|||$missing_tmdb")
                            fi
                            ;;
                        2)
                            # Already linked before lock
                            ((already_linked_count++)) || true
                            ;;
                        3)
                            # Locked by another instance
                            ((locked_count++)) || true
                            ;;
                        4)
                            # Already linked after lock (processed while waiting)
                            ((already_linked_count++)) || true
                            ;;
                        5)
                            # .ia duplicate skipped
                            ((lower_bitrate_count++)) || true
                            ;;
                        6)
                            # Lower quality duplicate skipped (filtered during processing)
                            ((lower_bitrate_count++)) || true
                            ;;
                        7)
                            # Destination exists with different source (movie already processed)
                            ((already_linked_count++)) || true
                            ;;
                        *)
                            # Failed to process
                            ((failed++)) || true
                            
                            # Parse the file to determine if it has title/year
                            parse_filename "$video_file"
                            
                            # Determine failure reason and write to temp file for aggregation
                            local fail_reason=""
                            if [[ -n "$PARSED_TITLE" && -n "$PARSED_YEAR" ]]; then
                                # File was parsed but IDs are missing - add to post-processing
                                fail_reason="API lookup failed - could not find IMDb/TMDb IDs for: $PARSED_TITLE ($PARSED_YEAR)"
                                FAILED_LOOKUPS+=("$video_file|||$PARSED_TITLE|||$PARSED_YEAR|||yes|||yes")
                                should_debug high && echo "[DEBUG] Added to FAILED_LOOKUPS: $PARSED_TITLE ($PARSED_YEAR)" >&2
                            else
                                # File couldn't be parsed at all - add to FAILED_PARSE
                                fail_reason="Could not parse title/year from filename or folder name"
                                FAILED_PARSE+=("$video_file")
                                should_debug high && echo "[DEBUG] Added to FAILED_PARSE: $(basename "$video_file")" >&2
                            fi
                            
                            # Write to temp file for aggregation (for failed files display) with reason
                            echo "$video_file|||$fail_reason" >> "${CACHE_DIR}/.failed_files_$$.tmp"
                            print_warning "Skipped: $(basename \"$video_file\")"
                            ;;
                    esac
                    
                    # Track which source folder was processed (for unprocessed folders report)
                    # Extract the immediate subfolder under the source directory
                    for src in "${SOURCES[@]}"; do
                        if [[ "$video_file" == "$src"/* ]]; then
                            # Get the relative path after the source
                            local rel_path="${video_file#$src/}"
                            # Get the first component (immediate subfolder)
                            local source_subfolder="${rel_path%%/*}"
                            if [[ -n "$source_subfolder" && "$source_subfolder" != "$rel_path" ]]; then
                                # File is in a subfolder, record it
                                echo "$source_subfolder" >> "${CACHE_DIR}/.processed_folders_$$.tmp"
                            fi
                            break
                        fi
                    done
                done
            fi
            
            # Restore previous traps
            if [[ -n "$old_trap" ]]; then
                eval "$old_trap"
            else
                trap - INT
            fi
            
            if [[ -n "$old_exit_trap" ]]; then
                eval "$old_exit_trap"
            else
                trap - EXIT
            fi
            
            # Debug: Show processing results
            local PROCESSING_FINISH_TIME=$(date '+%Y-%m-%d %H:%M:%S')
            
            # Calculate elapsed time
            local processing_elapsed=0
            if [[ -n "$PROCESSING_START_TIME" ]]; then
                local start_epoch=$(date -j -f "%Y-%m-%d %H:%M:%S" "$PROCESSING_START_TIME" "+%s" 2>/dev/null || echo 0)
                local finish_epoch=$(date -j -f "%Y-%m-%d %H:%M:%S" "$PROCESSING_FINISH_TIME" "+%s" 2>/dev/null || echo 0)
                if [[ $start_epoch -gt 0 && $finish_epoch -gt 0 ]]; then
                    processing_elapsed=$((finish_epoch - start_epoch))
                fi
            fi
            local processing_minutes=$((processing_elapsed / 60))
            local processing_seconds=$((processing_elapsed % 60))
            
            echo ""
            echo "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"
            echo "🔍 DEBUG: Instance PID $$ finished processing"
            echo "   Start time: ${PROCESSING_START_TIME:-unknown}"
            echo "   Finish time: $PROCESSING_FINISH_TIME"
            if [[ $processing_elapsed -gt 0 ]]; then
                echo "   Elapsed time: ${processing_minutes}m ${processing_seconds}s"
            fi
            echo "   Total files in array: $total_files"
            echo "   Successfully processed: $success"
            echo "   Lower bitrate duplicates skipped: $lower_bitrate_count"
            echo "   Failed to process: $failed"
            echo "   Already linked (skipped): $already_linked_count"
            echo "   Locked by other instance: $locked_count"
            if [[ ${#FAILED_LOOKUPS[@]} -gt 0 ]]; then
                echo "   With missing IDs: ${#FAILED_LOOKUPS[@]} (processed but ID fetch failed)"
            fi
            echo "   Accounted for: $((success + failed + already_linked_count + locked_count + lower_bitrate_count))/$total_files"
            if [[ $((success + failed + already_linked_count + locked_count + lower_bitrate_count)) -ne $total_files ]]; then
                echo "   ⚠️  WARNING: Numbers don't add up! Missing $((total_files - success - failed - already_linked_count - locked_count - lower_bitrate_count)) files!"
            fi
            echo "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"
            echo ""
            
            # Show adjusted file count after lower bitrate filtering
            if [[ $lower_bitrate_count -gt 0 ]]; then
                local actual_processed=$((total_files - lower_bitrate_count))
                echo ""
                print_info "Actual unique files processed: $actual_processed (excluded $lower_bitrate_count lower bitrate duplicate(s))"
                echo ""
            fi
            
            # Calculate elapsed time for this source
            local batch_elapsed=$((SECONDS - batch_start_time))
            local batch_minutes=$((batch_elapsed / 60))
            local batch_seconds=$((batch_elapsed % 60))
            
            # Calculate statistics for this source with 2 decimal places
            local avg_time_per_file="0.00"
            if [[ $success -gt 0 ]]; then
                if command -v bc &> /dev/null; then
                    avg_time_per_file=$(echo "scale=2; $batch_elapsed / $success" | bc)
                else
                    avg_time_per_file=$(awk "BEGIN {printf \"%.2f\", $batch_elapsed / $success}")
                fi
            fi
            
            # Calculate total size processed for this source
            local source_size=0
            for video_file in "${VIDEO_FILES[@]}"; do
                # Check for interrupt during size calculation
                check_interrupt
                
                # Skip files that no longer exist (moved to duplicates folder, etc.)
                [[ ! -f "$video_file" ]] && continue
                
                local file_size=$(_stat_size "$video_file" || echo 0)
                source_size=$((source_size + ${file_size:-0}))
            done
            overall_size=$((overall_size + source_size))
            local size_gb=$((source_size / 1073741824))
            local size_mb=$(((source_size % 1073741824) / 1048576))
            
            # Count cache entries using the already-set CACHE_FILE variable
            local total_cache_entries=0
            [[ -f "$CACHE_FILE" ]] && total_cache_entries=$(wc -l < "$CACHE_FILE" | tr -d ' ')
            
            # Determine cache name for display
            local cache_name=""
            case "$CACHE_FILE" in
                *"UNIFIED CACHE.txt") cache_name="Unified cache" ;;
                *"4K CACHE.txt") cache_name="4K cache" ;;
                *"1080p CACHE.txt") cache_name="1080p cache" ;;
                *"1080p X RATED CACHE.txt") cache_name="1080p X RATED cache" ;;
                *"4K X RATED CACHE.txt") cache_name="4K X RATED cache" ;;
                *"CARTOONS CACHE.txt") cache_name="Cartoons cache" ;;
                *"ANIME CACHE.txt") cache_name="Anime cache" ;;
                *) cache_name="cache" ;;
            esac
            
            echo ""
            # Display detailed statistics
            local total_completed=$((success + already_linked_count + locked_count + ia_duplicate_count + lower_bitrate_count))
            print_success "Completed: $success successfully processed, $already_linked_count already existed, $((locked_count + ia_duplicate_count + lower_bitrate_count)) skipped, $failed failed"
            if [[ $locked_count -gt 0 ]] || [[ $ia_duplicate_count -gt 0 ]] || [[ $lower_bitrate_count -gt 0 ]]; then
                print_info "  └─ Skipped breakdown: $locked_count locked by other instance, $ia_duplicate_count .ia duplicates, $lower_bitrate_count lower quality duplicates"
            fi
            print_info "Hardlinking/Batch time: ${batch_minutes}m ${batch_seconds}s (avg ${avg_time_per_file}s per file)"
            
            # Only report data size if files were actually processed (not all skipped)
            if [[ $success -gt 0 ]]; then
                print_info "Data processed: ${size_gb}.$(printf "%03d" $size_mb) GB"
            else
                print_info "Data processed: ${size_gb}.$(printf "%03d" $size_mb) GB (all files skipped - already linked)"
            fi
            local new_entries=$((total_cache_entries - cache_entries_before))
            print_info "Cache entries: $cache_entries_before → $total_cache_entries (+$new_entries new)"
            [[ -n "$cache_name" ]] && print_info "  • Using: $cache_name"
            total_success=$((total_success + success))
            total_failed=$((total_failed + failed))
            overall_success=$((overall_success + success))
            overall_already_existed=$((overall_already_existed + already_linked_count))
            overall_skipped=$((overall_skipped + locked_count + ia_duplicate_count + lower_bitrate_count))
            overall_failed=$((overall_failed + failed))
        fi
    fi  # end all_pre_linked check
   
    # Calculate overall statistics
    local overall_elapsed=$((SECONDS - overall_start_time))
    local overall_minutes=$((overall_elapsed / 60))
    local overall_seconds=$((overall_elapsed % 60))
    
    local overall_avg_time="0.00"
    if [[ $overall_success -gt 0 ]]; then
        # Calculate with 2 decimal places using bc or awk
        if command -v bc &> /dev/null; then
            overall_avg_time=$(echo "scale=2; $overall_elapsed / $overall_success" | bc)
        else
            # Fallback to awk if bc not available
            overall_avg_time=$(awk "BEGIN {printf \"%.2f\", $overall_elapsed / $overall_success}")
        fi
    fi
    
    local overall_size_gb=$((overall_size / 1073741824))
    local overall_size_mb=$(((overall_size % 1073741824) / 1048576))
    
    # Read API call count from file (for parallel processing)
    if [[ -f "$API_COUNTER_FILE" ]]; then
        API_CALL_COUNT=$(wc -l < "$API_COUNTER_FILE" | tr -d ' ')
        rm -f "$API_COUNTER_FILE"
    fi
    
    # Get cache statistics
    # Robust cache entry counting: always use final cache file after all processing
    local overall_cache_after=0
    if [[ -f "$CACHE_FILE" ]]; then
        overall_cache_after=$(awk 'NF' "$CACHE_FILE" 2>/dev/null | wc -l | tr -d ' ' || echo 0)
    else
        overall_cache_after=0
    fi
    local cache_entries_before=0
    local new_cache_entries=0
    if [[ -f "${CACHE_DIR}/movie_cache_before.txt" ]]; then
        cache_entries_before=$(cat "${CACHE_DIR}/movie_cache_before.txt")
        new_cache_entries=$((overall_cache_after - cache_entries_before))
        rm -f "${CACHE_DIR}/movie_cache_before.txt"
    fi
    
    # Summary with detailed statistics
    echo ""
    local STATISTICS_TIME=$(date '+%Y-%m-%d %H:%M:%S')
    echo -e "${BLUE}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
    echo -e "${CYAN}MOVIE PROCESSING STATISTICS${NC}"
    echo -e "${BLUE}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
    echo ""
    print_info "Instance PID: $$"
    print_info "Started: ${PROCESSING_START_TIME:-unknown}"
    print_info "Finished: $STATISTICS_TIME"
    echo ""
    print_info "Files found: $ORIGINAL_FILE_COUNT total"
    if [[ ${EXTENSION_DUPLICATES_FILTERED:-0} -gt 0 ]]; then
        print_info "Extension duplicates filtered: $EXTENSION_DUPLICATES_FILTERED (lower bitrate/resolution)"
        
        # Show details of kept vs rejected files in table format
        if [[ -f "$EXTENSION_DUP_LOG" ]]; then
            echo ""
            echo -e "${CYAN}Extension Duplicate Details:${NC}"
            echo -e "${DIM}────────────────────────────────────────────────────────────────────────────────${NC}"
            
            # Group by folder for table display
            local current_folder=""
            local folder_files=()
            local folder_statuses=()
            local folder_resolutions=()
            local folder_bitrates=()
            local folder_sizes=()
            local folder_reasons=()
            
            while IFS='|' read -r status filepath resolution bitrate reason; do
                local folder=$(dirname "$filepath")
                
                # If we hit a new folder, print the previous folder's table
                if [[ -n "$current_folder" && "$folder" != "$current_folder" ]]; then
                    # Print table for this folder
                    local parent_folder=$(basename "$current_folder")
                    echo -e "${CYAN}Folder: ${parent_folder}${NC}"
                    printf "%-51s %-13s %-16s %-13s %-15s %-25s\n" "File" "Status" "Resolution" "Bitrate" "Size" "Reason"
                    printf "%-51s %-13s %-16s %-13s %-15s %-25s\n" "$(printf '%.0s─' {1..51})" "$(printf '%.0s─' {1..13})" "$(printf '%.0s─' {1..16})" "$(printf '%.0s─' {1..13})" "$(printf '%.0s─' {1..15})" "$(printf '%.0s─' {1..25})"
                    
                    for i in "${!folder_files[@]}"; do
                        local filename=$(basename "${folder_files[$i]}")
                        local status_display=""
                        local color=""
                        local reason_text=""
                        
                        if [[ "${folder_statuses[$i]}" == "KEPT" ]]; then
                            status_display="✓ Kept"
                            color="${GREEN}"
                            if [[ "${folder_reasons[$i]}" == "bitrate" ]]; then
                                reason_text="Higher bitrate"
                            else
                                reason_text="Higher resolution"
                            fi
                        else
                            status_display="✗ Rejected"
                            color="${RED}"
                            if [[ "${folder_reasons[$i]}" == "bitrate" ]]; then
                                reason_text="Lower bitrate"
                            else
                                reason_text="Lower resolution"
                            fi
                        fi
                        
                        # Print filename in color, then reset and print rest without color interference
                        local bitrate_formatted=$(format_bitrate "${folder_bitrates[$i]}")
                        printf "${color}%-51s${NC} ${color}%-13s${NC} %-16s %-13s %-15s %-25s\n" \
                            "${filename:0:49}" \
                            "$status_display" \
                            "${folder_resolutions[$i]}" \
                            "$bitrate_formatted" \
                            "${folder_sizes[$i]}" \
                            "$reason_text"
                    done
                    echo ""
                    
                    # Reset arrays
                    folder_files=()
                    folder_statuses=()
                    folder_resolutions=()
                    folder_bitrates=()
                    folder_sizes=()
                    folder_reasons=()
                fi
                
                current_folder="$folder"
                
                # Get file size
                local file_size="N/A"
                if [[ -f "$filepath" ]]; then
                    local size_bytes=$(_stat_size "$filepath" || echo 0)
                    file_size=$(format_bytes "$size_bytes")
                fi
                
                # Add to arrays
                folder_files+=("$filepath")
                folder_statuses+=("$status")
                folder_resolutions+=("$resolution")
                folder_bitrates+=("$bitrate")
                folder_sizes+=("$file_size")
                folder_reasons+=("$reason")
            done < "$EXTENSION_DUP_LOG"
            
            # Print last folder's table
            if [[ -n "$current_folder" ]]; then
                local parent_folder=$(basename "$current_folder")
                echo -e "${CYAN}Folder: ${parent_folder}${NC}"
                printf "%-51s %-13s %-16s %-13s %-15s %-25s\n" "File" "Status" "Resolution" "Bitrate" "Size" "Reason"
                printf "%-51s %-13s %-16s %-13s %-15s %-25s\n" "$(printf '%.0s─' {1..51})" "$(printf '%.0s─' {1..13})" "$(printf '%.0s─' {1..16})" "$(printf '%.0s─' {1..13})" "$(printf '%.0s─' {1..15})" "$(printf '%.0s─' {1..25})"
                
                for i in "${!folder_files[@]}"; do
                    local filename=$(basename "${folder_files[$i]}")
                    local status_display=""
                    local color=""
                    local reason_text=""
                    
                    if [[ "${folder_statuses[$i]}" == "KEPT" ]]; then
                        status_display="✓ Kept"
                        color="${GREEN}"
                        if [[ "${folder_reasons[$i]}" == "bitrate" ]]; then
                            reason_text="Higher bitrate"
                        else
                            reason_text="Higher resolution"
                        fi
                    else
                        status_display="✗ Rejected"
                        color="${RED}"
                        if [[ "${folder_reasons[$i]}" == "bitrate" ]]; then
                            reason_text="Lower bitrate"
                        else
                            reason_text="Lower resolution"
                        fi
                    fi
                    
                    # Print filename in color, then reset and print rest without color interference
                    local bitrate_formatted=$(format_bitrate "${folder_bitrates[$i]}")
                    printf "${color}%-51s${NC} ${color}%-13s${NC} %-16s %-13s %-15s %-25s\n" \
                        "${filename:0:49}" \
                        "$status_display" \
                        "${folder_resolutions[$i]}" \
                        "$bitrate_formatted" \
                        "${folder_sizes[$i]}" \
                        "$reason_text"
                done
                echo ""
            fi
            
            echo -e "${DIM}────────────────────────────────────────────────────────────────────────────────${NC}"
        fi
    fi
        
    # Robust duplicate and filtered file statistics: always use final exported counts
    print_info "Files after filtering: ${FILTERED_FILE_COUNT:-$ORIGINAL_FILE_COUNT}"

    if [[ ${FILES_AFTER_CLAIMING:-$ORIGINAL_FILE_COUNT} -lt $ORIGINAL_FILE_COUNT ]]; then
        local claimed_by_others=$((ORIGINAL_FILE_COUNT - FILES_AFTER_CLAIMING))
        print_info "Files claimed by other instances: $claimed_by_others"
        print_info "Files claimed by this instance: $FILES_AFTER_CLAIMING"
    fi
    if [[ ${EXTENSION_DUPLICATES_FILTERED:-0} -gt 0 ]]; then
        local other_duplicates=$((${DUPLICATES_DETECTED:-0} - ${EXTENSION_DUPLICATES_FILTERED:-0}))
        if [[ $other_duplicates -gt 0 ]]; then
            print_info "Extension duplicates filtered: ${EXTENSION_DUPLICATES_FILTERED:-0}"
            print_info "Other duplicates detected: $other_duplicates file(s)"
            print_info "Total duplicates: ${DUPLICATES_DETECTED:-0} file(s)"
        else
            print_info "Extension duplicates filtered: ${EXTENSION_DUPLICATES_FILTERED:-0} (all duplicates were extension-based)"
        fi
        print_info "Unique files to process: ${TOTAL_FILES_FOUND:-${FILTERED_FILE_COUNT:-$ORIGINAL_FILE_COUNT}}"
    elif [[ ${DUPLICATES_DETECTED:-0} -gt 0 ]]; then
        print_info "Duplicates detected: ${DUPLICATES_DETECTED:-0} file(s) (non-extension based)"
        print_info "Unique files to process: ${TOTAL_FILES_FOUND:-${FILTERED_FILE_COUNT:-$ORIGINAL_FILE_COUNT}}"
    fi
    
    # --- AGGREGATE FAILED FILES FROM ALL TEMP FILES BEFORE DISPLAYING STATISTICS ---
    # Reset FAILED_FILES array to ensure clean aggregation
    FAILED_FILES=()
    if [[ -d "$CACHE_DIR" ]]; then
        for tmpfile in "$CACHE_DIR"/.failed_files_*.tmp; do
            [[ -e "$tmpfile" ]] || continue
            while IFS= read -r failed_file; do
                [[ -n "$failed_file" ]] && FAILED_FILES+=("$failed_file")
            done < "$tmpfile"
            rm -f "$tmpfile"
        done
    fi
    
    # Remove duplicates (if any) from aggregated failed files
    if [[ ${#FAILED_FILES[@]} -gt 0 ]]; then
        IFS=$'\n' FAILED_FILES=($(printf "%s\n" "${FAILED_FILES[@]}" | awk '!seen[$0]++'))
        unset IFS
    fi
    
    # Use aggregated failed files count for statistics display
    local reported_failed_count=${#FAILED_FILES[@]}
    local total_handled=$((overall_success + overall_already_existed + overall_skipped))
    print_success "Files processed: $overall_success/${FILTERED_FILE_COUNT:-$ORIGINAL_FILE_COUNT} successfully processed, $overall_already_existed already existed, $overall_skipped skipped, $reported_failed_count failed"
    print_info "Total processing time: ${overall_minutes}m ${overall_seconds}s (avg ${overall_avg_time}s per file)"
    print_info "  └─ Includes: file scanning, duplicate detection, filtering, hardlinking, and post-processing"
    
    # Calculate files per second (rounded to 2 decimal places)
    local files_per_second="0.00"
    if [[ $overall_elapsed -gt 0 && $overall_success -gt 0 ]]; then
        if command -v bc &> /dev/null; then
            files_per_second=$(echo "scale=2; $overall_success / $overall_elapsed" | bc)
        else
            files_per_second=$(awk "BEGIN {printf \"%.2f\", $overall_success / $overall_elapsed}")
        fi
    fi
    print_info "Processing rate: $files_per_second files/sec"
    
    # Show parallel processing info if enabled
    if [[ "$PARALLEL_PROCESSING" == "true" ]]; then
        local queue_mode="off"
        [[ "$ROLLING_QUEUE_MODE" == "true" ]] && queue_mode="on"
        local parse_info="off"
        [[ "$PARALLEL_PARSING" == "true" ]] && parse_info="${PARALLEL_PARSE_JOBS} jobs"
        print_info "Parallel processing: ${PARALLEL_JOBS} jobs, rolling queue: ${queue_mode}, parsing: ${parse_info}"
    fi
    
    # Only report data size if files were actually processed (not all skipped)
    if [[ $overall_success -gt 0 ]]; then
        print_info "Data processed: ${overall_size_gb}.$(printf "%03d" $overall_size_mb) GB"
    else
        print_info "Data processed: ${overall_size_gb}.$(printf "%03d" $overall_size_mb) GB (all files skipped - already linked)"
    fi
    # Calculate actual destination folder count vs cache entries to find discrepancies
    # This check runs regardless of whether new files were processed
    local dest_folder_count=0
    local cache_vs_dest_diff=0
    local -a missing_from_cache=()
    if [[ -n "$DESTINATION" && -d "$DESTINATION" ]]; then
        # Count only movie folders (exclude hidden folders like .qspacesettings, .DS_Store parent, etc.)
        dest_folder_count=$(find "$DESTINATION" -maxdepth 1 -mindepth 1 -type d -not -name ".*" 2>/dev/null | wc -l | tr -d ' ')
        # Compare destination folders to cache entries - any difference means files failed to cache
        if [[ $dest_folder_count -gt $overall_cache_after ]]; then
            cache_vs_dest_diff=$((dest_folder_count - overall_cache_after))
            
            # Find which destination folders are NOT in cache by comparing IMDb IDs
            # Exclude hidden folders from this check
            while IFS= read -r -d '' dest_dir; do
                local dir_name=$(basename "$dest_dir")
                # Skip hidden folders
                [[ "$dir_name" == .* ]] && continue
                local dir_imdb=$(echo "$dir_name" | grep -oE 'tt[0-9]+')
                if [[ -n "$dir_imdb" ]]; then
                    # Check if this IMDb ID exists in cache
                    if ! grep -q "$dir_imdb" "$CACHE_FILE" 2>/dev/null; then
                        missing_from_cache+=("$dir_name")
                    fi
                else
                    # No IMDb ID in folder name - definitely not in cache properly
                    missing_from_cache+=("$dir_name (no IMDb ID)")
                fi
            done < <(find "$DESTINATION" -maxdepth 1 -mindepth 1 -type d -print0 2>/dev/null)
        fi
    fi
    
    # Check for movies not added to cache (missing IDs)
    local not_cached_count=0
    if [[ -f "${CACHE_DIR}/.missing_cache_ids.tmp" ]]; then
        not_cached_count=$(wc -l < "${CACHE_DIR}/.missing_cache_ids.tmp" | tr -d ' ')
    fi
    
    # Check for files that matched existing cache entries (duplicates/variants)
    local duplicate_cache_count=0
    if [[ -f "${CACHE_DIR}/.duplicate_cache_entries.tmp" ]]; then
        duplicate_cache_count=$(wc -l < "${CACHE_DIR}/.duplicate_cache_entries.tmp" | tr -d ' ')
    fi
    
    # Total not cached: use the larger of missing IDs vs dest-cache gap to avoid double-counting
    # (movies with missing IDs also appear as dest folders not in cache - same movie, not two failures)
    local total_not_cached=$not_cached_count
    if [[ $cache_vs_dest_diff -gt $not_cached_count ]]; then
        total_not_cached=$cache_vs_dest_diff
    fi
    
    # Always show cache statistics if there are entries OR if there's a discrepancy
    if [[ $new_cache_entries -gt 0 ]] || [[ $overall_success -gt 0 ]] || [[ $total_not_cached -gt 0 ]] || [[ $overall_cache_after -gt 0 ]]; then
        if [[ $total_not_cached -gt 0 ]]; then
            print_info "Movie cache entries: $cache_entries_before → $overall_cache_after (+$new_cache_entries new, ${RED}$total_not_cached failed to cache${NC})"
            if [[ $not_cached_count -gt 0 ]]; then
                print_info "  └─ $not_cached_count missing IMDb/TMDb IDs"
                # Show which files are missing IDs inline
                while IFS='|' read -r _title _year _imdb _tmdb _filepath; do
                    local _missing=""
                    [[ -z "$_imdb" ]] && _missing="IMDb"
                    [[ -z "$_tmdb" ]] && { [[ -n "$_missing" ]] && _missing+=", TMDb" || _missing="TMDb"; }
                    echo -e "     ${RED}✗${NC} $_title ($_year) - Missing: $_missing"
                done < "${CACHE_DIR}/.missing_cache_ids.tmp"
            fi
            if [[ $cache_vs_dest_diff -gt 0 ]]; then
                print_info "  └─ $cache_vs_dest_diff destination folder(s) not in cache (dest: $dest_folder_count, cache: $overall_cache_after)"
                # Show which folders are missing from cache
                for missing_folder in "${missing_from_cache[@]}"; do
                    echo -e "     ${RED}✗${NC} $missing_folder"
                done
            fi
        else
            print_info "Movie cache entries: $cache_entries_before → $overall_cache_after (+$new_cache_entries new)"
        fi
        
        # Show files that mapped to existing cache entries with clear math breakdown
        local unique_movies=$((overall_success - duplicate_cache_count))
        print_info "  └─ $duplicate_cache_count file(s) matched an existing cache entry (hardlinked into an existing destination folder)"
        print_info "  └─ Breakdown: $overall_success processed = $unique_movies unique movies + $duplicate_cache_count shared destination folder(s)"
    fi
    
    # Display cache mode
    local cache_display="${CACHE_MODE:-unified}"
    case "$cache_display" in
        unified) cache_display="Unified cache" ;;
        4k) cache_display="4K cache" ;;
        1080p) cache_display="1080p cache" ;;
        1080p_xrated) cache_display="1080p X RATED cache" ;;
        4k_xrated) cache_display="4K X RATED cache" ;;
        cartoons) cache_display="Cartoons cache" ;;
        anime) cache_display="Anime cache" ;;
    esac
    print_info "  • Using: ${CYAN}${cache_display}${NC}"
    
    # API call statistics
    if [[ $API_CALL_COUNT -gt 0 ]]; then
        local api_rate="0.00"
        if [[ $overall_elapsed -gt 0 ]]; then
            # Use bash arithmetic: multiply by 100, divide, then format
            local rate_calc=$(( (API_CALL_COUNT * 100) / overall_elapsed ))
            api_rate=$(printf "%d.%02d" $((rate_calc / 100)) $((rate_calc % 100)))
        fi
        print_info "API calls: $API_CALL_COUNT total (${api_rate}/sec average)"
    else
        print_info "API calls: 0"
    fi

    # === SOURCE FOLDERS NOT HARDLINKED === (DISABLED - too slow for large libraries)
    # This feature was causing hangs. If needed in future, implement with pre-built inode cache.
    # if [[ ${#SOURCES[@]} -gt 0 && -n "$DESTINATION" && -d "$DESTINATION" ]]; then
    #     ...
    # fi

    # Clean up missing cache IDs temp file (info already shown inline in stats above)
    rm -f "${CACHE_DIR}/.missing_cache_ids.tmp"
    
    # Display files that matched existing cache entries (duplicate source files for same movie)
    if [[ -f "${CACHE_DIR}/.duplicate_cache_entries.tmp" ]]; then
        local dup_cache_count=$(wc -l < "${CACHE_DIR}/.duplicate_cache_entries.tmp" | tr -d ' ')
        if [[ $dup_cache_count -gt 0 ]]; then
            local unique_count=$((overall_success - dup_cache_count))
            echo ""
            echo -e "${YELLOW}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
            echo -e "${YELLOW}⚠  UNDETECTED DUPLICATES: $dup_cache_count file(s)${NC}"
            echo -e "${YELLOW}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
            echo ""
            print_info "Result: $overall_success files processed → $unique_count unique destination folders + $dup_cache_count extra hardlink(s) in existing folder(s)"
            print_info "Cache: $unique_count entries (1 per unique movie, not per source file)"
            echo ""
            print_info "$dup_cache_count file(s) hardlinked into an existing destination folder:"
            while IFS='|' read -r title year match_reason filepath dest_path; do
                echo -e "  ${YELLOW}•${NC} $title ($year)"
                echo -e "    ${APRICOT}Source: $filepath${NC}"
                [[ -n "$dest_path" ]] && echo -e "    ${SKY}Destination: $dest_path${NC}"
                echo -e "    ${DIM}Matched by: $match_reason${NC}"
            done < "${CACHE_DIR}/.duplicate_cache_entries.tmp"
            echo ""
            print_info "These will be cleaned up by the destination scan for duplicate IDs."
            if [[ ${DUPLICATES_DETECTED:-0} -gt 0 ]]; then
                print_info "Destination scans will run after duplicate processing (${DUPLICATES_DETECTED} detected duplicates pending)."
            else
                print_info "Destination scans are next (missing IDs first, then duplicate IDs)."
            fi
        fi
        rm -f "${CACHE_DIR}/.duplicate_cache_entries.tmp"
    fi
    rm -f "${CACHE_DIR}/.current_run_processed.tmp"

    # REMOVED: Failed files display - was showing false negatives
    # Failed files tracking is still done internally but no longer displayed
    
    # ID fetch statistics
    if [[ ${#FAILED_LOOKUPS[@]} -gt 0 ]]; then
        echo ""
        local missing_both=0
        local missing_imdb_only=0
        local missing_tmdb_only=0
        
        for entry in "${FAILED_LOOKUPS[@]}"; do
            IFS='|||' read -r file title year missing_imdb missing_tmdb <<< "$entry"
            if [[ "$missing_imdb" == "yes" && "$missing_tmdb" == "yes" ]]; then
                ((missing_both++)) || true
            elif [[ "$missing_imdb" == "yes" ]]; then
                ((missing_imdb_only++)) || true
            elif [[ "$missing_tmdb" == "yes" ]]; then
                ((missing_tmdb_only++)) || true
            fi
        done
        
        print_warning "ID fetch issues: ${#FAILED_LOOKUPS[@]} file(s) processed with missing IDs"
        if [[ $missing_both -gt 0 ]]; then
            print_info "  • Missing both IMDb & TMDb: $missing_both file(s)"
        fi
        if [[ $missing_imdb_only -gt 0 ]]; then
            print_info "  • Missing IMDb only: $missing_imdb_only file(s)"
        fi
        if [[ $missing_tmdb_only -gt 0 ]]; then
            print_info "  • Missing TMDb only: $missing_tmdb_only file(s)"
        fi
        print_info "  ${DIM}(Files were processed successfully but with placeholder IDs)${NC}"
    fi
    echo ""
    
    # Cleanup processed folders temp file (no longer displaying unprocessed folders report - causes false negatives)
    rm -f "${CACHE_DIR}/.processed_folders_$$.tmp"
    
    # Show rejected files (files that parsed but were rejected for other reasons)
    # Read from temp file to ensure cross-function persistence
    local rejected_temp_file="${CACHE_DIR}/.rejected_files_$$.tmp"
    if [[ -f "$rejected_temp_file" ]]; then
        local rejected_count=$(wc -l < "$rejected_temp_file" | tr -d ' ')
        if [[ $rejected_count -gt 0 ]]; then
            echo ""
            echo -e "${YELLOW}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
            echo -e "${YELLOW}⚠  ${rejected_count} FILE(S) REJECTED${NC}"
            echo -e "${YELLOW}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
            echo ""
            while IFS= read -r line; do
                local rejected_file="${line%|||*}"
                local reject_reason="${line#*|||}"
                echo -e "  ${YELLOW}⚠${NC} ${reject_reason}"
                echo -e "     ${DIM}Location: $rejected_file${NC}"
                echo ""
            done < "$rejected_temp_file"
            echo -e "${YELLOW}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
            echo ""
        fi
        # Clean up temp file
        rm -f "$rejected_temp_file"
    fi
    
    # Show files that couldn't be parsed (DISPLAY FIRST - before interactive prompts)
    if [[ ${#FAILED_PARSE[@]} -gt 0 ]]; then
        echo ""
        echo -e "${RED}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
        echo -e "${RED}⚠  ${#FAILED_PARSE[@]} FILE(S) COULD NOT BE PARSED${NC}"
        echo -e "${RED}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
        echo ""
        echo -e "${YELLOW}These files could not be processed because the title and/or year could not be detected:${NC}"
        echo -e "${CYAN}━━━ FOLDER/FILENAME EXAMPLES ━━━${NC}"
        echo -e "  ${GREEN}✓ Good:${NC} ${DIM}Weird.science.1985.REMASTERED/ → watchable-sd.mkv${NC} ${GREEN}(folder has title+year)${NC}"
        echo -e "  ${GREEN}✓ Good:${NC} ${DIM}Movie.Title.2020.1080p.mkv${NC} ${GREEN}(filename has title+year)${NC}"
        echo -e "  ${GREEN}✓ Good:${NC} ${DIM}The.Matrix.1999/ → movie.mkv${NC} ${GREEN}(folder has title+year)${NC}"
        echo -e "  ${RED}✗ Bad:${NC}  ${DIM}downloads/ → watchable-moviename-sd.mkv${NC} ${YELLOW}(no year anywhere)${NC}"
        echo -e "  ${RED}✗ Bad:${NC}  ${DIM}unsorted/ → movie.mkv${NC} ${YELLOW}(no title or year anywhere)${NC}"
        echo ""
        for failed_file in "${FAILED_PARSE[@]}"; do
            echo -e "  ${RED}✗${NC} $(basename "$failed_file")"
            echo -e "     ${DIM}Full path: $failed_file${NC}"
        done
        echo ""
        echo -e "${CYAN}━━━ WHY THIS HAPPENED ━━━${NC}"
        echo -e "The script requires ${YELLOW}either the folder name OR filename${NC} to contain both:"
        echo -e "  ${YELLOW}1.${NC} Movie title"
        echo -e "  ${YELLOW}2.${NC} Year (4 digits: 1900-2099)"
        echo -e "${DIM}(Script checks folder name first, then filename as fallback)${NC}"
        echo -e "${DIM}(Script checks folder name first, then filename as fallback)${NC}"
        echo ""
        echo -e "${CYAN}━━━ FOLDER/FILENAME EXAMPLES ━━━${NC}"
        echo -e "  ${GREEN}✓ Good:${NC} ${DIM}Guts.Of.A.Virgin.1986.REMASTERED/ → watchable-sd.mkv${NC} ${GREEN}(folder has title+year)${NC}"
        echo -e "  ${GREEN}✓ Good:${NC} ${DIM}Movie.Title.2020.1080p.mkv${NC} ${GREEN}(filename has title+year)${NC}"
        echo -e "  ${GREEN}✓ Good:${NC} ${DIM}The.Matrix.1999/ → movie.mkv${NC} ${GREEN}(folder has title+year)${NC}"
        echo -e "  ${RED}✗ Bad:${NC}  ${DIM}downloads/ → watchable-moviename-sd.mkv${NC} ${YELLOW}(no year anywhere)${NC}"
        echo -e "  ${RED}✗ Bad:${NC}  ${DIM}unsorted/ → movie.mkv${NC} ${YELLOW}(no title or year anywhere)${NC}"
        echo ""
        echo -e "${CYAN}━━━ HOW TO FIX ━━━${NC}"
        echo -e "${GREEN}Option 1:${NC} Rename the files to include title and year"
        echo -e "  ${DIM}The mv command in Unix/Linux systems is used to move or rename files and directories${NC}"
        echo -e "  ${DIM}Rename Example: mv 'watchable-weirdscience-sd.mkv' 'Weird.Science.1985.mkv'${NC}"
        echo ""
        echo -e "${GREEN}Option 2:${NC} Process these files now by manually entering title and year"
        echo -e "  ${DIM}You'll be prompted for each file individually${NC}"
        echo ""
        echo -e "${RED}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
        echo ""
        
        # Ask if user wants to manually process unparseable files
        print_info "Would you like to manually enter title/year for these files now? (y/n):"
        read -r process_failed_parse
        
        if [[ "$process_failed_parse" =~ ^[Yy]$ ]]; then
            echo ""
            print_info "Processing unparseable files with manual entry..."
            echo ""
            
            local parse_success=0
            local parse_failed=0
            
            for failed_file in "${FAILED_PARSE[@]}"; do
                echo ""
                echo -e "${YELLOW}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
                echo -e "${CYAN}File:${NC} $(basename "$failed_file")"
                echo -e "${DIM}Path: $failed_file${NC}"
                echo -e "${YELLOW}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
                echo ""
                
                # Ask if user wants to process this specific file
                print_info "Process this file? (y/n/q to quit):"
                read -r process_this_file
                
                if [[ "$process_this_file" =~ ^[Qq]$ ]]; then
                    print_info "Skipping remaining files"
                    break
                elif [[ ! "$process_this_file" =~ ^[Yy]$ ]]; then
                    print_info "Skipping this file"
                    ((parse_failed++)) || true
                    continue
                fi
                
                # Temporarily disable auto mode for manual entry
                local old_auto_mode="$AUTO_MODE"
                AUTO_MODE="false"
                
                if process_file "$failed_file" "$AUTO_MODE"; then
                    ((parse_success++)) || true
                    print_success "Successfully processed"
                else
                    ((parse_failed++)) || true
                    print_warning "Failed to process"
                fi
                
                # Restore auto mode
                AUTO_MODE="$old_auto_mode"
            done
            
            echo ""
            print_success "Manual processing complete: $parse_success successful, $parse_failed skipped"
        else
            print_info "Skipping manual entry for unparseable files"
        fi
    fi
    
    # POST-PROCESSING PHASE 0: Review extension duplicate selections (FIRST)
    if [[ ${EXTENSION_DUPLICATES_FILTERED:-0} -gt 0 && -f "$EXTENSION_DUP_LOG" && "$EXTENSION_DUP_MODE" == "manual" ]]; then
        echo ""
        print_info "========================================="
        print_info "Post-Processing: Review Extension Duplicates in Same Folder"
        print_info "========================================="
        echo ""
        
        print_warning "The script automatically selected files based on resolution/bitrate"
        print_info "You can review and change these selections if needed"
        echo ""
        
        # Ask if user wants to review selections
        local review_dupes=""
        read -r -p "$(print_info "Do you want to review extension duplicate selections? (y/n): ")" review_dupes
        echo ""
        
        if [[ "$review_dupes" =~ ^[Yy]$ ]]; then
            echo ""
            print_info "Reviewing extension duplicate selections..."
            echo ""
            
            # Parse the log file and group by folder (Bash 3.2 compatible)
            # Format: folder_path<TAB>KEPT<TAB>filepath|resolution|bitrate|reason
            # Format: folder_path<TAB>REJECTED<TAB>filepath|resolution|bitrate
            local temp_grouped="/tmp/movie_ext_dup_grouped_$$"
            > "$temp_grouped"
            
            while IFS='|' read -r status filepath resolution bitrate reason; do
                [[ -z "$filepath" ]] && continue
                local folder=$(dirname "$filepath")
                if [[ "$status" == "KEPT" ]]; then
                    echo "$folder"$'\t'"KEPT"$'\t'"$filepath|$resolution|$bitrate|$reason" >> "$temp_grouped"
                elif [[ "$status" == "REJECTED" ]]; then
                    echo "$folder"$'\t'"REJECTED"$'\t'"$filepath|$resolution|$bitrate" >> "$temp_grouped"
                fi
            done < "$EXTENSION_DUP_LOG"
            
            # Get unique folders
            local -a unique_folders=()
            while IFS=$'\t' read -r folder rest; do
                local already_added=false
                for existing in "${unique_folders[@]}"; do
                    [[ "$existing" == "$folder" ]] && already_added=true && break
                done
                [[ "$already_added" == "false" ]] && unique_folders+=("$folder")
            done < "$temp_grouped"
            
            # Review each folder group
            for folder in "${unique_folders[@]}"; do
                [[ -z "$folder" ]] && continue
                
                # Get kept file for this folder
                local kept_path="" kept_res="" kept_bitrate="" kept_reason=""
                while IFS=$'\t' read -r grp_folder status data; do
                    if [[ "$grp_folder" == "$folder" ]] && [[ "$status" == "KEPT" ]]; then
                        IFS='|' read -r kept_path kept_res kept_bitrate kept_reason <<< "$data"
                        break
                    fi
                done < "$temp_grouped"
                
                [[ -z "$kept_path" ]] && continue
                
                # Get rejected files for this folder
                local -a rejected_paths=()
                local -a rejected_resolutions=()
                local -a rejected_bitrates=()
                while IFS=$'\t' read -r grp_folder status data; do
                    if [[ "$grp_folder" == "$folder" ]] && [[ "$status" == "REJECTED" ]]; then
                        local rej_path rej_res rej_bitrate
                        IFS='|' read -r rej_path rej_res rej_bitrate <<< "$data"
                        rejected_paths+=("$rej_path")
                        rejected_resolutions+=("$rej_res")
                        rejected_bitrates+=("$rej_bitrate")
                    fi
                done < "$temp_grouped"
                
                echo ""
                echo -e "${CYAN}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
                echo -e "${CYAN}Folder: $(basename "$folder")${NC}"
                echo -e "${DIM}$folder${NC}"
                echo -e "${CYAN}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
                echo ""
                echo -e "${GREEN}Currently selected (kept):${NC}"
                echo -e "  ${GREEN}✓${NC} $(basename "$kept_path")"
                
                # Get file size for kept file
                local kept_size=$(_stat_size "$kept_path" || echo 0)
                local kept_size_display=$(format_bytes "$kept_size")
                
                echo -e "    Resolution: $kept_res | Bitrate: $kept_bitrate | Size: $kept_size_display"
                if [[ "$kept_reason" == "bitrate" ]]; then
                    echo -e "    ${CYAN}Reason: Higher bitrate (same resolution)${NC}"
                else
                    echo -e "    ${CYAN}Reason: Higher resolution${NC}"
                fi
                
                if [[ ${#rejected_paths[@]} -gt 0 ]]; then
                    echo ""
                    echo -e "${YELLOW}Rejected files:${NC}"
                    for i in "${!rejected_paths[@]}"; do
                        # Get file size for rejected file
                        local rej_size=$(_stat_size "${rejected_paths[$i]}" || echo 0)
                        local rej_size_display=$(format_bytes "$rej_size")
                        
                        echo -e "  ${RED}✗${NC} $(basename "${rejected_paths[$i]}")"
                        echo -e "    Resolution: ${rejected_resolutions[$i]} | Bitrate: ${rejected_bitrates[$i]} | Size: $rej_size_display"
                    done
                fi
                
                echo ""
                echo -e "${YELLOW}Do you want to change the selection for this group? (y/n):${NC}"
                read -r change_selection
                
                if [[ "$change_selection" =~ ^[Yy]$ ]]; then
                    # Build array of all files (kept + rejected)
                    local -a all_files=("$kept_path")
                    local -a all_resolutions=("$kept_res")
                    local -a all_bitrates=("$kept_bitrate")
                    local -a all_sizes=()
                    
                    # Get file size for kept file
                    local kept_size=$(_stat_size "$kept_path" || echo 0)
                    all_sizes+=("$kept_size")
                    
                    for i in "${!rejected_paths[@]}"; do
                        all_files+=("${rejected_paths[$i]}")
                        all_resolutions+=("${rejected_resolutions[$i]}")
                        all_bitrates+=("${rejected_bitrates[$i]}")
                        
                        # Get file size for rejected file
                        local rej_size=$(_stat_size "${rejected_paths[$i]}" || echo 0)
                        all_sizes+=("$rej_size")
                    done
                    
                    echo ""
                    echo -e "${CYAN}Select which file to keep:${NC}"
                    
                    for i in "${!all_files[@]}"; do
                        local idx=$((i + 1))
                        local file="${all_files[$i]}"
                        local is_current=""
                        [[ "$file" == "$kept_path" ]] && is_current=" ${GREEN}(current)${NC}"
                        
                        # Format file size and bitrate using format functions
                        local size_bytes="${all_sizes[$i]}"
                        local size_display=$(format_bytes "$size_bytes")
                        local bitrate_display=$(format_bitrate "${all_bitrates[$i]}")
                        
                        echo -e "  ${CYAN}$idx)${NC} $(basename "$file")$is_current"
                        echo -e "     Resolution: ${all_resolutions[$i]} | Bitrate: ${bitrate_display} | Size: ${size_display}"
                    done
                    
                    echo ""
                    echo -e "${YELLOW}Enter number (1-${#all_files[@]}):${NC}"
                    read -r selection_num
                    
                    if [[ "$selection_num" =~ ^[0-9]+$ ]] && [[ $selection_num -ge 1 ]] && [[ $selection_num -le ${#all_files[@]} ]]; then
                        local selected_idx=$((selection_num - 1))
                        local selected_file="${all_files[$selected_idx]}"
                        
                        if [[ "$selected_file" != "$kept_path" ]]; then
                            echo ""
                            print_info "Switching selection to: $(basename "$selected_file")"
                            
                            # Step 1: Remove the kept file's hardlink from destination
                            local kept_filename=$(basename "$kept_path")
                            local dest_file=""
                            local dest_folder=""
                            
                            print_info "Searching for existing kept file in destination..."
                            
                            # Get the inode of the kept file to find its hardlinks
                            if [[ -f "$kept_path" ]]; then
                                local kept_inode=$(ls -i "$kept_path" | awk '{print $1}')
                                
                                # Search destination for files with same inode (hardlinks)
                                while IFS= read -r -d '' potential_link; do
                                    local link_inode=$(ls -i "$potential_link" | awk '{print $1}')
                                    if [[ "$link_inode" == "$kept_inode" ]]; then
                                        dest_file="$potential_link"
                                        dest_folder=$(dirname "$dest_file")
                                        print_info "Found kept file: $(basename "$dest_folder")/$(basename "$dest_file")"
                                        print_info "Removing: $(basename "$dest_file")"
                                        rm -f "$dest_file"
                                        break
                                    fi
                                done < <(find "$DESTINATION" -type f -print0 2>/dev/null)
                            fi
                            
                            # Step 2: Remove any existing hardlinks of the newly selected file
                            print_info "Checking for existing hardlinks of selected file..."
                            if [[ -f "$selected_file" ]]; then
                                local selected_inode=$(ls -i "$selected_file" | awk '{print $1}')
                                local removed_count=0
                                
                                # Find and remove all hardlinks of the selected file in destination
                                while IFS= read -r -d '' existing_link; do
                                    print_info "Removing existing hardlink: $(basename "$(dirname "$existing_link")")/$(basename "$existing_link")"
                                    rm -f "$existing_link"
                                    ((removed_count++)) || true
                                done < <(find "$DESTINATION" -type f -inum "$selected_inode" -print0 2>/dev/null)
                                
                                [[ $removed_count -gt 0 ]] && print_info "Removed $removed_count existing hardlink(s)"
                            fi
                            
                            # Step 3: Process the newly selected file through normal pipeline
                            echo ""
                            print_info "Processing newly selected file..."
                            
                            # Process the file normally, bypassing duplicate check (third parameter = true)
                            # This allows the manually selected file to be processed even if it's lower quality
                            if process_file "$selected_file" "$AUTO_MODE"; then
                                print_success "Successfully processed: $(basename "$selected_file")"
                            else
                                print_error "Failed to process selected file"
                                
                                # If processing failed and we removed the old file, try to restore it
                                if [[ -n "$dest_file" && -n "$dest_folder" && -d "$dest_folder" ]]; then
                                    print_warning "Attempting to restore original file..."
                                    if ln "$kept_path" "$dest_file" 2>/dev/null; then
                                        print_info "Restored: $(basename "$dest_file")"
                                    fi
                                fi
                            fi
                        else
                            print_info "No change - keeping current selection"
                        fi
                    else
                        print_error "Invalid selection"
                    fi
                else
                    print_info "Keeping current selection"
                fi
            done
            
            # Clean up temp file
            rm -f "$temp_grouped" 2>/dev/null
            
            echo ""
            print_success "Extension duplicate review complete"
        else
            print_info "Skipping extension duplicate review"
        fi
    fi
    
    # POST-PROCESSING PHASE 1: Handle files with missing IDs (FIRST)
    if [[ ${#FAILED_LOOKUPS[@]} -gt 0 ]]; then
        handle_missing_ids_post_processing
    fi
    
    # POST-PROCESSING PHASE 2: Handle duplicate movies (process AFTER missing IDs)
    if [[ ${#ALL_DUPLICATE_FILES[@]} -gt 0 ]]; then
        echo ""
        print_info "========================================="
        print_info "Post-Processing: Duplicate Movies in Different Folders"
        print_info "========================================="
        echo ""
        
        print_warning "Found ${#ALL_DUPLICATE_FILES[@]} duplicate file(s) that were skipped during initial processing"
        print_info "These files have the same title and year as other files in the source"
        echo ""
        
        # Ask if user wants to process duplicates now
        local process_dupes=""
        stty echo 2>/dev/null
        read -r -p "$(print_info "Do you want to review and process duplicate movies now? (Enter or y to proceed/n to skip): ")" process_dupes
        stty -echo 2>/dev/null
        echo ""
        
        if [[ "$process_dupes" =~ ^[Yy]?$ ]]; then
            echo ""
            print_info "Processing duplicate movies..."
            echo ""
            
            # Re-enable poster display for interactive duplicate selection
            # (was disabled during parallel processing to prevent terminal corruption)
            export DISABLE_IMAGES="false"
            
            # Set cache file based on cache mode before processing
            set_cache_by_resolution ""
            
            # Use the interactive duplicate selection
            local -a SELECTED_DUPES=()
            while IFS= read -r file; do
                [[ -n "$file" ]] && SELECTED_DUPES+=("$file")
            done < <(select_duplicates_to_process "${ALL_DUPLICATE_FILES[@]}")
            
            if [[ ${#SELECTED_DUPES[@]} -gt 0 ]]; then
                print_success "Processing ${#SELECTED_DUPES[@]} selected duplicate(s)"
                echo ""
                
                local dup_success=0
                local dup_failed=0
                local dup_already_existed=0
                local dup_skipped=0
                local dup_start_time=$SECONDS
                local dup_cache_entries_before=0
                
                # Tracking arrays for detailed statistics (like movie processing)
                local -a DUP_SUCCESS_FILES=()
                local -a DUP_FAILED_FILES=()
                local -a DUP_ALREADY_EXISTED_FILES=()
                local -a DUP_SKIPPED_FILES=()
                local -a DUP_NOT_CACHED_FILES=()
                
                # Create temp files for cross-process tracking
                local dup_success_temp="${CACHE_DIR}/.dup_success_$$.tmp"
                local dup_failed_temp="${CACHE_DIR}/.dup_failed_$$.tmp"
                local dup_already_existed_temp="${CACHE_DIR}/.dup_already_existed_$$.tmp"
                local dup_skipped_temp="${CACHE_DIR}/.dup_skipped_$$.tmp"
                local dup_not_cached_temp="${CACHE_DIR}/.dup_not_cached_$$.tmp"
                > "$dup_success_temp"
                > "$dup_failed_temp"
                > "$dup_already_existed_temp"
                > "$dup_skipped_temp"
                > "$dup_not_cached_temp"
                
                # Count cache entries before duplicate processing
                local cache_mode_file="$CACHE_DIR/cache_mode.txt"
                local cache_mode="4k"
                [[ -f "$cache_mode_file" ]] && cache_mode=$(cat "$cache_mode_file")
                
                case "$cache_mode" in
                    unified)
                        [[ -f "$CACHE_DIR/MOVIE UNIFIED CACHE.txt" ]] && dup_cache_entries_before=$(wc -l < "$CACHE_DIR/MOVIE UNIFIED CACHE.txt" | tr -d ' ')
                        ;;
                    4k)
                        [[ -f "$CACHE_DIR/MOVIE 4K CACHE.txt" ]] && dup_cache_entries_before=$(wc -l < "$CACHE_DIR/MOVIE 4K CACHE.txt" | tr -d ' ')
                        ;;
                    1080p)
                        [[ -f "$CACHE_DIR/MOVIE 1080p CACHE.txt" ]] && dup_cache_entries_before=$(wc -l < "$CACHE_DIR/MOVIE 1080p CACHE.txt" | tr -d ' ')
                        ;;
                    1080p_xrated)
                        [[ -f "$CACHE_DIR/MOVIE 1080p X RATED CACHE.txt" ]] && dup_cache_entries_before=$(wc -l < "$CACHE_DIR/MOVIE 1080p X RATED CACHE.txt" | tr -d ' ')
                        ;;
                    4k_xrated)
                        [[ -f "$CACHE_DIR/MOVIE 4K X RATED CACHE.txt" ]] && dup_cache_entries_before=$(wc -l < "$CACHE_DIR/MOVIE 4K X RATED CACHE.txt" | tr -d ' ')
                        ;;
                esac
                
                # Check if parallel processing is enabled for duplicates
                echo "========== [FLOW-TRACE] DUPLICATE PROCESSING START ==========" >&2
                echo "[FLOW-TRACE] PARALLEL_PROCESSING='${PARALLEL_PROCESSING}'" >&2
                echo "[FLOW-TRACE] AUTO_MODE='${AUTO_MODE}'" >&2
                echo "[FLOW-TRACE] SELECTED_DUPES count=${#SELECTED_DUPES[@]}" >&2
                echo "=============================================================" >&2
                
                # Parallel processing for duplicates works regardless of AUTO_MODE since files are pre-selected
                if [[ "$PARALLEL_PROCESSING" == "true" && ${#SELECTED_DUPES[@]} -ge 2 ]]; then
                    echo "[FLOW-TRACE] ✓ Entering parallel processing block" >&2
                    # Load rolling queue mode setting
                    [[ -f "${CACHE_DIR}/rolling_queue_mode.txt" ]] && ROLLING_QUEUE_MODE=$(cat "${CACHE_DIR}/rolling_queue_mode.txt")
                    
                    echo "[FLOW-TRACE] ROLLING_QUEUE_MODE='${ROLLING_QUEUE_MODE}'" >&2
                    
                    if [[ "$ROLLING_QUEUE_MODE" == "true" ]]; then
                        echo "[FLOW-TRACE] ✓ Entering rolling queue if-block" >&2
                        print_success "Parallel processing enabled for duplicates: ${PARALLEL_JOBS} simultaneous jobs (rolling queue)"
                    else
                        echo "[FLOW-TRACE] ✓ Entering batch mode if-block" >&2
                        print_success "Parallel processing enabled for duplicates: ${PARALLEL_JOBS} simultaneous jobs (batch mode)"
                    fi
                    echo ""
                    
                    if [[ "$ROLLING_QUEUE_MODE" == "true" ]]; then
                        echo "========== [ROLLING-QUEUE] INITIALIZING ROLLING QUEUE ==========" >&2
                        # Use rolling queue approach - start new jobs as soon as slots open
                        local -a active_pids=()
                        local -a active_files=()
                        local -a active_indices=()
                        local -a active_job_ids=()
                        local job_id_counter=0
                        local dup_index=0
                        local dup_total=${#SELECTED_DUPES[@]}
                        
                        echo "[ROLLING-QUEUE] Variables set: dup_total=$dup_total, dup_index=$dup_index, active_pids=${#active_pids[@]}" >&2
                        
                        # Disable posters during parallel processing to prevent terminal corruption
                        export DISABLE_IMAGES="true"
                        
                        echo "[ROLLING-QUEUE] Disabled images, setting up loop" >&2
                        
                        # Main processing loop - continuously check for completed jobs and start new ones
                        local loop_iterations=0
                        local start_time=$SECONDS
                        local timeout=600  # 10 minute timeout
                        
                        while [[ $dup_index -lt $dup_total ]] || [[ ${#active_pids[@]} -gt 0 ]]; do
                            ((loop_iterations++)) || true
                            
                            # Safety check: prevent infinite loop
                            local elapsed=$((SECONDS - start_time))
                            if [[ $elapsed -gt $timeout ]]; then
                                echo ""
                                print_error "Timeout: Rolling queue exceeded ${timeout}s (${#active_pids[@]} jobs still active)"
                                # Kill hung jobs
                                for pid in "${active_pids[@]}"; do
                                    kill -9 "$pid" 2>/dev/null
                                done
                                break
                            fi
                            
                            # First, check for completed jobs by reading status files
                            
                            # Check each job's status file (using job ID, not PID)
                            local jobs_completed=0
                            for i in "${!active_pids[@]}"; do
                                local job_id="${active_job_ids[$i]}"
                                local status_file="${CACHE_DIR}/.job_status_${job_id}"
                                
                                # Check if status file exists (job completed and wrote status)
                                if [[ -f "$status_file" ]]; then
                                    local exit_status=$(cat "$status_file")
                                    rm -f "$status_file"
                                    
                                    local completed_file="${active_files[$i]}"
                                    ((jobs_completed++)) || true
                                    
                                    # Process exit status
                                    case $exit_status in
                                        0)
                                            ((dup_success++)) || true
                                            ((total_success++)) || true
                                            echo "$completed_file" >> "$dup_success_temp"
                                            ;;
                                        1)
                                            ((dup_failed++)) || true
                                            echo "$completed_file|||Parse/processing failed" >> "$dup_failed_temp"
                                            FAILED_PARSE+=("$completed_file")
                                            ;;
                                        2)
                                            # Already linked - count as already existed, not failed
                                            ((dup_already_existed++)) || true
                                            echo "$completed_file" >> "$dup_already_existed_temp"
                                            ;;
                                        3)
                                            # Locked by another instance - count as skipped
                                            ((dup_skipped++)) || true
                                            echo "$completed_file|||Locked by another instance" >> "$dup_skipped_temp"
                                            ;;
                                        4)
                                            # Already processed after lock - count as already existed
                                            ((dup_already_existed++)) || true
                                            echo "$completed_file" >> "$dup_already_existed_temp"
                                            ;;
                                        5)
                                            # .ia duplicate - count as skipped
                                            ((dup_skipped++)) || true
                                            echo "$completed_file|||Internet Archive duplicate" >> "$dup_skipped_temp"
                                            ;;
                                        6)
                                            # Lower quality duplicate - count as skipped
                                            ((dup_skipped++)) || true
                                            echo "$completed_file|||Lower quality duplicate" >> "$dup_skipped_temp"
                                            ;;
                                        *)
                                            ((dup_failed++)) || true
                                            echo "$completed_file|||Unknown error (exit $exit_status)" >> "$dup_failed_temp"
                                            FAILED_PARSE+=("$completed_file")
                                            ;;
                                    esac
                                    
                                    # Remove from arrays
                                    unset 'active_pids[$i]'
                                    unset 'active_files[$i]'
                                    unset 'active_indices[$i]'
                                    unset 'active_job_ids[$i]'
                                fi
                            done
                            
                            # Compact arrays if any jobs completed
                            if [[ $jobs_completed -gt 0 ]]; then
                                active_pids=("${active_pids[@]}")
                                active_files=("${active_files[@]}")
                                active_indices=("${active_indices[@]}")
                                active_job_ids=("${active_job_ids[@]}")
                            fi
                            
                            # Only log every 50 iterations to reduce noise
                            if [[ $((loop_iterations % 50)) -eq 0 ]]; then
                                should_debug high && echo "[LOOP-PHASE-2] Iteration $loop_iterations: active_pids=${#active_pids[@]}, dup_index=$dup_index/$dup_total" >&2
                            fi
                            
                            # Now start new jobs for any available slots
                            while [[ ${#active_pids[@]} -lt $PARALLEL_JOBS ]] && [[ $dup_index -lt $dup_total ]]; do
                                should_debug high && echo "[LOOP-PHASE-2] Inner while: active=${#active_pids[@]} < $PARALLEL_JOBS AND dup_index=$dup_index < $dup_total" >&2
                                local dup_file="${SELECTED_DUPES[$dup_index]}"
                                local display_index=$((dup_index + 1))
                                ((dup_index++)) || true
                                
                                # Assign unique job ID
                                ((job_id_counter++)) || true
                                local current_job_id=$job_id_counter
                                
                                # Show rolling queue activity
                                echo -e "${DIM}[QUEUE] Starting job ${display_index}/${dup_total} (active: ${#active_pids[@]}/${PARALLEL_JOBS}) JobID=${current_job_id}${NC}" >&2
                                
                                # Diagnostics: Log job start
                                if [[ "$DIAGNOSTICS_MODE" == "true" ]]; then
                                    local job_start_time=$(date '+%Y-%m-%d %H:%M:%S')
                                    echo "[DIAG] Parallel duplicate job START: File='$(basename "$dup_file")' Index=$display_index JobID=$current_job_id Time=$job_start_time" >&2
                                fi
                                
                                (
                                    # Receive job ID from parent
                                    JOB_ID=$current_job_id
                                    
                                    echo ""
                                    print_info "========================================="
                                    print_info "Duplicate ${display_index}/${dup_total}: $(basename "$dup_file")"
                                    print_info "========================================="
                                    
                                    # Capture process_file exit code without triggering set -e
                                    process_file "$dup_file" "$AUTO_MODE" || local exit_code=$?
                                    local exit_code=${exit_code:-0}
                                    
                                    [[ "$DIAGNOSTICS_MODE" == "true" ]] && echo "[EXIT-DEBUG] Returned: $exit_code for $(basename "$dup_file")" >&2
                                    
                                    # Write status to file using job ID (not PID)
                                    local status_file="${CACHE_DIR}/.job_status_${JOB_ID}"
                                    
                                    # Exit code 4 = file no longer exists (already moved/deleted)
                                    # Exit code 7 = destination exists with different source (movie already processed)
                                    # These are not errors - just skip them
                                    if [[ $exit_code -eq 4 ]]; then
                                        echo "0" > "$status_file"
                                        exit 0  # Treat as success (not a failure)
                                    elif [[ $exit_code -eq 7 ]]; then
                                        echo "0" > "$status_file"
                                        exit 0  # Already processed from another source - treat as success
                                    elif [[ $exit_code -eq 0 ]]; then
                                        echo "0" > "$status_file"
                                        exit 0  # Success
                                    else
                                        echo "1" > "$status_file"
                                        exit 1  # Failure
                                    fi
                                ) &
                                
                                local job_pid=$!
                                should_debug high && echo "[PID-DEBUG] Started job PID=$job_pid JobID=$current_job_id for $(basename "$dup_file")" >&2
                                active_pids+=("$job_pid")
                                active_files+=("$dup_file")
                                active_indices+=("$display_index")
                                active_job_ids+=("$current_job_id")
                                should_debug high && echo "[LOOP-PHASE-2] Job started, arrays updated. Continuing inner while loop..." >&2
                            done
                            
                            # Log job launch completion (less verbose)
                            if [[ $((loop_iterations % 50)) -eq 0 ]]; then
                                should_debug high && echo "[LOOP-PHASE-3] Iteration $loop_iterations: ${#active_pids[@]} active jobs, index $dup_index/$dup_total" >&2
                            fi
                            
                            # Small sleep to prevent CPU spinning, but only if jobs are still running
                            if [[ ${#active_pids[@]} -gt 0 ]]; then
                                sleep 0.1
                            fi
                        done
                        
                        # Clean up any remaining status files
                        rm -f "${CACHE_DIR}"/.job_status_* 2>/dev/null
                    
                    else
                        # Batch processing mode - wait for entire batch before starting next
                        local batch_size=$PARALLEL_JOBS
                        local dup_index=0
                        local dup_total=${#SELECTED_DUPES[@]}
                        
                        # Disable posters during parallel processing to prevent terminal corruption
                        export DISABLE_IMAGES="true"
                        
                        while [[ $dup_index -lt $dup_total ]]; do
                            # Start batch of parallel jobs
                            local batch_pids=()
                            local batch_files=()
                            
                            for ((i=0; i<batch_size && dup_index<dup_total; i++)); do
                                local dup_file="${SELECTED_DUPES[$dup_index]}"
                                local display_index=$((dup_index + 1))
                                ((dup_index++)) || true
                                batch_files+=("$dup_file")
                                
                                # Diagnostics: Log job start
                                if [[ "$DIAGNOSTICS_MODE" == "true" ]]; then
                                    local job_start_time=$(date '+%Y-%m-%d %H:%M:%S')
                                    echo "[DIAG] Parallel duplicate job START: File='$(basename "$dup_file")' Index=$display_index Time=$job_start_time" >&2
                                fi
                                
                                (
                                    echo ""
                                    print_info "========================================="
                                    print_info "Duplicate ${display_index}/${dup_total}: $(basename "$dup_file")"
                                    print_info "========================================="
                                    
                                    # Capture process_file exit code without triggering set -e
                                    process_file "$dup_file" "$AUTO_MODE" || local exit_code=$?
                                    local exit_code=${exit_code:-0}
                                    
                                    # Exit code 4 = file no longer exists (already moved/deleted)
                                    # Exit code 7 = destination exists with different source (movie already processed)
                                    # These are not errors - just skip them
                                    if [[ $exit_code -eq 4 ]]; then
                                        exit 0  # Treat as success (not a failure)
                                    elif [[ $exit_code -eq 7 ]]; then
                                        exit 0  # Already processed from another source - treat as success
                                    elif [[ $exit_code -eq 0 ]]; then
                                        exit 0  # Success
                                    else
                                        exit 1  # Failure
                                    fi
                                ) &
                                
                                batch_pids+=($!)
                            done
                            
                            # Wait for entire batch to complete
                            for j in "${!batch_pids[@]}"; do
                                local pid="${batch_pids[$j]}"
                                local dup_file="${batch_files[$j]}"
                                
                                if wait "$pid"; then
                                    ((dup_success++)) || true
                                    ((total_success++)) || true
                                    echo "$dup_file" >> "$dup_success_temp"
                                else
                                    ((dup_failed++)) || true
                                    print_warning "Skipped: $(basename "$dup_file")"
                                    echo "$dup_file|||Batch processing failed" >> "$dup_failed_temp"
                                    FAILED_PARSE+=("$dup_file")
                                fi
                                
                                # Diagnostics: Log job completion
                                if [[ "$DIAGNOSTICS_MODE" == "true" ]]; then
                                    local job_end_time=$(date '+%Y-%m-%d %H:%M:%S')
                                    echo "[DIAG] Parallel duplicate job END: File='$(basename "$dup_file")' Time=$job_end_time" >&2
                                fi
                            done
                        done
                        
                    fi
                    
                else
                    echo "[FLOW-TRACE] ✗ NOT using parallel processing - using sequential" >&2
                    echo "[FLOW-TRACE] Reason: PARALLEL_PROCESSING=$PARALLEL_PROCESSING, DUPES=${#SELECTED_DUPES[@]}" >&2
                    # Sequential processing for duplicates
                    for dup_file in "${SELECTED_DUPES[@]}"; do
                        echo ""
                        print_info "========================================="
                        print_info "File: $(basename "$dup_file")"
                        print_info "========================================="
                        
                        if process_file "$dup_file" "$AUTO_MODE"; then
                            ((dup_success++)) || true
                            ((total_success++)) || true
                            echo "$dup_file" >> "$dup_success_temp"
                        else
                            local exit_code=$?
                            case $exit_code in
                                2)
                                    ((dup_already_existed++)) || true
                                    echo "$dup_file" >> "$dup_already_existed_temp"
                                    ;;
                                3)
                                    ((dup_skipped++)) || true
                                    echo "$dup_file|||Locked by another instance" >> "$dup_skipped_temp"
                                    ;;
                                4)
                                    ((dup_already_existed++)) || true
                                    echo "$dup_file" >> "$dup_already_existed_temp"
                                    ;;
                                5)
                                    ((dup_skipped++)) || true
                                    echo "$dup_file|||Internet Archive duplicate" >> "$dup_skipped_temp"
                                    ;;
                                6)
                                    ((dup_skipped++)) || true
                                    echo "$dup_file|||Lower quality duplicate" >> "$dup_skipped_temp"
                                    ;;
                                7)
                                    # Destination exists with different source (movie already processed)
                                    ((dup_already_existed++)) || true
                                    echo "$dup_file" >> "$dup_already_existed_temp"
                                    ;;
                                *)
                                    ((dup_failed++)) || true
                                    print_warning "Skipped: $(basename "$dup_file")"
                                    echo "$dup_file|||Processing failed" >> "$dup_failed_temp"
                                    FAILED_PARSE+=("$dup_file")
                                    ;;
                            esac
                        fi
                    done
                fi
                
                # Calculate elapsed time
                local dup_elapsed=$((SECONDS - dup_start_time))
                local dup_minutes=$((dup_elapsed / 60))
                local dup_seconds=$((dup_elapsed % 60))
                
                # Calculate average time per file with 2 decimal places
                local dup_avg_time="0.00"
                if [[ $dup_success -gt 0 ]]; then
                    if command -v bc &> /dev/null; then
                        dup_avg_time=$(echo "scale=2; $dup_elapsed / $dup_success" | bc)
                    else
                        dup_avg_time=$(awk "BEGIN {printf \"%.2f\", $dup_elapsed / $dup_success}")
                    fi
                fi
                
                # Calculate total size processed
                local dup_total_size=0
                for dup_file in "${SELECTED_DUPES[@]}"; do
                    local file_size=$(_stat_size "$dup_file")
                    dup_total_size=$((dup_total_size + file_size))
                done
                local dup_size_gb=$((dup_total_size / 1073741824))
                local dup_size_mb=$(((dup_total_size % 1073741824) / 1048576))
                
                # Count cache entries after duplicate processing
                local dup_cache_entries_after=0
                case "$cache_mode" in
                    unified)
                        [[ -f "$CACHE_DIR/MOVIE UNIFIED CACHE.txt" ]] && dup_cache_entries_after=$(wc -l < "$CACHE_DIR/MOVIE UNIFIED CACHE.txt" | tr -d ' ')
                        ;;
                    4k)
                        [[ -f "$CACHE_DIR/MOVIE 4K CACHE.txt" ]] && dup_cache_entries_after=$(wc -l < "$CACHE_DIR/MOVIE 4K CACHE.txt" | tr -d ' ')
                        ;;
                    1080p)
                        [[ -f "$CACHE_DIR/MOVIE 1080p CACHE.txt" ]] && dup_cache_entries_after=$(wc -l < "$CACHE_DIR/MOVIE 1080p CACHE.txt" | tr -d ' ')
                        ;;
                    1080p_xrated)
                        [[ -f "$CACHE_DIR/MOVIE 1080p X RATED CACHE.txt" ]] && dup_cache_entries_after=$(wc -l < "$CACHE_DIR/MOVIE 1080p X RATED CACHE.txt" | tr -d ' ')
                        ;;
                    4k_xrated)
                        [[ -f "$CACHE_DIR/MOVIE 4K X RATED CACHE.txt" ]] && dup_cache_entries_after=$(wc -l < "$CACHE_DIR/MOVIE 4K X RATED CACHE.txt" | tr -d ' ')
                        ;;
                esac
                local dup_new_entries=$((dup_cache_entries_after - dup_cache_entries_before))
                
                # Get cache display name
                local dup_cache_name="cache"
                if [[ -n "$CACHE_FILE" ]]; then
                    local cache_basename=$(basename "$CACHE_FILE")
                    case "$cache_basename" in
                        *"UNIFIED CACHE.txt") dup_cache_name="Unified cache" ;;
                        *"4K CACHE.txt") dup_cache_name="4K cache" ;;
                        *"1080p CACHE.txt") dup_cache_name="1080p cache" ;;
                        *"1080p X RATED CACHE.txt") dup_cache_name="1080p X RATED cache" ;;
                        *"4K X RATED CACHE.txt") dup_cache_name="4K X RATED cache" ;;
                        *"CARTOONS CACHE.txt") dup_cache_name="Cartoons cache" ;;
                        *"ANIME CACHE.txt") dup_cache_name="Anime cache" ;;
                    esac
                fi
                
                # Add duplicate counters to overall statistics
                overall_success=$((overall_success + dup_success))
                overall_already_existed=$((overall_already_existed + dup_already_existed))
                overall_skipped=$((overall_skipped + dup_skipped))
                overall_failed=$((overall_failed + dup_failed))
                
                # Read tracking arrays from temp files
                local -a DUP_SUCCESS_FILES=()
                local -a DUP_FAILED_FILES=()
                local -a DUP_ALREADY_EXISTED_FILES=()
                local -a DUP_SKIPPED_FILES=()
                
                [[ -f "$dup_success_temp" ]] && while IFS= read -r line; do [[ -n "$line" ]] && DUP_SUCCESS_FILES+=("$line"); done < "$dup_success_temp"
                [[ -f "$dup_failed_temp" ]] && while IFS= read -r line; do [[ -n "$line" ]] && DUP_FAILED_FILES+=("$line"); done < "$dup_failed_temp"
                [[ -f "$dup_already_existed_temp" ]] && while IFS= read -r line; do [[ -n "$line" ]] && DUP_ALREADY_EXISTED_FILES+=("$line"); done < "$dup_already_existed_temp"
                [[ -f "$dup_skipped_temp" ]] && while IFS= read -r line; do [[ -n "$line" ]] && DUP_SKIPPED_FILES+=("$line"); done < "$dup_skipped_temp"
                
                # Calculate files not cached (success count minus new cache entries)
                local dup_not_cached=$((dup_success - dup_new_entries))
                [[ $dup_not_cached -lt 0 ]] && dup_not_cached=0
                
                # Calculate files per second
                local dup_files_per_second="0.00"
                if [[ $dup_elapsed -gt 0 && $dup_success -gt 0 ]]; then
                    if command -v bc &> /dev/null; then
                        dup_files_per_second=$(echo "scale=2; $dup_success / $dup_elapsed" | bc)
                    else
                        dup_files_per_second=$(awk "BEGIN {printf \"%.2f\", $dup_success / $dup_elapsed}")
                    fi
                fi
                
                # Detailed duplicate summary (matching movie processing statistics format)
                echo ""
                echo -e "${BLUE}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
                echo -e "${CYAN}DUPLICATE PROCESSING STATISTICS${NC}"
                echo -e "${BLUE}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
                echo ""
                
                # File counts
                local unprocessed=$((${#ALL_DUPLICATE_FILES[@]} - ${#SELECTED_DUPES[@]}))
                print_info "Duplicates detected: ${#ALL_DUPLICATE_FILES[@]} total"
                print_info "  • Selected for processing: ${#SELECTED_DUPES[@]}"
                print_info "  • Not selected (moved/left): $unprocessed"
                echo ""
                
                # Processing results
                print_success "Files processed: $dup_success/${#SELECTED_DUPES[@]} successfully processed, $dup_already_existed already existed, $dup_skipped skipped, $dup_failed failed"
                print_info "Total processing time: ${dup_minutes}m ${dup_seconds}s (avg ${dup_avg_time}s per file)"
                print_info "Processing rate: $dup_files_per_second files/sec"
                print_info "Data processed: ${dup_size_gb}.$(printf "%03d" $dup_size_mb) GB"
                
                # Cache statistics - just show the numbers, detailed breakdown comes later
                print_info "Cache entries: $dup_cache_entries_before → $dup_cache_entries_after (+$dup_new_entries new)"
                [[ -n "$dup_cache_name" ]] && print_info "  • Using: ${CYAN}$dup_cache_name${NC}"
                
                # Show files that already existed at destination
                if [[ ${#DUP_ALREADY_EXISTED_FILES[@]} -gt 0 ]]; then
                    echo ""
                    print_info "Already existed at destination: ${#DUP_ALREADY_EXISTED_FILES[@]}"
                    echo -e "${DIM}These files were already hardlinked or present at destination:${NC}"
                    for existed_file in "${DUP_ALREADY_EXISTED_FILES[@]}"; do
                        echo "  • $(basename "$existed_file")"
                        echo -e "    ${DIM}Path: $existed_file${NC}"
                    done
                fi
                
                # Show skipped files with reasons
                if [[ ${#DUP_SKIPPED_FILES[@]} -gt 0 ]]; then
                    echo ""
                    print_warning "Skipped files: ${#DUP_SKIPPED_FILES[@]}"
                    echo -e "${DIM}These files were skipped during processing:${NC}"
                    for skipped_entry in "${DUP_SKIPPED_FILES[@]}"; do
                        local skipped_file="${skipped_entry%|||*}"
                        local skip_reason="${skipped_entry#*|||}"
                        echo -e "  ${YELLOW}⚠${NC} $(basename "$skipped_file")"
                        echo -e "    ${DIM}Path: $skipped_file${NC}"
                        echo -e "    ${DIM}Reason: $skip_reason${NC}"
                    done
                fi
                
                # Show failed files with reasons
                if [[ ${#DUP_FAILED_FILES[@]} -gt 0 ]]; then
                    echo ""
                    echo -e "${RED}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
                    echo -e "${RED}⚠  ${#DUP_FAILED_FILES[@]} DUPLICATE FILE(S) FAILED${NC}"
                    echo -e "${RED}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
                    for failed_entry in "${DUP_FAILED_FILES[@]}"; do
                        local failed_file="${failed_entry%|||*}"
                        local fail_reason="${failed_entry#*|||}"
                        echo -e "  ${RED}✗${NC} $(basename "$failed_file")"
                        echo -e "     ${DIM}Full path: $failed_file${NC}"
                        echo -e "     ${DIM}Reason: $fail_reason${NC}"
                    done
                    echo -e "${RED}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
                fi
                
                # Initialize counter for missing IDs (used later for remaining_not_cached calculation)
                local missing_ids_count=0
                
                # Show files not added to cache (missing IDs) - read from temp file populated by process_file
                if [[ -f "${CACHE_DIR}/.missing_cache_ids.tmp" ]]; then
                    local dup_missing_count=$(wc -l < "${CACHE_DIR}/.missing_cache_ids.tmp" | tr -d ' ')
                    if [[ $dup_missing_count -gt 0 ]]; then
                        echo ""
                        print_warning "Files not saved to cache (missing IDs): $dup_missing_count"
                        echo -e "${DIM}These files processed successfully but won't be in cache for future runs:${NC}"
                        while IFS='|' read -r title year imdb tmdb filepath; do
                            local missing_ids=""
                            [[ -z "$imdb" ]] && missing_ids="IMDb"
                            [[ -z "$tmdb" ]] && { [[ -n "$missing_ids" ]] && missing_ids+=", TMDb" || missing_ids="TMDb"; }
                            
                            # Construct destination path from title/year/IDs
                            local dest_folder_name="$title ($year)"
                            [[ -n "$imdb" ]] && dest_folder_name+=" [imdbid-$imdb]"
                            [[ -n "$tmdb" ]] && dest_folder_name+=" [tmdbid-$tmdb]"
                            local dest_path="$DESTINATION/$dest_folder_name"
                            
                            echo -e "  ${YELLOW}⚠${NC} $title ($year) - Missing: $missing_ids"
                            echo -e "    ${APRICOT}Source: $filepath${NC}"
                            echo -e "    ${SKY}Destination: $dest_path${NC}"
                        done < "${CACHE_DIR}/.missing_cache_ids.tmp"
                        echo ""
                    fi
                    # Capture count BEFORE deleting (needed for remaining_not_cached calculation later)
                    missing_ids_count=$(wc -l < "${CACHE_DIR}/.missing_cache_ids.tmp" 2>/dev/null | tr -d ' ')
                    rm -f "${CACHE_DIR}/.missing_cache_ids.tmp"
                fi
                
                # Show files that matched existing cache entries (duplicate source files for same movie)
                local dup_cache_match_count=0
                if [[ -f "${CACHE_DIR}/.duplicate_cache_entries.tmp" ]]; then
                    dup_cache_match_count=$(wc -l < "${CACHE_DIR}/.duplicate_cache_entries.tmp" | tr -d ' ')
                    if [[ $dup_cache_match_count -gt 0 ]]; then
                        echo ""
                        print_info "Files mapped to existing cache entries: $dup_cache_match_count"
                        echo -e "${DIM}These files are alternate copies of movies already in cache, will be handled in the interactive destination scan for duplicate ID's below:${NC}"
                        echo -e "${DIM}Meaning 2 duplicates exist in a subfolder located within the Destination that have the same IMDB ID or TT-TITLE TAGS${NC}"
                        while IFS='|' read -r title year match_reason filepath dest_path; do
                            echo "  • $title ($year)"
                            echo -e "    ${APRICOT}Source: $filepath${NC}"
                            [[ -n "$dest_path" ]] && echo -e "    ${SKY}Destination: $dest_path${NC}"
                            echo -e "    ${DIM}Matched by: $match_reason${NC}"
                        done < "${CACHE_DIR}/.duplicate_cache_entries.tmp"
                        echo ""
                    fi
                    rm -f "${CACHE_DIR}/.duplicate_cache_entries.tmp"
                fi
                rm -f "${CACHE_DIR}/.current_run_processed.tmp"
                
                # Calculate actual unaccounted not-cached files
                # dup_not_cached = success - new_entries
                # But some are accounted for by: missing_cache_ids + duplicate_cache_entries
                # Note: missing_ids_count was captured above before the file was deleted
                
                local accounted_not_cached=$((missing_ids_count + dup_cache_match_count))
                local remaining_not_cached=$((dup_not_cached - accounted_not_cached))
                [[ $remaining_not_cached -lt 0 ]] && remaining_not_cached=0
                
                # Only show warning if there are truly unaccounted files
                if [[ $remaining_not_cached -gt 0 ]]; then
                    echo ""
                    print_warning "└─ ${dup_cache_name}: $remaining_not_cached file(s) didn't create new cache entries"
                    echo -e "${DIM}   These movies were already in cache from main processing or a previous run.${NC}"
                    
                    # List the actual files that didn't create new cache entries
                    # These are in .cached_files.tmp with "already_cached" tag
                    if [[ -f "${CACHE_DIR}/.cached_files.tmp" ]]; then
                        local _shown_remaining=0
                        while IFS='|' read -r _rc_title _rc_year _rc_source _rc_status; do
                            if [[ "$_rc_status" == "already_cached" ]]; then
                                # Check if this source file was in our duplicate success list
                                local _is_dup_success=false
                                for _ds_file in "${DUP_SUCCESS_FILES[@]}"; do
                                    if [[ "$_ds_file" == "$_rc_source" ]]; then
                                        _is_dup_success=true
                                        break
                                    fi
                                done
                                if [[ "$_is_dup_success" == "true" ]]; then
                                    echo -e "    ${DIM}• $_rc_title ($_rc_year)${NC}"
                                    echo -e "      ${DIM}Source: $_rc_source${NC}"
                                    ((_shown_remaining++)) || true
                                    [[ $_shown_remaining -ge $remaining_not_cached ]] && break
                                fi
                            fi
                        done < "${CACHE_DIR}/.cached_files.tmp"
                    fi
                fi
                
                echo ""
                echo -e "${BLUE}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
                
                # Cleanup temp files
                rm -f "$dup_success_temp" "$dup_failed_temp" "$dup_already_existed_temp" "$dup_skipped_temp" "$dup_not_cached_temp" 2>/dev/null
                
                echo ""
                echo "[FLOW-DEBUG] Continuing to destination scan..." >&2
            else
                print_warning "No duplicates selected for processing"
                print_info "Note: Duplicate files were not saved to cache"
                echo "[FLOW-DEBUG] No duplicates selected, continuing to destination scan..." >&2
            fi
        else
            print_info "Skipping duplicate processing"
            print_info "Note: Duplicate files were not saved to cache"
            echo "[FLOW-DEBUG] Skipped duplicate processing, continuing to destination scan..." >&2
        fi
    fi
    
    echo "[FLOW-DEBUG] Starting destination scan for missing IDs..." >&2
    # Scan destination for existing files/folders with missing IDs
    if [[ -d "$DESTINATION" ]]; then
        echo ""
        print_info "Scanning destination for files with missing IDs..."
        
        # Use awk for fast pattern matching instead of find loop
        find "$DESTINATION" -mindepth 1 -maxdepth 1 \( -type d -o -type f \) 2>/dev/null | awk -F'/' '
        {
            item = $0
            item_name = $NF
            
            # Check for empty ID patterns
            has_empty = 0
            if (match(item_name, /\[imdbid-\]/) || match(item_name, /\[tmdbid-\]/) || \
                match(item_name, /\[imdb-\]/) || match(item_name, /\[tmdb-\]/) || \
                match(item_name, /\{imdb-\}/) || match(item_name, /\{tmdb-\}/)) {
                has_empty = 1
            }
            
            if (has_empty) {
                # Extract title and year using BSD awk compatible method
                if (match(item_name, /\([0-9]{4}\)/)) {
                    year_match = substr(item_name, RSTART+1, RLENGTH-2)
                    title_match = substr(item_name, 1, RSTART-2)
                    
                    # Check which IDs are missing
                    missing_imdb = ""
                    missing_tmdb = ""
                    
                    if (match(item_name, /\[imdbid-\]/) || match(item_name, /\[imdb-\]/) || match(item_name, /\{imdb-\}/)) {
                        missing_imdb = "yes"
                    }
                    
                    if (match(item_name, /\[tmdbid-\]/) || match(item_name, /\[tmdb-\]/) || match(item_name, /\{tmdb-\}/)) {
                        missing_tmdb = "yes"
                    }
                    
                    print item "|||" title_match "|||" year_match "|||" missing_imdb "|||" missing_tmdb
                }
            }
        }
        ' | while IFS='|||' read -r item title year missing_imdb missing_tmdb; do
            # Check if already tracked
            local already_tracked=0
            for existing in "${FAILED_LOOKUPS[@]}"; do
                if [[ "$existing" =~ ^"$item"(\||\$) ]]; then
                    already_tracked=1
                    break
                fi
            done
            
            if [[ $already_tracked -eq 0 ]]; then
                FAILED_LOOKUPS+=("$item|||$title|||$year|||$missing_imdb|||$missing_tmdb")
            fi
        done
        
        if [[ ${#FAILED_LOOKUPS[@]} -gt 0 ]]; then
            print_success "Found ${#FAILED_LOOKUPS[@]} folder(s) with missing IDs"
        else
            print_success "No files with missing IDs found"
        fi
        
        # Scan for duplicate IMDb/TMDb IDs in destination (video files only)
        echo ""
        print_info "Scanning destination for duplicate IDs..."
        
        # Re-enable poster display for interactive duplicate ID correction
        export DISABLE_IMAGES="false"
        
        # Create temporary files for tracking IDs
        local tmp_imdb_file=$(mktemp)
        local tmp_tmdb_file=$(mktemp)
        
        # Trap to clean up temp files on interrupt
        trap "rm -f '$tmp_imdb_file' '$tmp_tmdb_file' 2>/dev/null; exit 130" INT
        
        # Scan video files at depth 2 and extract ID from parent folder
        # Only flag as duplicate when multiple VIDEO files share the same IMDb/TMDb ID
        local scan_count=0
        while IFS= read -r -d '' video_file; do
            # Check for interrupt periodically
            ((scan_count++)) || true
            if ((scan_count % 50 == 0)); then
                check_interrupt
            fi
            
            # Skip sample files — they share the same parent folder/ID but aren't real duplicates
            local _vf_bn=$(basename "$video_file" | tr '[:upper:]' '[:lower:]')
            [[ "$_vf_bn" =~ sample ]] && continue
            
            local parent_folder=$(dirname "$video_file")
            local folder_name=$(basename "$parent_folder")
            
            # Extract IMDb ID from parent folder name
            if [[ "$folder_name" =~ \[imdbid-(tt[0-9]+)\] ]]; then
                echo "${BASH_REMATCH[1]}|$video_file" >> "$tmp_imdb_file"
            elif [[ "$folder_name" =~ \[imdb-(tt[0-9]+)\] ]]; then
                echo "${BASH_REMATCH[1]}|$video_file" >> "$tmp_imdb_file"
            elif [[ "$folder_name" =~ \{imdb-(tt[0-9]+)\} ]]; then
                echo "${BASH_REMATCH[1]}|$video_file" >> "$tmp_imdb_file"
            fi
            
            # Extract TMDb ID from parent folder name
            if [[ "$folder_name" =~ \[tmdbid-([0-9]+)\] ]]; then
                echo "${BASH_REMATCH[1]}|$video_file" >> "$tmp_tmdb_file"
            elif [[ "$folder_name" =~ \[tmdb-([0-9]+)\] ]]; then
                echo "${BASH_REMATCH[1]}|$video_file" >> "$tmp_tmdb_file"
            elif [[ "$folder_name" =~ \{tmdb-([0-9]+)\} ]]; then
                echo "${BASH_REMATCH[1]}|$video_file" >> "$tmp_tmdb_file"
            fi
        done < <(find "$DESTINATION" -mindepth 2 -maxdepth 2 -type f \( -name "*.mkv" -o -name "*.mp4" -o -name "*.avi" -o -name "*.m4v" -o -name "*.mov" -o -name "*.wmv" -o -name "*.flv" -o -name "*.webm" \) -print0 2>/dev/null)
        
        # Find duplicate IMDb IDs (handle 2+ duplicates properly)
        local duplicate_imdb_count=0
        if [[ -f "$tmp_imdb_file" && -s "$tmp_imdb_file" ]]; then
            # Group by ID and collect all paths for each duplicate ID
            local duplicate_ids=$(sort "$tmp_imdb_file" | awk -F'|' '{id=$1; count[id]++} END {for (i in count) if (count[i] > 1) print i}')
            
            if [[ -n "$duplicate_ids" ]]; then
                echo ""
                print_warning "Found duplicate IMDb IDs:"
                
                # Convert to array for proper stdin handling
                local -a duplicate_ids_array=()
                while IFS= read -r id; do
                    [[ -n "$id" ]] && duplicate_ids_array+=("$id")
                done <<< "$duplicate_ids"
                
                # Process each duplicate with proper stdin
                for id in "${duplicate_ids_array[@]}"; do
                    # Get all items with this ID
                    local items=$(grep "^${id}|" "$tmp_imdb_file" | cut -d'|' -f2)
                    local item_count=$(echo "$items" | wc -l | tr -d ' ')
                    
                    echo ""
                    echo -e "  ${YELLOW}IMDb ID: $id (${item_count} items)${NC}"
                    
                    local idx=1
                    while IFS= read -r item_path; do
                        echo -e "    ${DIM}${idx}. $(basename "$item_path")${NC}"
                        
                        # Show file size
                        if [[ -f "$item_path" ]]; then
                            local file_size=$(_stat_size "$item_path")
                            if [[ -n "$file_size" ]]; then
                                local size_display=""
                                if [[ $file_size -ge 1099511627776 ]]; then
                                    size_display="$(echo "scale=1; $file_size / 1099511627776" | bc) TB"
                                elif [[ $file_size -ge 1073741824 ]]; then
                                    size_display="$(echo "scale=1; $file_size / 1073741824" | bc) GB"
                                elif [[ $file_size -ge 1048576 ]]; then
                                    size_display="$(echo "scale=1; $file_size / 1048576" | bc) MB"
                                else
                                    size_display="$(echo "scale=1; $file_size / 1024" | bc) KB"
                                fi
                                echo -e "       ${DIM}Size: ${size_display}${NC}"
                            fi
                        fi
                        
                        # Show runtime in IMDb format
                        if [[ -f "$item_path" ]]; then
                            local duration=$(ffprobe -v error -show_entries format=duration -of default=noprint_wrappers=1:nokey=1 "$item_path" 2>/dev/null)
                            if [[ -n "$duration" ]]; then
                                local total_minutes=$(echo "scale=0; $duration / 60" | bc)
                                echo -e "       ${DIM}Runtime: ${total_minutes} min${NC}"
                            fi
                        fi
                        
                        # Show source path if it's a hardlink
                        if [[ -f "$item_path" ]]; then
                            local inode=$(_stat_inode "$item_path")
                            local link_count=$(_stat_nlinks "$item_path")
                            
                            if [[ "$link_count" -gt 1 && -n "$inode" ]]; then
                                # Search SOURCE directory for hardlinks, excluding DESTINATION
                                local search_dir="$SOURCE"
                                local source_file=$(find "$search_dir" -path "${DESTINATION%/}" -prune -o -type f -inum "$inode" -print 2>/dev/null | grep -v "^${DESTINATION%/}/" | head -1)
                                if [[ -n "$source_file" ]]; then
                                    echo -e "       ${APRICOT}Source: $source_file${NC}"
                                fi
                            fi
                        fi
                        
                        echo -e "       ${SKY}Destination: $item_path${NC}"
                        ((idx++)) || true
                    done <<< "$items"
                    
                    ((duplicate_imdb_count++)) || true
                    
                    # Show IMDb details for verification before asking for action
                    echo ""
                    echo -e "${CYAN}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
                    echo -e "${GREEN}IMDb Details for ${id}:${NC}"
                    echo -e "${CYAN}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
                    
                    # Get and display IMDb runtime
                    local imdb_runtime=$(get_imdb_runtime "$id" 2>/dev/null)
                    if [[ -n "$imdb_runtime" && "$imdb_runtime" != "unknown" ]]; then
                        echo -e "${BLUE}Official Runtime: ${imdb_runtime} minutes${NC}"
                    else
                        echo -e "${YELLOW}Official Runtime: Not available${NC}"
                    fi
                    
                    # Get and display poster
                    local poster_url=$(get_imdb_poster "$id" 2>/dev/null)
                    if [[ -n "$poster_url" ]]; then
                        if show_poster "$id" "$poster_url" 35 2>/dev/null; then
                            echo ""
                        else
                            echo -e "${DIM}Poster URL: ${poster_url}${NC}"
                        fi
                    else
                        echo -e "${YELLOW}(No poster available)${NC}"
                    fi
                    
                    echo -e "${CYAN}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
                    echo ""
                    echo -e "${DIM}Compare the official runtime above with the file runtimes to verify which file matches.${NC}"
                    echo ""
                    
                    echo -e "${YELLOW}Would you like to correct or delete these items? (Enter or y to proceed/n to skip):${NC}"
                    stty echo 2>/dev/null
                    # Flush any stale input from terminal buffer (e.g., keypresses during poster display)
                    while read -t 0 _discard </dev/tty 2>/dev/null; do
                        read -t 0.1 -n 10000 _discard </dev/tty 2>/dev/null || true
                    done
                    read -r correct_choice </dev/tty || {
                        stty -echo 2>/dev/null
                        echo ""
                        print_info "Interrupted by user, exiting duplicate ID correction"
                        break
                    }
                    stty -echo 2>/dev/null
                    # Strip carriage returns (SSH/terminal compatibility)
                    correct_choice="${correct_choice//$'\r'/}"
                    
                    if [[ "$correct_choice" =~ ^[Nn]$ ]]; then
                        print_info "Skipping duplicate ID correction"
                        break
                    fi
                    
                    if [[ "$correct_choice" =~ ^[Yy]?$ ]]; then
                        # Build selection prompt based on number of items
                        local item_choice=""
                        while true; do
                            if [[ "$item_count" -eq 2 ]]; then
                                echo ""
                                echo -e "${YELLOW}Available Actions:${NC}"
                                echo -e "  ${GREEN}1${NC} = Correct first hardlinked item's ID"
                                echo -e "  ${GREEN}2${NC} = Correct second item's ID"
                                echo -e "  ${GREEN}b${NC} = Correct both items"
                                echo -e "  ${RED}d1${NC} = Delete first hardlinked item, its subs, and its extras"
                                echo -e "  ${RED}d2${NC} = Delete second hardlinked item, its subs, and its extras"
                                echo -e "  ${MAGENTA}h1${NC} = Delete first hardlinked item, its subs, and its extras + move its source folder to duplicates"
                                echo -e "  ${MAGENTA}h2${NC} = Delete second hardlinked item, its subs, and its extras + move its source folder to duplicates"
                                echo ""
                                echo -e "${YELLOW}Enter action:${NC}"
                            else
                                echo ""
                                echo -e "${YELLOW}Available Actions (for 2 or more, (delete or delete+move) commas are needed h4,5, or h2,5,7):${NC}"
                                echo -e "  ${GREEN}Correct:${NC} Enter numbers like 1,3 or 'a' for all"
                                echo -e "  ${RED}Delete:${NC} Enter d1,2,3 or 'da' for all"
                                echo -e "  ${MAGENTA}Hardlink Delete+Move:${NC} Enter h1,2,3 or 'ha' for all"
                                echo ""
                                echo -e "${YELLOW}Enter action:${NC}"
                            fi
                            stty echo 2>/dev/null
                            read -e -r item_choice </dev/tty || {
                                stty -echo 2>/dev/null
                                echo ""
                                print_info "Interrupted by user, skipping this duplicate ID"
                                break
                            }
                            stty -echo 2>/dev/null
                            
                            # Validate input before processing
                            local valid_input=false
                            if [[ "$item_choice" == "b" ]] || [[ "$item_choice" == "a" ]] || [[ "$item_choice" == "da" ]] || [[ "$item_choice" == "ha" ]]; then
                                valid_input=true
                            elif [[ "$item_choice" =~ ^[0-9,]+$ ]] || [[ "$item_choice" =~ ^d[0-9,]+$ ]] || [[ "$item_choice" =~ ^h[0-9,]+$ ]]; then
                                valid_input=true
                            fi
                            
                            if [[ "$valid_input" == "true" ]]; then
                                break
                            else
                                echo -e "${RED}Invalid choice. Please enter a valid option.${NC}"
                            fi
                        done
                        
                        # Check if interrupted
                        if [[ -z "$item_choice" ]]; then
                            continue
                        fi
                        
                        local -a items_to_correct=()
                        local -a items_to_delete=()
                        local -a items_to_hardlink_delete=()
                        local -a items_array=()
                        
                        # Convert items to array
                        while IFS= read -r item_path; do
                            items_array+=("$item_path")
                        done <<< "$items"
                        
                        # Parse selection - handle correct, delete, and hardlink delete actions
                        if [[ "$item_choice" =~ ^h ]]; then
                            # Hardlink delete action (delete file + move source folder)
                            if [[ "$item_choice" == "ha" ]]; then
                                items_to_hardlink_delete=("${items_array[@]}")
                            elif [[ "$item_choice" =~ ^h[0-9,]+$ ]]; then
                                local delete_nums=$(echo "$item_choice" | sed 's/^h//')
                                IFS=',' read -ra selections <<< "$delete_nums"
                                for sel in "${selections[@]}"; do
                                    sel=$(echo "$sel" | tr -d ' ')
                                    if [[ "$sel" =~ ^[0-9]+$ ]] && [[ "$sel" -ge 1 ]] && [[ "$sel" -le "$item_count" ]]; then
                                        items_to_hardlink_delete+=("${items_array[$((sel-1))]}")
                                    fi
                                done
                            elif [[ "$item_choice" == "h1" && "$item_count" -ge 1 ]]; then
                                items_to_hardlink_delete=("${items_array[0]}")
                            elif [[ "$item_choice" == "h2" && "$item_count" -ge 2 ]]; then
                                items_to_hardlink_delete=("${items_array[1]}")
                            else
                                print_warning "Invalid hardlink delete choice"
                                continue
                            fi
                        elif [[ "$item_choice" =~ ^d ]]; then
                            # Delete action
                            if [[ "$item_choice" == "da" ]]; then
                                items_to_delete=("${items_array[@]}")
                            elif [[ "$item_choice" =~ ^d[0-9,]+$ ]]; then
                                local delete_nums=$(echo "$item_choice" | sed 's/^d//')
                                IFS=',' read -ra selections <<< "$delete_nums"
                                for sel in "${selections[@]}"; do
                                    sel=$(echo "$sel" | tr -d ' ')
                                    if [[ "$sel" =~ ^[0-9]+$ ]] && [[ "$sel" -ge 1 ]] && [[ "$sel" -le "$item_count" ]]; then
                                        items_to_delete+=("${items_array[$((sel-1))]}")
                                    fi
                                done
                            elif [[ "$item_choice" == "d1" && "$item_count" -ge 1 ]]; then
                                items_to_delete=("${items_array[0]}")
                            elif [[ "$item_choice" == "d2" && "$item_count" -ge 2 ]]; then
                                items_to_delete=("${items_array[1]}")
                            else
                                print_warning "Invalid delete choice"
                                continue
                            fi
                        else
                            # Correct action
                            if [[ "$item_choice" == "a" ]]; then
                                items_to_correct=("${items_array[@]}")
                            elif [[ "$item_choice" == "b" && "$item_count" -eq 2 ]]; then
                                items_to_correct=("${items_array[@]}")
                            elif [[ "$item_choice" =~ ^[0-9,]+$ ]]; then
                                IFS=',' read -ra selections <<< "$item_choice"
                                for sel in "${selections[@]}"; do
                                    sel=$(echo "$sel" | tr -d ' ')
                                    if [[ "$sel" =~ ^[0-9]+$ ]] && [[ "$sel" -ge 1 ]] && [[ "$sel" -le "$item_count" ]]; then
                                        items_to_correct+=("${items_array[$((sel-1))]}")
                                    fi
                                done
                            elif [[ "$item_choice" =~ ^[0-9]+$ ]]; then
                                local sel="$item_choice"
                                if [[ "$sel" -ge 1 ]] && [[ "$sel" -le "$item_count" ]]; then
                                    items_to_correct=("${items_array[$((sel-1))]}")
                                fi
                            else
                                print_warning "Invalid choice, skipping"
                                continue
                            fi
                        fi
                        
                        # Process hardlink deletions first (delete file + move source folder to duplicates)
                        if [[ ${#items_to_hardlink_delete[@]} -gt 0 ]]; then
                            for item_to_delete in "${items_to_hardlink_delete[@]}"; do
                                echo ""
                                echo -e "${RED}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
                                echo -e "${RED}Hardlink Delete: $(basename "$item_to_delete")${NC}"
                                echo -e "${DIM}Full path: $item_to_delete${NC}"
                                
                                # Find source folder using hardlink cache
                                if [[ -f "$item_to_delete" ]]; then
                                    local inode=$(_stat_inode "$item_to_delete")
                                    local link_count=$(_stat_nlinks "$item_to_delete")
                                    
                                    if [[ "$link_count" -gt 1 && -n "$inode" ]]; then
                                        # Find source file using inode (exclude DESTINATION to avoid matching dest file itself)
                                        local source_file=""
                                        if [[ -n "$SOURCE" && -d "$SOURCE" ]]; then
                                            local search_dir="$SOURCE"
                                            source_file=$(find "$search_dir" -path "${DESTINATION%/}" -prune -o -type f -inum "$inode" -print 2>/dev/null | grep -v "^${DESTINATION%/}/" | head -1)
                                        fi
                                        
                                        if [[ -n "$source_file" ]]; then
                                            local source_folder=$(dirname "$source_file")
                                            echo -e "${APRICOT}Source file: $source_file${NC}"
                                            echo -e "${APRICOT}Source folder: $source_folder${NC}"
                                            
                                            # Find hardlinked files from this source in the destination
                                            local dest_folder=$(dirname "$item_to_delete")
                                            local files_to_delete=()
                                            
                                            # Check if source file is loose (directly in SOURCE root)
                                            local _is_loose_src=0
                                            if [[ "$source_folder" == "$SOURCE" ]]; then
                                                _is_loose_src=1
                                            fi
                                            
                                            # Pre-collect destination files and their inodes ONCE
                                            # (avoids nested process substitutions that leak FDs)
                                            local _cached_dest_files=()
                                            local _cached_dest_inodes=()
                                            while IFS= read -r -d '' _df; do
                                                _cached_dest_files+=("$_df")
                                                _cached_dest_inodes+=("$(_stat_inode "$_df")")
                                            done < <(find "$dest_folder" -type f -print0 2>/dev/null)
                                            
                                            if [[ $_is_loose_src -eq 1 ]]; then
                                                # Loose file: only delete the ONE dest file matching this specific source file's inode
                                                # Do NOT scan the entire SOURCE directory
                                                local _loose_inode=$(_stat_inode "$source_file")
                                                if [[ -n "$_loose_inode" ]]; then
                                                    for (( _di=0; _di<${#_cached_dest_files[@]}; _di++ )); do
                                                        if [[ "$_loose_inode" == "${_cached_dest_inodes[$_di]}" ]]; then
                                                            files_to_delete+=("${_cached_dest_files[$_di]}")
                                                        fi
                                                    done
                                                fi
                                            else
                                                # Folder-based: find all hardlinked files from source subfolder
                                                while IFS= read -r -d '' src_file; do
                                                    local src_inode=$(_stat_inode "$src_file")
                                                    local src_link_count=$(_stat_nlinks "$src_file")
                                                    
                                                    if [[ "$src_link_count" -gt 1 && -n "$src_inode" ]]; then
                                                        for (( _di=0; _di<${#_cached_dest_files[@]}; _di++ )); do
                                                            if [[ "$src_inode" == "${_cached_dest_inodes[$_di]}" ]]; then
                                                                files_to_delete+=("${_cached_dest_files[$_di]}")
                                                            fi
                                                        done
                                                    fi
                                                done < <(find "$source_folder" -type f -print0 2>/dev/null)
                                            fi
                                            
                                            # Delete all hardlinked files
                                            if [[ ${#files_to_delete[@]} -gt 0 ]]; then
                                                echo -e "${YELLOW}Found ${#files_to_delete[@]} hardlinked file(s) to delete:${NC}"
                                                for file_to_del in "${files_to_delete[@]}"; do
                                                    echo -e "${DIM}  - $(basename "$file_to_del")${NC}"
                                                    rm -f "$file_to_del"
                                                done
                                                print_success "✓ Deleted ${#files_to_delete[@]} hardlinked file(s) from destination"
                                            else
                                                # Fallback to just deleting the main file if nothing found
                                                rm -f "$item_to_delete"
                                                print_success "✓ Deleted hardlinked file from destination"
                                            fi
                                            
                                            # Clean up extras-type subdirectories in destination
                                            local _dest_extras_path=$(dirname "$item_to_delete")
                                            local _extras_del_count=0
                                            while IFS= read -r -d '' _ext_subdir; do
                                                local _ext_dir_name=$(basename "$_ext_subdir")
                                                local _ext_dir_lower=$(echo "$_ext_dir_name" | tr '[:upper:]' '[:lower:]')
                                                if [[ "$_ext_dir_lower" =~ ^(extras?|featurettes?|behind.the.scenes?|deleted.scenes?|interviews?|scenes?|samples?|shorts?|clips?|other|trailers?|bonus|bonus.discs?|outtakes?|gag.reels?|making.of|webisodes?|dvd.?extras?|blu.?ray.?extras?|bluray.?extras?)$ ]]; then
                                                    local _ext_fcount=0
                                                    while IFS= read -r -d '' _ef; do
                                                        echo -e "${DIM}  - ${_ext_dir_name}/$(basename "$_ef")${NC}"
                                                        rm -f "$_ef"
                                                        ((_ext_fcount++)) || true
                                                        ((_extras_del_count++)) || true
                                                    done < <(find "$_ext_subdir" -type f -print0 2>/dev/null)
                                                    rm -rf "$_ext_subdir" 2>/dev/null
                                                    if [[ $_ext_fcount -gt 0 ]]; then
                                                        print_info "  Removed extras folder: ${_ext_dir_name}/ ($_ext_fcount file(s))"
                                                    else
                                                        print_info "  Removed empty extras folder: ${_ext_dir_name}/"
                                                    fi
                                                fi
                                            done < <(find "$_dest_extras_path" -mindepth 1 -maxdepth 1 -type d -print0 2>/dev/null)
                                            [[ $_extras_del_count -gt 0 ]] && print_success "✓ Cleaned up $_extras_del_count extras file(s)"
                                            
                                            # Move source to duplicates
                                            # Determine drive root (same logic as unchosen duplicates)
                                            local drive_root=""
                                            if [[ "$source_folder" == /Volumes/* ]]; then
                                                drive_root=$(echo "$source_folder" | sed -E 's|^(/Volumes/[^/]+).*|\1|')
                                            elif [[ "$source_folder" == /mnt/* ]]; then
                                                drive_root=$(echo "$source_folder" | sed -E 's|^(/mnt/[^/]+).*|\1|')
                                            elif [[ "$source_folder" == /media/* ]]; then
                                                drive_root=$(echo "$source_folder" | sed -E 's|^(/media/[^/]+/[^/]+).*|\1|')
                                            elif [[ "$source_folder" == /run/media/* ]]; then
                                                drive_root=$(echo "$source_folder" | sed -E 's|^(/run/media/[^/]+/[^/]+).*|\1|')
                                            else
                                                drive_root=$(dirname "$SOURCE")
                                            fi
                                            [[ -z "$drive_root" ]] && drive_root=$(dirname "$source_folder")
                                            
                                            # Determine duplicates folder name using same logic as duplicate detection
                                            local duplicates_dir=""
                                            local cache_display_name=""
                                            if [[ -n "$CACHE_FILE" ]]; then
                                                local cache_basename=$(basename "$CACHE_FILE" .txt)
                                                cache_display_name=$(echo "$cache_basename" | sed -E 's/^(MOVIE|SHOWS) //;s/ CACHE$//')
                                            fi
                                            
                                            if [[ -n "$cache_display_name" ]]; then
                                                duplicates_dir="$drive_root/Duplicates ${cache_display_name}"
                                            else
                                                duplicates_dir="$drive_root/Duplicates"
                                            fi
                                            
                                            echo -e "${CYAN}DEBUG: source_folder=$source_folder${NC}"
                                            echo -e "${CYAN}DEBUG: drive_root=$drive_root${NC}"
                                            echo -e "${CYAN}DEBUG: duplicates_dir=$duplicates_dir${NC}"
                                            
                                            if ! mkdir -p "$duplicates_dir" 2>/dev/null; then
                                                print_error "✗ Failed to create duplicates directory: $duplicates_dir"
                                                echo -e "${RED}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
                                                continue
                                            fi
                                            
                                            # Check if source file is loose (directly in SOURCE root, not a subfolder)
                                            local _is_loose=0
                                            if [[ "$source_folder" == "$SOURCE" ]]; then
                                                _is_loose=1
                                            fi
                                            
                                            if [[ $_is_loose -eq 1 ]]; then
                                                # Loose file: move just the file, not the entire SOURCE directory
                                                local file_name=$(basename "$source_file")
                                                local dest_path="${duplicates_dir}/${file_name}"
                                                
                                                if [[ -e "$dest_path" ]]; then
                                                    local _base="${file_name%.*}"
                                                    local _ext="${file_name##*.}"
                                                    local counter=1
                                                    while [[ -e "${duplicates_dir}/${_base}_${counter}.${_ext}" ]]; do
                                                        ((counter++)) || true
                                                    done
                                                    dest_path="${duplicates_dir}/${_base}_${counter}.${_ext}"
                                                fi
                                                
                                                echo -e "${CYAN}DEBUG: Loose file move: mv \"$source_file\" \"$dest_path\"${NC}"
                                                
                                                if mv "$source_file" "$dest_path" 2>/dev/null; then
                                                    print_success "✓ Moved source file to duplicates: $(basename "$dest_path")"
                                                else
                                                    local mv_error=$?
                                                    print_error "✗ Failed to move source file (exit code: $mv_error)"
                                                    echo -e "${RED}  From: $source_file${NC}"
                                                    echo -e "${RED}  To: $dest_path${NC}"
                                                fi
                                            else
                                                # Folder-based: move the whole source subfolder
                                                local folder_name=$(basename "$source_folder")
                                                local dest_folder="${duplicates_dir}/${folder_name}"
                                                
                                                # Handle duplicate folder names
                                                local counter=1
                                                while [[ -d "$dest_folder" ]]; do
                                                    dest_folder="${duplicates_dir}/${folder_name}_${counter}"
                                                    ((counter++)) || true
                                                done
                                                
                                                echo -e "${CYAN}DEBUG: Folder move: mv \"$source_folder\" \"$dest_folder\"${NC}"
                                                
                                                if mv "$source_folder" "$dest_folder" 2>/dev/null; then
                                                    print_success "✓ Moved source folder to duplicates: $(basename "$dest_folder")"
                                                else
                                                    local mv_error=$?
                                                    print_error "✗ Failed to move source folder (exit code: $mv_error)"
                                                    echo -e "${RED}  From: $source_folder${NC}"
                                                    echo -e "${RED}  To: $dest_folder${NC}"
                                                    if [[ ! -d "$source_folder" ]]; then
                                                        echo -e "${YELLOW}  Reason: Source folder does not exist${NC}"
                                                    elif [[ ! -w "$(dirname "$source_folder")" ]]; then
                                                        echo -e "${YELLOW}  Reason: No write permission on source parent directory${NC}"
                                                    elif [[ ! -w "$duplicates_dir" ]]; then
                                                        echo -e "${YELLOW}  Reason: No write permission on duplicates directory${NC}"
                                                    fi
                                                fi
                                            fi
                                        else
                                            echo -e "${YELLOW}Warning: Source file not found for hardlink (inode: $inode)${NC}"
                                            echo -e "${YELLOW}Deleting destination file only${NC}"
                                            rm -f "$item_to_delete"
                                            print_success "✓ Deleted hardlinked file"
                                        fi
                                    else
                                        echo -e "${YELLOW}Warning: File is not a hardlink (link_count=$link_count)${NC}"
                                        echo -e "${YELLOW}Performing regular deletion instead${NC}"
                                        rm -f "$item_to_delete"
                                        print_success "✓ Deleted file"
                                    fi
                                    
                                    # Check if destination folder is now empty and remove it
                                    local folder_path=$(dirname "$item_to_delete")
                                    if [[ -d "$folder_path" ]]; then
                                        # Clean up any empty subdirectories first
                                        find "$folder_path" -mindepth 1 -depth -type d -empty -delete 2>/dev/null
                                        local remaining_items=$(find "$folder_path" -mindepth 1 -maxdepth 1 2>/dev/null | wc -l | tr -d ' ')
                                        if [[ "$remaining_items" -eq 0 ]]; then
                                            rmdir "$folder_path" 2>/dev/null
                                            print_info "  Removed empty destination folder: $(basename "$folder_path")"
                                        else
                                            local remaining_files=$(find "$folder_path" -mindepth 1 -type f 2>/dev/null | wc -l | tr -d ' ')
                                            print_info "  Destination folder retained ($remaining_files file(s) remaining)"
                                        fi
                                    fi
                                fi
                                echo -e "${RED}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
                            done
                        fi
                        
                        # Process regular deletions
                        if [[ ${#items_to_delete[@]} -gt 0 ]]; then
                            for item_to_delete in "${items_to_delete[@]}"; do
                                echo ""
                                echo -e "${RED}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
                                echo -e "${RED}Deleting: $(basename "$item_to_delete")${NC}"
                                echo -e "${DIM}Full path: $item_to_delete${NC}"
                                echo -e "${RED}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
                                
                                # Delete the file, its subs, and its extras
                                if [[ -f "$item_to_delete" ]]; then
                                    local _del_folder=$(dirname "$item_to_delete")
                                    local _del_basename=$(basename "$item_to_delete")
                                    local _del_stem="${_del_basename%.*}"
                                    
                                    rm -f "$item_to_delete"
                                    print_success "✓ Deleted file"
                                    
                                    # Delete associated subtitle files (matching video name stem)
                                    local _del_sub_count=0
                                    while IFS= read -r -d '' _sub_file; do
                                        local _sub_bn=$(basename "$_sub_file")
                                        if [[ "$_sub_bn" == "${_del_stem}."* ]]; then
                                            echo -e "${DIM}  - $_sub_bn${NC}"
                                            rm -f "$_sub_file"
                                            ((_del_sub_count++)) || true
                                        fi
                                    done < <(find "$_del_folder" -maxdepth 1 -type f \( -iname "*.srt" -o -iname "*.ass" -o -iname "*.sub" -o -iname "*.idx" -o -iname "*.ssa" -o -iname "*.vtt" -o -iname "*.sup" \) -print0 2>/dev/null)
                                    [[ $_del_sub_count -gt 0 ]] && print_success "✓ Deleted $_del_sub_count subtitle file(s)"
                                    
                                    # Clean up extras-type subdirectories
                                    local _d_extras_cleaned=0
                                    while IFS= read -r -d '' _d_ext_subdir; do
                                        local _d_ext_name=$(basename "$_d_ext_subdir")
                                        local _d_ext_lower=$(echo "$_d_ext_name" | tr '[:upper:]' '[:lower:]')
                                        if [[ "$_d_ext_lower" =~ ^(extras?|featurettes?|behind.the.scenes?|deleted.scenes?|interviews?|scenes?|samples?|shorts?|clips?|other|trailers?|bonus|bonus.discs?|outtakes?|gag.reels?|making.of|webisodes?|dvd.?extras?|blu.?ray.?extras?|bluray.?extras?)$ ]]; then
                                            local _d_ext_fcount=0
                                            while IFS= read -r -d '' _d_ef; do
                                                echo -e "${DIM}  - ${_d_ext_name}/$(basename "$_d_ef")${NC}"
                                                rm -f "$_d_ef"
                                                ((_d_ext_fcount++)) || true
                                                ((_d_extras_cleaned++)) || true
                                            done < <(find "$_d_ext_subdir" -type f -print0 2>/dev/null)
                                            rm -rf "$_d_ext_subdir" 2>/dev/null
                                            if [[ $_d_ext_fcount -gt 0 ]]; then
                                                print_info "  Removed extras folder: ${_d_ext_name}/ ($_d_ext_fcount file(s))"
                                            else
                                                print_info "  Removed empty extras folder: ${_d_ext_name}/"
                                            fi
                                        fi
                                    done < <(find "$_del_folder" -mindepth 1 -maxdepth 1 -type d -print0 2>/dev/null)
                                    [[ $_d_extras_cleaned -gt 0 ]] && print_success "✓ Cleaned up $_d_extras_cleaned extras file(s)"
                                    
                                    # Check if folder is now empty and remove it
                                    if [[ -d "$_del_folder" ]]; then
                                        find "$_del_folder" -mindepth 1 -depth -type d -empty -delete 2>/dev/null
                                        local _remaining=$(find "$_del_folder" -mindepth 1 -maxdepth 1 2>/dev/null | wc -l | tr -d ' ')
                                        if [[ "$_remaining" -eq 0 ]]; then
                                            rmdir "$_del_folder" 2>/dev/null
                                            print_info "  Removed empty folder: $(basename "$_del_folder")"
                                        else
                                            local _rem_files=$(find "$_del_folder" -mindepth 1 -type f 2>/dev/null | wc -l | tr -d ' ')
                                            print_info "  Folder retained ($_rem_files file(s) remaining)"
                                        fi
                                    fi
                                fi
                            done
                        fi
                        
                        if [[ ${#items_to_correct[@]} -eq 0 && ${#items_to_delete[@]} -eq 0 && ${#items_to_hardlink_delete[@]} -eq 0 ]]; then
                            print_warning "No valid items selected"
                            continue
                        fi
                        
                        # Process each selected item
                        for item_to_correct in "${items_to_correct[@]}"; do
                            echo ""
                            echo -e "${CYAN}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
                            echo -e "${GREEN}Correcting: $(basename "$item_to_correct")${NC}"
                            
                            # Find hardlink source by inode
                            if [[ -f "$item_to_correct" ]]; then
                                local inode=$(_stat_inode "$item_to_correct")
                                local link_count=$(_stat_nlinks "$item_to_correct")
                                
                                if [[ "$link_count" -gt 1 && -n "$inode" ]]; then
                                    # This is a hardlink - find the source (exclude DESTINATION)
                                    local source_file=""
                                    if [[ -n "$SOURCE" && -d "$SOURCE" ]]; then
                                        # Search SOURCE directory for hardlinks, excluding DESTINATION
                                        local search_dir="$SOURCE"
                                        source_file=$(find "$search_dir" -path "${DESTINATION%/}" -prune -o -type f -inum "$inode" -print 2>/dev/null | grep -v "^${DESTINATION%/}/" | head -1)
                                    fi
                                    
                                    if [[ -n "$source_file" ]]; then
                                        echo -e "${APRICOT}Source:      $source_file${NC}"
                                    else
                                        echo -e "${APRICOT}Source:      (hardlink source not found in SOURCE directory)${NC}"
                                    fi
                                else
                                    echo -e "${APRICOT}Source:      (not a hardlink)${NC}"
                                fi
                            fi
                            
                            echo -e "${SKY}Destination: $item_to_correct${NC}"
                            echo -e "${CYAN}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
                            echo ""
                            
                            # Extract title and year from folder name
                            local folder_name=$(basename "$(dirname "$item_to_correct")")
                            local title_year=$(echo "$folder_name" | sed -E 's/[[:space:]]*\[imdb.*$//')
                            local movie_title=$(echo "$title_year" | sed -E 's/[[:space:]]*\([0-9]{4}\)[[:space:]]*$//')
                            local movie_year=$(echo "$title_year" | grep -oE '\([0-9]{4}\)' | tr -d '()')
                            
                            # Show IMDb autocomplete to select correct ID
                            echo ""
                            echo -e "${GREEN}━━━ FILE BEING CORRECTED ━━━${NC}"
                            echo -e "${WHITE}  File: $(basename "$item_to_correct")${NC}"
                            echo -e "${DIM}  Path: $item_to_correct${NC}"
                            echo -e "${GREEN}━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
                            echo ""
                            echo -e "${CYAN}Select correct IMDb ID for this file from the autocomplete results:${NC}"
                            echo ""
                            
                            local new_id=""
                            new_id=$(imdb_autocomplete_search "$movie_title" "$movie_year") || true
                            
                            # Check if user chose to skip
                            if [[ "$new_id" == "SKIP" ]]; then
                                print_warning "Skipping correction for this item"
                                continue
                            fi
                            
                            # If autocomplete failed (no results), offer manual entry
                            if [[ -z "$new_id" ]]; then
                                echo -e "${YELLOW}No autocomplete results. Enter IMDb ID (tt123456), TMDb ID (digits), or 's' to skip:${NC}"
                                stty echo 2>/dev/null
                                read -r new_id </dev/tty
                                stty -echo 2>/dev/null
                                
                                if [[ "$new_id" == "s" || "$new_id" == "S" || -z "$new_id" ]]; then
                                    print_warning "Skipping correction for this item"
                                    continue
                                fi
                            fi
                            
                            # Determine if it's IMDb or TMDb
                            local new_imdb=""
                            local new_tmdb=""
                            if [[ "$new_id" =~ ^tt[0-9]+$ ]]; then
                                new_imdb="$new_id"
                                print_info "Updating to IMDb ID: $new_imdb"
                                # Get TMDb ID from IMDb using /find endpoint
                                if [[ -n "$TMDB_API_KEY" ]]; then
                                    local find_url="${TMDB_API_BASE}/find/${new_imdb}?api_key=${TMDB_API_KEY}&external_source=imdb_id"
                                    local result=$(curl -s "$find_url" 2>/dev/null)
                                    new_tmdb=$(echo "$result" | grep -oE '"id":[0-9]+' | head -1 | grep -oE '[0-9]+')
                                    [[ -n "$new_tmdb" ]] && echo "  TMDb ID: $new_tmdb"
                                fi
                            elif [[ "$new_id" =~ ^[0-9]+$ ]]; then
                                new_tmdb="$new_id"
                                print_info "Updating to TMDb ID: $new_tmdb"
                                # Get IMDb from TMDb
                                new_imdb=$(get_imdb_from_tmdb "$new_tmdb")
                                [[ -n "$new_imdb" ]] && echo "  IMDb ID: $new_imdb"
                            else
                                print_error "Invalid ID format (use tt123456 for IMDb or 123456 for TMDb)"
                                continue
                            fi
                            
                            # Fetch actual movie details from API for the new ID
                            local correct_title="$movie_title"
                            local correct_year="$movie_year"
                            if [[ -n "$new_tmdb" && -n "$TMDB_API_KEY" ]]; then
                                local movie_url="${TMDB_API_BASE}/movie/${new_tmdb}?api_key=${TMDB_API_KEY}"
                                local movie_data=$(curl -s "$movie_url" 2>/dev/null)
                                if [[ -n "$movie_data" ]]; then
                                    local api_title=$(echo "$movie_data" | grep -oE '"title":"[^"]+' | head -1 | sed 's/"title":"//')
                                    local api_year=$(echo "$movie_data" | grep -oE '"release_date":"[0-9]{4}' | head -1 | grep -oE '[0-9]{4}')
                                    [[ -n "$api_title" ]] && correct_title="$api_title"
                                    [[ -n "$api_year" ]] && correct_year="$api_year"
                                fi
                            fi
                            
                            # Update cache entry if it exists
                            if [[ -n "$CACHE_FILE" && -f "$CACHE_FILE" && -n "$movie_title" && -n "$movie_year" ]]; then
                                # Remove old cache entry (case-insensitive match)
                                local temp_cache=$(mktemp)
                                awk -F'|' -v title="$movie_title" -v year="$movie_year" \
                                    'BEGIN{IGNORECASE=1} tolower($1) != tolower(title) || $2 != year {print}' "$CACHE_FILE" > "$temp_cache"
                                mv "$temp_cache" "$CACHE_FILE"
                                
                                # Add new cache entry with correct title/year from API
                                # Remove any blank lines from cache before appending
                                if [[ -f "$CACHE_FILE" ]]; then
                                    local _tc="${CACHE_FILE}.tmp.$$"
                                    grep -v '^[[:space:]]*$' "$CACHE_FILE" > "$_tc" 2>/dev/null; mv "$_tc" "$CACHE_FILE" 2>/dev/null
                                    [[ -s "$CACHE_FILE" ]] && [[ -n "$(tail -c 1 "$CACHE_FILE" 2>/dev/null)" ]] && echo "" >> "$CACHE_FILE"
                                fi
                                echo "${correct_title}|${correct_year}|${new_imdb}|${new_tmdb}|$(date +%s)" >> "$CACHE_FILE"
                                print_success "✓ Updated cache entry for: $correct_title ($correct_year)"
                            fi
                            
                            # Rename the folder/file with new ID
                            local old_file_path="$item_to_correct"
                            local old_folder_path=$(dirname "$old_file_path")
                            local old_folder_name=$(basename "$old_folder_path")
                            local old_file_name=$(basename "$old_file_path")
                            
                            # correct_title and correct_year are already set from API fetch above
                            
                            # Extract edition tag from old folder name for preservation
                            local folder_edition_tag=$(echo "$old_folder_name" | grep -oiE '(THEATRICAL|EXTENDED|UNRATED|REMASTERED|RESTORED|IMAX|REDUX|DIRECTORS?[[:space:]]CUT|UNCUT|ULTIMATE|FINAL[[:space:]]CUT)' | head -1 | tr '[:lower:]' '[:upper:]')
                            
                            # Create new folder name with corrected title, year, and IDs
                            local new_folder_name=""
                            if [[ -n "$correct_title" && -n "$correct_year" ]]; then
                                # Use actual title and year from cache
                                local canonical_title=$(echo "$correct_title" | sed 's/[^a-zA-Z0-9]/-/g' | sed 's/-\+/-/g' | sed 's/^-\|-$//g')
                                new_folder_name="${canonical_title} (${correct_year})"
                                [[ -n "$folder_edition_tag" ]] && new_folder_name="${new_folder_name} ${folder_edition_tag}"
                                new_folder_name="${new_folder_name} [imdbid-${new_imdb}]"
                            else
                                # Fallback: just replace the ID in the old folder name
                                new_folder_name="$old_folder_name"
                                if [[ -n "$new_imdb" ]]; then
                                    new_folder_name=$(echo "$new_folder_name" | sed -E "s/\[imdbid-tt[0-9]+\]/[imdbid-$new_imdb]/")
                                    new_folder_name=$(echo "$new_folder_name" | sed -E "s/\[imdb-tt[0-9]+\]/[imdb-$new_imdb]/")
                                    new_folder_name=$(echo "$new_folder_name" | sed -E "s/\{imdb-tt[0-9]+\}/[imdb-$new_imdb]/")
                                fi
                                if [[ -n "$new_tmdb" ]]; then
                                    new_folder_name=$(echo "$new_folder_name" | sed -E "s/\[tmdbid-[0-9]+\]/[tmdbid-$new_tmdb]/")
                                    new_folder_name=$(echo "$new_folder_name" | sed -E "s/\[tmdb-[0-9]+\]/[tmdb-$new_tmdb]/")
                                    new_folder_name=$(echo "$new_folder_name" | sed -E "s/\{tmdb-[0-9]+\}/[tmdb-$new_tmdb]/")
                                fi
                            fi
                            
                            # Create new file name with corrected title, year, and IDs
                            local new_file_name=""
                            if [[ -n "$correct_title" && -n "$correct_year" ]]; then
                                # Extract quality, codec, edition, and release group from old filename
                                local quality_tag=$(echo "$old_file_name" | grep -oE '\[([Bb]luray|[Ww][Ee][Bb]|HDTV|DVDRip)(-[0-9]+p)?\]' | head -1)
                                local audio_tag=$(echo "$old_file_name" | grep -oE '\[([AD][A-Z]+[^]]*|[0-9]\.[0-9])\]' | head -1)
                                local codec_tag=$(echo "$old_file_name" | grep -oE '\[(x26[45]|[Hh]26[45]|[Hh][Ee][Vv][Cc]|AVC|HEVC)\]' | head -1)
                                # Extract edition tags (THEATRICAL, EXTENDED, UNRATED, etc.)
                                local edition_tag=$(echo "$old_file_name" | grep -oiE '(THEATRICAL|EXTENDED|UNRATED|REMASTERED|RESTORED|IMAX|REDUX|DIRECTORS?[[:space:]]CUT|UNCUT|ULTIMATE|FINAL[[:space:]]CUT)' | head -1 | tr '[:lower:]' '[:upper:]')
                                local release_group=$(echo "$old_file_name" | grep -oE '\-[A-Za-z0-9.]+\.(mkv|mp4|avi)$' | sed 's/^\-//;s/\.[^.]*$//')
                                local extension="${old_file_name##*.}"
                                
                                # Build new filename
                                local canonical_title=$(echo "$correct_title" | sed 's/[^a-zA-Z0-9]/-/g' | sed 's/-\+/-/g' | sed 's/^-\|-$//g')
                                new_file_name="${canonical_title} (${correct_year})"
                                [[ -n "$edition_tag" ]] && new_file_name="${new_file_name} ${edition_tag}"
                                new_file_name="${new_file_name} [imdbid-${new_imdb}]"
                                [[ -n "$quality_tag" ]] && new_file_name="${new_file_name} ${quality_tag}"
                                [[ -n "$audio_tag" ]] && new_file_name="${new_file_name} ${audio_tag}"
                                [[ -n "$codec_tag" ]] && new_file_name="${new_file_name} ${codec_tag}"
                                [[ -n "$release_group" ]] && new_file_name="${new_file_name}-${release_group}"
                                new_file_name="${new_file_name}.${extension}"
                            else
                                # Fallback: just replace the ID in the old filename
                                new_file_name="$old_file_name"
                                if [[ -n "$new_imdb" ]]; then
                                    new_file_name=$(echo "$new_file_name" | sed -E "s/\[imdbid-tt[0-9]+\]/[imdbid-$new_imdb]/")
                                    new_file_name=$(echo "$new_file_name" | sed -E "s/\[imdb-tt[0-9]+\]/[imdb-$new_imdb]/")
                                    new_file_name=$(echo "$new_file_name" | sed -E "s/\{imdb-tt[0-9]+\}/[imdb-$new_imdb]/")
                                fi
                                if [[ -n "$new_tmdb" ]]; then
                                    new_file_name=$(echo "$new_file_name" | sed -E "s/\[tmdbid-[0-9]+\]/[tmdbid-$new_tmdb]/")
                                    new_file_name=$(echo "$new_file_name" | sed -E "s/\[tmdb-[0-9]+\]/[tmdb-$new_tmdb]/")
                                    new_file_name=$(echo "$new_file_name" | sed -E "s/\{tmdb-[0-9]+\}/[tmdb-$new_tmdb]/")
                                fi
                            fi
                            
                            if [[ "$new_folder_name" != "$old_folder_name" || "$new_file_name" != "$old_file_name" ]]; then
                                local dest_base=$(dirname "$old_folder_path")
                                local new_folder_path="$dest_base/$new_folder_name"
                                local new_file_path="$new_folder_path/$new_file_name"
                                
                                # Create new folder if it doesn't exist
                                if [[ ! -d "$new_folder_path" ]]; then
                                    mkdir -p "$new_folder_path"
                                    print_info "Created new folder: $new_folder_name"
                                fi
                                
                                # Find source file by inode to remake hardlink
                                if [[ -f "$old_file_path" ]]; then
                                    local inode=$(_stat_inode "$old_file_path")
                                    local link_count=$(_stat_nlinks "$old_file_path")
                                    
                                    if [[ "$link_count" -gt 1 && -n "$inode" ]]; then
                                        # This is a hardlink - find the source and remake it (exclude DESTINATION)
                                        local source_file=""
                                        if [[ -n "$SOURCE" && -d "$SOURCE" ]]; then
                                            # Search SOURCE directory for hardlinks, excluding DESTINATION
                                            local search_dir="$SOURCE"
                                            source_file=$(find "$search_dir" -path "${DESTINATION%/}" -prune -o -type f -inum "$inode" -print 2>/dev/null | grep -v "^${DESTINATION%/}/" | head -1)
                                        fi
                                        
                                        if [[ -n "$source_file" && -f "$source_file" ]]; then
                                            # Remove old hardlink
                                            rm -f "$old_file_path"
                                            # Create new hardlink
                                            ln "$source_file" "$new_file_path" 2>/dev/null || cp "$source_file" "$new_file_path"
                                            print_success "✓ Recreated hardlink: $new_file_name"
                                            print_info "  New location: $new_file_path"
                                        else
                                            # Source not found, just move the file
                                            print_warning "  Hardlink source not found (inode: $inode), moving file instead"
                                            mv "$old_file_path" "$new_file_path"
                                            print_success "✓ Moved file: $new_file_name"
                                            print_info "  New location: $new_file_path"
                                        fi
                                    else
                                        # Not a hardlink, just move it
                                        mv "$old_file_path" "$new_file_path"
                                        print_success "✓ Moved file: $new_file_name"
                                        print_info "  New location: $new_file_path"
                                    fi
                                    
                                    # Move any subtitle/extra files from old folder to new folder
                                    local moved_extras=0
                                    if [[ -d "$old_folder_path" ]]; then
                                        while IFS= read -r extra_file; do
                                            [[ ! -f "$extra_file" ]] && continue
                                            local extra_name=$(basename "$extra_file")
                                            local new_extra_name="$extra_name"
                                            
                                            # Update IDs in extra file names
                                            if [[ -n "$new_imdb" ]]; then
                                                new_extra_name=$(echo "$new_extra_name" | sed -E "s/\[imdbid-tt[0-9]+\]/[imdbid-$new_imdb]/")
                                                new_extra_name=$(echo "$new_extra_name" | sed -E "s/\[imdb-tt[0-9]+\]/[imdb-$new_imdb]/")
                                            fi
                                            if [[ -n "$new_tmdb" ]]; then
                                                new_extra_name=$(echo "$new_extra_name" | sed -E "s/\[tmdbid-[0-9]+\]/[tmdbid-$new_tmdb]/")
                                                new_extra_name=$(echo "$new_extra_name" | sed -E "s/\[tmdb-[0-9]+\]/[tmdb-$new_tmdb]/")
                                            fi
                                            
                                            mv "$extra_file" "$new_folder_path/$new_extra_name"
                                            ((moved_extras++)) || true
                                        done < <(find "$old_folder_path" -maxdepth 1 -type f \( -name "*.srt" -o -name "*.ass" -o -name "*.sub" -o -name "*.idx" -o -name "*.nfo" -o -name "*.jpg" -o -name "*.png" \) 2>/dev/null)
                                        
                                        [[ $moved_extras -gt 0 ]] && print_info "  Moved $moved_extras extra file(s)"
                                        
                                        # Clean up empty old folder
                                        if [[ -d "$old_folder_path" ]]; then
                                            if [[ -z "$(ls -A "$old_folder_path" 2>/dev/null)" ]]; then
                                                rmdir "$old_folder_path"
                                                print_info "  Cleaned up empty folder: $old_folder_name"
                                            fi
                                        fi
                                    fi
                                fi
                            else
                                print_warning "No changes needed (IDs already correct)"
                            fi
                        done
                    else
                        print_info "Skipping correction for this duplicate"
                    fi
                done
            fi
        fi
        
        # Find duplicate TMDb IDs
        local duplicate_tmdb_count=0
        if [[ -f "$tmp_tmdb_file" && -s "$tmp_tmdb_file" ]]; then
            local tmdb_duplicates=$(sort "$tmp_tmdb_file" | awk -F'|' '{id=$1; path=$2; if (seen[id]) print id"|"seen[id]"|"path; seen[id]=path}')
            if [[ -n "$tmdb_duplicates" ]]; then
                echo ""
                print_warning "Found duplicate TMDb IDs:"
                
                # Convert to array for proper stdin handling
                local -a tmdb_dup_array=()
                while IFS='|' read -r id first_item second_item; do
                    [[ -n "$id" ]] && tmdb_dup_array+=("$id|$first_item|$second_item")
                done <<< "$tmdb_duplicates"
                
                # Process each duplicate with proper stdin
                for entry in "${tmdb_dup_array[@]}"; do
                    IFS='|' read -r id first_item second_item <<< "$entry"
                    
                    echo ""
                    echo -e "  ${YELLOW}TMDb ID: $id${NC}"
                    echo -e "    ${DIM}1. $(basename "$first_item")${NC}"
                    echo -e "    ${DIM}   Destination: $first_item${NC}"
                    echo -e "    ${DIM}2. $(basename "$second_item")${NC}"
                    echo -e "    ${DIM}   Destination: $second_item${NC}"
                    ((duplicate_tmdb_count++)) || true
                    
                    # Check if titles are similar (for IMDb autocomplete suggestion)
                    local first_title=$(basename "$first_item" | sed -E 's/[[:space:]]*\([0-9]{4}\).*$//')
                    local second_title=$(basename "$second_item" | sed -E 's/[[:space:]]*\([0-9]{4}\).*$//')
                    local titles_similar=false
                    local first_lower=$(echo "$first_title" | tr '[:upper:]' '[:lower:]')
                    local second_lower=$(echo "$second_title" | tr '[:upper:]' '[:lower:]')
                    if [[ "$first_lower" == "$second_lower" ]]; then
                        titles_similar=true
                    fi
                    
                    echo ""
                    echo -e "${YELLOW}Would you like to correct the IDs for these items? (y/n):${NC}"
                    stty echo 2>/dev/null
                    # Flush any stale input from terminal buffer
                    while read -t 0 _discard </dev/tty 2>/dev/null; do
                        read -t 0.1 -n 10000 _discard </dev/tty 2>/dev/null || true
                    done
                    read -r correct_choice </dev/tty
                    stty -echo 2>/dev/null
                    # Strip carriage returns (SSH/terminal compatibility)
                    correct_choice="${correct_choice//$'\r'/}"
                    if [[ "$correct_choice" =~ ^[Yy]$ ]]; then
                        echo -e "${YELLOW}Which items to correct? (1=first only, 2=second only, b=both):${NC}"
                        stty echo 2>/dev/null
                        read -r item_choice </dev/tty
                        stty -echo 2>/dev/null
                        
                        local items_to_correct=()
                        if [[ "$item_choice" == "1" ]]; then
                            items_to_correct=("$first_item")
                        elif [[ "$item_choice" == "2" ]]; then
                            items_to_correct=("$second_item")
                        elif [[ "$item_choice" == "b" ]]; then
                            items_to_correct=("$first_item" "$second_item")
                        else
                            print_warning "Invalid choice, skipping correction"
                            continue
                        fi
                        
                        # Process each selected item
                        for item_to_correct in "${items_to_correct[@]}"; do
                            echo ""
                            echo -e "${CYAN}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
                            echo -e "${GREEN}Correcting: $(basename "$item_to_correct")${NC}"
                            
                            # Find hardlink source by inode
                            if [[ -f "$item_to_correct" ]]; then
                                local inode=$(_stat_inode "$item_to_correct")
                                local link_count=$(_stat_nlinks "$item_to_correct")
                                
                                if [[ "$link_count" -gt 1 && -n "$inode" ]]; then
                                    # This is a hardlink - find the source
                                    local source_file=$(find "$SOURCE" -type f -inum "$inode" 2>/dev/null | head -1)
                                    if [[ -n "$source_file" ]]; then
                                        echo -e "${APRICOT}Source:      $source_file${NC}"
                                    fi
                                fi
                            fi
                            
                            echo -e "${SKY}Destination: $item_to_correct${NC}"
                            echo -e "${CYAN}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
                            
                            # Extract title and year from folder name
                            local folder_name=$(basename "$item_to_correct")
                            local title_year=$(echo "$folder_name" | sed -E 's/[[:space:]]*\[imdb.*$//')
                            local movie_title=$(echo "$title_year" | sed -E 's/[[:space:]]*\([0-9]{4}\)[[:space:]]*$//')
                            local movie_year=$(echo "$title_year" | grep -oE '\([0-9]{4}\)' | tr -d '()')
                            
                            local new_id=""
                            
                            # Offer IMDb autocomplete if titles are similar
                            if [[ "$titles_similar" == "true" ]]; then
                                echo -e "${YELLOW}Titles are similar. Use IMDb autocomplete to search? (y/n):${NC}"
                                stty echo 2>/dev/null
                                read -r use_autocomplete </dev/tty
                                stty -echo 2>/dev/null
                                if [[ "$use_autocomplete" == "y" ]]; then
                                    new_id=$(imdb_autocomplete_search "$movie_title" "$movie_year")
                                fi
                            fi
                            
                            # If autocomplete wasn't used or failed, ask for manual entry
                            if [[ -z "$new_id" ]]; then
                                echo -e "${YELLOW}Enter correct IMDb ID (tt followed by digits) or TMDb ID (just digits), or 's' to skip:${NC}"
                                stty echo 2>/dev/null
                                read -r new_id </dev/tty
                                stty -echo 2>/dev/null
                                
                                if [[ "$new_id" == "s" || -z "$new_id" ]]; then
                                    print_warning "Skipping correction for this item"
                                    continue
                                fi
                            fi
                            
                            # Determine if it's IMDb or TMDb
                            local new_imdb=""
                            local new_tmdb=""
                            if [[ "$new_id" =~ ^tt[0-9]+$ ]]; then
                                new_imdb="$new_id"
                                print_info "Updating to IMDb ID: $new_imdb"
                                # Get TMDb from IMDb using /find endpoint
                                if [[ -n "$TMDB_API_KEY" ]]; then
                                    local find_url="${TMDB_API_BASE}/find/${new_imdb}?api_key=${TMDB_API_KEY}&external_source=imdb_id"
                                    local result=$(curl -s "$find_url" 2>/dev/null)
                                    new_tmdb=$(echo "$result" | grep -oE '"id":[0-9]+' | head -1 | grep -oE '[0-9]+')
                                fi
                            elif [[ "$new_id" =~ ^[0-9]+$ ]]; then
                                new_tmdb="$new_id"
                                print_info "Updating to TMDb ID: $new_tmdb"
                                # Get IMDb from TMDb
                                new_imdb=$(get_imdb_from_tmdb "$new_tmdb")
                            else
                                print_error "Invalid ID format (use tt123456 for IMDb or 123456 for TMDb)"
                                continue
                            fi
                            
                            # Update cache entry if it exists
                            if [[ -n "$CACHE_FILE" && -f "$CACHE_FILE" && -n "$movie_title" && -n "$movie_year" ]]; then
                                # Remove old cache entry (case-insensitive match)
                                local temp_cache=$(mktemp)
                                awk -F'|' -v title="$movie_title" -v year="$movie_year" \
                                    'BEGIN{IGNORECASE=1} tolower($1) != tolower(title) || $2 != year {print}' "$CACHE_FILE" > "$temp_cache"
                                mv "$temp_cache" "$CACHE_FILE"
                                
                                # Add new cache entry with correct IDs
                                # Remove any blank lines from cache before appending
                                if [[ -f "$CACHE_FILE" ]]; then
                                    local _tc="${CACHE_FILE}.tmp.$$"
                                    grep -v '^[[:space:]]*$' "$CACHE_FILE" > "$_tc" 2>/dev/null; mv "$_tc" "$CACHE_FILE" 2>/dev/null
                                    [[ -s "$CACHE_FILE" ]] && [[ -n "$(tail -c 1 "$CACHE_FILE" 2>/dev/null)" ]] && echo "" >> "$CACHE_FILE"
                                fi
                                echo "${movie_title}|${movie_year}|${new_imdb}|${new_tmdb}|$(date +%s)" >> "$CACHE_FILE"
                                print_success "✓ Updated cache entry for: $movie_title ($movie_year)"
                            fi
                            
                            # Rename the folder/file with new ID
                            local old_name=$(basename "$item_to_correct")
                            local parent_dir=$(dirname "$item_to_correct")
                            local new_name="$old_name"
                            
                            # Replace old IMDb ID pattern
                            if [[ -n "$new_imdb" ]]; then
                                new_name=$(echo "$new_name" | sed -E "s/\[imdbid-[^\]]*\]/[imdbid-$new_imdb]/")
                                new_name=$(echo "$new_name" | sed -E "s/\[imdb-[^\]]*\]/[imdb-$new_imdb]/")
                            fi
                            
                            # Update TMDb ID
                            new_name=$(echo "$new_name" | sed -E "s/\[tmdbid-[^\]]*\]/[tmdbid-$new_tmdb]/")
                            new_name=$(echo "$new_name" | sed -E "s/\[tmdb-[^\]]*\]/[tmdb-$new_tmdb]/")
                            
                            if [[ "$new_name" != "$old_name" ]]; then
                                mv "$item_to_correct" "$parent_dir/$new_name"
                                print_success "✓ Renamed: $old_name → $new_name"
                            fi
                        done
                    else
                        print_info "Skipping correction for this duplicate"
                    fi
                done
            fi
        fi
        
        if [[ $duplicate_imdb_count -eq 0 && $duplicate_tmdb_count -eq 0 ]]; then
            print_success "No duplicate IDs found"
        fi
        
        # Cleanup temp files
        rm -f "$tmp_imdb_file" "$tmp_tmdb_file"
    fi
    
    # Show troubleshooting info, failed parse, and failed hardlinks
    show_troubleshooting_info "$total_failed"
    
    # Restore terminal echo
    stty echo 2>/dev/null
    
    # Temp files cleaned up automatically by trap
}

# Post-processing function for missing IDs
handle_missing_ids_post_processing() {
    # Ensure CACHE_FILE is set based on cache mode
    local cache_mode_file="$CACHE_DIR/cache_mode.txt"
    local cache_mode="4k"
    [[ -f "$cache_mode_file" ]] && cache_mode=$(cat "$cache_mode_file")
    
    case "$cache_mode" in
        unified)
            CACHE_FILE="$CACHE_DIR/MOVIE UNIFIED CACHE.txt"
            ;;
        4k)
            CACHE_FILE="$CACHE_DIR/MOVIE 4K CACHE.txt"
            ;;
        1080p)
            CACHE_FILE="$CACHE_DIR/MOVIE 1080p CACHE.txt"
            ;;
        1080p_xrated)
            CACHE_FILE="$CACHE_DIR/MOVIE 1080p X RATED CACHE.txt"
            ;;
        4k_xrated)
            CACHE_FILE="$CACHE_DIR/MOVIE 4K X RATED CACHE.txt"
            ;;
    esac
    
    echo ""
    echo -e "${YELLOW}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
    echo -e "${YELLOW}⚠  POST-PROCESSING: ${#FAILED_LOOKUPS[@]} file(s) with missing IDs${NC}"
    echo -e "${YELLOW}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
    echo ""
    echo -e "${CYAN}These files were successfully processed (hardlinked/renamed) but with placeholder IDs:${NC}"
    echo -e "${DIM}The IMDb and/or TMDb API lookups either failed or returned no information, so folders contain [imdbid-] or [tmdbid-] placeholders.${NC}"
    echo ""
    echo -e "${CYAN}Files with missing IDs:${NC}"
        for i in "${!FAILED_LOOKUPS[@]}"; do
            local entry="${FAILED_LOOKUPS[$i]}"
            IFS='|||' read -r file title year missing_imdb missing_tmdb <<< "$entry"
            
            local missing_msg=""
            if [[ "$missing_imdb" == "yes" && "$missing_tmdb" == "yes" ]]; then
                missing_msg="${RED}Missing: IMDb & TMDb${NC}"
            elif [[ "$missing_imdb" == "yes" ]]; then
                missing_msg="${YELLOW}Missing: IMDb${NC}"
            elif [[ "$missing_tmdb" == "yes" ]]; then
                missing_msg="${YELLOW}Missing: TMDb${NC}"
            fi
            
            echo -e "  ${YELLOW}$((i+1)).${NC} $title ($year) - $missing_msg"
            echo -e "      ${DIM}File: $(basename "$file")${NC}"
        done
        echo ""
        echo -e "${CYAN}How would you like to update these entries?${NC}"
        echo -e "  ${GREEN}1)${NC} Use IMDb autocomplete search (interactive)"
        echo -e "  ${GREEN}2)${NC} Manually provide IMDb/TMDb links"
        echo -e "  ${GREEN}3)${NC} Skip"
        echo ""
        echo -e "${YELLOW}Enter choice (1-3):${NC}"
        read -r update_choice
        
        if [[ "$update_choice" == "3" ]] || [[ ! "$update_choice" =~ ^[12]$ ]]; then
            print_info "Skipped post-processing"
        else
            # Track files to rename using parallel arrays (Bash 3.2 compatible)
            local -a RENAME_PATHS=()
            local -a RENAME_IDS=()
            
            for i in "${!FAILED_LOOKUPS[@]}"; do
                local entry="${FAILED_LOOKUPS[$i]}"
                IFS='|||' read -r file title year missing_imdb missing_tmdb <<< "$entry"
                
                # If title/year are empty, extract from filename
                if [[ -z "$title" || -z "$year" ]]; then
                    # Check cache first, then parse if needed
                    local cached_data=$(lookup_parse_cache "$file")
                    if [[ -n "$cached_data" ]]; then
                        PARSED_TITLE="${cached_data%%|*}"
                        PARSED_YEAR="${cached_data#*|}"
                    else
                        parse_filename "$file"
                    fi
                    
                    # Extract CLEAN title for cache (remove quality tags, IDs, etc.)
                    local item_name=$(basename "$file")
                    if [[ "$item_name" =~ ^([^[{]+)\ \(([0-9]{4})\) ]]; then
                        title="${BASH_REMATCH[1]}"
                        title="${title% }"  # trim trailing space
                        year="${BASH_REMATCH[2]}"
                    else
                        title="$PARSED_TITLE"
                        year="$PARSED_YEAR"
                    fi
                fi
                
                echo ""
                echo -e "${CYAN}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
                echo -e "${GREEN}$((i+1))/${#FAILED_LOOKUPS[@]}: $title ($year)${NC}"
                
                if [[ "$missing_imdb" == "yes" && "$missing_tmdb" == "yes" ]]; then
                    echo -e "${RED}Missing: Both IMDb and TMDb IDs${NC}"
                elif [[ "$missing_imdb" == "yes" ]]; then
                    echo -e "${YELLOW}Missing: IMDb ID${NC}"
                elif [[ "$missing_tmdb" == "yes" ]]; then
                    echo -e "${YELLOW}Missing: TMDb ID${NC}"
                fi
                
                echo -e "${CYAN}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
                echo ""
                
                local new_imdb=""
                local new_tmdb=""
                
                if [[ "$update_choice" == "1" ]]; then
                    # Use IMDb autocomplete search
                    echo -e "${YELLOW}Searching IMDb for: $title ($year)${NC}"
                    local selected_imdb=$(imdb_autocomplete_search "$title" "$year" || true)
                    
                    if [[ -z "$selected_imdb" ]]; then
                        print_warning "No selection made from autocomplete"
                        echo ""
                        echo -e "${CYAN}Would you like to manually enter the IMDb/TMDb link instead? (y/n)${NC}"
                        read -r manual_fallback </dev/tty
                        
                        if [[ ! "$manual_fallback" =~ ^[Yy]$ ]]; then
                            print_info "Skipped"
                            continue
                        fi
                        
                        # Fall through to manual entry
                        update_choice="2"
                    else
                        new_imdb="$selected_imdb"
                        print_success "Selected IMDb ID: $new_imdb"
                        
                        # Get TMDb ID from IMDb
                        if [[ "$missing_tmdb" == "yes" ]]; then
                            new_tmdb=$(search_tmdb "$title" "$year" "$new_imdb")
                            if [[ -n "$new_tmdb" ]]; then
                                print_success "Found TMDb ID from IMDb: $new_tmdb"
                            else
                                print_warning "Could not find TMDb ID from IMDb"
                            fi
                        fi
                    fi
                fi
                
                if [[ "$update_choice" == "2" ]]; then
                    # Manual link entry (option 2)
                    if [[ "$missing_imdb" == "yes" && "$missing_tmdb" == "yes" ]]; then
                        echo -e "${YELLOW}Paste IMDb link (https://www.imdb.com/title/tt1234567/) OR TMDb link (https://www.themoviedb.org/movie/12345):${NC}"
                        echo -e "${DIM}• Paste one or both links (any order), one per line${NC}"
                        echo -e "${DIM}• Press ENTER after each link${NC}"
                        flash_instruction "• Press ENTER twice when finished to continue" "$GREEN"
                        echo -e "${DIM}• Script will auto-fetch the missing ID if you provide only one${NC}"
                    elif [[ "$missing_imdb" == "yes" ]]; then
                        echo -e "${YELLOW}Paste IMDb link (https://www.imdb.com/title/tt1234567/):${NC}"
                        flash_instruction "Press ENTER twice after pasting to continue" "$GREEN"
                        echo -e "${RED}⚠ Only IMDb links accepted - TMDb links will be rejected${NC}"
                    elif [[ "$missing_tmdb" == "yes" ]]; then
                        echo -e "${YELLOW}Paste TMDb link (https://www.themoviedb.org/movie/12345/):${NC}"
                        flash_instruction "Press ENTER twice after pasting to continue" "$GREEN"
                        echo -e "${RED}⚠ Only TMDb links accepted - IMDb links will be rejected${NC}"
                    fi
                    echo -e "${DIM}Or press Enter to skip${NC}"
                    
                    # Collect all input lines (for multiple links)
                    local link_input=""
                    local first_line=1
                    while IFS= read -r line; do
                        [[ -z "$line" ]] && break
                        [[ $first_line -eq 1 ]] && first_line=0 || link_input+=$'\n'
                        link_input+="$line"
                    done
                    
                    if [[ -z "$link_input" ]]; then
                        print_info "Skipped"
                        continue
                    fi
                    
                    # Check for IMDb link
                    if [[ "$link_input" =~ imdb\.com/title/(tt[0-9]+) ]]; then
                        new_imdb="${BASH_REMATCH[1]}"
                        print_success "Extracted IMDb ID: $new_imdb"
                        
                        # Try to get TMDb ID from IMDb if TMDb is missing
                        if [[ "$missing_tmdb" == "yes" ]]; then
                            new_tmdb=$(search_tmdb "$title" "$year" "$new_imdb")
                            [[ -n "$new_tmdb" ]] && print_success "Found TMDb ID from IMDb: $new_tmdb"
                        fi
                    fi
                    
                    # Check for TMDb link
                    if [[ "$link_input" =~ themoviedb\.org/movie/([0-9]+) ]]; then
                        new_tmdb="${BASH_REMATCH[1]}"
                        print_success "Extracted TMDb ID: $new_tmdb"
                        
                        # Try to get IMDb ID from TMDb if IMDb is missing and we don't have it yet
                        if [[ "$missing_imdb" == "yes" && -z "$new_imdb" ]]; then
                            new_imdb=$(get_imdb_from_tmdb "$new_tmdb")
                            [[ -n "$new_imdb" ]] && print_success "Found IMDb ID from TMDb: $new_imdb"
                        fi
                    fi
                fi
                
                # Validate that we got the required ID type
                local validation_failed=0
                if [[ "$missing_imdb" == "yes" && "$missing_tmdb" == "yes" ]]; then
                    # Both missing - accept either but warn if only one provided
                    if [[ -z "$new_imdb" && -z "$new_tmdb" ]]; then
                        print_error "Please provide at least one valid IMDb or TMDb link"
                        validation_failed=1
                    fi
                elif [[ "$missing_imdb" == "yes" && -z "$new_imdb" ]]; then
                    # Only IMDb missing but wasn't provided
                    print_error "This file needs an IMDb ID - please provide an IMDb link (https://www.imdb.com/title/tt...)"
                    validation_failed=1
                elif [[ "$missing_tmdb" == "yes" && -z "$new_tmdb" ]]; then
                    # Only TMDb missing but wasn't provided
                    print_error "This file needs a TMDb ID - please provide a TMDb link (https://www.themoviedb.org/movie/...)"
                    validation_failed=1
                fi
                
                # Skip if validation failed
                if [[ $validation_failed -eq 1 ]]; then
                    print_warning "Skipping this entry - please try again"
                    continue
                fi
                
                # Update cache and fetch poster if we got IDs
                if [[ -n "$new_imdb" || -n "$new_tmdb" ]]; then
                    # Fetch and display poster
                    if [[ -n "$new_imdb" ]]; then
                        echo ""
                        local poster_url=$(get_imdb_poster "$new_imdb" || true)
                        if [[ -n "$poster_url" ]]; then
                            print_info "Fetching poster..."
                            show_poster "$new_imdb" "$poster_url" 30 || true
                            echo ""
                        fi
                    fi
                    
                    # Get existing IDs from cache if available
                    local existing_imdb=""
                    local existing_tmdb=""
                    local cached_line=$(awk -F'|' -v t="$title" -v y="$year" '$1 == t && $2 == y {print; exit}' "$CACHE_FILE" 2>/dev/null)
                    if [[ -n "$cached_line" ]]; then
                        IFS='|' read -r _ _ existing_imdb existing_tmdb _ <<< "$cached_line"
                    fi
                    
                    # Merge new IDs with existing ones
                    local final_imdb="${new_imdb:-$existing_imdb}"
                    local final_tmdb="${new_tmdb:-$existing_tmdb}"
                    
                    # Check if entry exists in cache
                    if awk -F'|' -v t="$title" -v y="$year" '$1 == t && $2 == y {found=1; exit} END {exit !found}' "$CACHE_FILE" 2>/dev/null; then
                        # Update existing entry
                        local temp_file="${CACHE_FILE}.tmp"
                        while IFS='|' read -r cached_title cached_year cached_imdb cached_tmdb cached_ts; do
                            # Skip blank lines
                            [[ -z "$cached_title" && -z "$cached_year" && -z "$cached_imdb" && -z "$cached_tmdb" && -z "$cached_ts" ]] && continue
                            if [[ "$cached_title" == "$title" && "$cached_year" == "$year" ]]; then
                                echo "${cached_title}|${cached_year}|${final_imdb}|${final_tmdb}|${cached_ts}"
                                print_success "Updated cache: $title ($year) - IMDb: $final_imdb, TMDb: $final_tmdb"
                            else
                                echo "${cached_title}|${cached_year}|${cached_imdb}|${cached_tmdb}|${cached_ts}"
                            fi
                        done < "$CACHE_FILE" > "$temp_file"
                        mv "$temp_file" "$CACHE_FILE"
                    else
                        # Add new entry (only if both IDs exist)
                        if [[ -n "$final_imdb" && -n "$final_tmdb" ]]; then
                            save_to_cache "$title" "$year" "$final_imdb" "$final_tmdb"
                            print_success "Added to cache: $title ($year) - IMDb: $final_imdb, TMDb: $final_tmdb"
                        else
                            print_warning "Cannot add to cache - missing IMDb='$final_imdb' or TMDb='$final_tmdb'"
                        fi
                    fi
                    
                    # Track for renaming if we got new IDs
                    if [[ -n "$new_tmdb" || -n "$new_imdb" ]]; then
                        RENAME_PATHS+=("$file")
                        RENAME_IDS+=("$final_tmdb|||$final_imdb")
                    fi
                else
                    print_warning "Could not extract IMDb or TMDb ID from link"
                fi
            done
            
            # Rename files/folders if we have updates
            if [[ ${#RENAME_PATHS[@]} -gt 0 ]]; then
                echo ""
                echo -e "${CYAN}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
                echo -e "${CYAN}Renaming files with updated IDs...${NC}"
                echo -e "${CYAN}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
                echo ""
                
                for i in "${!RENAME_PATHS[@]}"; do
                    local old_path="${RENAME_PATHS[$i]}"
                    local ids="${RENAME_IDS[$i]}"
                    IFS='|||' read -r final_tmdb final_imdb <<< "$ids"
                    
                    # Parse the filename
                    parse_filename "$old_path"
                    local old_name=$(basename "$old_path")
                    local dir_path=$(dirname "$old_path")
                    
                    # Build new filename with updated IDs
                    local new_name="$old_name"
                    
                    # Replace empty TMDb IDs (all naming schemes)
                    if [[ -n "$final_tmdb" ]]; then
                        # Jellyfin & Emby files: [tmdbid-]
                        if [[ "$new_name" =~ \[tmdbid-\] ]]; then
                            new_name="${new_name//\[tmdbid-\]/[tmdbid-$final_tmdb]}"
                        fi
                        # Emby folders: [tmdb-]
                        if [[ "$new_name" =~ \[tmdb-\] ]]; then
                            new_name="${new_name//\[tmdb-\]/[tmdb-$final_tmdb]}"
                        fi
                        # Plex: {tmdb-}
                        if [[ "$new_name" =~ \{tmdb-\} ]]; then
                            new_name="${new_name//\{tmdb-\}/\{tmdb-$final_tmdb\}}"
                        fi
                    fi
                    
                    # Replace empty IMDb IDs (all naming schemes)
                    if [[ -n "$final_imdb" ]]; then
                        # Jellyfin & Emby files: [imdbid-]
                        if [[ "$new_name" =~ \[imdbid-\] ]]; then
                            new_name="${new_name//\[imdbid-\]/[imdbid-$final_imdb]}"
                        fi
                        # Emby folders: [imdb-]
                        if [[ "$new_name" =~ \[imdb-\] ]]; then
                            new_name="${new_name//\[imdb-\]/[imdb-$final_imdb]}"
                        fi
                        # Plex: {imdb-}
                        if [[ "$new_name" =~ \{imdb-\} ]]; then
                            new_name="${new_name//\{imdb-\}/\{imdb-$final_imdb\}}"
                        fi
                    fi
                    
                    # Only rename if the name changed
                    if [[ "$old_name" != "$new_name" ]]; then
                        local new_path="${dir_path}/${new_name}"
                        
                        if [[ -e "$new_path" ]]; then
                            # New file already exists - check if it's the same file (hardlink)
                            local old_inode=$(_stat_inode "$old_path")
                            local new_inode=$(_stat_inode "$new_path")
                            
                            if [[ "$old_inode" == "$new_inode" ]]; then
                                # Same file - just remove the old hardlink
                                rm "$old_path"
                                print_success "Removed old filename: $old_name"
                                print_info "     (kept: $new_name)"
                            else
                                print_warning "Skipped (different file exists): $new_name"
                            fi
                        else
                            if mv "$old_path" "$new_path" 2>/dev/null; then
                                print_success "Renamed: $old_name"
                                print_info "     → $new_name"
                            else
                                print_warning "Failed to rename: $old_name"
                            fi
                        fi
                    fi
                done
                
                echo ""
                print_success "File renaming complete!"
            else
                echo ""
                print_success "Cache update complete!"
            fi
        fi
}

# Show cache info if any files failed
show_troubleshooting_info() {
    if [[ $1 -gt 0 ]]; then
        echo ""
        echo -e "${YELLOW}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
        echo -e "${YELLOW}⚠  TROUBLESHOOTING: $1 movie(s) failed to process${NC}"
        echo -e "${YELLOW}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
        echo ""
        if [[ ${#FAILED_FILES[@]} -gt 0 ]]; then
            echo -e "${RED}Failed files:${NC}"
            for failed_entry in "${FAILED_FILES[@]}"; do
                # Parse the entry - format is filepath|||reason or just filepath
                if [[ "$failed_entry" == *"|||"* ]]; then
                    local failed_file="${failed_entry%|||*}"
                    local fail_reason="${failed_entry#*|||}"
                    echo -e "  ${RED}✗${NC} $(basename "$failed_file")"
                    echo -e "     ${YELLOW}Reason: $fail_reason${NC}"
                    echo -e "     ${DIM}$failed_file${NC}"
                else
                    echo -e "  ${RED}✗${NC} $(basename "$failed_entry")"
                    echo -e "     ${DIM}$failed_entry${NC}"
                fi
            done
            echo ""
        fi
        echo -e "${CYAN}To manually add missing movies to cache:${NC}" or $HOME/user/.movie_simulator/cache_option_you_chose_in_menut.txt
        echo ""
        echo -e "  ${GREEN}1) Open cache file:${NC}"
        echo -e "     ${DIM}nano ${CACHE_FILE}${NC}"
        echo ""
        echo -e "  ${GREEN}2) Add a line with this format:${NC}"
        echo -e "     ${DIM}Movie Title|Year|tt1234567|12345|1234567890${NC}"
        echo ""
        echo -e "  ${GREEN}3) Find IMDb ID:${NC}"
        echo -e "     ${DIM}https://www.imdb.com/${NC} → copy 'tt' number from URL"
        echo ""
        echo -e "  ${GREEN}4) Find TMDb ID:${NC}"
        echo -e "     ${DIM}https://www.themoviedb.org/${NC} → copy number from URL"
        echo ""
        echo -e "  ${GREEN}5) Generate timestamp:${NC}"
        echo -e "     ${DIM}date +%s${NC}  (or use any number)"
        echo ""
        echo -e "${YELLOW}Example cache entry:${NC}"
        echo -e "  ${DIM}The Matrix|1999|tt0133093|603|1699564800${NC}"
        echo ""
        echo -e "${CYAN}Cache locations:${NC}"
        echo -e "  ${DIM}• Movie cache: ${CACHE_FILE}${NC}"
        echo -e "  ${DIM}• Poster cache: ${POSTER_CACHE_DIR}${NC}"
        echo -e "  ${DIM}• Documentation: See script lines 33-85${NC}"
        echo ""
        echo -e "${YELLOW}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
    fi

    # Handle failed hardlinks (cross-volume/filesystem issues)
    if [[ ${#FAILED_HARDLINKS[@]} -gt 0 ]]; then
        echo ""
        echo -e "${YELLOW}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
        echo -e "${YELLOW}⚠  HARDLINK FAILURES DETECTED${NC}"
        echo -e "${YELLOW}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
        echo ""
        echo -e "${CYAN}Some files could not be hardlinked (usually due to different volumes/filesystems).${NC}"
        echo -e "${CYAN}For each file, you can choose to create a symbolic link, copy the file, or skip it.${NC}"
        echo ""
        
        local failed_count=0
        local symlinked_count=0
        local copied_count=0
        local skipped_count=0
        
        for failed_entry in "${FAILED_HARDLINKS[@]}"; do
            IFS=$'\t' read -r source_file dest_file title year <<< "$failed_entry"
            failed_count=$((failed_count + 1))
            
            echo -e "${YELLOW}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
            echo -e "${CYAN}Movie:${NC} ${title} (${year})"
            echo -e "${APRICOT}Source: ${source_file}${NC}"
            echo -e "${SKY}Destination: ${dest_file}${NC}"
            echo ""
            echo -e "${GREEN}Options:${NC}"
            echo -e "  ${GREEN}1)${NC} Create symbolic link (soft link to original file)"
            echo -e "  ${GREEN}2)${NC} Copy file (duplicate the file - uses disk space)"
            echo -e "  ${GREEN}3)${NC} Skip this file (leave destination empty)"
            echo -e "  ${GREEN}4)${NC} Cancel all remaining files"
            echo ""
            
            while true; do
                read -p "Choose an option (1-4): " choice
                case "$choice" in
                    1)
                        # Create symbolic link
                        movie_folder=$(dirname "$dest_file")
                        mkdir -p "$movie_folder"
                        if ln -s "$source_file" "$dest_file" 2>/dev/null; then
                            echo -e "${GREEN}✓ Symbolic link created${NC}"
                            symlinked_count=$((symlinked_count + 1))
                        else
                            echo -e "${RED}✗ Failed to create symbolic link${NC}"
                            skipped_count=$((skipped_count + 1))
                        fi
                        break
                        ;;
                    2)
                        # Copy file
                        movie_folder=$(dirname "$dest_file")
                        mkdir -p "$movie_folder"
                        if cp "$source_file" "$dest_file" 2>/dev/null; then
                            echo -e "${GREEN}✓ File copied${NC}"
                            copied_count=$((copied_count + 1))
                        else
                            echo -e "${RED}✗ Failed to copy file${NC}"
                            skipped_count=$((skipped_count + 1))
                        fi
                        break
                        ;;
                    3)
                        # Skip
                        echo -e "${YELLOW}⊘ Skipped${NC}"
                        skipped_count=$((skipped_count + 1))
                        break
                        ;;
                    4)
                        # Cancel all remaining
                        echo -e "${RED}Cancelling remaining failed hardlinks...${NC}"
                        remaining=$((${#FAILED_HARDLINKS[@]} - failed_count))
                        skipped_count=$((skipped_count + remaining))
                        break 2
                        ;;
                    *)
                        echo -e "${RED}Invalid choice. Please enter 1, 2, 3, or 4.${NC}"
                        ;;
                esac
            done
            echo ""
        done
        
        # Show summary
        echo -e "${YELLOW}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
        echo -e "${CYAN}Failed Hardlinks Summary:${NC}"
        echo -e "  ${GREEN}• Symbolic links created:${NC} ${symlinked_count}"
        echo -e "  ${GREEN}• Files copied:${NC} ${copied_count}"
        echo -e "  ${YELLOW}• Skipped:${NC} ${skipped_count}"
        echo -e "  ${CYAN}• Total failed hardlinks:${NC} ${#FAILED_HARDLINKS[@]}"
        echo -e "${YELLOW}━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━${NC}"
        echo ""
    fi

    # Restart media server containers if we stopped them
    if [[ "$STOP_MEDIA_SERVERS" == "true" ]]; then
        start_media_server_containers
    fi
}

# Show usage
usage() {
    cat << EOF
Usage: $0 [options]
  Run without options for interactive mode

Options:
  --view-cache       View cached movie data
  --clear-cache      Clear the cache
  -h, --help         Show this help
EOF
    exit 0
}

# Main
# Clean up any stale locks from previous interrupted runs
rm -rf /tmp/tv_lookup_locks 2>/dev/null
mkdir -p /tmp/tv_lookup_locks 2>/dev/null

if [[ $# -eq 0 ]]; then
    interactive_mode
else
    case "$1" in
        --view-cache)
            if [[ -f "$CACHE_FILE" ]]; then
                echo ""
                print_info "Cached Movies"
                printf "%-40s %-6s %-12s %-10s\n" "TITLE" "YEAR" "IMDB" "TMDB"
                echo "--------------------------------------------------------------------------------"
                while IFS='|' read -r title year imdb tmdb timestamp; do
                    printf "%-40s %-6s %-12s %-10s\n" "$title" "$year" "$imdb" "$tmdb"
                done < "$CACHE_FILE"
                echo ""
                count=$(wc -l < "$CACHE_FILE")
                print_success "Total: ${count// /}"
            else
                print_warning "No cache found"
            fi
            ;;
        --clear-cache)
            if [[ -f "$CACHE_FILE" ]]; then
                rm "$CACHE_FILE"
                print_success "Cache cleared"
            else
                print_info "Cache already empty"
            fi
            ;;
        -h|--help)
            usage
            ;;
        *)
            print_error "Unknown option: $1"
            usage
            exit 1
            ;;
    esac
fi
